/* ═══════════════════════════════════════════════════
   AURA AI — APPLICATION CORE  (production-fixed)
═══════════════════════════════════════════════════ */
'use strict';

// ══════════════════════════════════════════════════
// GLOBAL ERROR BOUNDARY — catches crashes before they
// cause a white screen. Hoisted first.
// ══════════════════════════════════════════════════
window.addEventListener('error', function _globalErrHandler(e) {
  try {
    if (typeof ZenQLogger !== 'undefined')
      ZenQLogger.error('GlobalError', e.message, 'at', e.filename + ':' + e.lineno);
    else
      console.error('[ZenQ:GlobalError]', e.message, 'at', e.filename + ':' + e.lineno);
  } catch(_) {}
});

window.addEventListener('unhandledrejection', function _globalRejectHandler(e) {
  try {
    const reason = e.reason ? (e.reason.message || String(e.reason)) : 'Unknown rejection';
    if (typeof ZenQLogger !== 'undefined')
      ZenQLogger.error('UnhandledRejection', reason);
    else
      console.error('[ZenQ:UnhandledRejection]', reason);
    // Prevent the default browser "Uncaught (in promise)" noise
    e.preventDefault();
  } catch(_) {}
});

// ══════════════════════════════════════════════════
// AURA LOGGER — HOISTED: declared first so all code
// below (error handlers, storage, init) can reference
// it safely. Original placement at bottom caused TDZ
// risk when window.error fired before line ~10000.
// ══════════════════════════════════════════════════
const ZenQLogger = (() => {
  const MAX_LOGS = 500;
  const logs = [];
  const LEVELS = { DEBUG:0, INFO:1, WARN:2, ERROR:3 };
  let _minLevel = LEVELS.INFO;
  function _write(level, tag, ...args) {
    const entry = { level, tag, ts: Date.now(), msg: args.map(a => {
      try { return typeof a === 'object' ? JSON.stringify(a) : String(a); } catch(e) { return '[Unserializable]'; }
    }).join(' ')};
    logs.push(entry);
    if (logs.length > MAX_LOGS) logs.shift();
    if (LEVELS[level] >= _minLevel) {
      const fn = level === 'ERROR' ? console.error : level === 'WARN' ? console.warn : console.log;
      fn(`[ZenQ:${tag}]`, ...args);
    }
    // FIX: Deferred via microtask so ZenQDB is always defined when this runs
    if (level === 'ERROR') {
      Promise.resolve().then(() => {
        try { if (typeof ZenQDB !== 'undefined' && ZenQDB.db) ZenQDB.kvSet('zenq_last_error', {msg:entry.msg, ts:entry.ts, tag}).catch(()=>{}); } catch(e) {}
      });
    }
  }
  return {
    debug: (tag, ...a) => _write('DEBUG', tag, ...a),
    info:  (tag, ...a) => _write('INFO',  tag, ...a),
    warn:  (tag, ...a) => _write('WARN',  tag, ...a),
    error: (tag, ...a) => _write('ERROR', tag, ...a),
    getLogs: () => [...logs],
    setLevel: (l) => { if(LEVELS[l] !== undefined) _minLevel = LEVELS[l]; },
    exportLogs: () => {
      const txt = logs.map(l=>`[${new Date(l.ts).toISOString()}][${l.level}][${l.tag}] ${l.msg}`).join('\n');
      const b = new Blob([txt],{type:'text/plain'});
      const u = URL.createObjectURL(b);
      const a = document.createElement('a');
      a.href = u; a.download = `aura-logs-${Date.now()}.txt`;
      a.style.display = 'none';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      // Revoke after browser has had 2 frames to initiate the download
      requestAnimationFrame(() => requestAnimationFrame(() => URL.revokeObjectURL(u)));
    }
  };
})();

// ════════════════════════════════════════════════════
// AURA FRAMEWORK CORE  v19 — Module Registry + EventBus
// ────────────────────────────────────────────────────
// ZenQCore is the single framework kernel.
// Everything else is a named module registered here.
//
// API surface:
//   ZenQCore.register(name, factory) → registers a module (chainable)
//   ZenQCore.mount(name)             → runs factory(), stores instance
//   ZenQCore.mountAll()              → mounts all registered modules
//   ZenQCore.get(name)               → returns module instance (or null)
//   ZenQCore.list()                  → ['Config','Chat',...]
//   ZenQCore.on(event, handler)      → subscribe, returns unsubscribe fn
//   ZenQCore.once(event, handler)    → subscribe for one fire only
//   ZenQCore.off(event, handler)     → unsubscribe
//   ZenQCore.emit(event, data)       → broadcast to all subscribers
//
// Short-hand alias:
//   ZenQBus.on / once / off / emit   → same as ZenQCore event methods
// ════════════════════════════════════════════════════
const ZenQCore = (() => {
  /** @type {Map<string, {factory:Function, instance:*, mounted:boolean}>} */
  const _modules = new Map();
  /** @type {Map<string, Function[]>} */
  const _events  = new Map();

  const core = {
    // ── Module Registry ──────────────────────────────
    /**
     * Register a named module.
     * The factory is called lazily by mount() — not here.
     * Returns `this` for chaining.
     */
    register(name, factory) {
      if (_modules.has(name)) {
        console.warn(`[ZenQCore] Module "${name}" already registered — skipping`);
        return this;
      }
      if (typeof factory !== 'function') {
        console.error(`[ZenQCore] register("${name}"): factory must be a function`);
        return this;
      }
      _modules.set(name, { factory, instance: null, mounted: false });
      return this; // chainable
    },

    /**
     * Mount (initialise) a single registered module.
     * Calls factory(), stores the result, emits 'core:mounted'.
     */
    mount(name) {
      const mod = _modules.get(name);
      if (!mod) { console.warn(`[ZenQCore] mount("${name}"): module not registered`); return null; }
      if (mod.mounted) return mod.instance;
      try {
        mod.instance = mod.factory();
        mod.mounted  = true;
        this.emit('core:mounted', { name });
      } catch (e) {
        console.error(`[ZenQCore] Mount error in "${name}":`, e);
      }
      return mod.instance;
    },

    /** Mount every registered module in registration order. */
    mountAll() {
      _modules.forEach((_, name) => this.mount(name));
      this.emit('core:ready', { modules: [..._modules.keys()] });
    },

    /** Return a mounted module's public API, or null if not found / not mounted. */
    get(name) { return _modules.get(name)?.instance ?? null; },

    /** Return list of all registered module names. */
    list() { return [..._modules.keys()]; },

    // ── Event Bus ────────────────────────────────────
    /**
     * Subscribe to an event.
     * Returns an unsubscribe function: const off = ZenQCore.on('x', h); off();
     */
    on(event, handler) {
      if (!_events.has(event)) _events.set(event, []);
      _events.get(event).push(handler);
      return () => this.off(event, handler);
    },

    /**
     * Subscribe for exactly one firing.
     */
    once(event, handler) {
      const wrap = data => { this.off(event, wrap); handler(data); };
      return this.on(event, wrap);
    },

    /** Remove a specific handler. */
    off(event, handler) {
      if (!_events.has(event)) return;
      _events.set(event, _events.get(event).filter(h => h !== handler));
    },

    /**
     * Broadcast an event to all subscribers.
     * Errors in handlers are caught and logged so they never interrupt the caller.
     */
    emit(event, data) {
      const handlers = _events.get(event);
      if (!handlers || !handlers.length) return;
      handlers.forEach(h => {
        try { h(data); }
        catch (e) { console.error(`[ZenQCore] Handler error for "${event}":`, e); }
      });
    },
  };

  return core;
})();

/* ═══════════════════════════════════════════
   SECTION: FRAMEWORK CORE
   ZenQLogger · ZenQBus · ZenQCore
═══════════════════════════════════════════ */
// ── Short-hand alias: ZenQBus.on / emit / off / once ─────────────────
const ZenQBus = {
  on:   (...a) => ZenQCore.on(...a),
  once: (...a) => ZenQCore.once(...a),
  off:  (...a) => ZenQCore.off(...a),
  emit: (...a) => ZenQCore.emit(...a),
};
// ── END AURA FRAMEWORK CORE ──────────────────────────────────────────

// ════════════════════════════════════════════════════
// ██████████████████████████████████████████████████
//  AURA AI v25 — ARCHITECTURE IMPROVEMENTS
//  1.  window.APP_CONFIG   — env-aware config (no hardcoded URLs)
//  2.  ApiService          — centralised fetch layer
//  3.  safeRequest         — retry + timeout wrapper
//  4.  ResponseCache       — LRU response cache (bonus)
//  5.  Modules namespace   — Chat / UI / API / State
//  6.  sanitize()          — input sanitisation helper
//  7.  MAX_CHATS cap       — memory optimisation
//  8.  Offline detection   — robust network event handler
//  9.  Debounce input      — already in helpers, wired here
//  10. Request timeout     — AbortController + timeout
// ██████████████████████████████████████████████████
// ════════════════════════════════════════════════════

/* ═══════════════════════════════════════════
   SECTION: CONFIG
   APP_CONFIG · AURA_CONFIG · DEBUG
═══════════════════════════════════════════ */
// ── Global APP_CONFIG — single source of truth ─────────────
// Deployments override this by injecting a <script> before this file:
//   window.APP_CONFIG = { API_BASE_URL: 'https://api.myapp.com' };
//   This is the ONLY supported way to configure the backend URL (no runtime Settings UI).
// The app NEVER hardcodes a production URL — everything flows from this object.
window.APP_CONFIG = window.APP_CONFIG || (() => {
  const isLocal = (
    location.hostname === 'localhost' ||
    location.hostname === '127.0.0.1' ||
    location.hostname === '[::1]'
  );
  return {
    // IMPROVEMENT 3: Auto-switch between local dev and production via reverse proxy
    // In production your reverse proxy (Nginx / Caddy / Vercel) routes /api → backend.
    // No backend URL is ever exposed to the client in production.
    API_BASE_URL: isLocal ? 'http://localhost:3000/api' : '/api',

    // Feature flags (override from deployment config as needed)
    ENABLE_CACHE:      true,    // ResponseCache — cache identical prompts
    CACHE_TTL_MS:      60000,   // 60 s cache TTL
    REQUEST_TIMEOUT_MS: 30000,  // 30 s per request before auto-abort
    MAX_RETRIES:       2,       // safeRequest retry count
    MAX_CHATS:         50,      // IMPROVEMENT 7: max stored chats (memory cap)
    MAX_MSGS_PER_CHAT: 100,     // max messages kept per chat
    DEBUG: isLocal || new URLSearchParams(location.search).get('debug') === '1',
  };
})();

// ── IMPROVEMENT 6 + BUG FIX [v26]: Centralized sanitisation helpers ──────────────
// sanitize()       — DOMParser-based sanitization for user input text.
//                    Preserves plain text exactly, strips only genuine HTML.
//                    Belt-and-suspenders with parseMarkdown() which HTML-escapes all.
// sanitizeHTML()   — DOMParser-based sanitization for HTML fragments (rich content).
//                    Strips script tags, event handlers, javascript: URIs safely.
// sanitizeStrict() — whitelist of printable chars only (for display names, labels).
//
// Security approach: DOMParser correctly handles encoded payloads, nested tags,
// and Unicode tricks that regex-based sanitizers miss. Parsing via a detached
// document prevents any execution side-effects.
// ──────────────────────────────────────────────────────────────────────────────

// ── DOMParser instance (reused — one per session) ─────────────────────────────
const _domParser = (function() {
  try { return new DOMParser(); } catch(e) { return null; }
})();

// sanitize() — input sanitization for plain user message text
// Preserves all valid text content; strips only genuine injection patterns.
const sanitize = (input) => {
  if (typeof input !== 'string') return '';
  let s = input;
  // Strip null bytes
  s = s.replace(/\0/g, '');
  // Strip javascript: and data: URIs (case-insensitive, whitespace-tolerant)
  s = s.replace(/javascript\s*:/gi, '');
  s = s.replace(/data\s*:\s*text\/html/gi, '');
  // Strip on* event handler patterns
  s = s.replace(/\bon\w+\s*=/gi, '');
  return s.trim();
};

// sanitizeHTML() — DOMParser-based HTML fragment sanitizer
// Use for any content that will be set via innerHTML.
// Returns a safe HTML string with dangerous nodes/attrs removed.
const sanitizeHTML = (html) => {
  if (typeof html !== 'string') return '';
  if (!_domParser) {
    // Fallback: escape everything if DOMParser unavailable
    return html
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#x27;');
  }

  try {
    // Parse as HTML in a detached document — no script execution
    const doc = _domParser.parseFromString(html, 'text/html');

    // Remove dangerous elements
    const DANGEROUS_TAGS = ['script','style','iframe','object','embed','form',
                             'input','button','link','meta','base','svg','math'];
    DANGEROUS_TAGS.forEach(tag => {
      doc.querySelectorAll(tag).forEach(el => el.remove());
    });

    // Remove dangerous attributes from all elements
    const DANGEROUS_ATTRS = ['onerror','onload','onclick','onmouseover','onfocus',
                              'onblur','onchange','onsubmit','onkeydown','onkeyup',
                              'onkeypress','onmousedown','onmouseup','ontouchstart',
                              'ontouchend','ondragstart','onanimationstart','style'];
    doc.querySelectorAll('*').forEach(el => {
      DANGEROUS_ATTRS.forEach(attr => el.removeAttribute(attr));
      // Strip javascript: and data: hrefs/srcs
      ['href','src','action','data'].forEach(attr => {
        const val = el.getAttribute(attr);
        if (val && /^(javascript|data)\s*:/i.test(val.trim())) {
          el.removeAttribute(attr);
        }
      });
    });

    return doc.body ? doc.body.innerHTML : '';
  } catch(e) {
    // If parsing fails, fall back to full escaping
    return html
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }
};

const sanitizeStrict = (input) => {
  if (typeof input !== 'string') return '';
  // Whitelist: printable ASCII + common Unicode letters/spaces. Strips everything else.
  return input.replace(/[^\p{L}\p{N}\p{Z}\p{P}\p{S}]/gu, '').replace(/\0/g, '').trim();
};
// Alias used by IMPROVEMENT 10 ApiService body sanitisation
const sanitizeKey = (k) => encodeURIComponent(String(k).slice(0, 200));


// ── IMPROVEMENT 4 (BONUS): LRU Response Cache ─────────────────────────────────
// Caches identical {model+prompt} pairs for CACHE_TTL_MS to avoid duplicate backend hits.
// Cache is in-memory only — cleared on page refresh (no localStorage to avoid stale AI replies).
const ResponseCache = (() => {
  const MAX_ENTRIES = 40; // keep memory footprint tiny
  /** @type {Map<string, {value:string, ts:number}>} */
  const _store = new Map();

  function _makeKey(model, userText, sysPrompt, history) {
    // BUG FIX [v28]: Key must include conversation history, not just the latest message.
    // Without history, "What else?" in chat A and "What else?" in chat B would share a
    // cached response, which is semantically wrong — the reply depends on all prior turns.
    // Use a lightweight fingerprint: history length + last 2 role+content snippets.
    const historyFingerprint = Array.isArray(history) && history.length
      ? history.length + ':' + history.slice(-2).map(m => m.role[0] + m.content.slice(0, 20)).join('|')
      : '0';
    return `${model}||${(sysPrompt || '').slice(0, 40)}||${historyFingerprint}||${userText.slice(0, 200)}`;
  }

  return {
    /** Store a completed AI reply. */
    set(model, userText, sysPrompt, value, history) {
      if (!window.APP_CONFIG?.ENABLE_CACHE) return;
      const key = _makeKey(model, userText, sysPrompt, history);
      // LRU eviction: delete oldest when full
      if (_store.size >= MAX_ENTRIES) {
        _store.delete(_store.keys().next().value);
      }
      _store.set(key, { value, ts: Date.now() });
    },
    /** Retrieve a cached reply if still fresh, else null. */
    get(model, userText, sysPrompt, history) {
      if (!window.APP_CONFIG?.ENABLE_CACHE) return null;
      const key = _makeKey(model, userText, sysPrompt, history);
      const entry = _store.get(key);
      if (!entry) return null;
      if (Date.now() - entry.ts > (window.APP_CONFIG?.CACHE_TTL_MS ?? 60000)) {
        _store.delete(key); return null;
      }
      return entry.value;
    },
    /** Manually bust entire cache (e.g. on model switch). */
    clear() { _store.clear(); },
    size() { return _store.size; },
  };
})();


// ── IMPROVEMENT 5 (BONUS): safeRequest — retry + per-request timeout ──────────
// Wraps any async function with:
//   • Configurable retries (default: APP_CONFIG.MAX_RETRIES)
//   • Per-attempt timeout via AbortController (APP_CONFIG.REQUEST_TIMEOUT_MS)
//   • Exponential back-off + jitter between retries (prevents thundering-herd)
//   • Throws on final failure so callers can show UI errors
// PRODUCTION FIX [v29]: Added ±25% jitter to backoff delay. Without jitter, multiple
// concurrent requests all retry at the same interval, creating a thundering-herd
// that overwhelms the backend and causes all retries to fail together.
async function safeRequest(fn, retries = window.APP_CONFIG.MAX_RETRIES, _attempt = 0) {
  const timeoutMs = window.APP_CONFIG.REQUEST_TIMEOUT_MS;
  const controller = new AbortController();
  let _didTimeout = false;
  const timerId = setTimeout(() => { _didTimeout = true; controller.abort(); }, timeoutMs);
  try {
    const result = await fn(controller.signal);
    clearTimeout(timerId);
    return result;
  } catch (err) {
    clearTimeout(timerId);
    // BUG FIX [v28]: If the AbortError came from our timeout, surface a clear message.
    // If it came from a MANUAL abort (user stopped generation), never retry — the user
    // explicitly cancelled. Re-throwing immediately lets the caller handle it cleanly.
    if (err.name === 'AbortError') {
      if (_didTimeout) {
        ZenQLogger.warn('safeRequest', `Request timed out after ${timeoutMs}ms (attempt ${_attempt + 1})`);
        throw new Error(`Request timed out after ${timeoutMs}ms`);
      }
      // Manual abort (user-initiated or test) — do not retry, propagate immediately
      throw err;
    }
    // Never retry 4xx client errors — they won't self-heal
    if (err.status >= 400 && err.status < 500) {
      ZenQLogger.warn('safeRequest', `Non-retriable HTTP ${err.status} — propagating immediately`);
      throw err;
    }
    if (retries > 0) {
      // Jitter: add ±25% randomness to base backoff to spread retry storms
      const baseBackoff = Math.min(200 * Math.pow(2, _attempt), 3000); // cap at 3s
      const jitter      = baseBackoff * 0.25 * (Math.random() * 2 - 1); // ±25%
      const backoff     = Math.max(100, Math.round(baseBackoff + jitter));
      ZenQLogger.warn('safeRequest', `Retrying in ${backoff}ms — attempts left: ${retries}`, err.message);
      await new Promise(r => setTimeout(r, backoff));
      return safeRequest(fn, retries - 1, _attempt + 1);
    }
    throw err; // exhausted retries — propagate to caller
  }
}


/* ═══════════════════════════════════════════
   SECTION: API
   apiRequest() · ApiService · fetchWithRetry
   callBackendStreaming · OfflineDetector
═══════════════════════════════════════════ */
// ── ApiService — centralised, authenticated fetch layer ─────────
// ALL non-streaming HTTP calls go through ApiService.request().
// Streaming (SSE) has its own path in callBackendStreaming but also
// uses ApiService.buildHeaders() so auth is consistent.
//
// Features:
//   • Auto-injects Authorization: Bearer <firebase-token>
//   • Reads base URL from window.APP_CONFIG.API_BASE_URL (never hardcoded)
//   • Normalises error responses into a single Error shape
//   • Logs every request/response in debug mode via ZenQLogger
//   • Supports request body sanitisation (strips null bytes)
const ApiService = (() => {
  /** Build auth + content headers, injecting the Firebase ID token if available. */
  async function buildHeaders(extra = {}) {
    const headers = {
      'Content-Type': 'application/json',
      'Accept': 'application/json, text/event-stream',
      'X-ZenQ-Version': 'v32',
      ...extra,
    };
    // Inject Firebase ID token — getIdToken() is defined later in the auth section.
    // We wrap in try/catch so a missing/expired token never blocks a request.
    try {
      const token = (typeof getIdToken === 'function') ? await getIdToken() : null;
      if (token) headers['Authorization'] = 'Bearer ' + token;
    } catch (_) { /* guest mode — no token */ }
    return headers;
  }

  // OPT: Request deduplication — prevents concurrent identical requests (e.g. health checks)
  // Uses a Map<dedupKey, Promise> so all callers share the same in-flight response.
  const _inflightMap = new Map();

  /**
   * Core fetch wrapper used for all non-streaming API calls.
   *
   * @param {string} endpoint  — relative path, e.g. '/health' or '/chat'
   * @param {object} options   — { method, body, token, signal, _noRetry }
   * @returns {Promise<any>}   — parsed JSON response body
   */
  async function request(endpoint, options = {}) {
    const base = (window.APP_CONFIG.API_BASE_URL || '/api').replace(/\/$/, '');
    const url  = base + endpoint;
    const method = options.method || 'GET';

    if (window.APP_CONFIG.DEBUG) {
      ZenQLogger.debug('ApiService', `→ ${method} ${url}`,
        options.body ? { bodyKeys: Object.keys(options.body) } : '');
    }

    // OPT: Deduplicate GET requests — if an identical request is already in-flight,
    // return the same Promise rather than firing a second fetch.
    if (method === 'GET' && !options._noDedup) {
      const dedupKey = method + ':' + url;
      if (_inflightMap.has(dedupKey)) {
        ZenQLogger.debug('ApiService', `Dedup hit for ${dedupKey}`);
        return _inflightMap.get(dedupKey);
      }
      const promise = _doRequest(url, method, options);
      _inflightMap.set(dedupKey, promise);
      promise.finally(() => _inflightMap.delete(dedupKey));
      return promise;
    }

    return _doRequest(url, method, options);
  }

  async function _doRequest(url, method, options = {}) {
    const headers = await buildHeaders(
      options.token ? { Authorization: `Bearer ${options.token}` } : {}
    );

    let body = undefined;
    if (options.body) {
      // IMPROVEMENT 6: strip null bytes from all string fields before sending
      const sanitizedBody = JSON.parse(JSON.stringify(options.body, (_, v) =>
        typeof v === 'string' ? v.replace(/\0/g, '') : v
      ));
      body = JSON.stringify(sanitizedBody);
    }

    const doFetch = async (signal) => {
      const res = await fetch(url, {
        method,
        headers,
        body,
        signal: options.signal || signal,
      });

      if (window.APP_CONFIG.DEBUG) {
        ZenQLogger.debug('ApiService', `← ${res.status} ${url}`);
      }

      if (!res.ok) {
        let errMsg = `HTTP ${res.status}`;
        try { const d = await res.clone().json(); errMsg = d.error || d.message || errMsg; } catch(_) {}
        if (res.status === 401) errMsg = 'Unauthorized — please sign in again.';
        else if (res.status === 429) errMsg = 'Rate limit reached — please wait a moment.';
        else if (res.status === 503) errMsg = 'Service temporarily unavailable.';
        const err = new Error(errMsg);
        err.status = res.status;
        throw err;
      }
      return res.json();
    };

    // Use safeRequest for automatic retry + timeout (unless caller opts out)
    if (options._noRetry) {
      return doFetch(options.signal);
    }
    return safeRequest(doFetch);
  }

  /**
   * Health-check shorthand — returns true if backend is reachable.
   * v32: delegates to the unified apiRequest() wrapper.
   */
  async function health() {
    try {
      await apiRequest('/health', { method: 'GET' });
      return true;
    } catch (_) { return false; }
  }

  return { request, buildHeaders, health };
})();


// ── IMPROVEMENT 8: Robust offline detection ───────────────────────────────────
// Shows/hides the existing #offline-banner and prevents API calls when offline.
// The banner element already exists in the HTML (added in v17).
// ════════════════════════════════════════════════════════
// v32: OfflineDetector — online/offline + active reconnect polling
// ════════════════════════════════════════════════════════
const OfflineDetector = (() => {
  let _isOnline   = navigator.onLine;
  let _pollHandle = null;
  const POLL_INTERVAL_MS = 8000; // poll every 8s while offline

  function _update(online) {
    const wasOnline = _isOnline;
    _isOnline = online;
    const banner = document.getElementById('offline-banner');
    if (banner) banner.classList.toggle('on', !online);

    if (!online && wasOnline) {
      ZenQLogger.warn('Network', 'Connection lost — AI requests blocked');
      if (typeof toast === 'function') toast('📡 You are offline — AI unavailable', 'warn', 5000);
      _startPolling();
    } else if (online && !wasOnline) {
      ZenQLogger.info('Network', 'Connection restored');
      if (typeof toast === 'function') toast('✅ Back online', 'success', 2500);
      _stopPolling();
    }
  }

  /** Active reconnect polling — pings /favicon.ico (tiny, uncached) */
  function _startPolling() {
    if (_pollHandle) return;
    _pollHandle = setInterval(async () => {
      try {
        const res = await fetch('/favicon.ico?_=' + Date.now(), {
          method: 'HEAD', cache: 'no-store', signal: AbortSignal.timeout(4000),
        });
        if (res.ok || res.status === 304) _update(true);
      } catch (_) { /* still offline */ }
    }, POLL_INTERVAL_MS);
  }

  function _stopPolling() {
    if (_pollHandle) { clearInterval(_pollHandle); _pollHandle = null; }
  }

  window.addEventListener('online',  () => _update(true),  { passive: true });
  window.addEventListener('offline', () => _update(false), { passive: true });

  // Start polling now if already offline at page load
  if (!navigator.onLine) _startPolling();

  return {
    isOnline: () => _isOnline,
    /**
     * Returns true and shows toast if offline.
     * Usage: if (OfflineDetector.guard()) return;
     */
    guard() {
      if (!_isOnline) {
        if (typeof toast === 'function') toast('⚠️ No internet connection — AI unavailable', 'warn', 3000);
        return true;
      }
      return false;
    },
  };
})();


// ── IndexedDB-primary cleanup — replaces old localStorage MAX_CHATS cap ──────
// IDB has no meaningful size limit; cleanup is time/count based, not quota-based.
// Runs automatically in background on init and periodically during session.
function enforceMaxChats() {
  // No-op for in-memory APP.chats — IDB cleanup handles persistence
  // Legacy callers get a silent no-op; real cleanup runs via ZenQDB.runCleanup()
}

// Schedule periodic IDB cleanup (runs once per session, non-blocking)
let _cleanupScheduled = false;
function scheduleDBCleanup() {
  if (_cleanupScheduled) return;
  _cleanupScheduled = true;
  setTimeout(async () => {
    try {
      const removed = await ZenQDB.runCleanup({
        maxChats: window.APP_CONFIG?.MAX_CHATS || 1000,
        maxAgeDays: 90,
      });
      if (removed > 0) {
        // Sync in-memory APP.chats with IDB after cleanup
        const remaining = await ZenQDB.loadAllChats();
        const remainingIds = new Set(remaining.map(c => c.id));
        Object.keys(APP.chats).forEach(id => {
          if (!remainingIds.has(id) && id !== APP.activeChatId) delete APP.chats[id];
        });
        renderChatList();
      }
    } catch(e) { ZenQLogger.warn('Cleanup', 'DB cleanup error:', e.message); }
  }, 8000); // 8s after boot — avoid startup jank
}


// ── IMPROVEMENT 5: Modules namespace — Chat / UI / API / State ────────────────
// A lightweight façade over the existing functions so every domain has a single
// import-style access point. External scripts / debug console can call:
//   Modules.Chat.send('Hello')
//   Modules.UI.toast('Done', 'success')
//   Modules.API.health().then(ok => console.log('backend alive:', ok))
//   Modules.State.get()
//
// Functions are wired lazily (via getters) so they always point at the live
// closure-bound versions even if those functions are defined later in the file.
const Modules = {};

Modules.State = {
  get()          { return APP; },
  getChat()      { return typeof getChat      === 'function' ? getChat()      : null; },
  getAuthUser()  { return typeof getAuthUser  === 'function' ? getAuthUser()  : null; },
  getPlan()      { return typeof getPlan      === 'function' ? getPlan()      : null; },
  isOnline()     { return OfflineDetector.isOnline(); },
};

Modules.Chat = {
  send(text)          { if (typeof sendMessage    === 'function') sendMessage(text); },
  create(title, cat)  { if (typeof createChat     === 'function') return createChat(title, cat); },
  delete(id)          { if (typeof deleteChat     === 'function') deleteChat(id); },
  switch(id)          { if (typeof switchChat     === 'function') switchChat(id); },
  stop()              { if (typeof stopGeneration === 'function') stopGeneration(); else { APP.stopRequested = true; if (APP._abortController) APP._abortController.abort(); } },
  clearAll()          { 
    const ids = Object.keys(APP.chats);
    ids.forEach(k => delete APP.chats[k]); 
    APP.activeChatId = null; 
    if (typeof save === 'function') save();
    // Async IDB clear — fire and forget
    (async () => {
      try {
        for (const id of ids) {
          await ZenQDB.deleteMessages(id);
          await ZenQDB.deleteChatRecord(id);
        }
        await ZenQDB.kvSet('zenq_active', '');
      } catch(_) {}
    })();
  },
  cache:              ResponseCache,
};

Modules.UI = {
  toast(msg, type, dur)    { if (typeof toast        === 'function') toast(msg, type, dur); },
  openSettings(tab)        { if (typeof openSettings === 'function') openSettings(tab); },
  closeSettings()          { if (typeof closeSettings=== 'function') closeSettings(); },
  showWelcome()            { if (typeof showWelcome  === 'function') showWelcome(); },
  scrollBottom(f)          { if (typeof scrollBottom === 'function') scrollBottom(f); },
  applyTheme(t)            { if (typeof applyTheme   === 'function') applyTheme(t); },
};

Modules.API = {
  /** Centralised authenticated request (non-streaming). */
  request: (endpoint, opts) => ApiService.request(endpoint, opts),
  /** Quick backend health check. */
  health:  ()               => ApiService.health(),
  /** safeRequest retry wrapper for arbitrary async fns. */
  safe:    (fn, retries)    => safeRequest(fn, retries),
  /** Current resolved backend base URL. */
  baseUrl: ()               => (window.APP_CONFIG.API_BASE_URL || '/api'),
};

// Expose on window for debug console access
if (window.APP_CONFIG.DEBUG) {
  window.Modules       = Modules;
  window.ApiService    = ApiService;
  window.ResponseCache = ResponseCache;
  window.safeRequest   = safeRequest;
  console.log('[ZenQ v25] Modules ready:', Object.keys(Modules));
}

