// ── AI Provider Configuration ─────────────────────────────────────────
// All AI calls route through the backend — provider keys are server-side only.
// IMPROVEMENT 1 & 3: AURA_CONFIG now reads from window.APP_CONFIG — no hardcoded URL.
// Priority: 1) User-saved URL from localStorage (Settings → Backend URL)
//           2) APP_CONFIG.API_BASE_URL (set by deployment script)
//           3) Auto-detected local/production fallback
// v32: AURA_CONFIG — backend URL resolved from APP_CONFIG or user-saved value.
// Set window.APP_CONFIG.API_BASE_URL server-side before this script loads.
const AURA_CONFIG = (() => {
  // FIX: Bekend URL connect logic — read user-saved backend URL first.
  // Previously only APP_CONFIG was checked; user-configured URLs were silently ignored.
  let userSavedUrl = '';
  try { userSavedUrl = (localStorage.getItem('zenq_backend_url') || '').trim(); } catch(_) {}

  const configBase = userSavedUrl
    || (window.APP_CONFIG?.API_BASE_URL || '/api');

  const BASE = configBase
    .replace(/\/chat$/, '').replace(/\/api$/, '').replace(/\/$/, '');

  // FIX: disable fakeAI when a real backend URL has been saved/configured.
  // Previously fakeAI was always true, so even after saving a real backend URL
  // the app kept streaming fake replies with no error or indication.
  const hasRealBackend = !!(
    userSavedUrl ||
    (window.APP_CONFIG?.API_BASE_URL && window.APP_CONFIG.API_BASE_URL !== '/api')
  );

  return {
    backendUrl: BASE + '/api/chat',
    streamUrl:  BASE + '/api/stream',
    healthUrl:  BASE + '/api/health',
    version:    'v32',
    // FAKE AI: automatically disabled when a real backend URL is configured
    fakeAI:     !hasRealBackend,
  };
})();

// ── v32: DEBUG shorthand — replaces scattered DEBUG_MODE references ──────────
const DEBUG = !!(window.APP_CONFIG?.DEBUG);

// ════════════════════════════════════════════════════════════════
// v32: apiRequest() — CLEAN UNIFIED API WRAPPER (required pattern)
//
// All non-streaming API calls MUST use this wrapper:
//   const data = await apiRequest('/health');
//   const result = await apiRequest('/chat', { method:'POST', body:{...} });
//
// Features:
//   • Reads base URL from window.APP_CONFIG.API_BASE_URL (never hardcoded)
//   • Throws a typed ApiError with .status for callers to handle
//   • Auto-injects Firebase auth token when available
//   • Per-request AbortController timeout (APP_CONFIG.REQUEST_TIMEOUT_MS)
//   • User-friendly error mapping (401→sign-in, 429→rate-limit, 5xx→server)
//   • Offline guard — throws immediately when navigator.onLine is false
// ════════════════════════════════════════════════════════════════
class ApiError extends Error {
  constructor(message, status = 0, retryable = false) {
    super(message);
    this.name   = 'ApiError';
    this.status = status;
    this.retryable = retryable;
  }
}

async function apiRequest(path, options = {}) {
  const base = window.APP_CONFIG?.API_BASE_URL;
  if (!base) throw new ApiError('Backend URL not configured — set window.APP_CONFIG.API_BASE_URL', 0, false);

  // Offline guard — fail fast before attempting network
  if (!navigator.onLine) throw new ApiError('No internet connection', 0, true);

  const url    = base.replace(/\/$/, '') + path;
  const method = options.method || 'GET';

  // Build headers — inject Firebase token when available
  const headers = { 'Content-Type': 'application/json', ...(options.headers || {}) };
  try {
    const token = (typeof getIdToken === 'function') ? await getIdToken() : null;
    if (token) headers['Authorization'] = 'Bearer ' + token;
  } catch (_) { /* guest mode */ }

  // Per-request timeout via AbortController
  const timeoutMs = window.APP_CONFIG?.REQUEST_TIMEOUT_MS ?? 30000;
  const ctrl = new AbortController();
  const timerId = setTimeout(() => ctrl.abort(), timeoutMs);
  const signal = options.signal
    ? _mergeSignals(options.signal, ctrl.signal)
    : ctrl.signal;

  if (DEBUG) console.log(`[apiRequest] → ${method} ${url}`);

  let res;
  try {
    res = await fetch(url, {
      method,
      headers,
      signal,
      ...(options.body !== undefined && { body: JSON.stringify(options.body) }),
    });
  } catch (err) {
    clearTimeout(timerId);
    if (err.name === 'AbortError') throw new ApiError('Request timed out or cancelled', 0, true);
    throw new ApiError('Network error — ' + err.message, 0, true);
  }
  clearTimeout(timerId);

  if (DEBUG) console.log(`[apiRequest] ← ${res.status} ${url}`);

  if (!res.ok) {
    let msg = `Server error (${res.status})`;
    try { const d = await res.clone().json(); msg = d.error || d.message || msg; } catch (_) {}
    if (res.status === 401 || res.status === 403)
      msg = 'Session expired — please sign in again.';
    else if (res.status === 429)
      msg = 'Rate limit reached — please wait a moment.';
    else if (res.status === 503)
      msg = 'Service unavailable — server may be starting up.';
    else if (res.status >= 500)
      msg = `Server error (${res.status}) — try again in a moment.`;
    throw new ApiError(msg, res.status, res.status >= 500 || res.status === 429);
  }

  const ct = res.headers.get('content-type') || '';
  if (ct.includes('application/json')) return res.json();
  return res; // return raw Response for SSE/text streams
}

/** Merge two AbortSignals — aborts when either fires. */
function _mergeSignals(a, b) {
  const ctrl = new AbortController();
  const abort = () => ctrl.abort();
  a.addEventListener('abort', abort, { once: true });
  b.addEventListener('abort', abort, { once: true });
  return ctrl.signal;
}

