/* ═══════════════════════════════════════════
   SECTION: UTILITIES
   $() · on() · esc() · debounce() · throttle()
   genId() · clamp() · fmtTime()
═══════════════════════════════════════════ */
// ─── Helpers ─────────────────────────────────────
const $ = id => document.getElementById(id);
const qs = (sel, ctx=document) => ctx.querySelector(sel);
const qsa = (sel, ctx=document) => [...ctx.querySelectorAll(sel)];

// FIX: Safe event binding — prevents "Cannot read properties of null (reading 'addEventListener')"
// All direct $('id').addEventListener calls are now routed through this helper.
// PRODUCTION FIX [v29]: Duplicate listener guard via WeakMap registry.
// The old on() silently allowed the same fn+event to be registered multiple times on
// the same element, causing handlers to fire 2× or 3× after re-renders or hot paths.
// WeakMap<Element, Map<event, Set<fn>>> costs no memory leak because keys are weak.
const _listenerRegistry = new WeakMap();
function on(id, event, fn, opts) {
  const el = typeof id === 'string' ? $(id) : id;
  if (!el) {
    if (typeof id === 'string') console.warn(`[ZenQ] on(): element #${id} not found`);
    return;
  }
  // Build or retrieve the registry for this element
  if (!_listenerRegistry.has(el)) _listenerRegistry.set(el, new Map());
  const evMap = _listenerRegistry.get(el);
  if (!evMap.has(event)) evMap.set(event, new Set());
  const fnSet = evMap.get(event);
  // Only register if this exact function reference has not been added before
  if (fnSet.has(fn)) return; // already registered — skip silently
  fnSet.add(fn);
  el.addEventListener(event, fn, opts);
}
// Safe attribute setter
function attr(id, name, val) {
  const el = typeof id === 'string' ? $(id) : id;
  if (el) el.setAttribute(name, val);
}
function esc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;') }
// PRODUCTION FIX [v29]: Use crypto.randomUUID() for collision-free IDs.
// Math.random() has ~1-in-2^52 collision risk over large datasets; UUID v4 is 122 bits.
// Fallback: timestamp + two independent random bases ensures uniqueness even without SubtleCrypto.
function genId() {
  try {
    if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
      return 'id_' + crypto.randomUUID().replace(/-/g,'');
    }
  } catch(_) {}
  // Fallback: high-entropy manual UUID-ish string
  return '_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2,9) + Math.random().toString(36).slice(2,6);
}
function clamp(v,min,max){ return Math.max(min,Math.min(max,v)) }
// PRODUCTION FIX [v29]: Enhanced debounce with:
//   (a) .cancel() method — callers can flush/cancel pending invocations on cleanup
//       (e.g. beforeunload can call debouncedRenderChatList.cancel() to prevent
//        a post-unload DOM write that causes "cannot set properties of null")
//   (b) leading-edge option — fires immediately on first call, then silences for `ms`.
//       Useful for UI feedback buttons where you want instant response + rate limiting.
function debounce(fn, ms, { leading = false } = {}) {
  let t;
  let _called = false;
  function debounced(...a) {
    if (leading && !_called) { _called = true; fn(...a); }
    clearTimeout(t);
    t = setTimeout(() => { _called = false; if (!leading) fn(...a); }, ms);
  }
  debounced.cancel = () => { clearTimeout(t); _called = false; };
  return debounced;
}

// ── v32: throttle() — limit fn calls to at most once per `ms` ──────────────
// Unlike debounce, throttle guarantees the fn fires during the interval,
// not just at the end. Ideal for scroll handlers and resize events.
function throttle(fn, ms) {
  let last = 0;
  let rafId = null;
  return function(...args) {
    const now = Date.now();
    if (now - last >= ms) {
      last = now;
      fn.apply(this, args);
    } else if (!rafId) {
      // Queue trailing call for after interval via rAF (GPU-friendly)
      rafId = requestAnimationFrame(() => {
        rafId = null;
        if (Date.now() - last >= ms) { last = Date.now(); fn.apply(this, args); }
      });
    }
  };
}

// ── v20: Public security/utility aliases ────────────────────────────────
// escapeHTML: always use this before injecting any user content into innerHTML
const escapeHTML = esc;
// generateId: collision-resistant ID with ms timestamp + 16-bit entropy
// PRODUCTION FIX [v29]: generateId() was a second ID generator with weaker entropy
// (Date.now + Math.random hex, no UUID). Replaced with alias to genId() so all
// IDs come from one source — prevents mixed formats across old/new code paths.
const generateId = genId;
// loadChats: legacy helper — returns in-memory APP.chats (IDB is source of truth after init)
function loadChats() {
  // Post-init: return in-memory cache (already loaded from IDB by loadAsync)
  if (APP && Object.keys(APP.chats).length) return APP.chats;
  // Pre-init fallback: try localStorage (will be migrated to IDB on first loadAsync())
  try { return JSON.parse(localStorage.getItem('aura_chats')) || {}; } catch(_) { return {}; }
}

