function getAIResponse(msg) {
  const m = msg.toLowerCase();
  // Tamil mode — respond in Tamil
  if (APP.aiMode === 'tamil' || (APP._aiLangPrefix && APP._aiLangPrefix.includes('Tamil'))) {
    // BUG FIX [v28]: Use \b word boundary — "hi|" with trailing space missed "hi!", "hi.", "hi?"
    if (/\b(hello|hi|hey|வணக்கம்|ஹலோ)\b/i.test(m))
      return `வணக்கம்! நான் ஆரா, உங்கள் AI உதவியாளர். கோடிங், எழுத்து, பகுப்பாய்வு — எதிலும் உதவ தயாராக இருக்கிறேன். இன்று என்ன உதவி வேண்டும்?`;
    if (/code|python|javascript|function|கோட்|நிரல்/i.test(m))
      return `இதோ ஒரு சிறந்த Python தீர்வு:\n\n\`\`\`python\ndef sort_items(items: list, key: str = None, reverse: bool = False) -> list:\n    """பட்டியலை வரிசைப்படுத்துகிறது"""\n    return sorted(items, key=lambda x: x.get(key, x) if isinstance(x, dict) else x, reverse=reverse)\n\`\`\`\n\n**இந்த கோட் சிறந்தது ஏன்:**\n- Type hints உடன் தெளிவாக எழுதப்பட்டுள்ளது\n- dict மற்றும் list இரண்டையும் கையாளுகிறது\n- Non-mutating — அசல் list மாறாது`;
    return `நல்ல கேள்வி! இதை ஆழமாக யோசிக்கலாம்.\n\n**முக்கிய கருத்து:** சிக்கலான பிரச்சினைகளுக்கு எளிய அணுகுமுறையே சிறந்தது.\n\n1. **பிரச்சினையை புரிந்துகொள்ளுங்கள்** — மேற்பரப்பு அறிகுறிகள் அல்ல, மூல காரணத்தை கண்டறியுங்கள்\n2. **தீர்வுகளை பட்டியலிடுங்கள்** — குறைந்தது 5 வழிகள்\n3. **சிறந்ததை தேர்ந்தெடுங்கள்** — எளிமையானது, சக்திவாய்ந்தது\n\nமேலும் விவரமாக கூற விரும்புகிறீர்களா?`;
  }
  // Code Expert mode
  if (APP.aiMode === 'code') {
    // BUG FIX [v28]: word boundary fix for greeting detection
    if (/\b(hello|hi|hey)\b/i.test(m)) return `Hello! I'm ZenQ in **Code Expert** mode 👨‍💻. I'm optimized for programming, debugging, architecture, and code review. What are we building today?`;
    if (/landing page|website|html|css/i.test(m)) return AI_RESPONSES.landing[0];
    return pick(AI_RESPONSES.code);
  }
  // Creative mode
  if (APP.aiMode === 'creative') {
    if (/\b(hello|hi|hey)\b/i.test(m)) return `Hello! I'm ZenQ in **Creative Writer** mode 🎨. Ready to craft stories, scripts, poems, taglines — anything imaginative. What shall we create?`;
    return pick(AI_RESPONSES.general);
  }
  // Analyst mode
  if (APP.aiMode === 'analyst') {
    if (/\b(hello|hi|hey)\b/i.test(m)) return `Hello! I'm ZenQ in **Business Analyst** mode 📊. I'll give you structured, data-driven insights and strategic frameworks. What challenge are we solving?`;
    if (/startup|saas|business idea/i.test(m)) return AI_RESPONSES.startup[0];
    return pick(AI_RESPONSES.general);
  }
  // Default routing
  if (/\b(hello|hi|hey|greetings)\b/i.test(m)) return `Hello! I'm ZenQ, your AI assistant. I'm here to help with code, writing, analysis, brainstorming — you name it. What would you like to explore today?`;
  if (/landing page|website|html|css/i.test(m)) return AI_RESPONSES.landing[0];
  if (/sort|python|typescript|javascript|function|code|algorithm|bug|async|api/i.test(m)) return pick(AI_RESPONSES.code);
  if (/quantum/i.test(m)) return AI_RESPONSES.quantum[0];
  if (/startup|saas|business idea|product idea/i.test(m)) return AI_RESPONSES.startup[0];
  if (/email|cold email|outreach/i.test(m)) return AI_RESPONSES.email[0];
  return pick(AI_RESPONSES.general);
}
function pick(arr){ return arr[Math.floor(Math.random()*arr.length)] }

// ─── Markdown Parser ─────────────────────────────
// SECURITY [v23]: Multi-layer XSS defence:
//   1. HTML-escape ALL input before any regex replacement
//   2. Code block content is pre-escaped so injected tags are inert
//   3. Final sanitization pass strips any residual dangerous patterns
//      (belt-and-suspenders for future regex edge cases)
// FIX: Removed inline onclick - using event delegation instead (security)
// IMPROVED: parseMarkdown — two-phase code-block protection.
// Code blocks are extracted into a placeholder map BEFORE inline transformations
// so that patterns like **bold**, `code`, *italic* inside fenced blocks are never
// matched by the subsequent regexes. This prevents both mis-rendering and the
// theoretical XSS vector of injecting HTML via Markdown patterns inside code blocks.
function parseMarkdown(text) {
  if (!text || typeof text !== 'string') return '<p></p>';

  // ── PHASE 0: Extract code blocks into placeholder map ─────────────
  // Prevents inline-markdown regexes from matching content inside ```...```
  const codeBlocks = {};
  let cbIdx = 0;
  // FIXED: Extract code blocks before HTML-escaping so the regex finds backticks cleanly.
  // Each block is replaced with a unique placeholder: \x02CB_N\x03
  let safe = text.replace(/```(\w*)\n?([\s\S]*?)```/g, (_, lang, code) => {
    const key = `\x02CB_${cbIdx++}\x03`;
    const l = (lang || 'code').replace(/[^a-zA-Z0-9\-_]/g, '').slice(0, 20);
    // HTML-escape the code content for safe injection into <pre><code>
    const escapedCode = code.trim()
      .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
    const lineCount = code.trim().split('\n').length;
    const lineInfo = lineCount > 1
      ? `<span style="color:var(--ink-4);font-size:9.5px;margin-left:6px">${lineCount} lines</span>`
      : '';
    codeBlocks[key] = `<div class="cb"><div class="cb-hdr"><div class="cb-lang-wrap"><span class="cb-dot"></span><span class="cb-dot"></span><span class="cb-dot"></span><span class="cb-lang">${l}</span>${lineInfo}</div><button class="cb-cp" data-action="copy-code"><svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2"></rect><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path></svg> Copy</button></div><pre><code>${escapedCode}</code></pre></div>`;
    return key;
  });

  // ── PHASE 1: HTML-escape the remaining text (non-code) ─────────────
  let h = safe
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
    .replace(/^---$/gm,'<hr>')
    .replace(/^### (.+)$/gm,'<h3>$1</h3>')
    .replace(/^## (.+)$/gm,'<h2>$1</h2>')
    .replace(/^# (.+)$/gm,'<h1>$1</h1>')
    .replace(/\*\*\*(.+?)\*\*\*/g,'<strong><em>$1</em></strong>')
    .replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>')
    .replace(/\*(.+?)\*/g,'<em>$1</em>')
    .replace(/`([^`]+)`/g,'<code>$1</code>')
    .replace(/^&gt; (.+)$/gm,'<blockquote>$1</blockquote>')
    // Table: collect rows, then wrap all in one <table>
    .replace(/^\| (.+) \|$/gm, row => '<tr>'+row.slice(2,-2).split(' | ').map(c=>`<td>${c}</td>`).join('')+'</tr>')
    .replace(/^(\|[-| ]+\|)$/gm,'')
    // FIXED: wrap all consecutive <tr> blocks in a single <table> — old regex wrapped each individually
    .replace(/(<tr>[\s\S]*?<\/tr>)(\n<tr>[\s\S]*?<\/tr>)*/g, m => `<table>${m}</table>`)
    .replace(/^\s*[-*] (.+)$/gm,'<li>$1</li>')
    .replace(/^\s*\d+\. (.+)$/gm,'<li class="oli">$1</li>')
    .replace(/(<li>.*<\/li>\n?)+/g, m => `<ul>${m}</ul>`)
    .replace(/\n\n/g,'</p><p>').replace(/\n/g,'<br>');

  // ── PHASE 2: Restore code blocks (now safe — no further replacements run on them) ──
  Object.keys(codeBlocks).forEach(key => {
    h = h.replace(key, codeBlocks[key]);
  });

  // ── PHASE 3: Final sanitization pass ───────────────────────────────
  // Belt-and-suspenders: strip any residual on* event handlers or
  // javascript: URIs that might have slipped through.
  h = h
    // Strip on* event attributes
    .replace(/(<[a-zA-Z][^>]*?)(\s+on[a-zA-Z]+\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]*))+/gi,
      (m, tag) => tag + '>')
    // Strip javascript: and data: in href/src/action attributes
    .replace(/\s+(href|src|action|formaction)\s*=\s*["']?\s*(javascript:|data:text\/html)/gi,
      ' $1="#"')
    // Strip dangerous tags if somehow injected
    .replace(/<(script|iframe|object|embed|base|form|input|meta|link)(\s[^>]*)?>[\s\S]*?<\/\1>/gi, '')
    .replace(/<(script|iframe|object|embed|base|form|input|meta|link)(\s[^>]*)?\/?\s*>/gi, '');

  return `<p>${h}</p>`;
}

