// ─── Chat CRUD ───────────────────────────────────
function createChat(title='New Chat', category='personal') {
  const id  = genId();
  const now = Date.now();
  APP.chats[id] = { id, title, messages:[], createdAt:now, updatedAt:now, category, pinned:false, archived:false, messageCount:0 };
  APP.activeChatId = id;
  save();
  // Persist metadata to IDB immediately (non-blocking)
  ZenQDB.saveChat({ id, title, createdAt:now, updatedAt:now, category, pinned:false, archived:false, messageCount:0 }).catch(() => {});
  renderChatList(); updateHeader();
  ZenQBus.emit('chat:created', { id, title, category });
  return id;
}
function deleteChat(id) {
  // PRODUCTION FIX [v29]: If deleting the currently-generating chat, abort the
  // in-flight request first. Without this, the SSE stream continues writing to
  // a message that will shortly be removed from APP.chats, wasting bandwidth and
  // triggering "Cannot set properties of undefined" errors in the streaming loop.
  if (id === APP.activeChatId && APP.isGenerating) {
    APP.stopRequested = true;
    if (APP._abortController) { try { APP._abortController.abort(); } catch(_) {} APP._abortController = null; }
    if (APP._streamRafId) { cancelAnimationFrame(APP._streamRafId); APP._streamRafId = null; }
    APP.isGenerating = false;
  }
  delete APP.chats[id];
  if(APP.activeChatId===id){
    const ids = Object.keys(APP.chats);
    APP.activeChatId = ids.length ? ids[ids.length-1] : null;
  }
  // Persist deletion to IDB (messages + metadata) — non-blocking
  ZenQDB.deleteMessages(id).then(() => ZenQDB.deleteChatRecord(id)).catch(() => {});
  save(); renderChatList();
  APP.activeChatId ? renderMessages() : showWelcome();
  ZenQBus.emit('chat:deleted', { id });
}
function switchChat(id) {
  if(APP.activeChatId === id) return;
  APP.activeChatId = id; save();
  // Page transition animation
  const wrap = $('msgs-wrap');
  if(wrap){ wrap.classList.remove('switching'); void wrap.offsetWidth; wrap.classList.add('switching'); setTimeout(()=>wrap.classList.remove('switching'),240); }
  renderChatList(); updateHeader();
  if(isMob()) closeMobSidebar();
  // Load messages from IDB if not yet in memory, then render
  const chat = APP.chats[id];
  if (chat && (!chat.messages || !chat.messages.length) && ZenQDB.db) {
    ZenQDB.loadAllMessages(id).then(msgs => {
      if (APP.activeChatId !== id) return; // user switched away while loading
      if (msgs.length) chat.messages = msgs;
      renderMessages();
      scrollBottom(false);
    }).catch(() => { renderMessages(); });
  } else {
    renderMessages();
  }
  ZenQBus.emit('chat:switched', { id });
}
function getChat(){ return APP.activeChatId ? APP.chats[APP.activeChatId] : null }
function autoCategory(text) {
  // BUG FIX [v28]: Use \b word boundaries to prevent partial matches.
  // Without them: "encode", "recode", "decode" → matched as 'code' (wrong).
  // With boundaries: only whole words match. Also extended keyword sets for
  // better multilingual coverage (Tamil programming terms included).
  if (/\b(code|python|javascript|typescript|function|sql|bug|api|css|html|react|nodejs|bash|shell|script|algorithm|debug|compile|runtime|error|exception|stack|array|object|class|method|variable|database|query|endpoint)\b/i.test(text)) return 'code';
  if (/\b(idea|startup|product|creative|brainstorm|concept|design|brand|story|write|poem|art|music|game|imagine|invent)\b/i.test(text)) return 'ideas';
  return 'personal';
}

// ══════════════════════════════════════════════════
// ARCHITECTURE v19 — SIDEBAR RENDER ENGINE
// renderSidebar() = canonical public API.
// Uses createSidebarItem() for each entry.
