// ─── Inline Rename ───────────────────────────────
function startRename(id) {
  const chat = APP.chats[id]; if (!chat) return;
  const item = qs(`.chat-item[data-id="${id}"]`);
  if (!item) { toast('Rename: open this chat first', 'info'); promptRenameModal(id); return; }
  const titleEl = item.querySelector('.ci-title');
  if (!titleEl) return;
  const origTitle = chat.title;
  titleEl.innerHTML = `<input class="ci-rename-input" value="${esc(origTitle)}" maxlength="80" aria-label="Rename chat"/>`;
  const inp = titleEl.querySelector('input');
  inp.focus(); inp.select();
  let committed = false;
  function commit() {
    if (committed) return; committed = true;
    const v = inp.value.trim();
    if (v && v !== origTitle) {
      chat.title = v; save();
      toast('Renamed ✓', 'success');
    }
    renderChatList(); updateHeader();
  }
  inp.addEventListener('keydown', e => {
    if (e.key === 'Enter') { e.preventDefault(); commit(); }
    if (e.key === 'Escape') { committed = true; renderChatList(); }
  });
  inp.addEventListener('blur', commit);
  inp.addEventListener('click', e => e.stopPropagation());
  inp.addEventListener('pointerdown', e => e.stopPropagation());
}

// Fallback modal rename (for collapsed sidebar or missing DOM node)
// BUG FIX [v38-H4]: Replaced window.prompt() — it blocks the main thread,
// is unavailable in iframe WebViews (PWA), and has no styling capability.
// Now uses a lightweight inline modal that follows the app's design system.
function promptRenameModal(id) {
  const chat = APP.chats[id]; if (!chat) return;

  // Build inline rename modal
  const overlay = document.createElement('div');
  overlay.style.cssText = 'position:fixed;inset:0;z-index:9999;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.55);';

  const box = document.createElement('div');
  box.style.cssText = 'background:var(--surface-2,#1e1e2a);border:1px solid var(--border,rgba(255,255,255,0.1));border-radius:14px;padding:24px 20px 20px;width:min(340px,90vw);display:flex;flex-direction:column;gap:14px;box-shadow:0 20px 60px rgba(0,0,0,0.5)';

  const title = document.createElement('div');
  title.textContent = 'Rename chat';
  title.style.cssText = 'font-size:15px;font-weight:600;color:var(--ink-1,#fff)';
  box.appendChild(title);

  const input = document.createElement('input');
  input.type = 'text';
  input.value = chat.title || '';
  input.maxLength = 100;
  input.style.cssText = 'width:100%;box-sizing:border-box;padding:10px 12px;border-radius:8px;border:1px solid var(--border,rgba(255,255,255,0.15));background:var(--surface-3,rgba(255,255,255,0.06));color:var(--ink-1,#fff);font-size:14px;outline:none';
  box.appendChild(input);

  const btns = document.createElement('div');
  btns.style.cssText = 'display:flex;gap:8px;justify-content:flex-end';

  const cancelBtn = document.createElement('button');
  cancelBtn.textContent = 'Cancel';
  cancelBtn.style.cssText = 'padding:8px 16px;border-radius:8px;border:1px solid var(--border,rgba(255,255,255,0.15));background:none;color:var(--ink-2,rgba(255,255,255,0.7));font-size:13px;cursor:pointer';

  const saveBtn = document.createElement('button');
  saveBtn.textContent = 'Rename';
  saveBtn.style.cssText = 'padding:8px 16px;border-radius:8px;border:none;background:var(--accent,#8b5cf6);color:#fff;font-size:13px;cursor:pointer;font-weight:500';

  const doRename = () => {
    const v = input.value.trim();
    if (v) { chat.title = v; save(); renderChatList(); updateHeader(); toast('Renamed ✓', 'success'); }
    overlay.remove();
  };
  const doCancel = () => overlay.remove();

  cancelBtn.addEventListener('click', doCancel);
  saveBtn.addEventListener('click', doRename);
  input.addEventListener('keydown', e => { if (e.key === 'Enter') doRename(); if (e.key === 'Escape') doCancel(); });
  overlay.addEventListener('click', e => { if (e.target === overlay) doCancel(); });

  btns.appendChild(cancelBtn);
  btns.appendChild(saveBtn);
  box.appendChild(btns);
  overlay.appendChild(box);
  document.body.appendChild(overlay);

  requestAnimationFrame(() => { input.select(); input.focus(); });
}

// ─── Welcome / Messages ──────────────────────────
// v31: showWelcome — VML.load([]) clears rendered rows cleanly
// without triggering innerHTML reflows on the whole message list.
// Replaces void element.offsetWidth reflow with CSS animation reset.
function showWelcome() {
  const welcome = $('welcome');
  if (!welcome) return;
  welcome.style.display = 'flex';
  // v31: GPU-safe animation restart via CSS, not layout-triggering reflow
  welcome.style.animation = 'none';
  requestAnimationFrame(() => { welcome.style.animation = ''; });
  // Clear message list via VML (preserves spacer/sentinel elements)
  VML.load([]);
  const hdrTitle = $('hdrTitle');
  if (hdrTitle) hdrTitle.textContent = 'New Conversation';
  const stopBtnEl = $('stop-btn');
  if (stopBtnEl) stopBtnEl.classList.remove('visible');
  APP.isGenerating = false;
  updateSendBtn();
  setTimeout(renderPlaceholderChips, 0);
}
function updateHeader() {
  const chat = getChat();
  const hdrTitle = $('hdrTitle');
  if (hdrTitle) hdrTitle.textContent = chat ? chat.title : 'New Conversation'; // BUG FIX [v26]: null guard
}
// ══════════════════════════════════════════════════
// ARCHITECTURE v19 — MESSAGE RENDER ENGINE
// renderMessages() — full redraw (on chat switch/load)
// appendMessageToDOM() — incremental (during streaming)
// Both derive from State.messages (single source of truth)
// ══════════════════════════════════════════════════

/**
 * appendMessageToDOM(msg)
 * Appends a single message node to the live list.
 * Used by sendMessage and startGeneration so we never
 * trigger a full re-render for a single new message.
 *
 * @param {Object} msg - message record
 * @returns {HTMLElement} the appended element
 */
// v31: appendMessageToDOM — delegates to VML for windowed append
function appendMessageToDOM(msg) {
  const list = $('msg-list');
  if (!list) return null;
  // Dedup guard — never insert same message ID twice
  const existing = VML.getEl(msg.id) || list.querySelector(`[data-msg-id="${msg.id}"]`);
  if (existing) return existing;
  return VML.append(msg);
}

// ══════════════════════════════════════════════════
// v31: renderMessages — VirtualMessageList-backed render
// Replaces the old innerHTML + DocumentFragment approach.
// VML handles windowing, spacers, and IntersectionObserver.
// ══════════════════════════════════════════════════
function renderMessages() {
  const chat = getChat();
  if (!chat || !chat.messages.length) { showWelcome(); return; }

  const welcomeEl = $('welcome');
  if (welcomeEl) welcomeEl.style.display = 'none';
  updateHeader();
  try { document.title = chat.title ? `${chat.title} — ZenQ` : 'ZenQ'; } catch(e) {}

  const list = $('msg-list');
  if (!list) return;

  // Show skeleton while VML loads (instant visual feedback)
  const skWrap = document.createElement('div');
  skWrap.innerHTML = buildMsgSkeleton(Math.min(chat.messages.length, 4));
  // Clear only message rows — keep spacers/sentinels intact
  Array.from(list.children).forEach(child => {
    if (!child.id || !child.id.startsWith('vml-')) child.remove();
  });
  list.insertBefore(skWrap, list.querySelector('#vml-bottom-spacer'));

  requestAnimationFrame(() => {
    try {
      // Remove skeleton
      skWrap.remove();
      // VML.load handles windowing, date dividers, and grouping
      VML.load(chat.messages);
      VML.scrollToBottom(false);
    } catch (renderErr) {
      ZenQLogger && ZenQLogger.error('Render', 'renderMessages rAF failed:', renderErr.message);
      skWrap.remove();
      const errDiv = document.createElement('div');
      errDiv.style.cssText = 'padding:24px;text-align:center;color:var(--ink-3);font-size:13px';
      // BUG FIX [v38-H5]: Replaced inline onclick="renderMessages()" with a
      // programmatic listener — inline onclick requires unsafe-inline in CSP.
      const errText = document.createTextNode('⚠️ Failed to render messages. ');
      errDiv.appendChild(errText);
      const retryBtn = document.createElement('button');
      retryBtn.textContent = 'Retry';
      retryBtn.style.cssText = 'color:var(--accent);cursor:pointer;background:none;border:none;font-size:13px';
      retryBtn.addEventListener('click', () => renderMessages());
      errDiv.appendChild(retryBtn);
      list.insertBefore(errDiv, list.querySelector('#vml-bottom-spacer'));
    }
  });
}

// v31: loadMoreMessages is now handled transparently by VML's
// top-sentinel IntersectionObserver. This stub is kept for any
// external callers that may reference it directly.
function loadMoreMessages(currentOffset) {
  // VML handles infinite scroll internally via sentinel IO.
  // This is a no-op fallback for any legacy references.
  ZenQLogger && ZenQLogger.info('VML', 'loadMoreMessages called — VML handles this via sentinel IO');
}

function buildMsgSkeleton(count) {
  // PRODUCTION FIX [v29]: Deterministic skeleton widths — Math.random() caused
  // layout jitter on every re-render because different widths were generated
  // each time. Fixed widths per index produce stable, consistent skeletons.
  const WIDTHS  = [72, 58, 83, 64, 76, 55, 80, 68]; // pre-defined %
  const SHOW_B2 = [1, 0, 1, 1, 0, 1, 0, 1]; // deterministic "show second line"
  const SHOW_B3 = [0, 0, 1, 0, 0, 1, 0, 0]; // deterministic "show third line"
  let html = '<div class="msg-skel-wrap">';
  for (let i = 0; i < count; i++) {
    const isUsr = i % 2 === 0;
    const idx   = i % WIDTHS.length;
    html += `<div class="msg-skel-row ${isUsr ? 'usr' : ''}">
      <div class="msg-skel-av skel-base"></div>
      <div class="msg-skel-body">
        <div class="msg-skel-bubble skel-base" style="width:${WIDTHS[idx]}%"></div>
        ${SHOW_B2[idx] ? '<div class="msg-skel-bubble b2 skel-base"></div>' : ''}
        ${SHOW_B3[idx] ? '<div class="msg-skel-bubble b3 skel-base"></div>' : ''}
      </div>
    </div>`;
  }
  return html + '</div>';
}
function fmtTime(ts){ return new Date(ts).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}) }
function fmtRelTime(ts){
  const diff = Date.now() - ts;
  const m = Math.floor(diff/60000);
  if(m < 1) return 'just now';
  if(m < 60) return `${m}m ago`;
  const h = Math.floor(m/60);
  if(h < 24) return `${h}h ago`;
  return new Date(ts).toLocaleDateString([],{month:'short',day:'numeric'});
}

// OPT: Profile cache — loadProfile() hits localStorage on every message render (hot path).
// Cache for 5s to avoid repeated reads during message list rendering.
let _cachedProfile = null;
let _profileCacheTs = 0;
function getCachedProfile() {
  const now = Date.now();
  if (!_cachedProfile || (now - _profileCacheTs) > 5000) {
    _cachedProfile = (typeof loadProfile === 'function') ? loadProfile() : {};
    _profileCacheTs = now;
  }
  return _cachedProfile;
}
// Bust cache when profile is saved (called from saveProfile())
const _origSaveProfile = typeof saveProfile !== 'undefined' ? saveProfile : null;

// ── v31: buildMsgHTML — grouping-aware message builder ──────────
// opts.grouped:    true if prev message same sender (hide avatar, tighter gap)
// opts.groupStart: true if NEXT message is also same sender (rounder far edge)
// opts.prevDate / opts.currDate: date strings for date-divider injection
function buildMsgHTML(m, opts = {}) {
  const isUser = m.role === 'user';
  const content = isUser
    ? `<div class="mc">${esc(m.content).replace(/\n/g,'<br>')}</div>`
    : `<div class="mc">${parseMarkdown(m.content)}</div>`;
  const likeActive    = m.liked    ? ' liked'    : '';
  const dislikeActive = m.disliked ? ' disliked' : '';
  const tsLabel  = fmtTime(m.timestamp);
  const relLabel = fmtRelTime(m.timestamp);
  const profile  = getCachedProfile();
  const userInitial  = (profile.name ? profile.name[0] : 'U').toUpperCase();
  // v33: render photo avatar for user messages when photoURL is set
  const userAvContent = profile.photoURL
    ? `<img loading="lazy" decoding="async" src="${esc(profile.photoURL)}" alt="${userInitial}" style="width:100%;height:100%;object-fit:cover;border-radius:inherit;display:block">`
    : userInitial;
  const aiAvContent  = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>`;

  // Build row class list — grouped / group-start drive CSS radius/avatar changes
  const rowClasses = [
    'msg-row',
    isUser ? 'usr' : 'ai',
    opts.grouped    ? 'grouped'     : '',
    opts.groupStart ? 'group-start' : '',
  ].filter(Boolean).join(' ');

  return `<div class="${rowClasses}" data-msg-id="${m.id}" role="article" aria-label="${isUser ? 'You' : 'ZenQ'}: ${isUser ? esc(m.content.slice(0,80)) : 'AI response'}">
    <div class="msg-body">
      <div class="msg-bubble">${content}</div>
      <div class="msg-meta" aria-label="Message metadata">
        <div class="msg-actions" role="group" aria-label="Message actions">
          ${isUser
            ? ``
            : `<button class="ma-btn ma-copy" title="Copy" aria-label="Copy message" aria-pressed="false">
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true">
                  <rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/>
                </svg>
               </button>
               <button class="ma-btn ma-like${likeActive}" title="Good response" aria-label="Like response" aria-pressed="${m.liked ? 'true' : 'false'}">
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true">
                  <path d="M14 9V5a3 3 0 0 0-3-3l-4 9v11h11.28a2 2 0 0 0 2-1.7l1.38-9a2 2 0 0 0-2-2.3H14z"/><path d="M7 22H4a2 2 0 0 1-2-2v-7a2 2 0 0 1 2-2h3"/>
                </svg>
               </button>
               <button class="ma-btn ma-dislike${dislikeActive}" title="Bad response" aria-label="Dislike response" aria-pressed="${m.disliked ? 'true' : 'false'}">
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true">
                  <path d="M10 15v4a3 3 0 0 0 3 3l4-9V2H5.72a2 2 0 0 0-2 1.7l-1.38 9a2 2 0 0 0 2 2.3H10z"/><path d="M17 2h2.67A2.31 2.31 0 0 1 22 4v7a2.31 2.31 0 0 1-2.33 2H17"/>
                </svg>
               </button>
               <div class="ma-more-wrap">
                <button class="ma-btn ma-more" title="More options" aria-label="More options" aria-expanded="false" aria-haspopup="menu" data-msg-ts="${m.timestamp}">
                  <svg width="13" height="13" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
                    <circle cx="12" cy="5" r="1.6"/><circle cx="12" cy="12" r="1.6"/><circle cx="12" cy="19" r="1.6"/>
                  </svg>
                </button>
               </div>`}
        </div>
      </div>
    </div>
  </div>`;
}

// ── v31: dateDividerHTML — chat-date group label ─────────────────
function _buildDateDivider(ts) {
  const d = new Date(ts);
  const today = new Date();
  const yesterday = new Date(today); yesterday.setDate(today.getDate() - 1);
  const isSameDay = (a, b) =>
    a.getFullYear() === b.getFullYear() &&
    a.getMonth()    === b.getMonth()    &&
    a.getDate()     === b.getDate();
  let label = isSameDay(d, today)     ? 'Today'
            : isSameDay(d, yesterday) ? 'Yesterday'
            : d.toLocaleDateString([], {weekday:'long', month:'short', day:'numeric'});
  const wrapper = document.createElement('div');
  wrapper.className = 'msg-date-divider';
  wrapper.setAttribute('aria-label', label);
  wrapper.innerHTML = `<span class="msg-date-divider-label">${label}</span>`;
  return wrapper;
}

// ── v31: _dateKey — fast day-bucket string ───────────────────────
function _dateKey(ts) {
  const d = new Date(ts);
  return `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
}

// ══════════════════════════════════════════════════
// ARCHITECTURE v19 — COMPONENT SYSTEM
// Reusable factory functions that return DOM nodes.
// createMessageElement() — single message row
// createSidebarItem()    — chat list entry
// ══════════════════════════════════════════════════

// ══════════════════════════════════════════════════
// ARCHITECTURE v31 — VIRTUAL MESSAGE LIST ENGINE
// Renders only WINDOW_SIZE messages at a time.
// Sentinel IntersectionObservers trigger prepend/trim.
// Spacer divs maintain scroll position during windowing.
//
// Public API:
//   VML.mount(list, scrollWrap)  — attach to DOM
//   VML.load(messages)           — replace all messages
//   VML.append(msg)              — add single message
//   VML.refresh(msgId)           — re-render one message
//   VML.scrollToBottom(smooth?)  — scroll to newest
//   VML.destroy()                — tear down
// ══════════════════════════════════════════════════
const VirtualMessageList = (() => {
  const WINDOW_SIZE   = 50;   // messages to render at once
  const LOAD_SIZE     = 30;   // messages per sentinel trigger

  let _list       = null;     // #msg-list element
  let _vml_wrap  = null; // #msgs-wrap (scroll container)
  let _allMsgs    = [];       // full message array (source of truth)
  let _startIdx   = 0;        // first rendered message index
  let _endIdx     = 0;        // last rendered message index (exclusive)
  let _topSpacer  = null;
  let _botSpacer  = null;
  let _topSentinel = null;
  let _botSentinel = null;
  let _topObs     = null;
  let _botObs     = null;
  let _avgRowH    = 80;       // estimated row height (px), updated adaptively

  // ── Helpers ──────────────────────────────────────
  function _dateKeyFn(ts) { return _dateKey(ts); }

  /** Build a DocumentFragment of message rows from msgs[from..to) */
  function _buildFragment(msgs, from, to) {
    const frag = document.createDocumentFragment();
    let prevDate = null;
    let prevRole = null;
    for (let i = from; i < to; i++) {
      const m    = msgs[i];
      const mDate = _dateKeyFn(m.timestamp);
      // Date divider when day changes
      if (mDate !== prevDate) {
        frag.appendChild(_buildDateDivider(m.timestamp));
        prevDate = mDate;
        prevRole = null; // reset grouping across date boundaries
      }
      const prevM     = (i > 0) ? msgs[i - 1] : null;
      const nextM     = (i < msgs.length - 1) ? msgs[i + 1] : null;
      const grouped   = !!prevM && prevM.role === m.role && _dateKeyFn(prevM.timestamp) === mDate;
      // BUG FIX [v38-M1]: Was comparing nextM.timestamp === nextM.timestamp (always true).
      // Must compare the NEXT message's date against the CURRENT message's date.
      const groupStart = !!nextM && nextM.role === m.role && _dateKeyFn(nextM.timestamp) === _dateKeyFn(m.timestamp);
      frag.appendChild(createMsgEl(m, { grouped, groupStart }));
      prevRole = m.role;
    }
    return frag;
  }

  /** Update spacer heights based on estimated avg row height */
  function _updateSpacers() {
    if (!_topSpacer || !_botSpacer) return;
    _topSpacer.style.height = (_startIdx * _avgRowH) + 'px';
    _botSpacer.style.height = ((_allMsgs.length - _endIdx) * _avgRowH) + 'px';
  }

  /** Recalculate avg row height from rendered rows */
  function _recalcAvgRowH() {
    if (!_list) return;
    const rows = _list.querySelectorAll('.msg-row');
    if (rows.length < 2) return;
    const total = Array.from(rows).reduce((acc, r) => acc + r.offsetHeight, 0);
    _avgRowH = Math.max(40, Math.round(total / rows.length));
  }

  /** Render the initial window */
  function _renderWindow() {
    if (!_list) return;
    // Clear existing message rows but keep sentinels/spacers
    const existing = _list.querySelectorAll('.msg-row,.msg-date-divider');
    existing.forEach(n => n.remove());

    _startIdx = Math.max(0, _allMsgs.length - WINDOW_SIZE);
    _endIdx   = _allMsgs.length;
    _list.insertBefore(_buildFragment(_allMsgs, _startIdx, _endIdx), _botSentinel);
    _updateSpacers();
    requestAnimationFrame(_recalcAvgRowH);
  }

  /** Load older messages at top sentinel trigger */
  function _loadOlder() {
    if (_startIdx <= 0 || !_list) return;
    const prevScroll = _vml_wrap ? (_vml_wrap.scrollHeight - _vml_wrap.scrollTop) : 0;
    const newStart = Math.max(0, _startIdx - LOAD_SIZE);
    const frag = _buildFragment(_allMsgs, newStart, _startIdx);
    // Insert before first .msg-row
    const firstRow = _list.querySelector('.msg-row');
    if (firstRow) _list.insertBefore(frag, firstRow);
    else _list.insertBefore(frag, _botSentinel);
    _startIdx = newStart;
    // BUG FIX [v38-H2]: Trim bottom rows if window is too large.
    // Previous code used a static NodeList and then subtracted `trim` from
    // _endIdx, but `rows` was captured before removal so the count was wrong,
    // leaving _endIdx understated and producing phantom scroll space below the
    // last real message. Fix: remove rows first, then recalculate _endIdx from
    // the actual remaining live row count.
    if (_endIdx - _startIdx > WINDOW_SIZE + LOAD_SIZE) {
      const rows = Array.from(_list.querySelectorAll('.msg-row'));
      const trimCount = rows.length - WINDOW_SIZE;
      if (trimCount > 0) {
        // Remove from the bottom (newest visible rows — they will reload when user scrolls down)
        for (let i = rows.length - 1; i >= rows.length - trimCount; i--) {
          rows[i].remove();
        }
        // Recalculate _endIdx from actual remaining rows, not arithmetic
        _endIdx = _startIdx + _list.querySelectorAll('.msg-row').length;
      }
    }
    _updateSpacers();
    // JUMP FIX: Restore scroll position AFTER the browser has laid out the
    // newly inserted nodes. The previous synchronous assignment read scrollHeight
    // before the DOM was painted, so it computed the wrong offset and the scroll
    // position jumped when the layout caught up. Wrapping in rAF guarantees we
    // read the settled scrollHeight with all new rows measured.
    if (_vml_wrap) {
      const _target = _vml_wrap.scrollHeight - prevScroll;
      requestAnimationFrame(() => {
        if (_vml_wrap) _vml_wrap.scrollTop = _vml_wrap.scrollHeight - prevScroll;
      });
    }
    requestAnimationFrame(_recalcAvgRowH);
  }

  /** Wire IntersectionObserver sentinels */
  function _initSentinels() {
    if (!_vml_wrap) return;
    if (_topObs) _topObs.disconnect();
    if (_botObs) _botObs.disconnect();
    _topObs = new IntersectionObserver(entries => {
      if (entries[0].isIntersecting) _loadOlder();
    }, { root: _vml_wrap, rootMargin: '200px 0px 0px 0px', threshold: 0 });
    _topObs.observe(_topSentinel);
    // Bottom sentinel not needed for loading (append handles it)
  }

  // ── Public factory ───────────────────────────────
  function createMsgEl(msg, opts) {
    const wrapper = document.createElement('div');
    wrapper.innerHTML = buildMsgHTML(msg, opts);
    return wrapper.firstElementChild;
  }

  return {
    mount(list, wrap) {
      _list = list; _vml_wrap = wrap;
      // Inject spacers and sentinels
      _topSpacer   = Object.assign(document.createElement('div'), { id: 'vml-top-spacer' });
      _botSpacer   = Object.assign(document.createElement('div'), { id: 'vml-bottom-spacer' });
      _topSentinel = Object.assign(document.createElement('div'), { id: 'vml-top-sentinel' });
      _botSentinel = Object.assign(document.createElement('div'), { id: 'vml-bottom-sentinel' });
      _list.prepend(_topSentinel, _topSpacer);
      _list.append(_botSpacer, _botSentinel);
      _initSentinels();
    },

    /** Replace entire message set (on chat switch / load) */
    load(messages) {
      _allMsgs = messages || [];
      _renderWindow();
    },

    /** Append a single new message (during streaming / send) */
    append(msg) {
      _allMsgs.push(msg);
      _endIdx = _allMsgs.length;
      const i = _allMsgs.length - 1;
      const prevM = i > 0 ? _allMsgs[i - 1] : null;
      const mDate = _dateKeyFn(msg.timestamp);
      // Inject date divider if day changed
      if (prevM && _dateKeyFn(prevM.timestamp) !== mDate) {
        _botSpacer.before(_buildDateDivider(msg.timestamp));
      }
      const grouped = !!prevM && prevM.role === msg.role && _dateKeyFn(prevM.timestamp) === mDate;
      // If previous message was start of group, update its class
      if (grouped) {
        const rows = _list.querySelectorAll('.msg-row');
        const lastRow = rows[rows.length - 1];
        if (lastRow && !lastRow.classList.contains('group-start')) {
          lastRow.classList.add('group-start');
        }
      }
      const el = createMsgEl(msg, { grouped });
      _botSpacer.before(el);
      // Trim very old rows from top if window exceeds WINDOW_SIZE + LOAD_SIZE
      const rows = _list.querySelectorAll('.msg-row');
      if (rows.length > WINDOW_SIZE + LOAD_SIZE) {
        const trimCount = rows.length - WINDOW_SIZE;
        for (let t = 0; t < trimCount; t++) {
          const r = _list.querySelector('.msg-row');
          if (r) { r.remove(); _startIdx++; }
        }
        _updateSpacers();
      }
      return el;
    },

    /** Refresh (re-render) a single message by ID */
    refresh(msgId) {
      const msg = _allMsgs.find(m => m.id === msgId);
      if (!msg) return;
      const existing = _list.querySelector(`[data-msg-id="${msgId}"]`);
      if (!existing) return;
      const i = _allMsgs.indexOf(msg);
      const prevM = i > 0 ? _allMsgs[i - 1] : null;
      const mDate = _dateKeyFn(msg.timestamp);
      const grouped = !!prevM && prevM.role === msg.role && _dateKeyFn(prevM.timestamp) === mDate;
      const newEl = createMsgEl(msg, { grouped });
      existing.replaceWith(newEl);
    },

    /** Scroll to bottom of messages */
    scrollToBottom(smooth = false) {
      if (!_vml_wrap) return;
      requestAnimationFrame(() => {
        _vml_wrap.scrollTo({ top: _vml_wrap.scrollHeight, behavior: smooth ? 'smooth' : 'instant' });
      });
    },

    /** Get the DOM element for a message ID (only if rendered) */
    getEl(msgId) {
      return _list ? _list.querySelector(`[data-msg-id="${msgId}"]`) : null;
    },

    /** Reset / teardown */
    destroy() {
      if (_topObs) { _topObs.disconnect(); _topObs = null; }
      if (_botObs) { _botObs.disconnect(); _botObs = null; }
      _allMsgs = []; _startIdx = 0; _endIdx = 0;
      _topSpacer = _botSpacer = _topSentinel = _botSentinel = null;
      _list = null; _vml_wrap = null;
    }
  };
})();

// ── VML singleton — mounted once after DOM ready ──────────────────
const VML = VirtualMessageList;

// ── Mount VML when DOM is ready ───────────────────────────────────
(function mountVML() {
  const list = document.getElementById('msg-list');
  const wrap = document.getElementById('msgs-wrap');
  if (list && wrap) VML.mount(list, wrap);
})();

/**
 * createMessageElement(msg, opts)
 * Returns a real DOM element for a message record.
 * v31: supports grouping opts (grouped, groupStart)
 *
 * @param {Object} msg  - { id, role, content, timestamp }
 * @param {Object} opts - { grouped?, groupStart? }
 * @returns {HTMLElement}
 */
function createMessageElement(msg, opts = {}) {
  const wrapper = document.createElement('div');
  wrapper.innerHTML = buildMsgHTML(msg, opts);
  return wrapper.firstElementChild;
}

/**
 * createSidebarItem(chat, isActive)
 * Returns a DOM element for a sidebar chat list entry.
 * Reusable, avoids innerHTML injection in render loop.
 *
 * @param {Object}  chat     - chat record from APP.chats
 * @param {boolean} isActive - whether this is the active chat
 * @returns {HTMLElement}
 */
function createSidebarItem(chat, isActive) {
  const item = document.createElement('div');
  item.className = [
    'chat-item',
    isActive  ? 'active'  : '',
    chat.pinned   ? 'pinned'  : '',
    chat.archived ? 'archived': '',
  ].filter(Boolean).join(' ');
  item.dataset.id = chat.id;
  item.setAttribute('role', 'button');
  item.setAttribute('tabindex', '0');
  item.setAttribute('aria-label', `Chat: ${chat.title}`);
  item.setAttribute('aria-pressed', isActive ? 'true' : 'false');

  const catStyle = CAT_STYLES[chat.category] || '';
  const pinHtml  = chat.pinned
    ? `<span class="ci-pin" title="Pinned" aria-label="Pinned">
         <svg width="10" height="10" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
           <path d="M12 2l2.4 7.4H22l-6.2 4.5 2.4 7.4L12 17l-6.2 4.3 2.4-7.4L2 9.4h7.6L12 2z"/>
         </svg>
       </span>` : '';
  const catHtml  = (chat.category && !APP.sidebarCollapsed)
    ? `<span class="ci-cat ${catStyle}" aria-hidden="true">${esc(chat.category)}</span>` : '';

  const msgCount = chat.messages ? chat.messages.length : 0;
  const lastTs   = chat.updatedAt || chat.createdAt || Date.now();

  item.innerHTML = `
    <span class="ci-ico" aria-hidden="true">
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8">
        <path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/>
      </svg>
    </span>
    <div class="ci-meta">
      <div class="ci-title">${esc(chat.title)}</div>
      <div class="ci-sub">${fmtRelTime(lastTs)} · ${msgCount} msg${msgCount !== 1 ? 's' : ''}</div>
    </div>
    ${catHtml}
    ${pinHtml}
    <button class="ci-more" title="More" aria-label="More options: ${esc(chat.title)}">
      <svg width="15" height="15" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
        <circle cx="12" cy="5" r="1.9"/><circle cx="12" cy="12" r="1.9"/><circle cx="12" cy="19" r="1.9"/>
      </svg>
    </button>
    <button class="ci-del" title="Delete chat" aria-label="Delete chat: ${esc(chat.title)}">
      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true">
        <line x1="18" y1="6" x2="6" y2="18"/>
        <line x1="6" y1="6" x2="18" y2="18"/>
      </svg>
    </button>
  `;

  // ── Events wired on the element itself ───────────
  item.addEventListener('click', e => {
    if (e.target.closest('.ci-del')) {
      e.stopPropagation();
      deleteChat(chat.id);
      return;
    }
    if (e.target.closest('.ci-more')) {
      e.stopPropagation();
      const r = e.target.closest('.ci-more').getBoundingClientRect();
      showCtxMenu(chat.id, r.right, r.bottom + 4);
      return;
    }
    switchChat(chat.id);
  });
  item.addEventListener('contextmenu', e => {
    e.preventDefault();
    showCtxMenu(chat.id, e.clientX, e.clientY);
  });
  // Long-press on mobile → context menu
  let _lpTimer = null;
  // PRODUCTION FIX [v29]: Added pointercancel to cover browser gesture cancellation
  // (e.g. scroll starts and the browser synthesises a cancel event).
  // Without this the long-press timer kept running during scroll, showing the
  // context menu on top of the scrolled content — a known mobile UX bug.
  // Also guard getBoundingClientRect() — if the item was removed from DOM
  // between pointerdown and the 550ms timeout, all coordinates would be zero.
  const _clearLp = () => { clearTimeout(_lpTimer); _lpTimer = null; };
  item.addEventListener('pointerdown', () => {
    _clearLp();
    _lpTimer = setTimeout(() => {
      if (!item.isConnected) return; // element was removed from DOM — abort
      const rect = item.getBoundingClientRect();
      showCtxMenu(chat.id, rect.right, rect.top);
    }, 550);
  });
  item.addEventListener('pointerup',     _clearLp);
  item.addEventListener('pointerleave',  _clearLp);
  item.addEventListener('pointercancel', _clearLp);
  // Keyboard accessibility
  item.addEventListener('keydown', e => {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); switchChat(chat.id); }
    if (e.key === 'Delete' || e.key === 'Backspace') { e.preventDefault(); deleteChat(chat.id); }
  });

  return item;
}

// ─── EVENT DELEGATION ────────────────────────────
// FIX: Single delegated listener replaces per-element binding.
// Fixes: like/dislike broken on dynamic AI rows, duplicate listeners,
//        regen button not needing manual addEventListener.
function initMsgDelegation() {
  on('msg-list', 'click', e => {
    const row = e.target.closest('.msg-row');
    if (!row) return;
    const chat = getChat();
    const msgId = row.dataset.msgId;

    if (e.target.closest('.ma-copy')) {
      const bubble = row.querySelector('.msg-bubble');
      if (!bubble) return;
      // FIX: Get text from .mc if available (avoids including action button text)
      const mc = bubble.querySelector('.mc');
      const text = mc ? mc.innerText : bubble.innerText;
      // FIX: clipboard API fallback for non-HTTPS or older browsers
      const doCopy = () => {
        if(navigator.clipboard && window.isSecureContext){
          return navigator.clipboard.writeText(text);
        }
        // execCommand fallback
        const ta = document.createElement('textarea');
        ta.value = text; ta.style.cssText = 'position:fixed;opacity:0;top:-9999px';
        document.body.appendChild(ta); ta.select();
        const ok = document.execCommand('copy');
        document.body.removeChild(ta);
        return ok ? Promise.resolve() : Promise.reject();
      };
      doCopy().then(() => {
        const btn = row.querySelector('.ma-copy');
        btn.classList.add('copied'); toast('Copied!','success');
        setTimeout(()=>btn.classList.remove('copied'),1800);
      }).catch(()=>toast('Copy failed','error'));
      return;
    }

    if (e.target.closest('.ma-share')) {
      const bubble = row.querySelector('.msg-bubble');
      const mc = bubble.querySelector('.mc');
      const text = mc ? mc.innerText : bubble.innerText;
      const shareData = { title: 'ZenQ', text };
      if (navigator.share && navigator.canShare && navigator.canShare(shareData)) {
        navigator.share(shareData).catch(() => {});
      } else {
        const doCopy = () => {
          if (navigator.clipboard && window.isSecureContext) {
            return navigator.clipboard.writeText(text);
          }
          const ta = document.createElement('textarea');
          ta.value = text; ta.style.cssText = 'position:fixed;opacity:0;top:-9999px';
          document.body.appendChild(ta); ta.select();
          const ok = document.execCommand('copy');
          document.body.removeChild(ta);
          return ok ? Promise.resolve() : Promise.reject();
        };
        doCopy().then(() => {
          const btn = row.querySelector('.ma-share');
          if (btn) { btn.classList.add('copied'); }
          toast('Copied to share!', 'success');
          setTimeout(() => { if (btn) btn.classList.remove('copied'); }, 1800);
        }).catch(() => toast('Share failed', 'error'));
      }
      return;
    }

    // ── 3-dot more menu toggle ──────────────────────────
    if (e.target.closest('.ma-more')) {
      const btn  = e.target.closest('.ma-more');
      const wrap = btn.closest('.ma-more-wrap');
      if (!wrap) return;
      const existing = wrap.querySelector('.ma-more-menu');
      if (existing) {
        existing.remove();
        btn.setAttribute('aria-expanded','false');
        return;
      }
      // Close any other open menus
      document.querySelectorAll('.ma-more-menu').forEach(m => m.remove());
      document.querySelectorAll('.ma-more').forEach(b => b.setAttribute('aria-expanded','false'));

      // Get message timestamp from data attribute
      const msgTs = parseInt(btn.dataset.msgTs || '0', 10);
      const timeStr = msgTs ? fmtTime(msgTs) : '';
      const relStr  = msgTs ? fmtRelTime(msgTs) : '';

      const menu = document.createElement('div');
      menu.className = 'ma-more-menu';
      menu.setAttribute('role','menu');
      // Store the originating row ID so menu items can find it later
      menu.dataset.srcMsgId = msgId || '';
      // Use fixed positioning — appended to body so it isn't clipped by overflow:hidden parents
      menu.style.position = 'fixed';
      const btnRect = btn.getBoundingClientRect();
      const menuW = 188;
      const estimatedMenuH = 216;
      let leftPos = btnRect.right - menuW;
      if (leftPos < 8) leftPos = 8;
      if (leftPos + menuW > window.innerWidth - 8) leftPos = window.innerWidth - menuW - 8;
      // Place menu ABOVE the button; flip below if not enough space above
      let topPos = btnRect.top - estimatedMenuH - 6;
      if (topPos < 8) topPos = btnRect.bottom + 4;
      if (topPos + estimatedMenuH > window.innerHeight - 8) topPos = window.innerHeight - estimatedMenuH - 8;
      if (topPos < 8) topPos = 8;
      menu.style.left = leftPos + 'px';
      menu.style.top  = topPos + 'px';
      menu.style.zIndex = '9500';
      menu.innerHTML = `
        <button class="msg-more-item msg-more-branch" role="menuitem">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><line x1="6" y1="3" x2="6" y2="15"/><circle cx="18" cy="6" r="3"/><circle cx="6" cy="18" r="3"/><path d="M18 9a9 9 0 0 1-9 9"/></svg>
          Branch New Chat
        </button>
        <button class="msg-more-item msg-more-share" role="menuitem">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><line x1="8.59" y1="13.51" x2="15.42" y2="17.49"/><line x1="15.41" y1="6.51" x2="8.59" y2="10.49"/></svg>
          Share Response
        </button>
        <div class="msg-more-sep"></div>
        <button class="msg-more-item msg-more-web" role="menuitem">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
          Search on Web
        </button>
        <button class="msg-more-item msg-more-retry" role="menuitem">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 1 0 .49-3.52"/></svg>
          Retry
        </button>
        ${timeStr ? `<div class="msg-more-sep"></div>
        <div class="msg-more-item msg-more-time" role="menuitem" style="cursor:default;pointer-events:none;color:var(--ink-3)">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
          <span title="${relStr}">${timeStr}</span>
        </div>` : ''}`;
      // Append to body so it's never clipped by overflow:hidden parents
      document.body.appendChild(menu);
      btn.setAttribute('aria-expanded','true');
      // Wire menu item clicks directly (no delegation race condition)
      menu.addEventListener('click', function handleMenuClick(ev) {
        const item = ev.target.closest('.msg-more-item');
        if (!item) return;
        ev.stopPropagation();
        const srcMsgId = menu.dataset.srcMsgId;
        const srcRow = srcMsgId ? document.querySelector(`.msg-row[data-msg-id="${srcMsgId}"]`) : null;
        menu.remove();
        btn.setAttribute('aria-expanded','false');
        if (item.classList.contains('msg-more-branch')) {
          const srcChat = getChat();
          const branchTitle = srcChat ? `↳ ${(srcChat.title || 'Chat').slice(0, 36)}` : 'New Chat';
          const newId = createChat(branchTitle, 'general');
          APP.activeChatId = newId; save(); showWelcome(); renderChatList();
          const ta = $('msg-ta'); if (ta) ta.focus();
          toast('Branched to new chat ✦', 'success');
        } else if (item.classList.contains('msg-more-share')) {
          const bubble = srcRow?.querySelector('.msg-bubble');
          const mc = bubble?.querySelector('.mc');
          const text = mc ? mc.innerText : (bubble ? bubble.innerText : '');
          const sd = { title: 'ZenQ', text };
          if (navigator.share && navigator.canShare && navigator.canShare(sd)) {
            navigator.share(sd).catch(() => {});
          } else {
            const doCopy = () => navigator.clipboard && window.isSecureContext
              ? navigator.clipboard.writeText(text)
              : Promise.reject();
            doCopy().then(() => toast('Copied to share! 🔗','success')).catch(() => toast('Share failed','error'));
          }
        } else if (item.classList.contains('msg-more-retry')) {
          regenerate();
        } else if (item.classList.contains('msg-more-web')) {
          const bubble = srcRow?.querySelector('.msg-bubble');
          const mc = bubble?.querySelector('.mc');
          const query = (mc ? mc.innerText.trim() : '').slice(0, 200);
          if (query) window.open('https://www.google.com/search?q=' + encodeURIComponent(query), '_blank', 'noopener,noreferrer');
        }
      });
      e.stopPropagation();
      return;
    }

    if (e.target.closest('.ma-edit')) {
      if(!chat) return;
      const msg = chat.messages.find(m=>m.id===msgId); if(!msg) return;
      const bubble = row.querySelector('.msg-bubble');
      const orig = msg.content;
      bubble.classList.add('usr-edit-mode');
      bubble.innerHTML = `<textarea class="edit-ta"></textarea>
        <div class="edit-actions">
          <button class="edit-btn edit-save">Save &amp; Resend</button>
          <button class="edit-btn edit-cancel">Cancel</button>
        </div>`;
      const ta = bubble.querySelector('.edit-ta');
      // BUG FIX: Set value directly instead of via innerHTML to avoid HTML-entity
      // double-encoding issues (e.g. & rendered as &amp; in the textarea).
      ta.value = orig;
      // BUG FIX: Auto-resize the textarea to fit the original content, and
      // continue resizing as the user types (was only set once at focus time).
      function _resizeEditTa() {
        ta.style.height = 'auto';
        ta.style.height = Math.min(ta.scrollHeight, Math.floor(window.innerHeight * 0.45)) + 'px';
      }
      _resizeEditTa();
      ta.addEventListener('input', _resizeEditTa, { passive: true });
      // BUG FIX: On mobile the keyboard opens when the textarea is focused, which
      // may push it behind the keyboard. scrollIntoView after a short delay (after
      // the keyboard animation completes) ensures it stays visible.
      requestAnimationFrame(() => {
        ta.focus();
        // Place caret at end of text
        ta.selectionStart = ta.selectionEnd = ta.value.length;
        setTimeout(() => { ta.scrollIntoView({ behavior: 'smooth', block: 'nearest' }); }, 360);
      });
      return;
    }

    if (e.target.closest('.edit-save')) {
      if(!chat) return;
      const ta = row.querySelector('.edit-ta'); if(!ta) return;
      const newText = ta.value.trim(); if(!newText) return;
      const idx = chat.messages.findIndex(m=>m.id===msgId);
      chat.messages.splice(idx); save(); renderMessages(); sendMessage(newText);
      return;
    }

    if (e.target.closest('.edit-cancel')) {
      if(!chat) return;
      const msg = chat.messages.find(m=>m.id===msgId); if(!msg) return;
      const bubble = row.querySelector('.msg-bubble');
      bubble.classList.remove('usr-edit-mode');
      // BUG FIX: Use parseMarkdown for AI messages, esc+br for user messages.
      // Previously both paths used esc()+br which was correct for user messages
      // but left AI messages without markdown rendering after cancel.
      // Also: remove any resize listener added during edit to avoid memory leak.
      const oldTa = bubble.querySelector('.edit-ta');
      if (oldTa) { const cloned = oldTa.cloneNode(false); oldTa.parentNode.replaceChild(cloned, oldTa); }
      bubble.innerHTML = `<div class="mc">${esc(msg.content).replace(/\n/g,'<br>')}</div>`;
      return;
    }

    if (e.target.closest('.ma-like')) {
      if(!chat) return;
      const msg = chat.messages.find(m=>m.id===msgId); if(!msg) return;
      msg.liked = !msg.liked; msg.disliked = false;
      const btn = row.querySelector('.ma-like');
      const dis = row.querySelector('.ma-dislike');
      if (btn) {
        btn.classList.toggle('liked', msg.liked);
        btn.setAttribute('aria-pressed', String(msg.liked));
      }
      if (dis) { dis.classList.remove('disliked'); dis.setAttribute('aria-pressed','false'); }
      save();
      // Sync VML internal array so liked state persists after scroll-reinsertion
      const vmlMsg = VML ? VML._allMsgs?.find?.(m => m.id === msgId) : null;
      if (vmlMsg) { vmlMsg.liked = msg.liked; vmlMsg.disliked = false; }
      if (msg.liked) toast('Thanks for the feedback! 👍','success');
      return;
    }

    if (e.target.closest('.ma-dislike')) {
      if(!chat) return;
      const msg = chat.messages.find(m=>m.id===msgId); if(!msg) return;
      msg.disliked = !msg.disliked; msg.liked = false;
      const btn = row.querySelector('.ma-dislike');
      const lik = row.querySelector('.ma-like');
      if (btn) {
        btn.classList.toggle('disliked', msg.disliked);
        btn.setAttribute('aria-pressed', String(msg.disliked));
      }
      if (lik) { lik.classList.remove('liked'); lik.setAttribute('aria-pressed','false'); }
      save();
      // Sync VML internal array so disliked state persists after scroll-reinsertion
      const vmlMsg = VML ? VML._allMsgs?.find?.(m => m.id === msgId) : null;
      if (vmlMsg) { vmlMsg.disliked = msg.disliked; vmlMsg.liked = false; }
      if (msg.disliked) toast("Noted — we'll improve 👎",'info');
      return;
    }

    if (e.target.closest('.regen-btn')) {
      regenerate(); return;
    }
  });

  // ── Close 3-dot more menu on outside click ──────────
  // Menus are appended to document.body, so we check if click
  // is inside any .ma-more-menu or .ma-more button
  document.addEventListener('click', e => {
    if (!e.target.closest('.ma-more-wrap') && !e.target.closest('.ma-more-menu')) {
      document.querySelectorAll('.ma-more-menu').forEach(m => m.remove());
      document.querySelectorAll('.ma-more').forEach(b => b.setAttribute('aria-expanded','false'));
    }
  });
}

function appendRegenBtn() {
  // v31: search within the VML-rendered window (the visible DOM subset)
  const list = $('msg-list');
  if (!list) return;
  const aiRows = list.querySelectorAll('.msg-row.ai');
  if (!aiRows.length) return;
  const last = aiRows[aiRows.length - 1];
  const meta = last.querySelector('.msg-meta');
  if (meta && !meta.querySelector('.regen-btn')) {
    const b = document.createElement('button');
    b.className = 'regen-btn';
    b.setAttribute('aria-label', 'Regenerate response');
    b.innerHTML = `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" aria-hidden="true"><polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 1 0 .49-3.25"/></svg> Regenerate`;
    meta.appendChild(b);
  }
}

// ─── Smart Scroll + Premium FAB System ──────────────────────────────────────
// ChatGPT/Claude-style centered floating scroll button with:
// • Centered in chat area (accounts for sidebar width via CSS var)
// • rAF-gated IntersectionObserver + passive scroll fallback
// • Unread message badge with spring-pop animation
// • Auto-hide after inactivity, clears on scroll-to-bottom
// • Reduced-motion aware · mobile optimised · GPU-accelerated
// ─────────────────────────────────────────────────────────────────────────────

const SCROLL_THRESHOLD = 120;
let _scrollRafPending   = false;
let _userScrolledUp     = false;
const scrollFab         = document.getElementById('scroll-fab');
const scrollFabBadge    = document.getElementById('scroll-fab-badge');

let _fabUnreadCount     = 0;
let _fabInactivityTimer = null;
const FAB_INACTIVITY_MS = 4000;

/* ── Update sidebar-offset CSS var so FAB stays in sync with sidebar ── */
(function initFabCenterSync() {
  // FAB uses right:24px — clear any stale inline left on init AND resize.
  // Without the immediate clear, a leftover left:* style from older CSS
  // layers can persist until the first resize, offsetting the arrow icon.
  if (scrollFab) scrollFab.style.removeProperty('left');
  window.addEventListener('resize', () => {
    if (scrollFab) scrollFab.style.removeProperty('left');
  }, { passive: true });
})();

/* ── Helpers ── */
function isNearBottom() {
  const w = $('msgs-wrap');
  if (!w) return true;
  return (w.scrollHeight - w.scrollTop - w.clientHeight) <= SCROLL_THRESHOLD;
}

function showScrollFab() {
  if (!scrollFab) return;
  scrollFab.classList.add('visible');
  scrollFab.classList.remove('fab-inactive');
  _resetFabInactivityTimer();
}
function hideScrollFab() {
  if (!scrollFab) return;
  scrollFab.classList.remove('visible');
  scrollFab.classList.remove('fab-inactive');
  clearTimeout(_fabInactivityTimer);
  _fabUnreadCount = 0;
  _updateFabBadge();
}
function updateScrollFab() {
  if (isNearBottom()) { hideScrollFab(); } else { showScrollFab(); }
}

/* ── Inactivity auto-dim ── */
function _resetFabInactivityTimer() {
  clearTimeout(_fabInactivityTimer);
  if (!scrollFab) return;
  scrollFab.classList.remove('fab-inactive');
  if (scrollFab.classList.contains('visible') && _fabUnreadCount === 0) {
    _fabInactivityTimer = setTimeout(() => {
      if (scrollFab && scrollFab.classList.contains('visible')) {
        scrollFab.classList.add('fab-inactive');
      }
    }, FAB_INACTIVITY_MS);
  }
}

/* ── Badge ── */
function _updateFabBadge() {
  if (!scrollFabBadge) return;
  if (_fabUnreadCount > 0) {
    scrollFabBadge.textContent = _fabUnreadCount > 99 ? '99+' : String(_fabUnreadCount);
    scrollFabBadge.setAttribute('aria-label', `${_fabUnreadCount} unread message${_fabUnreadCount > 1 ? 's' : ''}`);
    if (!scrollFabBadge.classList.contains('has-unread')) {
      scrollFabBadge.style.animation = 'none';
      void scrollFabBadge.offsetWidth;
      scrollFabBadge.style.animation = '';
      scrollFabBadge.classList.add('has-unread');
    }
    if (scrollFab) {
      scrollFab.classList.remove('fab-inactive');
      clearTimeout(_fabInactivityTimer);
    }
  } else {
    scrollFabBadge.textContent = '';
    scrollFabBadge.setAttribute('aria-label', '');
    scrollFabBadge.classList.remove('has-unread');
  }
}

// BUG FIX: Added isNearBottom() as a secondary guard.
// When a new message is appended the sentinel momentarily leaves the
// viewport (before auto-scroll fires), so _userScrolledUp briefly
// flips true. Without the isNearBottom check, fabNotifyNewAIMessage
// would increment the badge even though the user is at the bottom.
// Dual-check (_userScrolledUp AND !isNearBottom) eliminates the race.
function fabNotifyNewAIMessage() {
  if (_userScrolledUp && !isNearBottom()) {
    _fabUnreadCount++;
    _updateFabBadge();
    if (scrollFab && !scrollFab.classList.contains('visible')) showScrollFab();
  }
}

/* ── IntersectionObserver (primary) ── */
(function initScrollFabObserver() {
  const sentinel   = document.getElementById('scroll-sentinel');
  const msgsWrapEl = document.getElementById('msgs-wrap');
  if (!sentinel || !msgsWrapEl || !scrollFab) return;

  // BUG FIX: The old guard `if (_ioRaf) return` silently dropped the
  // SECOND callback when two IO entries fired in quick succession (e.g.
  // sentinel going out-of-view then immediately back in-view as a new
  // message is appended + auto-scroll fires). This left _userScrolledUp
  // permanently true and the FAB stuck visible.
  // Fix: cancel any pending rAF and reschedule with the LATEST entry so
  // the final state always wins.
  let _ioRaf = null;
  let _ioLatestVisible = false;
  const obs = new IntersectionObserver(
    entries => {
      _ioLatestVisible = entries[entries.length - 1].isIntersecting;
      if (_ioRaf) cancelAnimationFrame(_ioRaf);
      _ioRaf = requestAnimationFrame(() => {
        _ioRaf = null;
        _userScrolledUp = !_ioLatestVisible;
        if (_ioLatestVisible) { hideScrollFab(); } else { showScrollFab(); }
      });
    },
    { root: msgsWrapEl, threshold: 0 }
  );
  obs.observe(sentinel);

  let _scrollRaf = null;
  msgsWrapEl.addEventListener('scroll', () => {
    if (_scrollRaf) return;
    _scrollRaf = requestAnimationFrame(() => {
      _scrollRaf = null;
      const near = isNearBottom();
      if (near && _userScrolledUp) {
        _userScrolledUp = false;
        hideScrollFab();
      } else if (!near && !_userScrolledUp) {
        _userScrolledUp = true;
        showScrollFab();
      }
      if (_userScrolledUp) _resetFabInactivityTimer();
    });
  }, { passive: true });
})();

/* ── Click handler ── */
if (scrollFab) {
  scrollFab.addEventListener('click', () => {
    _fabUnreadCount = 0;
    _updateFabBadge();
    _userScrolledUp = false;
    smoothScrollBottom();
    if (navigator.vibrate) navigator.vibrate(12);
  }, { passive: true });
  scrollFab.addEventListener('touchstart', () => {}, { passive: true });
}

/* ── scrollBottom / smoothScrollBottom ── */
function scrollBottom(force = false, smooth = true) {
  if (!force && _userScrolledUp) return;
  if (_scrollRafPending) return;
  _scrollRafPending = true;
  requestAnimationFrame(() => {
    _scrollRafPending = false;
    VML.scrollToBottom(smooth);
    setTimeout(updateScrollFab, 80);
  });
}
function smoothScrollBottom() {
  _userScrolledUp = false;
  VML.scrollToBottom(true);
  setTimeout(updateScrollFab, 500);
}

// ─── Smart Placeholder Chips ─────────────────────
// ── AI Suggestions removed — renderPlaceholderChips is a no-op ──
function renderPlaceholderChips() { /* removed */ }

// ─── Send Message ────────────────────────────────
// Guards: trims whitespace, blocks empty strings, blocks re-entrant sends,
// enforces max length, rejects null-byte injection.
// v19: uses State.isTyping (central state) + appendMessageToDOM (incremental render)
// RACE-CONDITION FIX [v23]: Added _sendLock flag as belt-and-suspenders guard
// alongside State.isTyping. This prevents the rare race where two rapid sends
// slip through between the isTyping setter and the first await in startGeneration.
let _sendLock = false;
const MSG_MAX_LENGTH = 16000; // ~4k tokens — reasonable single-message cap
function sendMessage(text) {
  if (typeof text !== 'string') {
    if (DEBUG) console.warn('[ZenQ:Send] sendMessage() called with non-string:', typeof text);
    return;
  }
  text = text.trim();
  // BUG FIX: Prepend active tool-mode prefix before sanitize so the backend sees it.
  // APP._toolPrefix is set by initToolPills() when the user activates a tool (e.g. Web Search,
  // Deep Think). Previously it was stored but NEVER injected into the outgoing message,
  // making all tool modes purely decorative with zero effect on AI behaviour.
  if (APP._toolPrefix) {
    text = APP._toolPrefix + text;
  }
  // IMPROVEMENT 6: sanitize() strips angle brackets / null bytes before any processing.
  // This is belt-and-suspenders on top of parseMarkdown()'s HTML-escaping — the first
  // line of defence at the point of user input.
  text = sanitize(text);
  // v19: check State.isTyping (canonical) instead of APP.isGenerating directly
  // v23: also check _sendLock for sub-frame race protection
  if (!text || State.isTyping || _sendLock) {
    if (DEBUG && (State.isTyping || _sendLock)) console.warn('[ZenQ:Send] Blocked — already generating or lock active');
    return;
  }
  // v32: Offline guard — block before attempting network call
  if (OfflineDetector.guard()) return;

  // v36: Guest 2-message trial — allow up to 2 sends without sign-in,
  // then show the AI gate to prompt account creation.
  if (!getAuthUser()) {
    const GUEST_MSG_LIMIT = 2;
    let _guestMsgCount = parseInt(sessionStorage.getItem('aura_guest_msgs') || '0', 10);
    if (_guestMsgCount >= GUEST_MSG_LIMIT) {
      showAIGate();
      return;
    }
    // Allow this send — increment counter
    sessionStorage.setItem('aura_guest_msgs', String(_guestMsgCount + 1));
    // Warn on the last free message
    if (_guestMsgCount + 1 >= GUEST_MSG_LIMIT) {
      toast('Last free message — sign in to continue chatting', 'warn', 3500);
    }
  }

  // FIX: Removed redundant APP.isGenerating check (already covered by State.isTyping above)
  // and removed duplicate OfflineDetector.guard() call (already called before guest block above).
  // Both extra checks caused the guest message counter to be consumed even when sends were blocked.

  // SECURITY: hard cap on message length to prevent backend abuse
  if (text.length > MSG_MAX_LENGTH) {
    toast(`Message too long (${text.length.toLocaleString()} / ${MSG_MAX_LENGTH.toLocaleString()} chars max)`, 'error', 4000);
    return;
  }
  // SECURITY: strip null bytes that can confuse downstream processing
  text = text.replace(/\0/g, '');

  if (DEBUG) console.log('[ZenQ:Send] Dispatching message →', { length: text.length, preview: text.slice(0, 80) + (text.length > 80 ? '...' : '') });
  
  // ── Auto-dismiss any open overlays when user sends ──
  if ($('sett-panel')?.classList.contains('on')) closeSettings();
  if ($('cmd-overlay')?.classList.contains('on')) closeCmd();
  if ($('voice-overlay')?.classList.contains('on')) closeVoice();
  
  _userScrolledUp = false;
  ZenQLogger.info('Chat', `Sending message (${text.length} chars)`);
  ZenQBus.emit('message:sent', { text, chatId: APP.activeChatId, len: text.length });

  if(!APP.activeChatId){
    createChat(text.slice(0,44)+(text.length>44?'…':''), autoCategory(text));
  } else {
    const chat = getChat();
    if(chat && chat.messages.length===0){
      chat.title = text.slice(0,44)+(text.length>44?'…':'');
      chat.category = autoCategory(text);
    }
  }

  const chat = getChat();
  // CRITICAL FIX [v26]: getChat() can return null if activeChatId was just set by createChat()
  // but APP.chats hasn't been populated yet (rare race). Guard before any property access.
  if (!chat) {
    ZenQLogger.error('Send', 'sendMessage: no active chat after createChat — aborting');
    _sendLock = false;
    return;
  }
  if (chat) chat.updatedAt = Date.now(); // FIX: was in broken window.sendMessage monkey-patch; moved here
  const uMsg = { id:genId(), role:'user', content:text, timestamp:Date.now() };
  chat.messages.push(uMsg);

  // IDB-primary: save individual message to IDB (unlimited — no cap)
  // MSG_HISTORY_CAP removed: IDB handles large histories efficiently.
  // Memory window is managed by VirtualMessageList; full history lives in IDB.
  ZenQDB.saveMessage(uMsg, chat.id).catch(() => {});
  // Update chat metadata (updatedAt, messageCount) in IDB
  ZenQDB.saveChat({
    id: chat.id, title: chat.title,
    createdAt: chat.createdAt, updatedAt: chat.updatedAt,
    category: chat.category || 'personal',
    pinned: chat.pinned || false, archived: chat.archived || false,
    messageCount: chat.messages.length,
  }).catch(() => {});
  save();

  const welcomeEl = $('welcome');
  if (welcomeEl) welcomeEl.style.display = 'none'; // FIX: null guard
  updateHeader();

  const msgListEl = $('msg-list');
  if (msgListEl) { // FIX: null guard
    // v20: Dedup guard — skip if this message ID is already in the DOM
    if (!msgListEl.querySelector(`[data-msg-id="${uMsg.id}"]`)) {
      // PRODUCTION FIX [v29]: Use createMessageElement() (component system) instead of
      // the old row.innerHTML = buildMsgHTML() pattern. This:
      //   (a) eliminates an extra DIV wrapper (row.firstElementChild was fragile)
      //   (b) keeps user-message render path identical to AI messages and renderMessages()
      //   (c) removes the explicit setAttribute fallback — createMessageElement already stamps it
      const msgEl = createMessageElement(uMsg);
      if (msgEl) msgListEl.appendChild(msgEl);
    }
  }
  scrollBottom(true);

  const msgTaEl = $('msg-ta');
  if (msgTaEl) { msgTaEl.value = ''; msgTaEl.style.height = 'auto'; } // FIX: null guard
  APP.attachedFiles = [];
  const attachedRowEl = $('attachedRow');
  if (attachedRowEl) attachedRowEl.innerHTML = ''; // FIX: null guard
  // Reset char counter
  const cc = $('inp-char-count'); if(cc) {cc.textContent=''; cc.className='inp-char-count';}
  updateSendBtn(); autosize();
  renderPlaceholderChips();
  if(APP.sounds) playPing();
  incrementUsage(); // track message for plan badge

  // RACE-CONDITION FIX [v23]: Set lock before async generation; always release in finally
  _sendLock = true;
  _pushMsgHistory(text);   // track in keyboard history (Ctrl+Up/Down)
  startGeneration(text).finally(() => { _sendLock = false; });
}

// ══════════════════════════════════════════════════
// BACKEND STREAMING — All models route through backend
// POST AURA_CONFIG.backendUrl  → SSE or JSON response
// Backend handles Gemini, OpenRouter, any provider.
// ══════════════════════════════════════════════════
// FIX: callGeminiStreaming and callOpenRouterStreaming were dead wrappers (just called
// callBackendStreaming directly). Replaced with thin named aliases so the ZenQCore
// 'API' module registration continues to work without dead function bodies.
const callGeminiStreaming     = (args) => callBackendStreaming(args);
const callOpenRouterStreaming = (args) => callBackendStreaming(args);
// callBackendFallback is a genuine public alias for API module compatibility
const callBackendFallback     = (args) => callBackendStreaming(args);

// ══════════════════════════════════════════════════
// FETCH INFRASTRUCTURE — Retry, Cache, Dedup
// ══════════════════════════════════════════════════

// ─── Exponential backoff fetch ───────────────────
async function fetchWithRetry(url, options, maxRetries = 3) {
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      const resp = await fetch(url, options);
      // Retry on 429 (rate limit) or 5xx (server error), but NOT on abort
      if ((resp.status === 429 || resp.status >= 500) && attempt < maxRetries) {
        const jitter  = Math.random() * 500;
        const backoff = Math.min(1000 * Math.pow(2, attempt), 10000) + jitter;
        ZenQLogger.warn('Fetch', `HTTP ${resp.status} — retrying in ${Math.round(backoff)}ms (attempt ${attempt + 1}/${maxRetries})`);
        await new Promise(r => setTimeout(r, backoff));
        continue;
      }
      return resp;
    } catch (err) {
      if (err.name === 'AbortError') throw err;  // Never retry aborted requests
      if (attempt === maxRetries) throw err;
      const jitter  = Math.random() * 500;
      const backoff = Math.min(1000 * Math.pow(2, attempt), 10000) + jitter;
      ZenQLogger.warn('Fetch', `Network error — retrying in ${Math.round(backoff)}ms (attempt ${attempt + 1}/${maxRetries}):`, err.message);
      await new Promise(r => setTimeout(r, backoff));
    }
  }
}

// ─── Response cache (model+message → reply, TTL 5 min) ─
const _responseCache = new Map();
const CACHE_TTL_MS   = 5 * 60 * 1000;
function _cacheKey(model, userText) {
  return `${model}::${userText.trim().slice(0, 512)}`;
}
function _cacheGet(model, userText) {
  const key = _cacheKey(model, userText);
  const entry = _responseCache.get(key);
  if (!entry) return null;
  if (Date.now() - entry.ts > CACHE_TTL_MS) { _responseCache.delete(key); return null; }
  return entry.text;
}
function _cacheSet(model, userText, text) {
  if (!text || text.length < 10) return;   // Don't cache empty/error replies
  const key = _cacheKey(model, userText);
  _responseCache.set(key, { text, ts: Date.now() });
  // Limit cache size to 50 entries (LRU-lite)
  if (_responseCache.size > 50) {
    const firstKey = _responseCache.keys().next().value;
    _responseCache.delete(firstKey);
  }
}

// ─── In-flight request deduplication ─────────────
const _inFlightRequests = new Map();
function _dedupKey(model, userText) { return _cacheKey(model, userText); }

async function callBackendStreaming({ model, history, userText, sysPrompt, mc, aiMsg, scrollBottom: _scrollBottomFn, signal: _callerSignal }) {
  // BUG FIX [v28]: Accept abort signal as an explicit parameter instead of reading
  // _localAbort from startGeneration's closure. Outer-scope variable access creates
  // invisible coupling — if this function is ever called from a different code path,
  // it silently gets undefined for _localAbort and ignores the abort signal entirely.
  // BUG FIX [v26]: renamed parameter to _scrollBottomFn to avoid shadowing the outer scrollBottom function.
  // Falls back to the outer scrollBottom if caller passes undefined.
  const _scroll = (typeof _scrollBottomFn === 'function') ? _scrollBottomFn : scrollBottom;
  // DOM safety — bail early if critical nodes missing
  if (!mc) {
    console.error('[ZenQ:API] callBackendStreaming: mc (message content node) is null — aborting');
    return '';
  }

  // BUG FIX [v38-H1+H3]: Declare accumulated, cursorEl, and scheduleRender HERE —
  // BEFORE any conditional branching. Previously they were declared after the
  // cache-hit block, so the cache-hit typewriter path read `accumulated` as
  // undefined (prepending "undefined" to the first character), and used an
  // undefined `cursorEl` causing a crash in /* cursor removed */.
  let accumulated = '';
  let fullText = '';
  let _renderScheduled = false;
  let _lastRenderedAccumulated = '';
  let _lastRenderedHTML = '';

  // cursorEl removed — no blinking cursor at end of AI response

  function scheduleRender() {
    if (_renderScheduled) return;
    _renderScheduled = true;
    requestAnimationFrame(() => {
      _renderScheduled = false;
      if (!mc.isConnected) return;

      // DOTS FIX: Never overwrite mc when accumulated is empty.
      // The fakeAI path calls scheduleRender() immediately before the first token,
      // which would call parseMarkdown('') = '' and wipe the bouncing dots —
      // making them invisible before any text is shown. Guard here is the fix.
      if (!accumulated) return;

      // Only re-parse + re-render when accumulated text actually changed
      if (accumulated !== _lastRenderedAccumulated) {
        _lastRenderedHTML = parseMarkdown(accumulated);
        _lastRenderedAccumulated = accumulated;
        mc.innerHTML = _lastRenderedHTML;
      }

      // JUMP FIX: Scroll in the SAME rAF frame immediately after innerHTML is
      // updated. The previous path called scrollBottom() which queued TWO more
      // rAFs (scrollBottom → VML.scrollToBottom → rAF). By the time that
      // third rAF fired, scrollHeight had already changed again (next token
      // arrived), so the scroll landed short → content appeared to jump up.
      // Reading scrollHeight right here gives the freshest value after render.
      if (!_userScrolledUp) {
        const _w = document.getElementById('msgs-wrap');
        if (_w) _w.scrollTop = _w.scrollHeight;
      }
    });
  }

  // BUG FIX [v38-CRITICAL]: _dk MUST be declared here — BEFORE the fakeAI block.
  // Previously it was declared after the fakeAI block (line ~15574), putting it in
  // the Temporal Dead Zone when the fakeAI path ran. Every response with fakeAI:true
  // crashed with "ReferenceError: Cannot access '_dk' before initialization".
  const _dk = _dedupKey(model, userText);

  // ── Deduplication guard — block identical in-flight request ─
  if (_inFlightRequests.has(_dk)) {
    ZenQLogger.warn('API', 'Duplicate in-flight request blocked:', _dk.slice(0, 60));
    if (mc) mc.innerHTML = `<div class="msg-error-bubble">${parseMarkdown('⚠️ **Duplicate request.** Please wait for the current response.')}</div>`;
    return '';
  }
  _inFlightRequests.set(_dk, true);

  // ── Cache hit — return without hitting backend ────────────
  const _cached = _cacheGet(model, userText);
  if (_cached && !_callerSignal?.aborted) {
    ZenQLogger.info('API', 'Cache hit — replaying cached response');
    _inFlightRequests.delete(_dk);
    // Animate cached response through typewriter for UX consistency
    let charIdx = 0; const chunkSize = 8;
    await new Promise(resolve => {
      function writeChunk() {
        if (APP.stopRequested) { resolve(); return; }
        for (let i = 0; i < chunkSize && charIdx < _cached.length; i++, charIdx++) {
          accumulated += _cached[charIdx];
        }
        scheduleRender();
        if (charIdx < _cached.length) { APP._streamRafId = requestAnimationFrame(writeChunk); }
        else resolve();
      }
      APP._streamRafId = requestAnimationFrame(writeChunk);
    });
    return _cached;
  }

  // ══════════════════════════════════════════════════════════════════
  // FAKE AI — streams a mock reply instead of hitting the backend.
  // Toggle on/off at runtime: AURA_CONFIG.fakeAI = false in console.
  // Default is true so the app works with no backend.
  // ══════════════════════════════════════════════════════════════════
  if (AURA_CONFIG.fakeAI !== false) {
    const _fakeReplies = [
      `Hello! I'm **ZenQ** \u2014 your intelligent assistant. How can I help you today? \uD83D\uDE0A`,
      `That's a great question! Here's what I think:\n\n- **Point one:** Start simple and iterate.\n- **Point two:** Keep your goals clear.\n- **Point three:** Always test your assumptions.\n\nWould you like me to go deeper on any of these?`,
      `Sure! Here's a quick example in JavaScript:\n\n\`\`\`js\nfunction greet(name) {\n  return \`Hello, \${name}! \uD83D\uDC4B\`;\n}\nconsole.log(greet('World'));\n\`\`\`\n\nLet me know if you'd like me to explain it.`,
      `I understand. Let me think about that...\n\nBased on what you've shared, I'd suggest taking a step back and considering the bigger picture. Sometimes the simplest solution is the most effective one. What do you think?`,
      `Absolutely! Here are some ideas:\n\n1. **Option A** \u2014 Quick and easy, good for prototyping.\n2. **Option B** \u2014 More robust, better for production.\n3. **Option C** \u2014 Balanced approach, works well in most cases.\n\nWhich one sounds most relevant to your situation?`,
      `Great choice! \uD83D\uDE80 This approach is widely used because it balances **performance** and **readability**. Starting with the basics and building up complexity only when needed is usually the right call.`,
      `Hmm, that's an interesting problem. Let me break it down:\n\n> The core issue seems to be around state management.\n\nOnce you resolve that, everything else should fall into place. Want me to walk through a solution step by step?`,
    ];
    const _idx = (userText.length + (userText.charCodeAt(0) || 0)) % _fakeReplies.length;
    const _fakeText = _fakeReplies[_idx];
    // ── ChatGPT-style word-by-word streaming ──────────────────────────────
    // Split on whitespace boundaries so each "token" is a word or space,
    // producing the natural left-to-right word-at-a-time feel of ChatGPT.
    const _fakeTokens = _fakeText.match(/\S+|\s+/g) || [];
    let _fti = 0;
    // DOTS FIX: removed premature scheduleRender() here — it was a vestige of
    // the blinking cursor feature (now removed). With accumulated='' it called
    // mc.innerHTML='' and wiped the bouncing dots before the first word appeared.
    await new Promise(resolve => {
      function _writeToken() {
        if (APP.stopRequested) { resolve(); return; }
        if (_fti >= _fakeTokens.length) { resolve(); return; }

        const token = _fakeTokens[_fti++];
        accumulated += token;
        scheduleRender();

        if (_fti < _fakeTokens.length) {
          // Pure whitespace tokens render instantly; words get a natural delay
          const isSpace = /^\s+$/.test(token);
          // Vary speed: short words fast, longer words slightly slower, random jitter
          const wordLen = token.trim().length;
          const base    = isSpace ? 0 : Math.max(18, Math.min(45, wordLen * 4));
          const jitter  = isSpace ? 0 : Math.floor(Math.random() * 18);
          APP._streamRafId = setTimeout(_writeToken, base + jitter);
        } else {
          resolve();
        }
      }
      // Small initial pause like GPT "thinking" before first word
      APP._streamRafId = setTimeout(_writeToken, 100);
    });
    _inFlightRequests.delete(_dk);
    return _fakeText;
  }
  // ── END FAKE AI ─────────────────────────────────────────────────

  const url = AURA_CONFIG.backendUrl;
  const payload = {
    message: userText,
    model,
    history: history.map(m => ({ role: m.role, content: m.content })),
    stream: true,
    ...(sysPrompt && { systemPrompt: sysPrompt }),
  };

  // ── Debug: log outbound request ───────────────────
  if (DEBUG) {
    console.log('[ZenQ:API] → Request', {
      url,
      model,
      historyLength: history.length,
      messagePreview: userText.slice(0, 100),
      ts: new Date().toISOString(),
    });
  }

  let resp;
  try {
    // ── v22: Attach Firebase ID token to every backend request ──
    const authHeaders = {};
    const fbToken = await getIdToken().catch(() => null);
    if (fbToken) {
      authHeaders['Authorization'] = 'Bearer ' + fbToken;
    }

    resp = await fetchWithRetry(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'text/event-stream, application/json',
        'X-ZenQ-Version': AURA_CONFIG.version,
        ...authHeaders,
      },
      body: JSON.stringify(payload),
      signal: _callerSignal || undefined,
    }, 3); // up to 3 retries with exponential backoff
  } catch(fetchErr) {
    _inFlightRequests.delete(_dk);
    if (fetchErr.name === 'AbortError') throw fetchErr;
    // Network-level failure → try health check to give better error
    console.error('[ZenQ:API] ✗ Fetch failed after retries:', fetchErr.message);
    const healthy = await checkBackendHealth().catch(() => false);
    const hint = healthy
      ? 'Backend reachable but request failed.'
      : 'Cannot reach the server. Check your connection.';
    const msg = `⚠️ **Connection error.** ${hint}`;
    mc.innerHTML = `<div class="msg-error-bubble">${parseMarkdown(msg)}</div>`;
    aiMsg.content = msg; save(); _inFlightRequests.delete(_dk);
    // v32: Show dismissible banner with retry option
    showApiError(hint, { retryFn: () => startGeneration(userText) });
    return '';
  }

  if (DEBUG) {
    console.log('[ZenQ:API] ← Response', {
      status: resp.status,
      contentType: resp.headers.get('content-type'),
      ok: resp.ok,
    });
  }

  if (!resp.ok) {
    let errMsg = `Server error (${resp.status})`;
    try { const d = await resp.json(); errMsg = d.error || d.message || errMsg; } catch(e) {}
    if (resp.status === 401 || resp.status === 403) {
      errMsg = '**Session expired.** Please sign in again.';
      // v32: Show auth banner with sign-in button
      showApiError('Your session has expired.', { authRequired: true });
    }
    else if (resp.status === 429) errMsg = '**Rate limit reached.** Please wait a moment.';
    else if (resp.status === 503) errMsg = '**Backend unavailable.** Server may be starting up — retry in a moment.';
    else if (resp.status >= 500) errMsg = `**Server error (${resp.status}).** Backend temporarily unavailable.`;
    console.error(`[ZenQ:API] ✗ HTTP ${resp.status}:`, errMsg);
    const msg = `⚠️ ${errMsg}`;
    mc.innerHTML = `<div class="msg-error-bubble">${parseMarkdown(msg)}</div>`;
    aiMsg.content = msg; save(); return '';
  }

  const contentType = resp.headers.get('content-type') || '';
  const isSSE = contentType.includes('text/event-stream');

  // ── Smooth streaming helpers ───────────────────────
  const SPEED_MAP = { slow: 40, normal: 12, fast: 4, instant: 0 };
  const charDelay = SPEED_MAP[APP.typingSpeed] ?? 12;
  // NOTE: accumulated, cursorEl, and scheduleRender are declared at the top of
  // callBackendStreaming (before the cache-hit branch) so they are always initialised.
  // BUG FIX [v38-H1+H3]: removed duplicate declarations that were previously here.

  if (isSSE) {
    // ── SSE streaming path ─────────────────────────
    if (DEBUG) console.log('[ZenQ:API] ⚡ SSE stream started');
    const reader = resp.body.getReader();
    const decoder = new TextDecoder();
    let buf = '';

    // OPT: Stream timeout — abort if no data arrives for 60s (zombie stream guard)
    const STREAM_TIMEOUT_MS = 60000;
    let _streamTimeoutHandle = null;
    const _resetStreamTimeout = () => {
      clearTimeout(_streamTimeoutHandle);
      _streamTimeoutHandle = setTimeout(() => {
        if (!APP.stopRequested) {
          ZenQLogger.warn('Stream', 'SSE timeout after 60s — cancelling reader');
          APP.stopRequested = true;
          reader.cancel().catch(() => {});
        }
      }, STREAM_TIMEOUT_MS);
    };
    _resetStreamTimeout();

    while (true) {
      if (APP.stopRequested) { reader.cancel().catch(() => {}); break; }
      const { done, value } = await reader.read();
      if (done) break;
      _resetStreamTimeout(); // reset timer on each chunk

      buf += decoder.decode(value, { stream: true });
      const lines = buf.split('\n');
      buf = lines.pop(); // keep partial line

      for (const line of lines) {
        if (!line.startsWith('data: ')) continue;
        const raw = line.slice(6).trim();
        if (!raw || raw === '[DONE]') continue;
        try {
          const parsed = JSON.parse(raw);
          // Support Gemini, OpenAI-compatible, and plain {text} formats
          const chunk =
            parsed?.candidates?.[0]?.content?.parts?.[0]?.text ||
            parsed?.choices?.[0]?.delta?.content ||
            parsed?.delta?.text ||
            parsed?.text ||
            parsed?.content ||
            '';
          if (chunk) {
            fullText += chunk;
            accumulated += chunk;
            scheduleRender();
            // OPT: No per-chunk await in SSE path — rAF batching is the correct throttle.
            // Adding setTimeout here serializes chunks, degrading streaming throughput.
            // charDelay only applies to the typewriter animation for non-SSE responses below.
          }
        } catch(e) { /* partial JSON, skip */ }
      }
    }
    clearTimeout(_streamTimeoutHandle); // OPT: Clean up timer on normal completion

  } else {
    // ── JSON response path (non-streaming fallback) ─
    let data;
    try { data = await resp.json(); } catch(e) {
      console.error('[ZenQ:API] ✗ Failed to parse JSON response:', e.message);
      mc.innerHTML = `<div class="msg-error-bubble">${parseMarkdown('⚠️ **Invalid backend response.** Expected JSON or SSE.')}</div>`;
      aiMsg.content = ''; save(); return '';
    }
    if (DEBUG) console.log('[ZenQ:API] ← JSON payload keys:', Object.keys(data || {}));
    const replyText = data?.reply || data?.content || data?.text || data?.message || '';
    if (!replyText || replyText.trim().length === 0) {
      console.warn('[ZenQ:API] ⚠ Empty response — API returned 0 chars');
      const fallback = 'No response from AI. Please try again.';
      mc.innerHTML = `<div class="msg-error-bubble">${parseMarkdown('⚠️ ' + fallback)}</div>`;
      aiMsg.content = fallback; save(); return '';
    }

    // Typewriter animation for JSON responses
    if (charDelay === 0) {
      accumulated = replyText;
      mc.innerHTML = parseMarkdown(replyText);
    } else {
      let charIdx = 0;
      const chunkSize = charDelay <= 4 ? 10 : 5;
      await new Promise(resolve => {
        function writeChunk() {
          if (APP.stopRequested) { resolve(); return; }
          for (let i = 0; i < chunkSize && charIdx < replyText.length; i++, charIdx++) {
            accumulated += replyText[charIdx];
          }
          scheduleRender();
          if (charIdx < replyText.length) {
            APP._streamRafId = requestAnimationFrame(writeChunk);
          } else { resolve(); }
        }
        APP._streamRafId = requestAnimationFrame(writeChunk);
      });
    }
    fullText = replyText;
  }

  // Final clean render — remove cursor
  if (accumulated || fullText) {
    const final = fullText || accumulated;
    if (DEBUG) {
      console.log('[ZenQ:API] ✓ Response complete', {
        chars: final.length,
        mode: isSSE ? 'SSE' : 'JSON',
        preview: final.slice(0, 120) + (final.length > 120 ? '...' : ''),
      });
    }
    mc.innerHTML = parseMarkdown(final);
    _scroll(false);
    _cacheSet(model, userText, final);   // store in response cache
    _inFlightRequests.delete(_dk);       // release dedup lock
    return final;
  }

  // SSE stream ended but produced zero chars
  console.warn('[ZenQ:API] ⚠ SSE stream completed with 0 chars — empty response from AI');
  const emptyFallback = 'No response from AI. Please try again.';
  mc.innerHTML = `<div class="msg-error-bubble">${parseMarkdown('⚠️ ' + emptyFallback)}</div>`;
  if (aiMsg) { aiMsg.content = emptyFallback; save(); }
  _inFlightRequests.delete(_dk);
  return '';
}

// ─── AI Generation (Backend) ─────────────────────
// FIXED: stopBtn captured at script parse time — safe because <script> is at end of <body>
// but we additionally use getStopBtn() for any internal call that runs after DOM mutations.
// The `on()` helper already null-checks the element, so this is always safe.
function getStopBtn() { return $('stop-btn'); }
const stopBtn = $('stop-btn'); // kept for ZenQCore 'Chat' module external reference
on(stopBtn, 'click', () => {
  APP.stopRequested = true;
  if (APP._abortController) { APP._abortController.abort(); APP._abortController = null; }
  if (APP._streamRafId) { cancelAnimationFrame(APP._streamRafId); APP._streamRafId = null; }
});

async function startGeneration(userText) {
  if (!userText || typeof userText !== 'string') {
    ZenQLogger.error('Gen', 'Invalid input to startGeneration');
    return;
  }

  ZenQLogger.info('Gen', `Starting generation, model: ${State.currentModel}, mode: ${APP.aiMode}`);
  ZenQBus.emit('generation:start', { model: State.currentModel, mode: APP.aiMode });

  // v20: Capture active chat ID snapshot — race condition guard.
  // If the user switches chats while the AI is generating, we discard
  // the response so it doesn't land in the wrong conversation.
  const _chatIdSnapshot = APP.activeChatId;

  // v20: Use canonical State.isTyping setter — syncs all UI in one place
  State.isTyping = true;
  showTypingIndicator(); // v20: body.loading class for global loading state
  // CRITICAL FIX [v26]: Snapshot the AbortController at call-site to prevent race where
  // stopGeneration() nulls APP._abortController between here and the fetch() call.
  APP.stopRequested = false;
  APP._abortController = new AbortController();
  const _localAbort = APP._abortController; // stable local ref
  updateSendBtn();
  // AUTO-SCROLL: reset user-scroll-up flag so new AI output auto-scrolls
  _userScrolledUp = false;

  // ── Build typing indicator row — DOTS IMMEDIATELY ──────────────────
  // DOTS VISIBILITY FIX: Show the bouncing dots right away.
  // The old skeleton → dissolve → dots sequence had 920ms of non-dot animation
  // before the dots appeared, then dots showed for only ~32ms before typRow
  // was removed. Users never actually saw the dots. Now:
  //   • typRow shows dots immediately (visible while API call is in-flight)
  //   • When aiNode replaces typRow, mc.innerHTML also starts as dots
  //   • scheduleRender() won't clear dots until the first real token arrives
  const typRow = document.createElement('div');
  typRow.id = 'typing-row';
  typRow.className = 'msg-row ai';
  typRow.setAttribute('aria-label', 'ZenQ is typing');
  typRow.setAttribute('aria-live', 'polite');
  typRow.innerHTML = `<div class="msg-av" aria-hidden="true"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></div>
    <div class="msg-body">
      <div class="msg-bubble" style="min-width:64px">
        <div class="ai-typing-dots" aria-hidden="true" aria-label="ZenQ is thinking">
          <span class="atd"></span><span class="atd"></span><span class="atd"></span>
        </div>
      </div>
    </div>`;

  const msgList = $('msg-list');
  if (msgList) msgList.appendChild(typRow);
  scrollBottom(true);
  // Let the browser paint the dots for at least two frames before continuing.
  // Without this rAF, synchronous JS immediately removes typRow before the
  // browser composites the dots to screen — making them invisible on all devices.
  await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)));
  // 3-second thinking delay — dots are fully visible and bouncing during this wait.
  // Stop button works during this delay (APP.stopRequested is checked below).
  await new Promise(r => setTimeout(r, 3000));

  if (APP.stopRequested) {
    typRow.isConnected && typRow.remove();
    APP.isGenerating = false; getStopBtn()?.classList.remove('visible'); updateSendBtn();
    toast('Generation stopped', 'info'); return;
  }

  const chat = getChat();
  if (!chat) {
    typRow.isConnected && typRow.remove();
    APP.isGenerating = false; getStopBtn()?.classList.remove('visible'); updateSendBtn();
    ZenQLogger.error('Gen', 'startGeneration: no active chat');
    return;
  }

  // ── Create AI message record ──────────────────────
  const aiMsg = { id: genId(), role: 'assistant', content: '', timestamp: Date.now() };
  chat.messages.push(aiMsg);

  // IDB-primary: removed in-memory 200-msg trim — VML handles render window;
  // full history lives in IDB with no cap for 100k+ message support.
  save();

  // Insert AI row into DOM
  // PRODUCTION FIX [v29]: Replace innerHTML+firstElementChild with createMessageElement().
  // The old pattern could silently return null if buildMsgHTML produced unexpected HTML,
  // causing the entire streaming flow to continue with a null aiNode — no visible error,
  // but all subsequent querySelector('.msg-bubble') calls crashed silently.
  const aiNode = createMessageElement({ ...aiMsg });
  typRow.isConnected && typRow.remove();
  if (msgList) msgList.appendChild(aiNode);
  // Hide actions during streaming — revealed on generation complete
  if (aiNode) aiNode.dataset.streaming = 'true';
  scrollBottom(true);

  const bubble = aiNode?.querySelector('.msg-bubble');
  const mc     = bubble?.querySelector('.mc');

  if (!bubble || !mc) {
    ZenQLogger.error('Gen', 'startGeneration: message DOM nodes not found');
    // FIXED: use getStopBtn() helper instead of potentially-null top-level stopBtn const
    APP.isGenerating = false; getStopBtn()?.classList.remove('visible'); updateSendBtn();
    return;
  }

  // BUG FIX: Show typing dots in the AI bubble while waiting for the first streaming chunk.
  // Previously the bubble was empty (blank flash) between typRow removal and first rAF render.
  // scheduleRender() overwrites mc.innerHTML on the first chunk, clearing these dots automatically.
  // BUG FIX: matched structure/class to the typRow dots so alignment is identical.
  mc.innerHTML = '<div class="ai-typing-dots" aria-hidden="true" aria-label="ZenQ is typing"><span class="atd"></span><span class="atd"></span><span class="atd"></span></div>';

  // ── Helper: render error inside bubble with retry ──
  function showError(msg, retryFn) {
    aiMsg.content = msg;
    const retryBtn = retryFn
      ? `<button class="msg-retry-btn" id="retryBtn_${aiMsg.id}">
           <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" aria-hidden="true"><polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 1 0 .49-3.25"/></svg>
           Retry
         </button>`
      : '';
    mc.innerHTML = `<div class="msg-error-bubble">${parseMarkdown(msg)}${retryBtn}</div>`;
    if (retryFn) {
      const btn = mc.querySelector(`#retryBtn_${aiMsg.id}`);
      if (btn) btn.addEventListener('click', () => {
        // Remove this AI message and retry
        const idx = chat.messages.indexOf(aiMsg);
        if (idx !== -1) chat.messages.splice(idx, 1);
        save();
        aiNode.remove();
        retryFn();
      });
    }
    save(); scrollBottom(true);
    APP.isGenerating = false; getStopBtn()?.classList.remove('visible'); updateSendBtn();
  }

  // ── Frontend rate-limit guard ─────────────────────
  const NOW = Date.now();
  if (APP._lastSendTime && NOW - APP._lastSendTime < 800) {
    toast('Sending too fast — please wait a moment', 'warn');
    // BUG FIX: State.isTyping was already set true above; this early return bypasses the
    // finally block, permanently locking the UI. Must clean up explicitly before returning.
    typRow.isConnected && typRow.remove();
    State.isTyping = false;
    hideTypingIndicator();
    return;
  }
  APP._lastSendTime = NOW;

  // ── Build history for context (exclude empty aiMsg) ─
  const history = chat.messages
    .slice(0, -1)
    .map(m => ({ role: m.role, content: m.content }));

  // ── System prompt ──────────────────────────────────
  let sysPrompt = APP.systemPrompt || '';
  if (APP._aiLangPrefix) sysPrompt = APP._aiLangPrefix + sysPrompt;

  // ── Provider & model resolution ───────────────────
  const providerCfg = AI_PROVIDERS[APP.activeAiModel] || AI_PROVIDERS['gemini-flash'];
  const { provider, model: resolvedModel } = providerCfg;

  // ── Real AI call dispatcher — all via backend ──────
  let replyText = '';
  try {
    if (DEBUG) console.log('[ZenQ:Gen] Starting generation →', { model: resolvedModel, provider, historyLen: history.length });
    // All models now go through backend regardless of provider config
    // BUG FIX [v28]: pass signal explicitly so callBackendStreaming doesn't rely on outer-scope _localAbort
    replyText = await callBackendStreaming({ model: resolvedModel, history, userText, sysPrompt, mc, aiMsg, scrollBottom, signal: _localAbort?.signal });

    // v20: Race condition guard — discard if user switched chats during generation.
    // The response is silently dropped; the user sees whatever is in the new chat.
    if (APP.activeChatId !== _chatIdSnapshot) {
      ZenQLogger.warn('Gen', 'Chat switched mid-generation — response discarded to prevent wrong-chat injection');
      aiNode?.remove();
      // Clean up the dangling aiMsg that was already pushed
      const staleChat = APP.chats[_chatIdSnapshot];
      if (staleChat) {
        staleChat.messages = staleChat.messages.filter(m => m.id !== aiMsg.id);
        save();
      }
      return;
    }

    if (APP.stopRequested && !replyText) {
      aiMsg.content = '*(generation stopped)*';
      mc.innerHTML = parseMarkdown(aiMsg.content);
    } else if (replyText) {
      aiMsg.content = replyText;
      mc.innerHTML = parseMarkdown(replyText);
    }

    save(); scrollBottom(true);
    // Persist completed AI message to IDB (non-blocking)
    if (replyText && chat) {
      ZenQDB.saveMessage(aiMsg, chat.id).catch(() => {});
      ZenQDB.saveChat({
        id: chat.id, title: chat.title,
        createdAt: chat.createdAt, updatedAt: Date.now(),
        category: chat.category || 'personal',
        pinned: chat.pinned || false, archived: chat.archived || false,
        messageCount: chat.messages.length,
      }).catch(() => {});
    }
    ZenQLogger.info('Gen', `Generation complete — ${replyText.length} chars, provider: ${provider}`);
    ZenQBus.emit('generation:done', { chars: replyText.length, provider, model: resolvedModel });
    if (DEBUG) console.log(`[ZenQ:Gen] ✓ Done — ${replyText.length} chars returned`);
    if (APP.sounds && !APP.stopRequested) playPing();
    if (APP.stopRequested) toast('Generation stopped', 'info');

  } catch (err) {
    ZenQLogger.error('Gen', 'Generation error:', err?.message || err);
    console.error('[ZenQ:Gen] ✗ Caught error:', err?.name, err?.message);

    if (err.name === 'AbortError') {
      const stopped = APP.stopRequested;
      if (!replyText) {
        aiMsg.content = stopped ? '*(generation stopped)*' : '*(request cancelled)*';
        mc.innerHTML = parseMarkdown(aiMsg.content);
        save();
      }
      if (stopped) toast('Generation stopped', 'info');
    } else if (err.name === 'TypeError' && (err.message.includes('fetch') || err.message.includes('Failed to fetch') || err.message.includes('NetworkError'))) {
      console.error('[ZenQ:Gen] ✗ Network error — backend unreachable:', AURA_CONFIG.backendUrl);
      const netMsg = `⚠️ **Network error.** Could not reach the server. Please check your connection and try again.`;
      showError(netMsg, () => startGeneration(userText));
      toast('Network error — check backend server', 'error', 4000);
    } else {
      const errMsg = '⚠️ **Unexpected error.** ' + (err.message || 'Please try again.');
      showError(errMsg, () => startGeneration(userText));
      toast('An error occurred', 'error', 4000);
    }
  } finally {
    // Reveal AI message actions now that streaming is complete
    if (aiNode) delete aiNode.dataset.streaming;
    // v20: remove body.loading class — mirrors showTypingIndicator above
    hideTypingIndicator();
    // v19: State.isTyping setter handles stop-btn, sendBtn, aria-busy cleanup
    State.isTyping = false;
    APP._abortController = null;
    APP._streamRafId = null;
    // Release any dedup lock that may have been held for this request
    const _dk2 = typeof _dedupKey === 'function' ? _dedupKey(resolvedModel, userText) : null;
    if (_dk2) _inFlightRequests.delete(_dk2);
  }
}

// ─── Regenerate ──────────────────────────────────
function regenerate() {
  const chat=getChat(); if(!chat||APP.isGenerating) return;
  // findLastIndex polyfill for older browsers
  let li = -1;
  for(let i=chat.messages.length-1; i>=0; i--){ if(chat.messages[i].role==='assistant'){ li=i; break; } }
  if(li===-1) return;
  chat.messages.splice(li,1); save();
  const aiNodes=qsa('.msg-row.ai');
  if(aiNodes.length) aiNodes[aiNodes.length-1].remove();
  const lastUser = [...chat.messages].reverse().find(m=>m.role==='user');
  if(!lastUser) return;
  toast('Regenerating…','info');
  startGeneration(lastUser.content);
}

// ─── Input ───────────────────────────────────────
// IMPROVED: Captured at script parse time (safe — script is at bottom of <body>).
// Both elements are required; updateSendBtn() guards against null internally.
const msgTa = $('msg-ta');
const sendBtnEl = $('send-btn');

function updateSendBtn(){
  // FIXED: early return if either element is missing (prevents crash in edge cases)
  if (!msgTa || !sendBtnEl) return;
  if (APP.isGenerating) {
    // Streaming: button is ENABLED so user can click to stop
    sendBtnEl.disabled = false;
    sendBtnEl.setAttribute('aria-disabled', 'false');
    sendBtnEl.classList.add('streaming');
    sendBtnEl.setAttribute('title', 'Stop generation');
    sendBtnEl.setAttribute('aria-label', 'Stop AI generation');
  } else {
    const hasText = msgTa.value.trim().length > 0;
    sendBtnEl.disabled = !hasText;
    sendBtnEl.setAttribute('aria-disabled', String(!hasText));
    sendBtnEl.classList.remove('streaming');
    sendBtnEl.setAttribute('title', 'Send message');
    sendBtnEl.setAttribute('aria-label', 'Send message');
  }
}

// FIXED: Guard against updatePlanBadge being called before its definition.
// The function is defined later in the plan system block. This shim prevents
// a ReferenceError if execution order ever changes.
if (typeof updatePlanBadge === 'undefined') {
  window.updatePlanBadge = function() {
    if (typeof updatePlanUI === 'function') updatePlanUI();
  };
}

// ── v20: Global loading state helpers ───────────────────────────────────
// body.loading provides a CSS hook for any element that needs to react
// to the in-flight API state (spinner overlays, disabled states, etc.)
function showTypingIndicator() {
  document.body.classList.add('loading'); document.body.classList.add('streaming');
  if (sendBtnEl) {
    sendBtnEl.disabled = false; // ENABLED so user can click to stop
    sendBtnEl.classList.add('streaming'); // v36+: show stop icon
  }
}
function hideTypingIndicator() {
  document.body.classList.remove('loading'); document.body.classList.remove('streaming');
  if (sendBtnEl) {
    sendBtnEl.classList.remove('streaming'); // restore send arrow
    updateSendBtn(); // re-evaluate enabled/disabled based on textarea
  }
}

// JUMP FIX: Use height:'1px' instead of height:'auto'.
// height:auto forces the browser to re-layout the textarea's parent
// chain to determine intrinsic height, which triggers a ResizeObserver
// callback → _applyFrame → paddingBottom change → visible jump.
// height:'1px' collapses the textarea to a known size; scrollHeight then
// reports overflow content height correctly without touching the parent.
function autosize() {
  if (!msgTa) return;
  requestAnimationFrame(()=>{
    msgTa.style.height = '1px';
    const maxH = window.innerWidth < 769 ? 140 : 180;
    const h = Math.min(msgTa.scrollHeight, maxH);
    msgTa.style.height = h+'px';
  });
}

on(msgTa, 'input', ()=>{ 
  if (!msgTa || !sendBtnEl) return;
  updateSendBtn(); 
  autosize();
  const val = msgTa.value.trim();
  // BUG FIX: Do NOT create a chat when the user starts typing — only sendMessage() should do that.
  // Previously, typing on the welcome screen immediately called createChat() with partial text,
  // so clearing the textarea left the user stranded in an empty chat with no welcome screen.
  // Now we only hide/show the welcome screen based on whether there is any input text.
  const welcomeEl = $('welcome');
  if (val && welcomeEl && welcomeEl.style.display !== 'none') {
    // User started typing → hide welcome (chat will be created when they actually send)
    welcomeEl.style.display = 'none';
  } else if (!val && !APP.activeChatId && welcomeEl && welcomeEl.style.display === 'none') {
    // User cleared the textarea and no chat is active → restore welcome screen
    welcomeEl.style.display = 'flex';
  }
  // ── Char counter handled by initWordCount() below ──
});

// ─── Keyboard History (ChatGPT-style Ctrl+Up/Down) ───
// Tracks sent messages for inline textarea history navigation.
const _msgHistory  = [];      // ring buffer of sent messages
const _MAX_HISTORY = 50;
let   _historyIdx  = -1;      // -1 = not navigating
let   _historyDraft = '';     // draft saved before navigation begins

function _pushMsgHistory(text) {
  if (!text || text === _msgHistory[_msgHistory.length - 1]) return;
  _msgHistory.push(text);
  if (_msgHistory.length > _MAX_HISTORY) _msgHistory.shift();
  _historyIdx = -1;
}

on(msgTa, 'keydown', e=>{
  if (!msgTa || !sendBtnEl) return;
  // Ignore IME composition events (CJK input, etc.)
  if (e.isComposing || e.keyCode === 229) return;

  // ── Ctrl+↑ / ⌘+↑ → scroll back through sent history ──
  if ((e.ctrlKey || e.metaKey) && e.key === 'ArrowUp') {
    e.preventDefault();
    if (_msgHistory.length === 0) return;
    if (_historyIdx === -1) {
      _historyDraft = msgTa.value;
      _historyIdx   = _msgHistory.length - 1;
    } else if (_historyIdx > 0) {
      _historyIdx--;
    }
    msgTa.value = _msgHistory[_historyIdx];
    requestAnimationFrame(() => {
      msgTa.selectionStart = msgTa.selectionEnd = msgTa.value.length;
    });
    autosize(); updateSendBtn();
    return;
  }

  // ── Ctrl+↓ / ⌘+↓ → scroll forward (or restore draft) ──
  if ((e.ctrlKey || e.metaKey) && e.key === 'ArrowDown') {
    e.preventDefault();
    if (_historyIdx === -1) return;
    if (_historyIdx < _msgHistory.length - 1) {
      _historyIdx++;
      msgTa.value = _msgHistory[_historyIdx];
    } else {
      _historyIdx = -1;
      msgTa.value = _historyDraft;
    }
    requestAnimationFrame(() => {
      msgTa.selectionStart = msgTa.selectionEnd = msgTa.value.length;
    });
    autosize(); updateSendBtn();
    return;
  }

  // ── Any other key resets history navigation ───────────
  if (_historyIdx !== -1 && !e.ctrlKey && !e.metaKey && !e.altKey) {
    if (!['ArrowLeft','ArrowRight','Home','End','Shift'].includes(e.key)) {
      _historyIdx = -1;
    }
  }

  // ── Enter to send (unless Shift held) ─────────────────
  if(e.key==='Enter' && !e.shiftKey && APP.enterToSend !== false){
    e.preventDefault();
    const val = msgTa.value.trim();
    if (val && !sendBtnEl.disabled) {
      sendMessage(val);
    }
  }
});
// v20: Use .onclick (idempotent assignment) instead of addEventListener to
// guarantee exactly one handler even if this code runs more than once.
// FIXED: Added null guard — sendBtnEl could be null if DOM is missing
// v39: During streaming, clicking the button STOPS the generation instead of sending.
if (sendBtnEl) {
  sendBtnEl.onclick = function(e) {
    // ── STOP MODE: cancel ongoing AI generation ─────────────────
    if (APP.isGenerating || sendBtnEl.classList.contains('streaming')) {
      APP.stopRequested = true;
      // Abort the fetch stream if an AbortController is available
      // BUG FIX: was APP._streamAbortCtrl (wrong property — never set); correct name is APP._abortController
      if (APP._abortController && typeof APP._abortController.abort === 'function') {
        APP._abortController.abort();
        APP._abortController = null;
      }
      // Visual feedback — button snaps back immediately
      sendBtnEl.classList.remove('streaming');
      sendBtnEl.disabled = true;
      APP.isGenerating = false;
      hideTypingIndicator();
      updateSendBtn();
      if (typeof toast === 'function') toast('Generation stopped', 'info', 1800);
      return;
    }
    // ── SEND MODE: send the message ─────────────────────────────
    if (!sendBtnEl.disabled) {
      const r = document.createElement('span');
      r.className = 'ripple-ring';
      sendBtnEl.style.position = 'relative';
      sendBtnEl.style.overflow = 'hidden';
      sendBtnEl.appendChild(r);
      setTimeout(() => r.remove(), 520);
      if (msgTa) sendMessage(msgTa.value);
    }
  };
}

// ─── Enhanced Swipe Sidebar (mobile) ─────────────
let _touchStartX = 0, _touchStartY = 0, _touchStartTime = 0;
let _swipeSidebarActive = false;

document.addEventListener('touchstart', e => {
  _touchStartX = e.touches[0].clientX;
  _touchStartY = e.touches[0].clientY;
  _touchStartTime = Date.now();
  const sb = $('sidebar');
  const sh = $('swipe-handle');
  if (_touchStartX < 28 && sb && !sb.classList.contains('mob-open')) {
    if (sh) sh.classList.add('peek'); // FIX: null guard
    _swipeSidebarActive = true;
  }
}, { passive: true });

document.addEventListener('touchmove', e => {
  if (!_swipeSidebarActive) return;
  const sb = $('sidebar');
  const bd = $('mob-sb-backdrop');
  if (!sb) return; // FIX: null guard
  const dx = e.touches[0].clientX - _touchStartX;
  if (dx > 0 && dx < 220 && !sb.classList.contains('mob-open')) {
    sb.style.transition = 'none';
    sb.style.transform = `translateX(calc(-100% + ${dx}px))`;
    if (bd) { bd.style.opacity = (dx / 220) * 0.6; bd.style.pointerEvents = 'none'; }
  }
}, { passive: true });

document.addEventListener('touchend', e => {
  const sh = $('swipe-handle');
  if (sh) sh.classList.remove('peek'); // FIX: null guard
  const dx = e.changedTouches[0].clientX - _touchStartX;
  const dy = e.changedTouches[0].clientY - _touchStartY;
  const dt = Date.now() - _touchStartTime;
  const velocity = Math.abs(dx) / dt;
  const sb = $('sidebar');
  const bd = $('mob-sb-backdrop');

  if (_swipeSidebarActive && sb) { // FIX: null guard
    sb.style.transition = '';
    if (bd) { bd.style.opacity = ''; bd.style.pointerEvents = ''; }
    requestAnimationFrame(() => { if (sb) sb.style.transform = ''; });
  }
  _swipeSidebarActive = false;

  if (Math.abs(dx) < Math.abs(dy) * 1.2) return;
  if ((_touchStartX < 40 && dx > 50) || (velocity > 0.5 && dx > 30)) {
    openMobSidebar(); return;
  }
  if ((dx < -50 || (velocity > 0.5 && dx < -20)) && sb?.classList.contains('mob-open')) {
    closeMobSidebar();
  }
}, { passive: true });

// ─── Drag & Drop ─────────────────────────────────
// FIX: Use a Set of relatedTargets to robustly track enter/leave on child elements
let _isDragging = false;
function _showDropOverlay(){
  if(_isDragging) return; _isDragging=true;
  const el = $('drop-overlay'); if(!el) return; // FIX: null guard
  el.classList.add('on'); el.removeAttribute('aria-hidden');
}
function _hideDropOverlay(){
  _isDragging=false;
  const el = $('drop-overlay'); if(!el) return; // FIX: null guard
  el.classList.remove('on'); el.setAttribute('aria-hidden','true');
}
document.addEventListener('dragenter',e=>{
  if(e.dataTransfer && Array.from(e.dataTransfer.types).includes('Files')) _showDropOverlay();
},{passive:true});
document.addEventListener('dragleave',e=>{
  // Only hide when leaving the document entirely
  if(!e.relatedTarget || e.relatedTarget===document.documentElement) _hideDropOverlay();
},{passive:true});
document.addEventListener('dragend', _hideDropOverlay, {passive:true});
document.addEventListener('dragover',e=>e.preventDefault());
document.addEventListener('drop',e=>{
  e.preventDefault(); _hideDropOverlay();
  handleFiles(e.dataTransfer.files);
});
// NOTE: attachBtn and fileInputHidden handlers are registered below (lines ~7084+)

function handleFiles(files) {
  if(!files?.length) return;
  const row = $('attachedRow');
  Array.from(files).forEach(f=>{
    APP.attachedFiles.push(f);
    if(f.type.startsWith('image/')){
      const reader = new FileReader();
      reader.onload=ev=>{
        const wrap=document.createElement('div'); wrap.className='afile-img';
        wrap.innerHTML=`<img loading="lazy" decoding="async" src="${ev.target.result}" alt="${esc(f.name)}"/><span class="afile-img-rm" role="button" tabindex="0" aria-label="Remove ${esc(f.name)}">×</span>`;
        wrap.querySelector('.afile-img-rm').addEventListener('click',()=>{ APP.attachedFiles=APP.attachedFiles.filter(x=>x!==f); wrap.remove(); });
        row.appendChild(wrap);
      };
      reader.readAsDataURL(f);
    } else {
      const chip=document.createElement('div'); chip.className='afile-chip';
      chip.innerHTML=`📎 ${esc(f.name)} <button class="afile-rm" aria-label="Remove ${esc(f.name)}">×</button>`;
      chip.querySelector('.afile-rm').addEventListener('click',()=>{ APP.attachedFiles=APP.attachedFiles.filter(x=>x!==f); chip.remove(); });
      row.appendChild(chip);
    }
  });
  toast(`${files.length} file${files.length>1?'s':''} attached`,'success');
}

