// ─── Model Selector ──────────────────────────────
const modelSel = $('modelSel');
const modelMenu = $('modelMenu');

on('modelBtn', 'click', e=>{
  e.stopPropagation();
  const open = modelSel.classList.toggle('open');
  modelMenu.classList.toggle('hidden',!open);
  // FIX: aria-expanded synced on every toggle
  $('modelBtn').setAttribute('aria-expanded', open?'true':'false');
  // Update aria-selected on options
  qsa('.mm-opt').forEach(o=>o.setAttribute('aria-selected', o.classList.contains('sel')?'true':'false'));
});
if (modelMenu) modelMenu.addEventListener('click',e=>{
  const opt=e.target.closest('.mm-opt'); if(!opt) return;
  const modelId = opt.dataset.model;
  // v19: Use State.currentModel setter — updates APP + saves in one call
  State.currentModel = modelId;
  // Update header label — use human-friendly name
  const mmName = opt.querySelector('.mm-name');
  $('modelLabel').textContent = mmName ? mmName.textContent : modelId;
  qsa('.mm-opt').forEach(o=>{
    o.classList.toggle('sel',o===opt);
    o.setAttribute('aria-selected', o===opt?'true':'false');
  });
  syncModelPills(modelId);
  modelSel.classList.remove('open'); modelMenu.classList.add('hidden');
  $('modelBtn').setAttribute('aria-expanded','false');
  // Warn if key not set
  const pCfg = AI_PROVIDERS[modelId];
  if (pCfg) {
    const k = getApiKey(pCfg.provider);
    if (!k) {
      toast(`Set ${pCfg.provider === 'gemini' ? 'Gemini' : 'OpenRouter'} key in Settings → AI Keys`, 'warn', 4000);
    } else {
      toast('Switched to ' + (mmName ? mmName.textContent : modelId), 'info');
    }
  } else {
    toast('Switched to ' + (mmName ? mmName.textContent : modelId), 'info');
  }
});
document.addEventListener('click',e=>{
  if(!modelSel.contains(e.target)){
    modelSel.classList.remove('open'); modelMenu.classList.add('hidden');
    $('modelBtn').setAttribute('aria-expanded','false');
  }
});

// ─── Prompt Grid (removed — tabs feature disabled) ───────────────

// ─── Sidebar new / header new ────────────────────
on('sbNewBtn', 'click', ()=>{
  APP.activeChatId=null; save(); showWelcome(); renderChatList();
  if(isMob()) closeMobSidebar(); msgTa.focus();
});
on('hdrNewChatBtn', 'click', ()=>{
  APP.activeChatId=null; save(); showWelcome(); renderChatList(); msgTa.focus();
  toast('New conversation started','info');
});
on('sbSearch', 'input', debouncedRenderChatList);
// v17: Search clear button
on('sbSearch', 'input', () => {
  const clear = $('sbSearchClear');
  if (clear) clear.classList.toggle('visible', $('sbSearch').value.length > 0);
  // If query has 3+ chars, also trigger IDB message search in background
  const q = ($('sbSearch') || {}).value || '';
  if (q.length >= 3) {
    clearTimeout(_sbMsgSearchTimer);
    _sbMsgSearchTimer = setTimeout(async () => {
      try {
        const msgs = await ZenQDB.searchMessages(q, { limit: 10, maxScan: 2000 });
        if (!msgs.length) return;
        // Surface chat IDs that have matching messages — they'll appear highlighted in sidebar
        const matchingChatIds = new Set(msgs.map(m => m.chatId));
        qsa('.chat-item').forEach(el => {
          el.classList.toggle('search-match', matchingChatIds.has(el.dataset.id));
        });
      } catch(_) {}
    }, 400);
  } else {
    qsa('.chat-item.search-match').forEach(el => el.classList.remove('search-match'));
  }
});
let _sbMsgSearchTimer = null;
on('sbSearchClear', 'click', () => {
  const inp = $('sbSearch');
  if (inp) { inp.value = ''; inp.dispatchEvent(new Event('input')); inp.focus(); }
  const clear = $('sbSearchClear');
  if (clear) clear.classList.remove('visible');
});

// ─── Command Menu ────────────────────────────────
const CMD_ACTIONS = [
  { id:'new',         name:'New Chat',              desc:'Start a fresh conversation',       icon:'✦',  kbd:'Ctrl+N' },
  { id:'clear',       name:'Clear Current Chat',    desc:'Remove all messages',              icon:'🗑',  kbd:'' },
  { id:'export-txt',  name:'Export Chat as TXT',    desc:'Save current chat as text file',   icon:'📄',  kbd:'' },
  { id:'export-json', name:'Export Chat as JSON',   desc:'Save current chat as JSON',        icon:'{}',  kbd:'' },
  { id:'export-all',  name:'Export All Chats',      desc:'Download full chat history (IDB)', icon:'💾',  kbd:'' },
  { id:'import-all',  name:'Import Chats',          desc:'Restore from ZenQ export file',    icon:'📥',  kbd:'' },
  { id:'search-msgs', name:'Search Messages',       desc:'Full-text search across all chats',icon:'🔍',  kbd:'' },
  { id:'settings',    name:'Open Settings',         desc:'Preferences & themes',             icon:'⚙',  kbd:',' },
  { id:'theme',       name:'Toggle Theme',          desc:'Dark / Light mode',                icon:'🌙',  kbd:'' },
];

function buildCmdResults(query='') {
  const q=query.toLowerCase().trim();
  const chats=Object.values(APP.chats).filter(c=>!q||c.title.toLowerCase().includes(q)).slice(0,5);
  const actions=CMD_ACTIONS.filter(a=>!q||a.name.toLowerCase().includes(q)||a.desc.toLowerCase().includes(q));
  APP.cmdFocusIndex=-1;

  let html='';
  if(actions.length){
    html+=`<div class="cmd-section"><div class="cmd-sec-lbl">Actions</div>`;
    html+=actions.map(a=>`<div class="cmd-item" data-action="${a.id}" role="option">
      <div class="cmd-item-ico" aria-hidden="true">${a.icon}</div>
      <div class="cmd-item-info"><div class="cmd-item-name">${a.name}</div><div class="cmd-item-desc">${a.desc}</div></div>
      ${a.kbd?`<span class="cmd-item-kbd" aria-label="Shortcut: ${a.kbd}">${a.kbd}</span>`:''}
    </div>`).join('');
    html+=`</div>`;
  }
  if(chats.length){
    html+=`<div class="cmd-section"><div class="cmd-sec-lbl">Chats</div>`;
    html+=chats.map(c=>`<div class="cmd-item" data-chat-id="${c.id}" role="option">
      <div class="cmd-item-ico" aria-hidden="true">💬</div>
      <div class="cmd-item-info"><div class="cmd-item-name">${esc(c.title)}</div><div class="cmd-item-desc">${c.messages.length} messages</div></div>
    </div>`).join('');
    html+=`</div>`;
  }
  if(!html) html='<div style="padding:20px;text-align:center;color:var(--ink-3);font-size:13px">No results</div>';
  $('cmd-results').innerHTML=html;

  qsa('.cmd-item').forEach(item=>{
    item.addEventListener('click',()=>execCmdItem(item));
    item.addEventListener('mouseenter',()=>{
      qsa('.cmd-item').forEach(i=>i.classList.remove('focused'));
      item.classList.add('focused');
      APP.cmdFocusIndex=qsa('.cmd-item').indexOf(item);
    });
  });
}

function execCmdItem(item) {
  const aid=item.dataset.action, cid=item.dataset.chatId;
  closeCmd();
  if(cid){ switchChat(cid); return; }
  switch(aid){
    case 'new': APP.activeChatId=null; save(); showWelcome(); renderChatList(); msgTa.focus(); break;
    case 'clear': { const c=getChat(); if(c){ c.messages=[]; save(); renderMessages(); toast('Chat cleared'); } break; }
    case 'export-txt':  exportTXT(); break;
    case 'export-json': exportJSON(); break;
    case 'export-all':  exportAllChats(); break;
    case 'import-all':  importChatsFromFile(); break;
    case 'search-msgs': openSearchOverlay(); break;
    case 'settings': openSettings('general'); break;
    case 'theme': applyTheme(APP.theme==='dark'?'light':'dark'); break;
  }
}
function openCmd(){ $('cmd-overlay').classList.add('on'); $('cmd-input').value=''; buildCmdResults(); setTimeout(()=>$('cmd-input').focus(),50); }
function closeCmd(){ $('cmd-overlay').classList.remove('on'); }

on('cmdBtn', 'click', openCmd);
on('cmd-overlay', 'click', e=>{ if(e.target===$('cmd-overlay')) closeCmd(); });
on('cmd-input', 'input', e=>buildCmdResults(e.target.value));
on('cmd-input', 'keydown', e=>{
  const items=qsa('.cmd-item');
  if(e.key==='ArrowDown'){ e.preventDefault(); APP.cmdFocusIndex=Math.min(APP.cmdFocusIndex+1,items.length-1); items.forEach((it,i)=>it.classList.toggle('focused',i===APP.cmdFocusIndex)); }
  else if(e.key==='ArrowUp'){ e.preventDefault(); APP.cmdFocusIndex=Math.max(APP.cmdFocusIndex-1,0); items.forEach((it,i)=>it.classList.toggle('focused',i===APP.cmdFocusIndex)); }
  else if(e.key==='Enter'){ const f=qs('.cmd-item.focused'); if(f) execCmdItem(f); }
  else if(e.key==='Escape') closeCmd();
});

