// FIXED: Added null guards — prevents crash when settings elements don't exist
function _syncSettNavUser() {
  // Sync nav sidebar avatar / name / email from profile state
  const nameEl  = $('settNavName');
  const emailEl = $('settNavEmail');
  const initEl  = $('settNavAvInitial');
  const imgEl   = $('settNavAvImg');
  const name  = ($('profileNameDisplay') || {}).textContent  || APP.userName || 'User';
  const email = ($('profileEmailDisplay') || {}).textContent || '';
  if (nameEl)  nameEl.textContent  = name;
  if (emailEl) emailEl.textContent = email;
  if (initEl)  initEl.textContent  = (name[0] || 'U').toUpperCase();
  // Mirror profile avatar image if loaded
  const srcImg = $('profileAvImg');
  if (imgEl && srcImg && srcImg.src && srcImg.style.display !== 'none') {
    imgEl.src = srcImg.src; imgEl.style.display = 'block';
    if (initEl) initEl.style.display = 'none';
  }
}
function openSettings(tabId) {
  const sp = $('sett-panel'); const so = $('sett-overlay');
  if (sp) sp.classList.add('on');
  if (so) so.classList.add('on');
  if(tabId) switchSettTab(tabId);
  _syncSettNavUser();
  // Refresh API key status on every open
  setTimeout(updateApiKeyStatus, 80);
}
function closeSettings() {
  const sp = $('sett-panel'); const so = $('sett-overlay');
  if (sp) sp.classList.remove('on');
  if (so) so.classList.remove('on');
}
function switchSettTab(id) {
  qsa('.sp-nav-item').forEach(b=>{
    b.classList.toggle('active',b.dataset.tab===id);
    b.setAttribute('aria-selected',b.dataset.tab===id?'true':'false');
  });
  qsa('.sp-tab').forEach(t=>t.classList.remove('active'));
  const tab=$('tab-'+id);
  if(tab){ tab.classList.remove('active'); void tab.offsetWidth; tab.classList.add('active'); }
}

