on('clearAllBtn', 'click', ()=>{
  if(!confirm('Delete all chat history? This cannot be undone.')) return;
  const ids = Object.keys(APP.chats);
  ids.forEach(k => delete APP.chats[k]);
  APP.activeChatId=null; save();
  // Also clear IDB (non-blocking)
  (async () => {
    for (const id of ids) {
      await ZenQDB.deleteMessages(id).catch(() => {});
      await ZenQDB.deleteChatRecord(id).catch(() => {});
    }
    await ZenQDB.kvSet('zenq_active', '').catch(() => {});
  })();
  renderChatList(); showWelcome(); closeSettings(); toast('All chats cleared','info');
});

