// ─── Export / Import / Search ─────────────────────
function exportTXT() {
  const chat=getChat(); if(!chat||!chat.messages.length){ toast('No messages to export','error'); return; }
  const lines=[`ZenQ — "${chat.title}"\nExported: ${new Date().toLocaleString()}\n${'─'.repeat(50)}\n`];
  chat.messages.forEach(m=>lines.push(`[${fmtTime(m.timestamp)}] ${m.role==='user'?'You':'ZenQ'}:\n${m.content}\n`));
  dl(lines.join('\n'),`aura-${Date.now()}.txt`,'text/plain');
  toast('Exported as TXT','success');
}
function exportJSON() {
  const chat=getChat(); if(!chat||!chat.messages.length){ toast('No messages to export','error'); return; }
  dl(JSON.stringify(chat,null,2),`aura-${Date.now()}.json`,'application/json');
  toast('Exported as JSON','success');
}
// FIX: Immediate URL revocation after download (was delayed, causing memory leak)
function dl(content,filename,type) {
  try {
    const blob = new Blob([content], {type});
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; 
    a.download = filename;
    a.style.display = 'none';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    // FIX: Immediate revocation in next tick (was setTimeout 100ms - memory leak risk)
    requestAnimationFrame(() => URL.revokeObjectURL(url));
  } catch(err) {
    console.error('[ZenQ] Download error:', err);
    toast('Download failed', 'error');
  }
}

// Export ALL chats from IDB as a single JSON download
async function exportAllChats() {
  toast('Preparing export…', 'info', 2000);
  try {
    await ZenQDB.downloadExport();
    toast('All chats exported ✓', 'success', 3000);
  } catch(e) {
    ZenQLogger.error('Export', 'exportAllChats failed:', e.message);
    toast('Export failed — ' + (e.message || 'unknown error'), 'error', 4000);
  }
}

// Import chats from a JSON file (exported by exportAllChats)
function importChatsFromFile() {
  const inp = document.createElement('input');
  inp.type = 'file'; inp.accept = '.json,application/json';
  inp.style.display = 'none';
  document.body.appendChild(inp);
  inp.addEventListener('change', async () => {
    const file = inp.files[0];
    document.body.removeChild(inp);
    if (!file) return;
    try {
      toast('Importing…', 'info', 2000);
      const text = await file.text();
      const data = JSON.parse(text);
      const count = await ZenQDB.importAll(data);
      // Merge imported chats into in-memory APP.chats
      if (data.chats && Array.isArray(data.chats)) {
        data.chats.forEach(c => {
          const { messages = [], ...meta } = c;
          if (!APP.chats[meta.id]) {
            APP.chats[meta.id] = { ...meta, messages };
          }
        });
      }
      renderChatList();
      toast(`Imported ${count} chat(s) ✓`, 'success', 3500);
    } catch(e) {
      ZenQLogger.error('Import', 'importChatsFromFile failed:', e.message);
      toast('Import failed — invalid file format', 'error', 4000);
    }
  });
  inp.click();
}

// Global message search across all IDB messages
let _searchOverlayEl = null;
function openSearchOverlay() {
  // Remove any existing overlay
  if (_searchOverlayEl) { _searchOverlayEl.remove(); _searchOverlayEl = null; }

  const overlay = document.createElement('div');
  overlay.id = 'msg-search-overlay';
  overlay.style.cssText = `
    position:fixed;inset:0;z-index:9000;background:rgba(0,0,0,0.72);
    display:flex;align-items:flex-start;justify-content:center;padding-top:80px;
  `;
  overlay.innerHTML = `
    <div style="width:min(560px,94vw);background:var(--glass-bg);border:1px solid var(--glass-border-2);
      border-radius:var(--r-lg);box-shadow:var(--shadow-float);overflow:hidden;display:flex;flex-direction:column;max-height:70vh">
      <div style="display:flex;align-items:center;gap:10px;padding:14px 16px;border-bottom:none">
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="color:var(--ink-3);flex-shrink:0"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
        <input id="msgSearchInp" type="text" placeholder="Search all messages…" autocomplete="off"
          style="flex:1;font-size:15px;color:var(--ink-1);background:none;outline:none;border:none;font-family:var(--font-body)"/>
        <button id="msgSearchClose" style="color:var(--ink-3);font-size:20px;line-height:1;background:none;border:none;cursor:pointer;padding:2px 6px">&times;</button>
      </div>
      <div id="msgSearchResults" style="overflow-y:auto;flex:1;padding:8px 0;min-height:80px">
        <div style="padding:24px;text-align:center;color:var(--ink-3);font-size:13px">Type to search across all chats…</div>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  _searchOverlayEl = overlay;

  const inp     = overlay.querySelector('#msgSearchInp');
  const results = overlay.querySelector('#msgSearchResults');
  const closeBtn= overlay.querySelector('#msgSearchClose');

  function closeSearch() {
    overlay.remove(); _searchOverlayEl = null;
  }
  closeBtn.addEventListener('click', closeSearch);
  overlay.addEventListener('click', e => { if (e.target === overlay) closeSearch(); });
  document.addEventListener('keydown', function _esc(e) {
    if (e.key === 'Escape') { closeSearch(); document.removeEventListener('keydown', _esc); }
  });

  let _searchTimer = null;
  inp.addEventListener('input', () => {
    clearTimeout(_searchTimer);
    const q = inp.value.trim();
    if (!q) {
      results.innerHTML = '<div style="padding:24px;text-align:center;color:var(--ink-3);font-size:13px">Type to search across all chats…</div>';
      return;
    }
    results.innerHTML = '<div style="padding:24px;text-align:center;color:var(--ink-3);font-size:13px">Searching…</div>';
    _searchTimer = setTimeout(async () => {
      try {
        const msgs = await ZenQDB.searchMessages(q, { limit: 25 });
        if (!msgs.length) {
          results.innerHTML = '<div style="padding:24px;text-align:center;color:var(--ink-3);font-size:13px">No results found</div>';
          return;
        }
        results.innerHTML = msgs.map(m => {
          const chat = APP.chats[m.chatId];
          const chatTitle = chat ? esc(chat.title) : 'Chat';
          const preview = esc((m.content||'').slice(0,160));
          const role = m.role === 'user' ? 'You' : 'ZenQ';
          return `<div class="msg-search-result" data-chat-id="${m.chatId}" style="
            display:flex;flex-direction:column;gap:3px;padding:10px 16px;cursor:pointer;
            border-bottom:none;transition:background 0.14s">
            <div style="display:flex;align-items:center;gap:6px">
              <span style="font-size:11px;font-weight:700;color:var(--accent);text-transform:uppercase;letter-spacing:0.05em">${chatTitle}</span>
              <span style="font-size:10px;color:var(--ink-3)">${role} · ${fmtRelTime(m.timestamp)}</span>
            </div>
            <div style="font-size:13px;color:var(--ink-2);line-height:1.5;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical">${preview}</div>
          </div>`;
        }).join('');
        // Wire click → switch to chat
        results.querySelectorAll('.msg-search-result').forEach(el => {
          el.addEventListener('mouseenter', () => { el.style.background = 'var(--glass-bg-3)'; });
          el.addEventListener('mouseleave', () => { el.style.background = ''; });
          el.addEventListener('click', () => {
            const chatId = el.dataset.chatId;
            if (chatId) { switchChat(chatId); closeSearch(); }
          });
        });
      } catch(e) {
        results.innerHTML = `<div style="padding:24px;text-align:center;color:var(--red);font-size:13px">Search error: ${esc(e.message)}</div>`;
      }
    }, 320);
  });

  setTimeout(() => inp.focus(), 50);
}

on('sbExportBtn', 'click', exportTXT);
on('exportTxtBtn', 'click', exportTXT);
on('exportJsonBtn', 'click', exportJSON);
// NOTE: themeToggleBtn is already bound inside applyTheme block above

// ─── Keyboard Shortcuts ──────────────────────────
document.addEventListener('keydown',e=>{
  // Never handle shortcuts while auth wall is visible
  const authOv = $('auth-overlay');
  if (authOv && !authOv.classList.contains('gone')) return;

  // FIXED: All DOM lookups null-guarded to prevent crash on missing elements
  const _cmdOv   = $('cmd-overlay');
  const _settPnl = $('sett-panel');
  const _voiceOv = $('voice-overlay');
  const _sbSearch= $('sbSearch');

  if((e.ctrlKey||e.metaKey)&&e.key==='k'){ e.preventDefault(); if(_cmdOv) _cmdOv.classList.contains('on')?closeCmd():openCmd(); return; }
  if((e.ctrlKey||e.metaKey)&&e.key==='n'){ e.preventDefault(); APP.activeChatId=null; save(); showWelcome(); renderChatList(); if(msgTa) msgTa.focus(); return; }
  if((e.ctrlKey||e.metaKey)&&e.key===','){ e.preventDefault(); openSettings('general'); return; }
  // Ctrl+F — global message search overlay
  if((e.ctrlKey||e.metaKey)&&e.key==='f'&&!e.shiftKey){ e.preventDefault(); openSearchOverlay(); return; }
  // Ctrl+Shift+E — export all chats
  if((e.ctrlKey||e.metaKey)&&e.shiftKey&&e.key==='E'){ e.preventDefault(); exportAllChats(); return; }
  // v31: Ctrl+/ = focus the message input (standard chat shortcut)
  if((e.ctrlKey||e.metaKey)&&e.key==='/'){e.preventDefault();if(msgTa){msgTa.focus();msgTa.select();}return;}
  if(e.key==='Escape'){
    if(_searchOverlayEl){ _searchOverlayEl.remove(); _searchOverlayEl = null; return; }
    if(_cmdOv  && _cmdOv.classList.contains('on')){ closeCmd(); return; }
    if(_settPnl && _settPnl.classList.contains('on')){ closeSettings(); return; }
    if(_voiceOv && _voiceOv.classList.contains('on')){ closeVoice(); return; }
  }
  if(e.key==='/'&&document.activeElement!==msgTa&&document.activeElement!==_sbSearch&&document.activeElement!==$('cmd-input')){
    e.preventDefault(); if (_sbSearch) _sbSearch.focus();
  }
});

on('sbKbBtn', 'click', ()=>{
  toast('Ctrl+K: Command · Ctrl+N: New chat · Ctrl+,: Settings · /: Search · Esc: Close');
});

// ─── Header 3-dot Menu ────────────────────────────
(function initHdr3dotMenu() {
  const btn  = $('hdr3dotBtn');
  const menu = $('hdr3dotMenu');
  if (!btn || !menu) return;

  // Sync model name in the dropdown
  function syncModelName() {
    const nameEl = $('hdr3dotModelName');
    if (!nameEl) return;
    // Use modelLabel text (already updated by model selector logic)
    const mlEl = $('modelLabel');
    if (mlEl) nameEl.textContent = mlEl.textContent || 'Flash';
  }

  function openMenu() {
    syncModelName();
    menu.classList.remove('hidden');
    btn.setAttribute('aria-expanded', 'true');
  }
  function closeMenu() {
    menu.classList.add('hidden');
    btn.setAttribute('aria-expanded', 'false');
  }
  function toggleMenu() {
    menu.classList.contains('hidden') ? openMenu() : closeMenu();
  }

  btn.addEventListener('click', (e) => { e.stopPropagation(); toggleMenu(); });

  // Close on outside click
  document.addEventListener('click', (e) => {
    if (!e.target.closest('#hdr3dotWrap')) closeMenu();
  });

  // Close on Escape
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && !menu.classList.contains('hidden')) closeMenu();
  });

  // Keep model name synced whenever modelLabel changes (observe mutations)
  // BUG FIX [v38-H7]: Store the MutationObserver on APP so it can be disconnected
  // if the element is ever replaced — previously the observer was anonymous and leaked.
  const mlEl = $('modelLabel');
  if (mlEl && typeof MutationObserver !== 'undefined') {
    if (APP._modelLabelMO) APP._modelLabelMO.disconnect();
    APP._modelLabelMO = new MutationObserver(syncModelName);
    APP._modelLabelMO.observe(mlEl, { childList: true, characterData: true, subtree: true });
  }

  // ── Branch New Chat ──
  const branchBtn = $('hdr3dotBranchBtn');
  if (branchBtn) {
    branchBtn.addEventListener('click', () => {
      closeMenu();
      const srcChat = getChat();
      // Create new chat; if a conversation is open, copy its title as a branch seed
      const branchTitle = srcChat
        ? `↳ ${(srcChat.title || 'Chat').slice(0, 36)}`
        : 'New Chat';
      const newId = createChat(branchTitle, 'general');
      APP.activeChatId = newId;
      save();
      showWelcome();
      renderChatList();
      if (msgTa) msgTa.focus();
      toast('Branched to new chat ✦', 'success');
    });
  }

  // ── Share ──
  const shareBtn = $('hdr3dotShareBtn');
  if (shareBtn) {
    shareBtn.addEventListener('click', () => {
      closeMenu();
      const chat = getChat();
      if (!chat || !chat.messages.length) {
        toast('Nothing to share yet', 'info'); return;
      }
      // Build plain-text export of conversation
      const lines = [`ZenQ — "${chat.title || 'Chat'}"\n${'─'.repeat(40)}\n`];
      chat.messages.slice(-20).forEach(m => {
        const who = m.role === 'user' ? 'You' : 'ZenQ';
        lines.push(`${who}: ${m.content.slice(0, 500)}${m.content.length > 500 ? '…' : ''}`);
      });
      const text = lines.join('\n');
      const url = window.location.href;
      const shareData = { title: `ZenQ — ${chat.title || 'Chat'}`, text, url };
      if (navigator.share && navigator.canShare && navigator.canShare(shareData)) {
        navigator.share(shareData).catch(() => {});
      } else {
        const copyFn = () => {
          if (navigator.clipboard && window.isSecureContext)
            return navigator.clipboard.writeText(text);
          const ta = document.createElement('textarea');
          ta.value = text;
          ta.style.cssText = 'position:fixed;opacity:0;top:-9999px';
          document.body.appendChild(ta);
          ta.select();
          document.execCommand('copy');
          document.body.removeChild(ta);
          return Promise.resolve();
        };
        copyFn()
          .then(() => toast('Chat copied to clipboard! 🔗', 'success'))
          .catch(() => toast('Share failed', 'error'));
      }
    });
  }
})();

// ─── Sound ───────────────────────────────────────
// FIX: Single shared AudioContext — was creating a new one every call (resource leak)
// IMPROVEMENT: Safe resume() + suspended state handling + browser fallback
let _audioCtx = null;
function getAudioCtx(){
  try {
    if (!_audioCtx || _audioCtx.state === 'closed') {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return null;
      _audioCtx = new AC();
    }
    // Resume if suspended (required after user-gesture gating on some browsers)
    if (_audioCtx.state === 'suspended') {
      _audioCtx.resume().catch(() => {});
    }
  } catch(e) {
    // AudioContext creation failed (some browsers block it without user gesture)
    return null;
  }
  return _audioCtx;
}
function playPing(){
  try{
    const ctx=getAudioCtx();
    if(!ctx) return;
    if(ctx.state==='suspended') ctx.resume();
    const o=ctx.createOscillator(),g=ctx.createGain();
    o.connect(g); g.connect(ctx.destination);
    o.frequency.setValueAtTime(880,ctx.currentTime);
    g.gain.setValueAtTime(0.08,ctx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.001,ctx.currentTime+0.15);
    o.start(); o.stop(ctx.currentTime+0.15);
  }catch(e){}
}

