// ─── Init — wrapped in DOMContentLoaded for safe DOM access ──────────────────
document.addEventListener('DOMContentLoaded', async function initApp() {
  // ── Critical element safety check ──────────────
  const criticalElements = ['app', 'sidebar', 'msg-list', 'msg-ta', 'send-btn'];
  const missing = criticalElements.filter(id => !$(id));
  if (missing.length > 0) {
    ZenQLogger.error('Init', 'Critical elements missing:', missing.join(', '));
    document.body.innerHTML = `<div style="display:flex;flex-direction:column;align-items:center;justify-content:center;height:100vh;font-family:system-ui;color:#f25c6e;gap:12px;background:#000000">
      <div style="font-size:48px">⚠️</div>
      <div style="font-size:18px;font-weight:600">App initialization failed</div>
      <div style="font-size:13px;color:#a0a0a0">Missing: ${missing.join(', ')}</div>
      <button id="_errReloadBtn" style="margin-top:8px;padding:10px 22px;border-radius:8px;background:#6c6ef7;color:#fff;border:none;cursor:pointer;font-size:14px">Reload Page</button>
    </div>`;
    // Wire reload via JS — no inline onclick
    const rb = document.getElementById('_errReloadBtn');
    if (rb) rb.addEventListener('click', () => location.reload());
    return;
  }

  ZenQLogger.info('Init', 'App starting…');

  // Suppress transitions during load to prevent theme flash
  document.body.classList.add('no-trans');

  await loadAsync();
  applyTheme(APP.theme, true);
  applyFont(APP.fontSize);

  // FIXED: All settings element reads guarded — prevents crash when elements absent
  const _tsT = $('tsToggle');       if (_tsT)  _tsT.checked  = APP.showTs;
  const _stT = $('streamToggle');   if (_stT)  _stT.checked  = APP.streaming;
  const _snT = $('soundToggle');    if (_snT)  _snT.checked  = APP.sounds;
  const _fsT = $('fontSlider');     if (_fsT)  _fsT.value    = APP.fontSize;
  const _esT = $('enterSendToggle');if (_esT)  _esT.checked  = APP.enterToSend !== false;
  qsa('[data-theme-opt]').forEach(b=>b.classList.toggle('active',b.dataset.themeOpt===APP.theme));
  qsa('[data-speed]').forEach(b=>b.classList.toggle('active',b.dataset.speed===(APP.typingSpeed||'normal')));
  switchSettTab('profile');

  // FIXED: null guards for sbCollapseBtn and sidebar
  if(APP.sidebarCollapsed && !isMob()){
    const _sb = $('sidebar'); if (_sb) _sb.classList.add('collapsed');
    const _scb = $('sbCollapseBtn'); if (_scb) _scb.setAttribute('aria-expanded','false');
  }

  // FIXED: null guard for modelLabel
  const _bootModel = APP.activeAiModel || APP.model || 'gemini-flash';
  const _bootLabelMap = {
    'gemini-flash':'Flash','gemini-pro':'Pro','gemini-ultra':'Ultra',
    'openrouter-llama':'Llama','openrouter-mistral':'Mistral',
    'openrouter-gemini':'Flash (OR)','openrouter-gpt4o':'GPT-4o',
  };
  const _mlEl = $('modelLabel');
  if (_mlEl) _mlEl.textContent = _bootLabelMap[_bootModel] || APP.model || 'Flash';
  // FIXED: Sync model label on boot — null-guarded above via _mlEl
  const _bootModel2 = APP.activeAiModel || APP.model || 'gemini-flash';
  qsa('.mm-opt').forEach(o => {
    const active = o.dataset.model === _bootModel2;
    o.classList.toggle('sel', active);
    o.setAttribute('aria-selected', active ? 'true' : 'false');
  });

  if(APP.activeChatId && APP.chats[APP.activeChatId]){
    renderChatList(); renderMessages();
  } else {
    renderChatList(); showWelcome();
  }

  initMsgDelegation();
  setupCodeCopyDelegation();
  updateSendBtn();

  // ── Feature inits ──────────────────────────────
  initProfile();
  initGroupChat();
  initNotificationToggles();
  startRealTimeClock();
  initLanguage();
  initAIMode();
  initMultiAIModel();
  // initApiKeySettings removed — v31
  // Re-sync key status every time settings opens — handled by single handler below
  initToolPills();

  // Auth & Plan inits
  initAuth();
  initAIGate();
  updateGuestBadge();
  initPlan();
  initArchive();
  updatePlanBadge();

  // FIX Bug 4: single sbSettBtn handler — was registered twice causing duplicate health-check requests
  on('sbSettBtn', 'click', () => setTimeout(() => { updateApiKeyStatus(); updatePlanBadge(); }, 50));

  // FIXED: Removed duplicate hdr-plan-badge click handler — initPlan() registers the authoritative one.
  // Previously both DOMContentLoaded and initPlan() registered handlers, causing double invocations.
  requestAnimationFrame(()=>requestAnimationFrame(()=>{
    document.body.classList.remove('no-trans');
    ZenQLogger.info('Init', 'App ready ✓');
  }));
}); // END DOMContentLoaded

