// USER PROFILE SYSTEM
// ══════════════════════════════════════════════════
const PROFILE_KEY = 'aura_profile_v1';

function loadProfile() {
  try { return JSON.parse(localStorage.getItem(PROFILE_KEY)) || {}; } catch(e){ return {}; }
}
function saveProfile(p) {
  localStorage.setItem(PROFILE_KEY, JSON.stringify(p));
  // Also persist to IDB (non-blocking, for cross-device potential)
  ZenQDB.kvSet(PROFILE_KEY, p).catch(() => {});
}

function getInitials(name) {
  if(!name || !name.trim()) return 'U';
  const parts = name.trim().split(' ');
  return parts.length >= 2
    ? (parts[0][0] + parts[parts.length-1][0]).toUpperCase()
    : parts[0][0].toUpperCase();
}

// ══════════════════════════════════════════════════════════════
// v33: applyProfileUI — renders photo/initials across ALL avatar spots:
//   • Settings profileAvBig (large card)
//   • Sidebar sbAvatarEl (small strip)
//   • Existing .msg-row.usr .msg-av DOM nodes (live messages)
//   • fb-user-av chip (Firebase header chip)
// Photo takes precedence over initials everywhere.
// ══════════════════════════════════════════════════════════════
function applyProfileUI(p) {
  const name     = p.name     || 'Your Name';
  const email    = p.email    || 'you@example.com';
  const photoURL = p.photoURL || '';
  const initials = getInitials(name);

  // ── Sidebar avatar ───────────────────────────────────
  const sbInitial = $('sbAvatarInitial');
  const sbImg     = $('sbAvatarImg');
  const sbAvEl    = $('sbAvatarEl');
  if (sbInitial) sbInitial.textContent = initials;
  if (sbImg && sbAvEl) {
    if (photoURL) {
      sbImg.src = photoURL;
      sbImg.style.display = 'block';
      sbInitial && (sbInitial.style.display = 'none');
      sbAvEl.classList.add('has-image');
    } else {
      sbImg.style.display = 'none';
      sbInitial && (sbInitial.style.display = '');
      sbAvEl.classList.remove('has-image');
    }
  }
  if ($('sbProfileName')) $('sbProfileName').textContent = name;

  // ── Settings profile card ────────────────────────────
  const avBig     = $('profileAvBig');
  const avInitial = $('profileAvInitial');
  const avImg     = $('profileAvImg');
  if (avBig) {
    if (photoURL && avImg) {
      avImg.src = photoURL;
      avImg.style.display = 'block';
      if (avInitial) avInitial.style.display = 'none';
      avBig.classList.add('has-image');
      avBig.style.background = 'none';
    } else {
      if (avImg) avImg.style.display = 'none';
      if (avInitial) { avInitial.style.display = ''; avInitial.textContent = initials; }
      avBig.classList.remove('has-image');
      avBig.style.background = 'linear-gradient(135deg,var(--accent),var(--accent-2))';
    }
  }
  if ($('profileNameDisplay'))  $('profileNameDisplay').textContent  = name;
  if ($('profileEmailDisplay')) $('profileEmailDisplay').textContent = email;

  // ── Sync form inputs ─────────────────────────────────
  if ($('profileNameInput'))  $('profileNameInput').value  = name  !== 'Your Name'        ? name  : '';
  if ($('profileEmailInput')) $('profileEmailInput').value = email !== 'you@example.com'  ? email : '';
  if ($('profileBioInput') && p.bio) $('profileBioInput').value = p.bio;

  // ── Live message avatars ─────────────────────────────
  // Update all existing .msg-row.usr .msg-av nodes in the current DOM window
  qsa('.msg-row.usr .msg-av').forEach(av => {
    if (photoURL) {
      // Show image — replace content only if not already showing this photo
      const existingImg = av.querySelector('img');
      if (existingImg) {
        if (existingImg.src !== photoURL) existingImg.src = photoURL;
      } else {
        av.innerHTML = '';
        const img = document.createElement('img');
        img.src = photoURL;
        img.alt = initials;
        img.style.cssText = 'width:100%;height:100%;object-fit:cover;border-radius:inherit;display:block';
        av.appendChild(img);
      }
    } else {
      // No photo — show initial
      const existingImg = av.querySelector('img');
      if (existingImg) existingImg.remove();
      if (!av.querySelector('img')) av.textContent = initials[0] || 'U';
    }
  });

  // ── Firebase header chip ─────────────────────────────
  const fbAv = $('fbUserAv');
  if (fbAv && photoURL && !fbAv.querySelector('img')) {
    fbAv.innerHTML = `<img src="${esc(photoURL)}" alt="${esc(initials)}" loading="lazy">`;
  }

  // ── Bust profile cache so next message render picks up the photo ──
  _cachedProfile = null;
  _profileCacheTs = 0;
}

function initProfile() {
  const p = loadProfile();
  applyProfileUI(p);

  // Sidebar profile click → open profile settings
  on('sbProfileBtn', 'click', () => openSettings('profile'));

  // Save profile button
  if($('profileSaveBtn')) {
    on('profileSaveBtn', 'click', () => {
      const p = loadProfile();
      // FIXED: null guards for all profile inputs
      const nameInp  = $('profileNameInput');
      const emailInp = $('profileEmailInput');
      const bioInp   = $('profileBioInput');
      const nameVal  = nameInp  ? sanitizeStrict(nameInp.value.trim())  : '';
      const emailVal = emailInp ? sanitize(emailInp.value.trim()) : '';
      const bioVal   = bioInp   ? sanitize(bioInp.value.trim())   : '';
      if(!nameVal){ toast('Please enter a name', 'error'); return; }
      p.name = nameVal;
      if(emailVal) p.email = emailVal;
      if(bioVal) p.bio = bioVal;
      saveProfile(p);
      applyProfileUI(p);
      toast('Profile saved ✓', 'success');
    });
  }
}

