// GROUP CHAT SYSTEM
// ══════════════════════════════════════════════════
const GROUP_KEY = 'aura_groups_v1';

const DEMO_MEMBERS = [
  { id:'m1', name:'Alex Chen', emoji:'👨‍💻' },
  { id:'m2', name:'Priya Sharma', emoji:'👩‍🎨' },
  { id:'m3', name:'Jordan Lee', emoji:'🧑‍🔬' },
  { id:'m4', name:'Sam Rivera', emoji:'👩‍💼' },
  { id:'m5', name:'Morgan Park', emoji:'🧑‍🎤' },
];

function loadGroups() {
  try { return JSON.parse(localStorage.getItem(GROUP_KEY)) || []; } catch(e){ return []; }
}
function saveGroups(g) { localStorage.setItem(GROUP_KEY, JSON.stringify(g)); }
function genGroupId() {
  try {
    if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
      return 'g_' + crypto.randomUUID().replace(/-/g,'').slice(0,16);
    }
  } catch(_) {}
  return 'g_' + Date.now().toString(36) + Math.random().toString(36).slice(2,6);
}

function renderGroupList() {
  const groups = loadGroups();
  const el = $('groupList');
  if(!el) return;
  if(!groups.length) {
    el.innerHTML = '<div style="font-size:11.5px;color:var(--ink-4);padding:4px 4px 8px;transition:opacity var(--t);" id="noGroupsMsg">No groups yet</div>';
    return;
  }
  el.innerHTML = groups.map(g => `
    <div class="group-item${g.active?' active':''}" data-gid="${g.id}" role="listitem" tabindex="0" aria-label="${esc(g.name)}">
      <div class="group-av">
        <span>${g.emoji||'👥'}</span>
      </div>
      <div class="group-meta">
        <div class="group-name">${esc(g.name)}</div>
        <div class="group-preview">${g.members.length} members · ${g.lastMsg||'Say hello!'}</div>
      </div>
      ${g.unread ? `<span class="group-badge">${g.unread}</span>` : ''}
    </div>
  `).join('');

  qsa('.group-item', el).forEach(item => {
    item.addEventListener('click', () => openGroupChat(item.dataset.gid));
  });

  renderSettingsGroupsList();
}

function renderSettingsGroupsList() {
  const groups = loadGroups();
  const el = $('settGroupsList');
  if(!el) return;
  if(!groups.length) {
    el.innerHTML = '<div style="font-size:12px;color:var(--ink-3);padding:8px 0">No groups yet. Create one below!</div>';
    return;
  }
  // SECURITY FIX [v23]: Replaced inline onclick="deleteGroup('id')" with data-gid attribute.
  // Event delegation via the container handles the click — no string eval, no XSS vector.
  el.innerHTML = groups.map(g => `
    <div style="display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:var(--r-sm);background:var(--glass-bg-3);border:1px solid var(--glass-border)">
      <div style="font-size:20px">${g.emoji||'👥'}</div>
      <div style="flex:1;min-width:0">
        <div style="font-size:13px;font-weight:600;color:var(--ink-1)">${esc(g.name)}</div>
        <div style="font-size:11px;color:var(--ink-3)">${g.members.length} members</div>
      </div>
      <button class="sett-del-group-btn" data-gid="${esc(g.id)}" style="color:var(--red);font-size:11px;padding:4px 8px;border-radius:6px;border:1px solid rgba(242,92,110,0.2);background:rgba(242,92,110,0.06);cursor:pointer;transition:all 0.2s">Delete</button>
    </div>
  `).join('');
  // Wire delete buttons via event delegation (no inline onclick)
  el.querySelectorAll('.sett-del-group-btn').forEach(btn => {
    btn.addEventListener('click', () => deleteGroup(btn.dataset.gid));
  });
}

function deleteGroup(gid) {
  if(!confirm('Delete this group?')) return;
  let groups = loadGroups();
  groups = groups.filter(g => g.id !== gid);
  saveGroups(groups);
  renderGroupList();
  toast('Group deleted', 'info');
}

function openGroupChat(gid) {
  const groups = loadGroups();
  const g = groups.find(x => x.id === gid);
  if(!g) return;
  // Mark active
  groups.forEach(x => x.active = x.id === gid);
  g.unread = 0;
  saveGroups(groups);

  // Create or switch to a chat representing this group
  APP.activeChatId = null;
  if(!APP.chats['grp_'+gid]) {
    const id = 'grp_'+gid;
    APP.chats[id] = {
      id, title: '👥 '+g.name,
      category: 'personal',
      messages: [{
        id: genId(), role: 'assistant', content: `Welcome to **${g.name}**! This group has ${g.members.length} members: ${g.members.map(m=>m.name).join(', ')}. Start chatting!`, timestamp: Date.now()
      }],
      pinned: false, isGroup: true, groupId: gid
    };
  }
  APP.activeChatId = 'grp_'+gid;
  save(); renderChatList(); renderMessages();
  if(isMob()) closeMobSidebar();
  renderGroupList();
  toast(`Opened: ${g.name}`, 'info');
}

function openGroupModal() {
  const nameInput = $('groupNameInput');
  const grid = $('gmMembersGrid');
  const overlay = $('group-modal-overlay');
  
  // FIX: Add null checks before DOM operations
  if (!nameInput || !grid || !overlay) {
    console.error('[ZenQ] openGroupModal: Required elements not found');
    toast('Unable to open group modal', 'error');
    return;
  }
  
  nameInput.value = '';
  
  // Render member chips with null-safe operations
  try {
    grid.innerHTML = DEMO_MEMBERS.map(m => `
      <div class="gm-member-chip" data-mid="${m.id}" data-mname="${esc(m.name)}" data-memoji="${m.emoji}">
        <div class="chip-av">${m.emoji}</div>${esc(m.name)}
      </div>
    `).join('');
    
    // FIX: Verify elements exist before adding listeners
    const chips = qsa('.gm-member-chip', grid);
    if (chips && chips.length > 0) {
      chips.forEach(chip => {
        if (chip) chip.addEventListener('click', () => chip.classList.toggle('selected'));
      });
    }
  } catch(err) {
    console.error('[ZenQ] openGroupModal render error:', err);
    toast('Error loading members', 'error');
    return;
  }
  
  overlay.classList.add('on');
  setTimeout(() => nameInput.focus(), 80);
}
function closeGroupModal() {
  // FIXED: null guard — was crashing when element absent
  const ov = $('group-modal-overlay');
  if (ov) ov.classList.remove('on');
}

function createGroup() {
  // FIXED: null guards for all DOM reads
  const nameEl = $('groupNameInput');
  if (!nameEl) { toast('Unable to create group', 'error'); return; }
  const name = nameEl.value.trim();
  if(!name){ toast('Please enter a group name', 'error'); return; }
  const selected = qsa('.gm-member-chip.selected');
  const members = Array.from(selected).map(c => ({
    id: c.dataset.mid, name: c.dataset.mname, emoji: c.dataset.memoji
  }));
  if(!members.length){ toast('Select at least one member', 'error'); return; }

  const GROUP_EMOJIS = ['🚀','🌟','💎','🎯','🔥','⚡','🌈','🎪'];
  const newGroup = {
    id: genGroupId(),
    name, emoji: GROUP_EMOJIS[Math.floor(Math.random()*GROUP_EMOJIS.length)],
    members, lastMsg: '', unread: 0, active: false,
    createdAt: Date.now()
  };
  const groups = loadGroups();
  groups.unshift(newGroup);
  saveGroups(groups);
  renderGroupList();
  closeGroupModal();
  toast(`Group "${name}" created! 🎉`, 'success');
}

function initGroupChat() {
  renderGroupList();

  on('sbGroupAddBtn', 'click', openGroupModal);
  if($('settCreateGroupBtn')) on('settCreateGroupBtn', 'click', () => { closeSettings(); setTimeout(openGroupModal, 200); });
  if($('groupModalClose')) on('groupModalClose', 'click', closeGroupModal);
  if($('groupModalCancel')) on('groupModalCancel', 'click', closeGroupModal);
  if($('groupModalCreate')) on('groupModalCreate', 'click', createGroup);
  on('group-modal-overlay', 'click', e => { if(e.target === $('group-modal-overlay')) closeGroupModal(); });
}

// ══════════════════════════════════════════════════
// NOTIFICATION TOGGLES
// ══════════════════════════════════════════════════
function initNotificationToggles() {
  const stored = (() => { try{ return JSON.parse(localStorage.getItem('aura_notifs_v1'))||{}; }catch(e){ return {}; } })();

  function bindToggle(id, key, onFn, offFn) {
    const el = $(id); if(!el) return;
    el.checked = stored[key] !== false;
    el.addEventListener('change', e => {
      stored[key] = e.target.checked;
      localStorage.setItem('aura_notifs_v1', JSON.stringify(stored));
      if(e.target.checked && onFn) onFn();
      else if(!e.target.checked && offFn) offFn();
    });
  }

  bindToggle('pushNotifToggle', 'push',
    () => {
      if('Notification' in window && Notification.permission === 'default') {
        Notification.requestPermission().then(p => toast(p==='granted' ? 'Notifications enabled 🔔' : 'Permission denied', p==='granted'?'success':'error'));
      } else toast('Push notifications enabled', 'info');
    },
    () => toast('Push notifications disabled', 'info')
  );
  bindToggle('soundAlertToggle', 'soundAlert');
  bindToggle('mentionToggle', 'mention');
  bindToggle('autoScrollToggle', 'autoScroll');
  bindToggle('typingIndicatorToggle', 'typingIndicator');
  bindToggle('unreadBadgeToggle', 'unreadBadge');
  bindToggle('focusModeToggle', 'focusMode',
    () => toast('🎯 Focus Mode on — all notifications muted', 'info'),
    () => toast('Focus Mode off', 'info')
  );
  bindToggle('quietHoursToggle', 'quietHours',
    () => toast('Quiet Hours enabled (22:00–08:00)', 'info'),
    () => toast('Quiet Hours disabled', 'info')
  );

  // Group notification toggles (these are always in DOM now)
  ['groupNotifToggle','groupOnlineToggle','groupPreviewToggle'].forEach(id => {
    const el = $(id); if(!el) return;
    el.addEventListener('change', e => toast(e.target.checked ? 'Setting enabled' : 'Setting disabled', 'info'));
  });
}

// ══════════════════════════════════════════════════
// REAL-TIME CLOCK & ONLINE STATUS
// ══════════════════════════════════════════════════
// PRODUCTION FIX [v29]:
// (a) Guard against multiple registrations — if called twice the old setInterval leaked
//     and two ticks ran simultaneously, causing incorrect display and memory waste.
// (b) Replaced setInterval(30s) with recursive setTimeout(30s) — setInterval accumulates
//     backpressure if the callback is slow; setTimeout resets the timer after each call.
// (c) Exposed _clockHandle so beforeunload can clear it and suppress benign errors.
let _clockHandle = null;
function startRealTimeClock() {
  if (_clockHandle !== null) return; // already running — idempotent
  function tick() {
    const now = new Date();
    const timeStr = now.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'});
    const el = $('onlineCountEl');
    if (el) {
      const lang = APP.uiLang || 'en';
      el.textContent = lang === 'ta'
        ? `ஆரா ஆன்லைன் · ${timeStr}`
        : `ZenQ online · ${timeStr}`;
    }
    _clockHandle = setTimeout(tick, 30000);
  }
  tick();
}

