// ══════════════════════════════════════════════════
// AUTH SYSTEM — v22 Firebase Edition
// ══════════════════════════════════════════════════
// SETUP INSTRUCTIONS:
//  1. Go to https://console.firebase.google.com
//  2. Create a project → Add a web app → copy firebaseConfig
//  3. Enable Authentication → Sign-in methods:
//       • Email/Password
//       • Google
//  4. Paste your real config values into FIREBASE_CONFIG below
//  5. For Google Sign-In to work on your domain, add it to
//     Firebase Console → Authentication → Settings → Authorized domains
// ══════════════════════════════════════════════════

const FIREBASE_CONFIG = {
  apiKey:            "YOUR_API_KEY",
  authDomain:        "YOUR_PROJECT_ID.firebaseapp.com",
  projectId:         "YOUR_PROJECT_ID",
  storageBucket:     "YOUR_PROJECT_ID.appspot.com",
  messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
  appId:             "YOUR_APP_ID"
};

// Token cache — refreshed automatically by Firebase SDK.
// SECURITY FIX [v26]: Token stored in MEMORY ONLY — never in localStorage.
// localStorage is accessible by any XSS payload; in-memory is cleared on tab close.
const AUTH_KEY      = 'aura_auth_v1';      // legacy compat key (stores serialised user stub only)
// FB_TOKEN_KEY removed — token no longer persisted to localStorage
let _memToken = null; // in-memory token cache (cleared on page unload)

// ── Firebase singleton ────────────────────────────
let _fbApp  = null;
let _fbAuth = null;

function getFBAuth() {
  if (_fbAuth) return _fbAuth;
  if (typeof firebase === 'undefined') {
    console.error('[ZenQ:Auth] Firebase SDK not loaded — check script tags');
    return null;
  }
  if (!_fbApp) {
    _fbApp  = firebase.initializeApp(FIREBASE_CONFIG);
    _fbAuth = firebase.auth();
    // Persist session across page reloads using localStorage
    _fbAuth.setPersistence(firebase.auth.Auth.Persistence.LOCAL).catch(console.error);
  }
  return _fbAuth;
}

// ── Token helpers ─────────────────────────────────
/** Returns cached ID token from memory only (never localStorage). */
function getCachedToken() {
  return _memToken || null;
}

/** Forces a fresh ID token from Firebase and caches it in memory. Returns null on failure. */
// PRODUCTION FIX [v29]: Token refresh hardening.
// (a) In-flight dedup: if a refresh is already pending, return the same Promise
//     instead of firing a parallel getIdToken(true). Firebase rate-limits rapid refresh
//     calls and double-refresh caused "too many requests" 429 errors.
// (b) Exponential backoff retry (up to 3 attempts) handles transient network failures.
let _tokenRefreshPromise = null;
async function refreshIdToken() {
  // Return in-flight promise if one exists
  if (_tokenRefreshPromise) return _tokenRefreshPromise;
  const auth = getFBAuth();
  if (!auth || !auth.currentUser) return null;

  _tokenRefreshPromise = (async () => {
    const MAX_ATTEMPTS = 3;
    for (let attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
      try {
        const token = await auth.currentUser.getIdToken(/* forceRefresh */ true);
        // SECURITY FIX [v26]: Store in memory only — never localStorage
        _memToken = token;
        return token;
      } catch (err) {
        const isLast = attempt === MAX_ATTEMPTS - 1;
        if (isLast) {
          ZenQLogger && ZenQLogger.error('Auth', 'Token refresh exhausted retries:', err.message);
          return null;
        }
        const backoff = 300 * Math.pow(2, attempt); // 300ms, 600ms
        await new Promise(r => setTimeout(r, backoff));
      }
    }
    return null;
  })().finally(() => { _tokenRefreshPromise = null; });

  return _tokenRefreshPromise;
}

/** Returns a valid ID token, using Firebase's built-in cache. */
async function getIdToken() {
  const auth = getFBAuth();
  if (!auth || !auth.currentUser) return null;
  try {
    // getIdToken(false) returns cached if not expired; Firebase auto-refreshes when < 5 min left
    const token = await auth.currentUser.getIdToken(false);
    // SECURITY FIX [v26]: memory only
    _memToken = token;
    return token;
  } catch (err) {
    console.error('[ZenQ:Auth] getIdToken failed:', err.message);
    return null;
  }
}

// ── Legacy compat shims (keep existing callers working) ──
function getAuthUser() {
  const auth = getFBAuth();
  if (auth && auth.currentUser) {
    // FIXED: email can be null for phone/anonymous auth — guard before .split()
    const _cu = auth.currentUser;
    const _emailName = _cu.email ? _cu.email.split('@')[0] : 'User';
    return {
      id:       _cu.uid,
      uid:      _cu.uid,
      name:     _cu.displayName || _emailName,
      email:    _cu.email || '',
      photoURL: _cu.photoURL || '',
      provider: _cu.providerData?.[0]?.providerId || 'firebase',
      plan:     'free',
    };
  }
  // Fallback: legacy localStorage stub (handles brief window between auth-state-change)
  try { return JSON.parse(localStorage.getItem(AUTH_KEY)) || null; } catch(e) { return null; }
}
function setAuthUser(u) {
  // Store a lightweight stub for getAuthUser() during brief page-load window
  if (u) localStorage.setItem(AUTH_KEY, JSON.stringify({ id: u.uid||u.id, name: u.name||u.displayName, email: u.email, provider: u.provider||'firebase' }));
  else     localStorage.removeItem(AUTH_KEY);
}

// ══════════════════════════════════════════════════
// AUTH SYSTEM — main init + event handlers
// Features:
//   • Firebase Email/Password sign-in & sign-up
//   • Firebase Google sign-in (real OAuth popup)
//   • onAuthStateChanged session persistence
//   • ID token saved to localStorage after every login
//   • Token injected into every backend API call header
//   • Real-time inline field validation with hints
//   • Password strength meter (4-segment)
//   • Show/hide password toggle
//   • Loading spinner + disabled state on submit
//   • Success message before overlay closes
//   • Shake animation on error
//   • All elements null-checked via on() helper
// ══════════════════════════════════════════════════

/* ── Validation helpers ─────────────────────────── */
function isValidEmail(v) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim());
}
function isValidName(v) {
  return v.trim().length >= 2 && v.trim().length <= 30;
}
function isValidPassword(v) {
  return v.length >= 6 && v.length <= 128;
}

/* ── Password strength scorer (0–4) ───────────────
   Returns { score: 0-4, label: string }           */
function getPasswordStrength(pw) {
  if (pw.length < 6) return { score: 0, label: 'Too short' };
  let score = 0;
  if (pw.length >= 8)  score++;
  if (pw.length >= 12) score++;
  if (/[A-Z]/.test(pw) && /[a-z]/.test(pw)) score++;
  if (/[0-9]/.test(pw)) score++;
  if (/[^A-Za-z0-9]/.test(pw)) score++;
  score = Math.min(4, score);
  const labels = ['Weak', 'Fair', 'Good', 'Strong', 'Very strong'];
  return { score, label: labels[score] };
}

/* ── Render strength bar ───────────────────────── */
function renderPwStrength(pw) {
  const wrap = $('pwStrengthWrap');
  if (!wrap) return;
  if (!pw) { wrap.style.display = 'none'; return; }
  wrap.style.display = 'flex';
  const { score, label } = getPasswordStrength(pw);
  const classes = ['', 's1', 's2', 's3', 's4'];
  for (let i = 1; i <= 4; i++) {
    const seg = $(`pwSeg${i}`);
    if (seg) {
      seg.className = 'pw-strength-seg' + (i <= score ? ' ' + classes[score] : '');
    }
  }
  const lbl = $('pwStrengthLbl');
  if (lbl) {
    lbl.textContent = label;
    lbl.style.color = score <= 1 ? 'var(--red)' : score === 2 ? 'var(--amber)' : score === 3 ? 'var(--blue)' : 'var(--mint)';
  }
}

/* ── Inline field hint setter ──────────────────── */
function setHint(id, msg, type) {
  const el = $(id);
  if (!el) return;
  el.textContent = msg;
  el.className = 'auth-field-hint' + (type ? ' ' + type : '');
}
function setInputState(id, state) {
  const el = $(id);
  if (!el) return;
  el.classList.remove('is-valid', 'is-invalid');
  if (state) el.classList.add(state);
}

/* ── Button loading state ──────────────────────── */
function setAuthBtnLoading(btnId, loading, successText) {
  const btn = $(btnId);
  if (!btn) return;
  if (loading) {
    btn.classList.add('loading');
    btn.disabled = true;
  } else if (successText) {
    btn.classList.remove('loading');
    btn.classList.add('success');
    const lbl = btn.querySelector('.btn-label');
    if (lbl) lbl.textContent = successText;
  } else {
    btn.classList.remove('loading', 'success');
    btn.disabled = false;
  }
}

/* ── Show/hide password toggle ─────────────────── */
function initPwToggle(toggleId, inputId) {
  on(toggleId, 'click', () => {
    const inp = $(inputId);
    if (!inp) return;
    const isHidden = inp.type === 'password';
    inp.type = isHidden ? 'text' : 'password';
    // Swap eye icon SVG
    const btn = $(toggleId);
    if (btn) btn.innerHTML = isHidden
      ? `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"/><line x1="1" y1="1" x2="23" y2="23"/></svg>`
      : `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>`;
  });
}

/* ── Auth error display ────────────────────────── */
function showAuthErr(el, msg) {
  if (!el) return;
  el.textContent = msg;
  el.classList.add('show');
  // Auto-hide after 5s
  clearTimeout(el._hideTimer);
  el._hideTimer = setTimeout(() => el.classList.remove('show'), 5000);
}
function clearAuthErr(el) {
  if (el) { el.classList.remove('show'); el.textContent = ''; }
}
function showAuthSuccess(elId, msg) {
  const el = $(elId);
  if (!el) return;
  el.textContent = msg;
  el.classList.add('show');
}

function initAuth() {
  const auth = getFBAuth();
  if (!auth) {
    // Firebase SDK not loaded — show overlay immediately so user sees something
    console.error('[ZenQ:Auth] Firebase SDK not available');
    _dismissFBLoadingScreen();
    const overlay = $('auth-overlay');
    if (overlay) overlay.classList.remove('gone');
    return;
  }

  // ── Password show/hide toggles ──
  initPwToggle('loginPwToggle', 'authLoginPassword');
  initPwToggle('signupPwToggle', 'authSignupPassword');

  // ── Tab switching ──
  on('authLoginTab', 'click', () => {
    $('authLoginTab').classList.add('active');
    attr('authLoginTab', 'aria-selected', 'true');
    $('authSignupTab').classList.remove('active');
    attr('authSignupTab', 'aria-selected', 'false');
    $('authLoginForm').classList.remove('hidden');
    $('authSignupForm').classList.add('hidden');
    clearAuthErr($('authLoginErr'));
    setTimeout(() => { const el = $('authLoginEmail'); if (el) el.focus(); }, 50);
  });
  on('authSignupTab', 'click', () => {
    $('authSignupTab').classList.add('active');
    attr('authSignupTab', 'aria-selected', 'true');
    $('authLoginTab').classList.remove('active');
    attr('authLoginTab', 'aria-selected', 'false');
    $('authSignupForm').classList.remove('hidden');
    $('authLoginForm').classList.add('hidden');
    clearAuthErr($('authSignupErr'));
    setTimeout(() => { const el = $('authSignupName'); if (el) el.focus(); }, 50);
  });

  // ── Real-time validation — Login ──
  on('authLoginEmail', 'blur', () => {
    const v = $('authLoginEmail')?.value.trim() || '';
    if (!v) { setInputState('authLoginEmail',''); setHint('authLoginEmailHint',''); return; }
    if (isValidEmail(v)) { setInputState('authLoginEmail','is-valid'); setHint('authLoginEmailHint','✓ Looks good','ok'); }
    else { setInputState('authLoginEmail','is-invalid'); setHint('authLoginEmailHint','Please enter a valid email','err'); }
  });
  on('authLoginEmail', 'input', () => {
    setInputState('authLoginEmail',''); setHint('authLoginEmailHint','');
  });

  // ── Real-time validation — Signup ──
  on('authSignupName', 'blur', () => {
    const v = $('authSignupName')?.value.trim() || '';
    if (!v) { setInputState('authSignupName',''); return; }
    if (isValidName(v)) { setInputState('authSignupName','is-valid'); setHint('authSignupNameHint','✓ Great name','ok'); }
    else { setInputState('authSignupName','is-invalid'); setHint('authSignupNameHint','2–30 characters required','err'); }
  });
  on('authSignupEmail', 'blur', () => {
    const v = $('authSignupEmail')?.value.trim() || '';
    if (!v) { setInputState('authSignupEmail',''); return; }
    if (isValidEmail(v)) { setInputState('authSignupEmail','is-valid'); setHint('authSignupEmailHint','✓ Valid email','ok'); }
    else { setInputState('authSignupEmail','is-invalid'); setHint('authSignupEmailHint','Please enter a valid email','err'); }
  });
  on('authSignupPassword', 'input', () => {
    const v = $('authSignupPassword')?.value || '';
    renderPwStrength(v);
    if (!v) { setInputState('authSignupPassword',''); setHint('authSignupPasswordHint',''); return; }
    const { score } = getPasswordStrength(v);
    if (v.length < 6) { setInputState('authSignupPassword','is-invalid'); setHint('authSignupPasswordHint','At least 6 characters required','err'); }
    else if (score <= 1) { setInputState('authSignupPassword',''); setHint('authSignupPasswordHint','Consider adding numbers or symbols',''); }
    else { setInputState('authSignupPassword','is-valid'); setHint('authSignupPasswordHint','',''); }
  });

  // ── LOGIN form submit → Firebase Email/Password ──
  on('authLoginForm', 'submit', async e => {
    e.preventDefault();
    const email = ($('authLoginEmail')?.value || '').trim();
    const pass  = $('authLoginPassword')?.value || '';
    const errEl = $('authLoginErr');
    clearAuthErr(errEl);

    let valid = true;
    if (!email) { setInputState('authLoginEmail','is-invalid'); setHint('authLoginEmailHint','Email is required','err'); valid = false; }
    else if (!isValidEmail(email)) { setInputState('authLoginEmail','is-invalid'); setHint('authLoginEmailHint','Please enter a valid email','err'); valid = false; }
    if (!pass) { setInputState('authLoginPassword','is-invalid'); setHint('authLoginPasswordHint','Password is required','err'); valid = false; }
    if (!valid) return;

    setAuthBtnLoading('authLoginSubmit', true);
    try {
      const cred = await auth.signInWithEmailAndPassword(email, pass);
      const token = await cred.user.getIdToken();
      _memToken = token; // SECURITY FIX [v26]: memory only, not localStorage
      setAuthBtnLoading('authLoginSubmit', false, '✓ Signed in!');
      showAuthSuccess('authLoginSuccess', '✓ Welcome back!');
      // onAuthStateChanged fires and calls loginSuccess
    } catch (err) {
      setAuthBtnLoading('authLoginSubmit', false);
      const msg = _fbErrMsg(err.code);
      showAuthErr(errEl, msg);
      if (err.code === 'auth/user-not-found' || err.code === 'auth/invalid-credential') {
        setInputState('authLoginEmail','is-invalid');
      } else if (err.code === 'auth/wrong-password') {
        setInputState('authLoginPassword','is-invalid');
      }
    }
  });

  // ── SIGNUP form submit → Firebase createUser ──
  on('authSignupForm', 'submit', async e => {
    e.preventDefault();
    const name  = ($('authSignupName')?.value  || '').trim();
    const email = ($('authSignupEmail')?.value || '').trim();
    const pass  = $('authSignupPassword')?.value || '';
    const errEl = $('authSignupErr');
    clearAuthErr(errEl);

    let valid = true;
    if (!isValidName(name))     { setInputState('authSignupName','is-invalid');     setHint('authSignupNameHint','2–30 characters required','err'); valid = false; }
    if (!isValidEmail(email))   { setInputState('authSignupEmail','is-invalid');    setHint('authSignupEmailHint','Please enter a valid email','err'); valid = false; }
    if (!isValidPassword(pass)) { setInputState('authSignupPassword','is-invalid'); setHint('authSignupPasswordHint','Password must be 6–128 characters','err'); valid = false; }
    if (!valid) return;

    setAuthBtnLoading('authSignupSubmit', true);
    try {
      const cred = await auth.createUserWithEmailAndPassword(email, pass);
      // Set display name
      await cred.user.updateProfile({ displayName: name });
      const token = await cred.user.getIdToken();
      _memToken = token; // SECURITY FIX [v26]: memory only, not localStorage
      setAuthBtnLoading('authSignupSubmit', false, '✓ Account created!');
      showAuthSuccess('authSignupSuccess', '✓ Welcome to ZenQ, ' + name + '!');
      // onAuthStateChanged fires → loginSuccess
    } catch (err) {
      setAuthBtnLoading('authSignupSubmit', false);
      const msg = _fbErrMsg(err.code);
      showAuthErr(errEl, msg);
      if (err.code === 'auth/email-already-in-use') setInputState('authSignupEmail','is-invalid');
    }
  });

  // ── Google Sign-In (real OAuth popup) ──
  [$('googleSignInBtn'), $('googleSignUpBtn')].forEach(btn => {
    if (!btn) return;
    on(btn, 'click', () => handleGoogleAuth());
  });

  // ── Auto-focus on open — skip on splash (no form visible yet) ──
  // setTimeout(() => { const el = $('authLoginEmail'); if (el) el.focus(); }, 500);

  // ── Splash: "Log in another way" → show email card ──
  const _loginOtherBtn = document.getElementById('authLoginOtherBtn');
  const _authCardView  = document.getElementById('authCardView');
  const _authCardBack  = document.getElementById('authCardBack');
  if (_loginOtherBtn && _authCardView) {
    _loginOtherBtn.addEventListener('click', () => {
      _authCardView.style.display = 'flex';
      // Reset animation
      _authCardView.style.animation = 'none';
      requestAnimationFrame(() => {
        _authCardView.style.animation = '';
        setTimeout(() => { const el = $('authLoginEmail'); if (el) el.focus(); }, 80);
      });
    });
  }
  if (_authCardBack && _authCardView) {
    _authCardBack.addEventListener('click', () => {
      _authCardView.style.display = 'none';
    });
  }
  // Tap outside card also closes it
  if (_authCardView) {
    _authCardView.addEventListener('click', e => {
      if (e.target === _authCardView) _authCardView.style.display = 'none';
    });
  }

  // ── onAuthStateChanged — the heart of Firebase session persistence ──
  // Fires immediately on page load with the persisted user (or null).
  auth.onAuthStateChanged(async (firebaseUser) => {
    _dismissFBLoadingScreen();

    if (firebaseUser) {
      // ── User is signed in ──
      const token = await firebaseUser.getIdToken().catch(() => null);
      if (token) _memToken = token; // SECURITY FIX [v26]: memory only, not localStorage

      const userStub = {
        id:       firebaseUser.uid,
        uid:      firebaseUser.uid,
        // BUG FIX [v28]: firebaseUser.email can be null for Google/phone auth users;
        // guard before .split() to prevent "Cannot read property 'split' of null"
        name:     firebaseUser.displayName || (firebaseUser.email ? firebaseUser.email.split('@')[0] : 'User'),
        email:    firebaseUser.email || '',
        photoURL: firebaseUser.photoURL || null,
        provider: firebaseUser.providerData?.[0]?.providerId || 'firebase',
        plan:     'free',
      };
      setAuthUser(userStub);
      loginSuccess(userStub);

      // ── Auto-refresh token every 50 minutes ──
      // PRODUCTION FIX [v29]: Replaced setInterval with recursive setTimeout.
      // setInterval fires regardless of how long the previous refresh takes;
      // if the network is slow and a refresh takes >50 min, two concurrent
      // refreshes run simultaneously. setTimeout always waits for the previous
      // call to finish before scheduling the next one.
      // Also replaced window._fbTokenRefreshTimer (interval) with a timeout handle.
      if (window._fbTokenRefreshTimer) clearTimeout(window._fbTokenRefreshTimer);
      const scheduleTokenRefresh = () => {
        window._fbTokenRefreshTimer = setTimeout(async () => {
          await refreshIdToken();
          scheduleTokenRefresh(); // reschedule only after previous refresh resolves
        }, 50 * 60 * 1000);
      };
      scheduleTokenRefresh();
      // Cleanup on navigation — prevents zombie timer errors
      window.addEventListener('pagehide', () => {
        clearTimeout(window._fbTokenRefreshTimer);
        window._fbTokenRefreshTimer = null;
      }, { once: true });

    } else {
      // ── User is signed out ──
      localStorage.removeItem(AUTH_KEY);
      _memToken = null; // SECURITY FIX [v26]: clear in-memory token on signout
      clearTimeout(window._fbTokenRefreshTimer); // PRODUCTION FIX [v29]: clearTimeout (was clearInterval)
      _showAuthOverlayOnSignOut();
      updateGuestBadge();
      _updateFBUserChip(null);
    }
  });
}

// ── Guest Mode Helpers ────────────────────────────
// BUG FIX [v23]: Removed 3 orphaned lines (setInputState / setHint / valid=false)
// that were floating outside any function between initAuth() close-brace and
// dismissAuthAsGuest(). They were dead code from a partial edit but caused a
// strict-mode syntax error in some JS engines and cluttered the global scope.
function dismissAuthAsGuest() {
  const overlay = $('auth-overlay');
  if (!overlay) { updateGuestBadge(); return; }
  overlay.classList.add('hiding');
  setTimeout(() => overlay.classList.add('gone'), 420);
  updateGuestBadge();
}

function updateGuestBadge() {
  const badge = $('guestBadge');
  const chip  = $('fb-user-chip');
  const user  = getAuthUser();
  if (badge) {
    if (!user) {
      badge.classList.add('visible');
    } else {
      badge.classList.remove('visible');
    }
  }
  if (chip) {
    if (user) {
      chip.classList.add('visible');
    } else {
      chip.classList.remove('visible');
    }
  }
}

// ── AI Gate Modal ─────────────────────────────────
function showAIGate() {
  const gate = $('ai-gate-overlay');
  if (!gate) return;
  gate.classList.add('on');
  // Focus first button for accessibility
  setTimeout(() => { const b = $('aigLoginBtn'); if(b) b.focus(); }, 80);
}

function hideAIGate() {
  const gate = $('ai-gate-overlay');
  if (!gate) return;
  gate.classList.remove('on');
}

function initAIGate() {
  const gate = $('ai-gate-overlay');
  if (!gate) return;

  // Close on backdrop click
  gate.addEventListener('click', e => { if (e.target === gate) hideAIGate(); });

  // Login button — opens auth overlay on login tab
  const loginBtn = $('aigLoginBtn');
  if (loginBtn) loginBtn.addEventListener('click', () => {
    hideAIGate();
    openAuthOverlay('login');
  });

  // Create account button — opens auth overlay on signup tab
  const signupBtn = $('aigSignupBtn');
  if (signupBtn) signupBtn.addEventListener('click', () => {
    hideAIGate();
    openAuthOverlay('signup');
  });

  // Dismiss
  const dismissBtn = $('aigDismissBtn');
  if (dismissBtn) dismissBtn.addEventListener('click', hideAIGate);

  // Escape closes
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape' && gate.classList.contains('on')) hideAIGate();
  });

  // Guest badge opens auth
  const guestBadge = $('guestBadge');
  if (guestBadge) guestBadge.addEventListener('click', () => openAuthOverlay('login'));

  // Auth guest link
  const guestLink = $('authGuestLink');
  if (guestLink) guestLink.addEventListener('click', dismissAuthAsGuest);
}

function openAuthOverlay(tab) {
  const overlay = $('auth-overlay');
  if (!overlay) return;
  overlay.classList.remove('gone', 'hiding');
  overlay.style.opacity = '1';
  overlay.style.pointerEvents = 'all';
  // Show card view (email login sheet)
  const cardView = document.getElementById('authCardView');
  if (cardView) cardView.style.display = 'flex';
  // Switch to correct tab
  if (tab === 'signup') {
    $('authSignupTab')?.click();
  } else {
    $('authLoginTab')?.click();
  }
  setTimeout(() => {
    const inp = tab === 'signup' ? $('authSignupName') : $('authLoginEmail');
    if (inp) inp.focus();
  }, 200);
}

// ── Check auth before AI action ───────────────────
function requireAuth(action) {
  if (getAuthUser()) {
    // Logged in — allow
    if (typeof action === 'function') action();
  } else {
    // Guest — show gate modal
    showAIGate();
  }
}

function loginSuccess(user) {
  setAuthUser(user);
  syncAuthProfile(user);
  // Clear guest message counter — user is now signed in
  sessionStorage.removeItem('aura_guest_msgs');
  // Dismiss auth overlay
  const overlay = $('auth-overlay');
  if (overlay) {
    overlay.classList.add('hiding');
    setTimeout(() => overlay.classList.add('gone'), 420);
  }
  updatePlanUI();
  updateGuestBadge();
  hideAIGate();
  _updateFBUserChip(user);
  ZenQBus.emit('auth:login', { user });
  const firstName = (user.name || user.displayName || user.email || '').split(/[\s@]/)[0];
  toast('Welcome back, ' + firstName + '! 🎉', 'success');
}

// v33: syncAuthProfile — also copies Firebase photoURL to the local profile
// so the avatar shows immediately after Google sign-in without manual upload.
function syncAuthProfile(user) {
  if (!user) return;
  const p = loadProfile();
  if (!p.name || p.name === 'Your Name') {
    // PRODUCTION FIX [v29]: user.email can be null for phone/anonymous auth providers.
    // Calling .split('@') on null throws "Cannot read properties of null".
    const emailFallback = user.email ? user.email.split('@')[0] : 'User';
    p.name  = user.name || user.displayName || emailFallback;
    p.email = user.email || '';
    if (user.photoURL) {
      p.photoURL = user.photoURL;
      // v33: refresh avatar UI immediately when Firebase photo is applied
      if (typeof applyProfileUI === 'function') requestAnimationFrame(() => applyProfileUI(p));
    }
    saveProfile(p);
    applyProfileUI(p);
  }
  const emailEl = $('settSignedInEmail');
  if (emailEl && user.email) emailEl.textContent = user.email;
}

async function handleLogout(clearData=false) {
  if (!confirm(clearData
    ? 'Sign out and delete ALL local data? This cannot be undone.'
    : 'Are you sure you want to sign out?')) return;

  if (clearData) { APP.chats = {}; APP.activeChatId = null; save(); }

  // Sign out from Firebase
  const auth = getFBAuth();
  if (auth) {
    try { await auth.signOut(); } catch(e) { console.error('[ZenQ:Auth] signOut error:', e); }
  }

  localStorage.removeItem(AUTH_KEY);
  _memToken = null; // SECURITY FIX [v26]: clear in-memory token
  clearTimeout(window._fbTokenRefreshTimer); // FIX: was clearInterval — timer is setTimeout-based

  closeSettings();
  ZenQBus.emit('auth:logout', { clearData });
  toast(clearData ? 'Signed out & data cleared' : 'Signed out successfully', 'info');

  // onAuthStateChanged will fire and call _showAuthOverlayOnSignOut
  // but we also do it here for instant feedback
  _showAuthOverlayOnSignOut();
  _updateFBUserChip(null);
  updateGuestBadge();
}

// ── Private helpers ────────────────────────────────
/** Translate Firebase error codes to user-friendly messages */
function _fbErrMsg(code) {
  const map = {
    'auth/user-not-found':        '⚠ No account found with this email.',
    'auth/wrong-password':        '⚠ Incorrect password. Please try again.',
    'auth/invalid-credential':    '⚠ Incorrect email or password.',
    'auth/email-already-in-use':  '⚠ An account with this email already exists.',
    'auth/weak-password':         '⚠ Password must be at least 6 characters.',
    'auth/invalid-email':         '⚠ Please enter a valid email address.',
    'auth/too-many-requests':     '⚠ Too many attempts. Please wait and try again.',
    'auth/network-request-failed':'⚠ Network error — check your connection.',
    'auth/popup-closed-by-user':  '⚠ Sign-in popup was closed. Please try again.',
    'auth/popup-blocked':         '⚠ Popup blocked by browser. Please allow popups.',
    'auth/cancelled-popup-request': '',  // ignore — user opened another popup
  };
  return map[code] || '⚠ Sign-in failed (' + (code || 'unknown') + '). Please try again.';
}

/** Reset auth overlay back to login tab for sign-out flow */
function _showAuthOverlayOnSignOut() {
  const overlay = $('auth-overlay');
  if (!overlay) return;
  overlay.classList.remove('gone', 'hiding');
  overlay.style.opacity = '1';
  overlay.style.pointerEvents = 'all';

  ['authLoginEmail','authLoginPassword','authSignupName','authSignupEmail','authSignupPassword'].forEach(id => {
    const el = $(id); if(el) el.value = '';
  });
  ['authLoginErr','authSignupErr'].forEach(id => {
    const el = $(id); if(el) el.classList.remove('show');
  });

  $('authLoginTab')?.classList.add('active');
  $('authLoginTab')?.setAttribute('aria-selected','true');
  $('authSignupTab')?.classList.remove('active');
  $('authSignupTab')?.setAttribute('aria-selected','false');
  $('authLoginForm')?.classList.remove('hidden');
  $('authSignupForm')?.classList.add('hidden');

  // Block keyboard shortcuts while auth wall is up (restored when user logs in)
  overlay.addEventListener('keydown', function _authKbGuard(e) {
    if (!overlay.classList.contains('gone')) {
      if (e.key === 'Escape') { e.preventDefault(); e.stopImmediatePropagation(); }
      if ((e.ctrlKey || e.metaKey) && ['k','n',','].includes(e.key)) { e.preventDefault(); e.stopImmediatePropagation(); }
    } else {
      overlay.removeEventListener('keydown', _authKbGuard, true);
    }
  }, true);

  setTimeout(() => { const el = $('authLoginEmail'); if(el) el.focus(); }, 200);
}

/** Dismiss the full-screen Firebase loading screen */
function _dismissFBLoadingScreen() {
  const el = $('fb-auth-loading');
  if (!el) return;
  el.classList.add('gone');
  setTimeout(() => { if(el.parentNode) el.parentNode.removeChild(el); }, 400);
}

/** Real Google OAuth via Firebase popup */
async function handleGoogleAuth() {
  const auth = getFBAuth();
  if (!auth) { toast('Firebase not initialised', 'error'); return; }
  try {
    const provider = new firebase.auth.GoogleAuthProvider();
    provider.addScope('email');
    provider.addScope('profile');
    const result = await auth.signInWithPopup(provider);
    const token  = await result.user.getIdToken();
    _memToken = token; // SECURITY FIX [v26]: memory only, not localStorage
    // onAuthStateChanged fires → loginSuccess
    toast('Signed in with Google ✓', 'success');
  } catch (err) {
    if (err.code === 'auth/cancelled-popup-request') return; // silent — user opened another
    const msg = _fbErrMsg(err.code);
    if (msg) toast(msg, 'error', 4000);
    console.error('[ZenQ:Auth] Google sign-in error:', err);
  }
}

/** Update the header Firebase user chip */
function _updateFBUserChip(user) {
  const chip    = $('fb-user-chip');
  const emailEl = $('fbUserEmail');
  const avEl    = $('fbUserAv');
  if (!chip) return;

  if (!user) {
    chip.classList.remove('visible');
    return;
  }

  chip.classList.add('visible');
  if (emailEl) emailEl.textContent = user.email || '';

  if (avEl) {
    if (user.photoURL) {
      avEl.innerHTML = `<img src="${esc(user.photoURL)}" alt="avatar" loading="lazy">`;
    } else {
      const initials = ((user.name || user.email || 'U').trim()[0] || 'U').toUpperCase();
      avEl.textContent = initials;
      avEl.style.background = 'linear-gradient(135deg,var(--accent),var(--accent-2))';
    }
  }

  // Wire logout button (idempotent)
  const logoutBtn = $('fbHeaderLogoutBtn');
  if (logoutBtn && !logoutBtn._fbBound) {
    logoutBtn._fbBound = true;
    logoutBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      handleLogout(false);
    });
  }
}

// ══════════════════════════════════════════════════
// PLAN / SUBSCRIPTION SYSTEM
// ══════════════════════════════════════════════════
const PLAN_KEY   = 'aura_plan_v1';
const USAGE_KEY  = 'aura_usage_v1';
const FREE_LIMIT = 5;

function getPlan() {
  const user = getAuthUser();
  if (user && user.plan && user.plan !== 'free') return user.plan;
  try { return JSON.parse(localStorage.getItem(PLAN_KEY)) || { type:'free' }; } catch(e){ return {type:'free'}; }
}
function setPlan(p) {
  localStorage.setItem(PLAN_KEY, JSON.stringify(p));
  const user = getAuthUser();
  if (user) { user.plan = p.type; setAuthUser(user); }
}
function getUsage() {
  try {
    const u = JSON.parse(localStorage.getItem(USAGE_KEY)) || {};
    const today = new Date().toDateString();
    if (u.date !== today) return { date: today, count: 0 };
    return u;
  } catch(e){ return { date: new Date().toDateString(), count: 0 }; }
}
function isPro() {
  const p = getPlan();
  return p.type === 'pro_monthly' || p.type === 'pro_yearly' || p.type === 'first_month';
}
function isUsageLimitReached() {
  if (isPro()) return false;
  return getUsage().count >= FREE_LIMIT;
}

function initPlan() {
  updatePlanUI();

  // Plan badge button opens upgrade modal
  // FIX: ID is 'hdr-plan-badge', not 'planBadgeBtn' — was throwing [ZenQ] on(): element #planBadgeBtn not found
  on('hdr-plan-badge', 'click', () => {
    if (!isPro()) openPlanModal();
  });

  // Close plan modal
  on('planCloseBtn', 'click', closePlanModal);
  on('plan-overlay', 'click', e => {
    if (e.target === $('plan-overlay')) closePlanModal();
  });

  // Plan card clicks
  on('planFirstMonth', 'click', () => selectPlanCard('first_month'));
  on('planMonthly', 'click', () => selectPlanCard('pro_monthly'));
  on('planYearly', 'click', () => selectPlanCard('pro_yearly'));

  // Upgrade button
  on('planUpgradeBtn', 'click', () => {
    const selected = qs('.plan-card.selected');
    const type = selected ? selected.id.replace('plan','').toLowerCase() : 'first_month';
    const planMap = {
      firstmonth:  { type:'first_month', label:'First Month ₹59', price:'₹59' },
      monthly:     { type:'pro_monthly',  label:'Pro Monthly ₹199', price:'₹199/mo' },
      yearly:      { type:'pro_yearly',   label:'Pro Yearly ₹1999', price:'₹1999/yr' },
    };
    // Normalize key
    const key = type.replace('pro_','').replace('_','');
    const plan = planMap[key] || planMap['firstmonth'];
    setPlan({ type: plan.type, activatedAt: Date.now() });
    closePlanModal();
    updatePlanUI();
    toast(`✦ ${plan.label} activated! Unlimited AI unlocked 🚀`, 'success', 3500);
  });
}

function selectPlanCard(type) {
  qsa('.plan-card').forEach(c => c.classList.remove('selected'));
  const map = { first_month:'planFirstMonth', pro_monthly:'planMonthly', pro_yearly:'planYearly' };
  const el = $(map[type]); if(el) el.classList.add('selected');
}

function openPlanModal(msg) {
  const u = getUsage();
  /* FIX Bug 5: null-guard planLimitMsg before writing to it */
  const lm = $('planLimitMsg');
  if(lm) lm.textContent = msg || `Daily free limit reached (${u.count}/${FREE_LIMIT} messages)`;
  const po = $('plan-overlay'); if(!po) return;
  po.classList.add('on');
  selectPlanCard('first_month');
}
function closePlanModal() {
  const po = $('plan-overlay'); if(po) po.classList.remove('on');
}

function updatePlanUI() {
  const pro = isPro();
  const u = getUsage();

  const badgeLabel = $('planBadgeLabel');
  const usageMini  = $('planUsageMini');

  if (pro) {
    if(badgeLabel){ badgeLabel.textContent = '✦ PRO'; badgeLabel.style.color='var(--accent)'; }
    if(usageMini) usageMini.textContent = '∞';
  } else {
    if(badgeLabel){ badgeLabel.textContent = 'FREE'; badgeLabel.style.color='var(--ink-3)'; }
    const remaining = Math.max(0, FREE_LIMIT - u.count);
    if(usageMini) usageMini.textContent = `${remaining} left`;
  }

  // Sync settings subscription tab
  const settPlanName = $('settPlanName');
  const settPlanDesc = $('settPlanDesc');
  const settPlanBadge = $('settPlanBadge');
  const settUsageCount = $('settUsageCount');
  const settUsageBar = $('settUsageBar');
  if (pro) {
    const plan = getPlan();
    const labels = { first_month:'First Month Special', pro_monthly:'Pro Monthly', pro_yearly:'Pro Yearly' };
    if(settPlanName) settPlanName.textContent = labels[plan.type] || 'Pro Plan';
    if(settPlanDesc) settPlanDesc.textContent = '✦ Unlimited AI messages & all features';
    if(settPlanBadge) settPlanBadge.innerHTML = '<span class="plan-pro-badge">✦ PRO</span>';
    if(settUsageCount) settUsageCount.textContent = '∞ unlimited';
    if(settUsageBar){ settUsageBar.style.width='100%'; settUsageBar.style.background='linear-gradient(90deg,var(--accent),var(--mint))'; }
  } else {
    if(settPlanName) settPlanName.textContent = 'Free Plan';
    if(settPlanDesc) settPlanDesc.textContent = `${FREE_LIMIT} messages/day · Resets daily`;
    if(settPlanBadge) settPlanBadge.innerHTML = '<span class="plan-free-badge">FREE</span>';
    const pct = Math.min(100, (u.count / FREE_LIMIT) * 100);
    if(settUsageCount) settUsageCount.textContent = `${u.count} / ${FREE_LIMIT}`;
    if(settUsageBar){
      settUsageBar.style.width = pct+'%';
      settUsageBar.className = 'usage-bar-fill' + (pct >= 100 ? ' danger' : pct >= 70 ? ' warn' : '');
    }
  }
}

// IMPROVED: window.sendMessage wrapper — delegates to internal sendMessage which
// already owns the _sendLock and State.isTyping guards. The wrapper only adds the
// empty-string guard for external callers who may pass untrimmed text.
// NOTE: internal callers (keyboard handler, send button, chips) already call
// the closure-scoped sendMessage directly so _sendLock is always respected.
const _origSendMessage = sendMessage;
window.sendMessage = function(text) {
  if (typeof text !== 'string' || !text.trim()) return;
  _origSendMessage(text);
};

