function initArchive() {
  // Archive context menu
  on('ctxArchive', 'click', () => {
    const id = _ctxId; hideCtxMenu();
    if (!id) return;
    const chat = APP.chats[id]; if (!chat) return;
    chat.archived = !chat.archived;
    if (chat.archived) { chat.pinned = false; }
    save(); renderChatList();
    toast(chat.archived ? '📦 Chat archived' : '📬 Chat unarchived', 'info');
  });
}

// Patch renderChatList to also handle archive label and ctxArchive label
const _origShowCtxMenu = showCtxMenu;
window.showCtxMenu = function(id, x, y) {
  _origShowCtxMenu(id, x, y);
  const chat = APP.chats[id];
  if (chat && $('ctxArchiveLbl')) {
    $('ctxArchiveLbl').textContent = chat.archived ? 'Unarchive Chat' : 'Archive Chat';
  }
};

// ══════════════════════════════════════════════════
// PATCH renderChatList to support archived chats
// ══════════════════════════════════════════════════
// FIXED: Removed unused _origRenderChatList capture — the archive patch below
// assigns _renderChatListImpl directly. The capture was a dead variable that
// created a confusing impression of monkey-patching when nothing used it.
// ══════════════════════════════════════════════════
// ARCHITECTURE v19 — SIDEBAR RENDER IMPLEMENTATION
// Uses createSidebarItem() component for each entry.
// DocumentFragment batch insert — single reflow.
// ══════════════════════════════════════════════════
window.renderChatList = _renderChatListImpl = function() {
  const el = $('sbChatList');
  if (!el) return;
  const q = ($('sbSearch')?.value || '').toLowerCase().trim();
  const all = Object.values(APP.chats)
    .filter(c => {
      if (c.archived) return false;
      if (q && !c.title.toLowerCase().includes(q) &&
          !c.messages.some(m => m.content.toLowerCase().includes(q))) return false;
      if (APP.activeCategory !== 'all' && c.category !== APP.activeCategory) return false;
      return true;
    })
    .sort((a, b) => {
      // Pinned first, then by createdAt desc
      if (a.pinned && !b.pinned) return -1;
      if (!a.pinned && b.pinned) return 1;
      return (b.createdAt || 0) - (a.createdAt || 0);
    });

  const archived = Object.values(APP.chats).filter(c => c.archived);

  // ── Empty state ────────────────────────────────
  if (!all.length && !archived.length) {
    el.innerHTML = q
      ? `<div class="sb-empty"><div class="sb-empty-ico">🔍</div><div class="sb-empty-title">No results</div><div class="sb-empty-sub">No chats match "<em>${esc(q)}</em>"</div></div>`
      : `<div class="sb-empty"><div class="sb-empty-ico">💬</div><div class="sb-empty-title">No chats yet</div><div class="sb-empty-sub">Start a new conversation to get going</div><button class="sb-empty-btn" id="sbEmptyStartBtn">Start chatting →</button></div>`;
    // Wire the button via JS (no inline onclick)
    const startBtn = el.querySelector('#sbEmptyStartBtn');
    if (startBtn) startBtn.addEventListener('click', () => { const ta = document.getElementById('msg-ta'); if(ta) ta.focus(); });
    return;
  }

  // ── Build via DocumentFragment (single DOM insertion) ─
  const frag = document.createDocumentFragment();

  const pinned   = all.filter(c => c.pinned);
  const unpinned = all.filter(c => !c.pinned);

  // v19: Pinned section
  if (pinned.length) {
    const lbl = document.createElement('div');
    lbl.className = 'sb-pinned-lbl';
    lbl.setAttribute('aria-hidden', 'true');
    lbl.innerHTML = `<svg width="10" height="10" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M5 17h14v-1.76a2 2 0 0 0-1.11-1.79l-1.78-.9A2 2 0 0 1 15 10.76V6h1a2 2 0 0 0 0-4H8a2 2 0 0 0 0 4h1v4.76a2 2 0 0 1-1.11 1.79l-1.78.9A2 2 0 0 0 5 15.24Z"/></svg> Pinned`;
    frag.appendChild(lbl);
    // v19: Use createSidebarItem() component for each pinned chat
    pinned.forEach((c, i) => {
      const item = createSidebarItem(c, c.id === APP.activeChatId);
      item.style.animationDelay = `${i * 0.03}s`;
      frag.appendChild(item);
    });
  }

  // v19: Recent section
  if (unpinned.length) {
    const lbl = document.createElement('div');
    lbl.className = 'sb-section-lbl';
    lbl.setAttribute('aria-hidden', 'true');
    lbl.textContent = pinned.length ? 'Recent' : 'Recent';
    if (pinned.length) lbl.style.paddingTop = '6px';
    frag.appendChild(lbl);
    // v19: Use createSidebarItem() component for each unpinned chat
    unpinned.forEach((c, i) => {
      const item = createSidebarItem(c, c.id === APP.activeChatId);
      item.style.animationDelay = `${(pinned.length + i) * 0.03}s`;
      frag.appendChild(item);
    });
  }

  // Archived section (collapsible)
  if (archived.length) {
    const showArch = APP._showArchived;
    const archLbl = document.createElement('div');
    archLbl.className = 'sb-archived-lbl';
    archLbl.id = 'sbArchivedToggle';
    archLbl.setAttribute('aria-expanded', showArch ? 'true' : 'false');
    archLbl.setAttribute('title', 'Toggle archived');
    archLbl.innerHTML = `<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><polyline points="21 8 21 21 3 21 3 8"/><rect x="1" y="3" width="22" height="5"/></svg>
      Archived (${archived.length})
      <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="margin-left:auto;transform:rotate(${showArch?'180':'0'}deg);transition:transform 0.2s" aria-hidden="true"><polyline points="6 9 12 15 18 9"/></svg>`;
    archLbl.addEventListener('click', () => {
      APP._showArchived = !APP._showArchived;
      renderChatList();
    });
    frag.appendChild(archLbl);
    if (showArch) {
      archived.forEach((c, i) => {
        const item = createSidebarItem(c, c.id === APP.activeChatId);
        item.classList.add('archived');
        item.style.animationDelay = `${i * 0.03}s`;
        frag.appendChild(item);
      });
    }
  }

  // v19: Single DOM write — replaces entire list in one reflow
  el.innerHTML = '';
  el.appendChild(frag);
};

// Extend APP state for archive toggle
APP._showArchived = false;

// Initial render using our patched version
setTimeout(() => { window.renderChatList(); }, 50);

