// ── Plus Toggle Button — popover open/close ───────
(function initPlusPopover() {
  const plusBtn = $('plusToggleBtn');
  const popover = $('plus-popover');
  if (!plusBtn || !popover) return;

  function openPop() {
    popover.classList.add('open');
    popover.setAttribute('aria-hidden', 'false');
    plusBtn.classList.add('open');
    plusBtn.setAttribute('aria-expanded', 'true');
  }
  function closePop() {
    popover.classList.remove('open');
    popover.setAttribute('aria-hidden', 'true');
    plusBtn.classList.remove('open');
    plusBtn.setAttribute('aria-expanded', 'false');
  }
  function togglePop() {
    popover.classList.contains('open') ? closePop() : openPop();
  }

  on('plusToggleBtn', 'click', (e) => {
    e.stopPropagation();
    // FIX: sync active states on every open so popover reflects current model/tool
    if (!popover.classList.contains('open')) {
      const curModel = (typeof APP !== 'undefined' && APP.activeAiModel) || 'gemini-flash';
      popover.querySelectorAll('.plus-pop-model').forEach(b => b.classList.toggle('active', b.dataset.model === curModel));
      popover.querySelectorAll('.plus-pop-tool').forEach(b => {
        const rp = $(b.dataset.tool);
        b.classList.toggle('active', rp && rp.dataset.active === 'true');
      });
    }
    togglePop();
  });

  // Close on outside click
  document.addEventListener('click', (e) => {
    if (popover.classList.contains('open') && !popover.contains(e.target) && e.target !== plusBtn) closePop();
  });
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape') closePop(); });

  // File upload
  const ppFile = $('ppFileUpload');
  if (ppFile) ppFile.addEventListener('click', () => { closePop(); if (fileInputHidden) fileInputHidden.click(); });

  // Image upload
  const ppImg = $('ppImgUpload');
  if (ppImg) ppImg.addEventListener('click', () => { closePop(); if (imgInputHidden) imgInputHidden.click(); });

  // Camera
  const ppCam = $('ppCamera');
  if (ppCam) ppCam.addEventListener('click', () => { closePop(); toast('Camera capture — coming soon!'); });

  // Model switcher via popover
  popover.querySelectorAll('.plus-pop-model').forEach(btn => {
    btn.addEventListener('click', () => {
      const model = btn.dataset.model;
      // Sync with the existing model pill system
      document.querySelectorAll('.ai-model-pill').forEach(p => {
        const isMatch = p.dataset.model === model;
        p.classList.toggle('active', isMatch);
        p.setAttribute('aria-pressed', String(isMatch));
      });
      // Update app state
      if (typeof APP !== 'undefined') APP.activeAiModel = model;
      // Update model label in header if present
      const modelLabel = $('modelLabel');
      if (modelLabel) {
        const names = {'gemini-flash':'Flash','gemini-pro':'Pro','openrouter-llama':'Llama','openrouter-mistral':'Mistral','gemini-ultra':'Ultra','openrouter-gemini':'Gemini','openrouter-gpt4o':'GPT-4o'};
        modelLabel.textContent = names[model] || model;
      }
      // Mark active in popover
      popover.querySelectorAll('.plus-pop-model').forEach(b => b.classList.toggle('active', b.dataset.model === model));
      closePop();
      toast(`Model: ${btn.querySelector('.plus-pop-lbl').textContent}`, 'info', 1800);
    });
  });

  // Tool toggles via popover
  popover.querySelectorAll('.plus-pop-tool').forEach(btn => {
    btn.addEventListener('click', () => {
      const toolId = btn.dataset.tool;
      const realPill = $(toolId);
      if (realPill) realPill.click(); // delegate to existing pill handler
      // Mirror active state back to popover item
      setTimeout(() => {
        const isActive = realPill && realPill.dataset.active === 'true';
        btn.classList.toggle('active', isActive);
      }, 50);
    });
  });
})();

// FIXED: null guard — imgInputHidden captured at top level, may be null if element absent
