function addFileChip(name) {
  const row = $('attachedRow'); if(!row) return;
  const chip = document.createElement('div');
  chip.className = 'afile-chip';
  chip.innerHTML = `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M13 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9z"/><polyline points="13 2 13 9 20 9"/></svg><span style="max-width:140px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(name)}</span><button class="afile-rm" title="Remove" aria-label="Remove ${esc(name)}">×</button>`;
  chip.querySelector('.afile-rm').addEventListener('click', () => chip.remove());
  row.appendChild(chip);
}

if (fileInputHidden) {
  fileInputHidden.addEventListener('change', () => {
    [...fileInputHidden.files].forEach(f => addFileChip(f.name));
    fileInputHidden.value = '';
  });
}

function addImageThumb(file) {
  const row = $('attachedRow'); if(!row) return;
  const reader = new FileReader();
  reader.onload = e => {
    const wrap = document.createElement('div');
    wrap.className = 'afile-img';
    wrap.innerHTML = `<img loading="lazy" decoding="async" src="${e.target.result}" alt="${esc(file.name)}"/><button class="afile-img-rm" title="Remove" aria-label="Remove image">×</button>`;
    wrap.querySelector('.afile-img-rm').addEventListener('click', () => wrap.remove());
    row.appendChild(wrap);
  };
  reader.readAsDataURL(file);
}

if (imgInputHidden) {
  imgInputHidden.addEventListener('change', () => {
    [...imgInputHidden.files].forEach(f => addImageThumb(f));
    imgInputHidden.value = '';
  });
}

// Patch sendMessage to prepend tool prefix
const _sendMsg_orig2 = window.sendMessage;
window.sendMessage = function(text) {
  if (!text.trim()) return;
  const full = APP._toolPrefix ? APP._toolPrefix + text : text;
  _sendMsg_orig2(full);
};

// ══════════════════════════════════════════════════
// GUEST LIMIT MODAL — 5 messages then sign-in wall
// ══════════════════════════════════════════════════
let _glmTimer = null;

function showGuestLimitModal() {
  const overlay = $('guest-limit-overlay'); if(!overlay) return;
  overlay.classList.add('on');
  // Disable input
  const ta = $('msg-ta'); const sb = $('send-btn');
  if(ta) ta.disabled = true;
  if(sb) sb.disabled = true;
  qsa('.inp-tool-pill').forEach(b => b.disabled = true);

  // Countdown: 10s → auto-close chat
  let secs = 10;
  const cdEl = $('glmCountdown');
  if(cdEl) cdEl.textContent = secs;
  _glmTimer = setInterval(() => {
    secs--;
    if(cdEl) cdEl.textContent = secs;
    if(secs <= 0) {
      clearInterval(_glmTimer);
      overlay.classList.remove('on');
      lockChat();
    }
  }, 1000);
}

function hideGuestLimitModal() {
  const overlay = $('guest-limit-overlay'); if(!overlay) return;
  overlay.classList.remove('on');
  if(_glmTimer) { clearInterval(_glmTimer); _glmTimer=null; }
  // Re-enable input only if user is logged in
  if(getAuthUser()) {
    const ta=$('msg-ta'); if(ta) ta.disabled=false;
    updateSendBtn();
    qsa('.inp-tool-pill').forEach(b => b.disabled=false);
  }
}

function lockChat() {
  // Show locked overlay — input permanently blocked until sign-in
  const locked = $('chat-locked-overlay');
  if(locked) locked.style.display = 'flex';
  const ta=$('msg-ta'); if(ta) ta.disabled=true;
  const sb=$('send-btn'); if(sb) sb.disabled=true;
}

function unlockChat() {
  const locked = $('chat-locked-overlay');
  if(locked) locked.style.display='none';
  const ta=$('msg-ta'); if(ta) ta.disabled=false;
  updateSendBtn();
}

// Wire up modal buttons (guest limit modal — UI only, no hard block)
(function initGuestLimitModal() {
  const glmSignup = $('glmSignupBtn');
  const glmLogin  = $('glmLoginBtn');
  const glmClose  = $('glmCloseX');
  const cloSignup = $('cloSignupBtn');
  const cloLogin  = $('cloLoginBtn');

  if(glmSignup) glmSignup.addEventListener('click', () => { hideGuestLimitModal(); openAuthOverlay('signup'); });
  if(glmLogin)  glmLogin.addEventListener('click',  () => { hideGuestLimitModal(); openAuthOverlay('login'); });
  if(glmClose)  glmClose.addEventListener('click',  () => { hideGuestLimitModal(); });
  if(cloSignup) cloSignup.addEventListener('click', () => openAuthOverlay('signup'));
  if(cloLogin)  cloLogin.addEventListener('click',  () => openAuthOverlay('login'));
})();

// PRODUCTION FIX [v29]: Replaced the fragile window.loginSuccess monkey-patch with
// ZenQBus event subscription. The old pattern mutated window.loginSuccess, which:
//   (a) broke if loginSuccess was called before the override was assigned
//   (b) caused subtle bugs if the override ran more than once (double-wrap)
//   (c) violated the module boundary — internal callers held local references
// The event bus is the correct seam for cross-cutting concerns like this.
ZenQBus.on('auth:login', () => {
  hideGuestLimitModal();
  unlockChat();
});

function applyLanguage(lang) {
  APP.uiLang = lang;
  try { localStorage.setItem('aura_lang', lang); } catch(e){}
  const s = LANG_STRINGS[lang] || LANG_STRINGS.en;

  // Update all static UI strings
  const map = {
    'sbNewBtn':        s.newChat,
    'sbSearch':        null, // placeholder handled below
    'sbSettBtn':       null,
    'hdrTitle':        null,
    'stop-btn':        null,
  };

  // Sidebar labels
  const sbl = document.querySelectorAll('.sb-new-lbl');
  sbl.forEach(el => el.textContent = s.newChat);
  const sbSearch = $('sbSearch');
  if(sbSearch) sbSearch.placeholder = s.searchChats;

  // BUG FIX: Use locale messagePlaceholder string (includes keyboard hints) instead of hardcoded short string.
  const ta = $('msg-ta');
  if (ta) {
    ta.placeholder = s.messagePlaceholder || 'Message ZenQ';
    ta.setAttribute('aria-label', s.messagePlaceholder || 'Message ZenQ');
  }
  const hint = document.querySelector('.inp-hint');
  if(hint) hint.innerHTML = s.inputHint;

  // Welcome screen
  const wt = document.querySelector('.wlc-title');
  if(wt) wt.textContent = s.welcome;
  const ws = document.querySelector('.wlc-sub');
  if(ws) ws.textContent = s.welcomeSub;

  // Footer buttons
  const sbFootBtns = document.querySelectorAll('.sb-foot-lbl');
  const footKeys = ['shortcuts','exportChat','settings'];
  sbFootBtns.forEach((el,i) => { if(s[footKeys[i]]) el.textContent = s[footKeys[i]]; });

  // Sidebar section labels
  document.querySelectorAll('.sb-section-lbl').forEach(el => {
    const txt = el.textContent.trim();
    if(['Recent','சமீபத்தியது','हाल का','最近','最近の','최근','Récent','Reciente','Zuletzt','الأخيرة'].includes(txt))
      el.textContent = s.recent;
  });

  // RTL support for Arabic
  document.documentElement.setAttribute('dir', lang === 'ar' ? 'rtl' : 'ltr');

  qsa('[data-lang]').forEach(b=>b.classList.toggle('active', b.dataset.lang===lang));
  renderPlaceholderChips();
}

