// ══════════════════════════════════════════════════
// SHARED LINKS SYSTEM
// ══════════════════════════════════════════════════
(function initSharedLinks() {
  const SHARED_KEY = 'aura_shared_links';

  function getSharedLinks() {
    try { return JSON.parse(localStorage.getItem(SHARED_KEY)) || []; } catch(e) { return []; }
  }
  function saveSharedLinks(links) {
    try { localStorage.setItem(SHARED_KEY, JSON.stringify(links)); } catch(e) {}
  }

  function generateLinkId() {
    return Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
  }

  function renderActiveLinks() {
    const list = document.getElementById('activeSharedLinksList');
    if (!list) return;
    const links = getSharedLinks();
    if (!links.length) {
      list.innerHTML = '<div style="padding:16px;text-align:center;color:var(--ink-3);font-size:13px">No active shared links</div>';
      return;
    }
    list.innerHTML = links.map(l => {
      const date = new Date(l.createdAt).toLocaleDateString();
      const expiry = l.expiry === 'never' ? 'No expiry' : `Expires: ${l.expiry}`;
      return `<div style="padding:12px 16px;border-bottom:1px solid var(--sp-row-sep,var(--glass-border));display:flex;align-items:center;gap:10px;last-child:border-none">
        <div style="flex:1;min-width:0">
          <div style="font-size:13px;font-weight:500;color:var(--ink-1);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(l.chatTitle || 'Untitled Chat')}</div>
          <div style="font-size:11px;color:var(--ink-3);margin-top:2px">${date} · ${expiry}</div>
        </div>
        <button onclick="navigator.clipboard&&window.isSecureContext?navigator.clipboard.writeText('${esc(l.url)}').then(()=>toast('Link copied!','success')):toast('Copied!','success')" style="padding:5px 10px;border-radius:8px;background:var(--glass-bg-3);border:1px solid var(--glass-border);color:var(--ink-2);font-size:11px;cursor:pointer;flex-shrink:0">Copy</button>
        <button data-link-id="${esc(l.id)}" class="shared-link-revoke-btn" style="padding:5px 10px;border-radius:8px;background:rgba(242,92,110,0.1);border:1px solid rgba(242,92,110,0.25);color:var(--red);font-size:11px;cursor:pointer;flex-shrink:0">Remove</button>
      </div>`;
    }).join('');

    // Wire revoke buttons
    list.querySelectorAll('.shared-link-revoke-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const id = btn.dataset.linkId;
        const updated = getSharedLinks().filter(l => l.id !== id);
        saveSharedLinks(updated);
        renderActiveLinks();
        toast('Link revoked', 'info');
      });
    });
  }

  // Generate link button
  const genBtn = document.getElementById('generateSharedLinkBtn');
  if (genBtn) {
    genBtn.addEventListener('click', () => {
      const expiry = document.querySelector('.speed-opt[data-expiry].active')?.dataset.expiry || 'never';
      const showName = document.getElementById('shareLinkNameToggle')?.checked !== false;
      const includeAI = document.getElementById('shareLinkAiToggle')?.checked !== false;
      const chatId = typeof APP !== 'undefined' ? APP.activeChatId : null;
      const chat = chatId && typeof APP !== 'undefined' ? APP.chats[chatId] : null;
      const id = generateLinkId();
      const url = `${location.origin}${location.pathname}?share=${id}`;

      const links = getSharedLinks();
      links.unshift({
        id,
        url,
        chatTitle: chat?.title || 'Untitled Chat',
        chatId: chatId || null,
        createdAt: Date.now(),
        expiry,
        showName,
        includeAI,
      });
      saveSharedLinks(links);

      const inp = document.getElementById('sharedLinkInput');
      if (inp) { inp.value = url; inp.select(); }
      renderActiveLinks();
      toast('🔗 Shared link created!', 'success');
    });
  }

  // Copy button
  const copyBtn = document.getElementById('copySharedLinkBtn');
  if (copyBtn) {
    copyBtn.addEventListener('click', () => {
      const inp = document.getElementById('sharedLinkInput');
      if (!inp || !inp.value) { toast('Generate a link first', 'warn'); return; }
      if (navigator.clipboard && window.isSecureContext) {
        navigator.clipboard.writeText(inp.value).then(() => toast('Link copied! 🔗', 'success'));
      } else {
        inp.select();
        document.execCommand('copy');
        toast('Link copied! 🔗', 'success');
      }
    });
  }

  // Revoke current link
  const revokeBtn = document.getElementById('revokeSharedLinkBtn');
  if (revokeBtn) {
    revokeBtn.addEventListener('click', () => {
      const inp = document.getElementById('sharedLinkInput');
      if (inp) inp.value = '';
      toast('Current link revoked', 'info');
    });
  }

  // Revoke all
  const revokeAllBtn = document.getElementById('revokeAllLinksBtn');
  if (revokeAllBtn) {
    revokeAllBtn.addEventListener('click', () => {
      saveSharedLinks([]);
      const inp = document.getElementById('sharedLinkInput');
      if (inp) inp.value = '';
      renderActiveLinks();
      toast('All shared links revoked', 'info');
    });
  }

  // Expiry option buttons
  document.querySelectorAll('.speed-opt[data-expiry]').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.speed-opt[data-expiry]').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
    });
  });

  // Render on settings open
  const origOpen = window.openSettings;
  if (typeof origOpen === 'function') {
    window.openSettings = function(tabId) {
      origOpen(tabId);
      if (!tabId || tabId === 'sharedlink') renderActiveLinks();
    };
  }
  renderActiveLinks();
})();

// ══════════════════════════════════════════════════
// CUSTOMIZE AURA SETTINGS
// ══════════════════════════════════════════════════
(function initCustomizeZenQ() {
  const CUSTOM_KEY = 'aura_customization';

  function getAuraCustom() {
    try { return JSON.parse(localStorage.getItem(CUSTOM_KEY)) || {}; } catch(e) { return {}; }
  }
  function saveAuraCustom(obj) {
    try { localStorage.setItem(CUSTOM_KEY, JSON.stringify(obj)); } catch(e) {}
  }

  const DEFAULTS = {
    name: 'ZenQ',
    greeting: 'How can I help you today?',
    tone: 'balanced',
    length: 'medium',
    emoji: true,
    think: false,
    avatar: 'orb',
    autoSuggest: true,
    memory: true,
    tips: true,
  };

  function applyAuraCustomization(cfg) {
    // Update sidebar wordmark with custom name
    const wordmark = document.querySelector('.sb-wordmark');
    if (wordmark) wordmark.textContent = cfg.name || 'ZenQ';

    // Update page title
    document.title = `${cfg.name || 'ZenQ'} AI v38`;

    // Update welcome screen subtitle
    const wlcSub = document.querySelector('.wlc-sub');
    if (wlcSub && cfg.greeting) wlcSub.textContent = cfg.greeting;

    // Update placeholder
    const ta = document.getElementById('msg-ta');
    if (ta) ta.placeholder = `Message ${cfg.name || 'ZenQ'}`;

    // Tone → system prompt prefix
    const toneMap = {
      friendly: 'Be warm, friendly, and encouraging in your responses. Use a conversational tone. ',
      formal: 'Be professional, precise, and formal in all responses. ',
      concise: 'Be very concise and to the point. Keep responses as brief as possible. ',
      balanced: '',
    };
    APP._tonePrefix = toneMap[cfg.tone] || '';

    // Length → hint
    const lengthMap = {
      short: 'Keep your response brief (2-4 sentences max). ',
      detailed: 'Be thorough and detailed in your response. ',
      medium: '',
    };
    APP._lengthPrefix = lengthMap[cfg.length] || '';

    // Emoji toggle
    APP._noEmoji = !cfg.emoji;
    if (!cfg.emoji) APP._tonePrefix = (APP._tonePrefix || '') + 'Do not use emojis in your responses. ';

    // Think toggle
    APP._thinkMode = cfg.think;
    if (cfg.think) APP._lengthPrefix = (APP._lengthPrefix || '') + 'Before answering, briefly explain your reasoning process. ';
  }

  function loadCustomizeUI() {
    const cfg = Object.assign({}, DEFAULTS, getAuraCustom());

    const nameInp = document.getElementById('zenqNameInput');
    const greetInp = document.getElementById('auraGreetingInput');
    if (nameInp) nameInp.value = cfg.name;
    if (greetInp) greetInp.value = cfg.greeting;

    // Tone buttons
    document.querySelectorAll('#auraToneBtns .speed-opt').forEach(btn => {
      btn.classList.toggle('active', btn.dataset.tone === cfg.tone);
    });

    // Length buttons
    document.querySelectorAll('#auraLengthBtns .speed-opt').forEach(btn => {
      btn.classList.toggle('active', btn.dataset.length === cfg.length);
    });

    // Toggles
    const emojiToggle = document.getElementById('zenqEmojiToggle');
    const thinkToggle = document.getElementById('zenqThinkToggle');
    const autoSuggestToggle = document.getElementById('auraAutoSuggestToggle');
    const memoryToggle = document.getElementById('zenqMemoryToggle');
    const tipsToggle = document.getElementById('zenqTipsToggle');
    if (emojiToggle) emojiToggle.checked = cfg.emoji;
    if (thinkToggle) thinkToggle.checked = cfg.think;
    if (autoSuggestToggle) autoSuggestToggle.checked = cfg.autoSuggest;
    if (memoryToggle) memoryToggle.checked = cfg.memory;
    if (tipsToggle) tipsToggle.checked = cfg.tips;

    // Avatar buttons
    document.querySelectorAll('.aura-avatar-opt').forEach(btn => {
      const isActive = btn.dataset.avatar === cfg.avatar;
      btn.style.borderColor = isActive ? 'var(--accent)' : 'var(--glass-border)';
      btn.style.background = isActive ? 'linear-gradient(135deg,var(--accent),var(--accent-2))' : 'var(--glass-bg-3)';
      btn.classList.toggle('active', isActive);
    });
  }

  function saveCustomizeSettings() {
    const cfg = Object.assign({}, DEFAULTS, getAuraCustom());

    const nameInp = document.getElementById('zenqNameInput');
    const greetInp = document.getElementById('auraGreetingInput');
    if (nameInp && nameInp.value.trim()) cfg.name = nameInp.value.trim();
    if (greetInp && greetInp.value.trim()) cfg.greeting = greetInp.value.trim();

    const activeTone = document.querySelector('#auraToneBtns .speed-opt.active');
    if (activeTone) cfg.tone = activeTone.dataset.tone;

    const activeLen = document.querySelector('#auraLengthBtns .speed-opt.active');
    if (activeLen) cfg.length = activeLen.dataset.length;

    const emojiToggle = document.getElementById('zenqEmojiToggle');
    const thinkToggle = document.getElementById('zenqThinkToggle');
    const autoSuggestToggle = document.getElementById('auraAutoSuggestToggle');
    const memoryToggle = document.getElementById('zenqMemoryToggle');
    const tipsToggle = document.getElementById('zenqTipsToggle');
    if (emojiToggle) cfg.emoji = emojiToggle.checked;
    if (thinkToggle) cfg.think = thinkToggle.checked;
    if (autoSuggestToggle) cfg.autoSuggest = autoSuggestToggle.checked;
    if (memoryToggle) cfg.memory = memoryToggle.checked;
    if (tipsToggle) cfg.tips = tipsToggle.checked;

    const activeAvatar = document.querySelector('.aura-avatar-opt.active');
    if (activeAvatar) cfg.avatar = activeAvatar.dataset.avatar;

    saveAuraCustom(cfg);
    applyAuraCustomization(cfg);
    toast('✦ ZenQ customized!', 'success');
  }

  // Wire tone buttons
  document.querySelectorAll('#auraToneBtns .speed-opt').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('#auraToneBtns .speed-opt').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
    });
  });

  // Wire length buttons
  document.querySelectorAll('#auraLengthBtns .speed-opt').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('#auraLengthBtns .speed-opt').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
    });
  });

  // Wire avatar buttons
  document.querySelectorAll('.aura-avatar-opt').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.aura-avatar-opt').forEach(b => {
        b.style.borderColor = 'var(--glass-border)';
        b.style.background = 'var(--glass-bg-3)';
        b.classList.remove('active');
      });
      btn.style.borderColor = 'var(--accent)';
      btn.style.background = 'linear-gradient(135deg,var(--accent),var(--accent-2))';
      btn.classList.add('active');
    });
  });

  // Identity save
  const identitySaveBtn = document.getElementById('auraIdentitySaveBtn');
  if (identitySaveBtn) identitySaveBtn.addEventListener('click', saveCustomizeSettings);

  // Settings save
  const settingsSaveBtn = document.getElementById('auraSettingsSaveBtn');
  if (settingsSaveBtn) settingsSaveBtn.addEventListener('click', saveCustomizeSettings);

  // Reset
  const resetBtn = document.getElementById('resetZenQSettingsBtn');
  if (resetBtn) {
    resetBtn.addEventListener('click', () => {
      saveAuraCustom(DEFAULTS);
      loadCustomizeUI();
      applyAuraCustomization(DEFAULTS);
      toast('ZenQ reset to defaults', 'info');
    });
  }

  // Patch sendMessage to prepend tone+length prefixes
  const _origSend = window.sendMessage;
  if (typeof _origSend === 'function') {
    window.sendMessage = function(text) {
      if (!text || !text.trim()) return;
      const prefix = (APP._tonePrefix || '') + (APP._lengthPrefix || '');
      _origSend(prefix ? prefix + text : text);
    };
  }

  // Load on settings open — always refresh customize UI when that tab becomes active
  const origOpen2 = window.openSettings;
  if (typeof origOpen2 === 'function') {
    window.openSettings = function(tabId) {
      origOpen2(tabId);
      // FIX: always call loadCustomizeUI — tabId may be 'appearance' (sidebar button)
      // or undefined, but user can click to customize tab anytime; refreshing is cheap
      // and ensures the UI reflects current saved state whenever settings opens.
      loadCustomizeUI();
    };
  }

  // Also wire tab nav clicks directly so switching to customize always refreshes
  const _customizeNavBtn = document.querySelector('.sp-nav-item[data-tab="customize"]');
  if (_customizeNavBtn) {
    _customizeNavBtn.addEventListener('click', () => {
      // Small delay so switchSettTab() has time to show the tab
      setTimeout(loadCustomizeUI, 30);
    });
  }

  // Boot: apply saved customization
  const saved = getAuraCustom();
  if (Object.keys(saved).length) {
    applyAuraCustomization(Object.assign({}, DEFAULTS, saved));
  }
  loadCustomizeUI();
})();

