// ── Tool Pills Toggle ─────────────────────────────
function initToolPills() {
  qsa('.inp-tool-pill').forEach(pill => {
    pill.addEventListener('click', () => {
      const wasActive = pill.dataset.active === 'true';
      // Deactivate all pills
      qsa('.inp-tool-pill').forEach(p => { p.dataset.active = 'false'; p.setAttribute('aria-pressed','false'); p.classList.remove('on'); });
      const badge = $('activeToolBadge');
      if (!wasActive) {
        pill.dataset.active = 'true';
        pill.setAttribute('aria-pressed','true');
        pill.classList.add('on');
        // Sync _toolPrefix so sendMessage patch injects the correct prefix
        APP._toolPrefix = TOOL_MODES[pill.id]?.prefix || '';
        APP._activeTool = pill.id.replace('tool','').toLowerCase();
        const label = TOOL_MODES[pill.id]?.label || pill.textContent.trim();
        if (badge) { badge.textContent = label; badge.style.display = 'block'; }
        toast(label + ' activated', 'info', 1600);
      } else {
        APP._toolPrefix = '';
        APP._activeTool = null;
        if (badge) badge.style.display = 'none';
        toast('Tool off', 'info', 1400);
      }
    });
  });
}

function selectAIMode(card) {
  const mode = card.dataset.mode;
  // ACCESSIBILITY FIX [v23]: Update aria-pressed on all cards
  qsa('.aimode-card').forEach(c => {
    c.classList.remove('active');
    c.setAttribute('aria-pressed', 'false');
  });
  card.classList.add('active');
  card.setAttribute('aria-pressed', 'true');
  const customArea = $('customPromptArea');
  if (mode === 'custom') { if(customArea) customArea.style.display = 'block'; return; }
  if (customArea) customArea.style.display = 'none';
  APP.aiMode = mode;
  APP.systemPrompt = AI_MODES[mode]?.prompt || '';
  try { localStorage.setItem('aura_ai_mode', mode); localStorage.setItem('aura_sys_prompt', APP.systemPrompt); } catch(e){}
  const badge = $('activeModeDisplay');
  if (badge) badge.textContent = `✦ ${AI_MODES[mode]?.emoji||''} ${AI_MODES[mode]?.name||mode}`;
  ZenQLogger.info('AIMode', `Switched to mode: ${mode}`);
  toast(`${AI_MODES[mode]?.emoji||''} ${AI_MODES[mode]?.name||mode} mode activated`, mode==='default'?'info':'success');
  // ── Auto-close settings panel after mode selection ──
  setTimeout(() => {
    if ($('sett-panel')?.classList.contains('on')) closeSettings();
  }, 600);
}

function applyCustomMode() {
  const ta = $('customSystemPrompt');
  if(!ta||!ta.value.trim()){ toast('Please enter a custom system prompt','error'); return; }
  APP.aiMode = 'custom'; APP.systemPrompt = ta.value.trim();
  try { localStorage.setItem('aura_ai_mode','custom'); localStorage.setItem('aura_sys_prompt',APP.systemPrompt); } catch(e){}
  const badge = $('activeModeDisplay');
  if(badge) badge.textContent = '✦ ✏️ Custom Mode';
  toast('✦ Custom AI mode applied','success');
}

function initAIMode() {
  try {
    const savedMode = localStorage.getItem('aura_ai_mode') || 'default';
    const savedPrompt = localStorage.getItem('aura_sys_prompt') || '';
    APP.aiMode = savedMode; APP.systemPrompt = savedPrompt;
    const card = qs(`.aimode-card[data-mode="${savedMode}"]`);
    if(card){
      qsa('.aimode-card').forEach(c => { c.classList.remove('active'); c.setAttribute('aria-pressed','false'); });
      card.classList.add('active');
      card.setAttribute('aria-pressed','true');
    }
    const badge = $('activeModeDisplay');
    const m = AI_MODES[savedMode];
    if(badge&&m) badge.textContent = `✦ ${m.emoji} ${m.name}`;
    if(savedMode==='custom'){
      const ta=$('customSystemPrompt'); if(ta) ta.value=savedPrompt;
      const ca=$('customPromptArea'); if(ca) ca.style.display='block';
    }
  } catch(e){}

  // SECURITY FIX [v23]: Event delegation on the grid — replaces inline onclick handlers.
  // Single listener instead of one per card. Also handles keyboard activation.
  const grid = $('aimodeGrid');
  if (grid) {
    grid.addEventListener('click', e => {
      const card = e.target.closest('.aimode-card');
      if (card) selectAIMode(card);
    });
    grid.addEventListener('keydown', e => {
      if (e.key === 'Enter' || e.key === ' ') {
        const card = e.target.closest('.aimode-card');
        if (card) { e.preventDefault(); selectAIMode(card); }
      }
    });
  }

  // Wire "Apply Custom Mode" button via JS (not inline onclick)
  on('applyCustomModeBtn', 'click', applyCustomMode);
}

function initLanguage() {
  try {
    const savedLang = localStorage.getItem('aura_lang') || 'en';
    const savedAiLang = localStorage.getItem('aura_ai_lang') || 'en';
    APP.uiLang = savedLang; APP.aiLang = savedAiLang;
    APP._aiLangPrefix = savedAiLang==='ta' ? 'Please respond in Tamil (தமிழ்). ' : '';
    qsa('[data-lang]').forEach(b=>b.classList.toggle('active', b.dataset.lang===savedLang));
    qsa('[data-ai-lang]').forEach(b=>b.classList.toggle('active', b.dataset.aiLang===savedAiLang));
    if(savedLang!=='en') setTimeout(()=>applyLanguage(savedLang), 200);
  } catch(e){}

  // SECURITY FIX [v23]: Replace inline onclick on lang-opt buttons with event delegation.
  // Wire [data-lang] buttons → applyLanguage, [data-ai-lang] buttons → setAILang
  document.querySelectorAll('[data-lang]').forEach(btn => {
    btn.addEventListener('click', () => applyLanguage(btn.dataset.lang));
  });
  document.querySelectorAll('[data-ai-lang]').forEach(btn => {
    btn.addEventListener('click', () => setAILang(btn.dataset.aiLang));
  });

  // SECURITY FIX [v23]: Wire all remaining settings-panel buttons that previously
  // used inline onclick. Centralised here so all wiring is in one auditable place.
  on('revokeSessionsBtn',   'click', () => toast('All sessions revoked', 'info'));
  on('clearActivityLogBtn', 'click', () => toast('Activity log cleared', 'success'));
  on('changelogBtn',        'click', () => toast('Opening changelog…', 'info'));
  on('docsBtn',             'click', () => toast('Opening documentation…', 'info'));
  on('privacyBtn',          'click', () => window.open('https://privacy-policy-zenq.vercel.app/', '_blank', 'noopener,noreferrer'));
  on('exportLogsBtn',       'click', () => { ZenQLogger.exportLogs(); toast('Logs exported', 'success'); });
  on('submitBugReportBtn',  'click', submitBugReport);
  on('settLogoutBtn',       'click', () => handleLogout(false));
  on('settLogoutClearBtn',  'click', () => handleLogout(true));

  // Plan upgrade cards — wire via JS (onclick was previously inline on the divs)
  on('planCardOffer',    'click', () => { switchSettTab('subscription'); openPlanModal(); });
  on('planCardMonthly',  'click', openPlanModal);
  on('planCardYearly',   'click', openPlanModal);
}

// ══════════════════════════════════════════════════
// MULTI-AI MODEL SWITCHER
// ══════════════════════════════════════════════════
function initMultiAIModel() {
  // Restore saved model
  try {
    const saved = localStorage.getItem('aura_ai_model_sel') || 'gemini-flash';
    APP.activeAiModel = saved;
    syncModelPills(saved);
  } catch(e) {}

  // Bind pill clicks — Gemini + OpenRouter models
  qsa('.ai-model-pill').forEach(pill => {
    pill.addEventListener('click', () => {
      const model = pill.dataset.model;
      APP.activeAiModel = model;
      try { localStorage.setItem('aura_ai_model_sel', model); } catch(e) {}
      syncModelPills(model);
      const pCfg = AI_PROVIDERS[model];
      const labels = {
        'gemini-flash':        '⚡ Gemini 2.0 Flash — fast & smart',
        'gemini-pro':          '✨ Gemini 1.5 Pro — 1M context',
        'gemini-ultra':        '🌟 Gemini 1.5 Pro Latest',
        'openrouter-llama':    '🦙 Llama 3.3 70B — free',
        'openrouter-mistral':  '🌪️ Mistral 7B — free',
        'openrouter-gemini':   '🔀 Gemini Flash via OpenRouter',
        'openrouter-gpt4o':    '🟢 GPT-4o via OpenRouter',
      };
      // All models go through backend — no frontend key needed
      toast(labels[model] || model, 'info');
    });
  });
}

function syncModelPills(model) {
  qsa('.ai-model-pill').forEach(p => {
    const active = p.dataset.model === model;
    p.classList.toggle('active', active);
    p.setAttribute('aria-pressed', active ? 'true' : 'false');
  });
  // Also sync the header model label
  const pCfg = AI_PROVIDERS[model];
  const labelMap = {
    'gemini-flash':'Flash','gemini-pro':'Pro','gemini-ultra':'Ultra',
    'openrouter-llama':'Llama','openrouter-mistral':'Mistral',
    'openrouter-gemini':'Flash (OR)','openrouter-gpt4o':'GPT-4o',
  };
  const lbl = $('modelLabel');
  if (lbl && labelMap[model]) lbl.textContent = labelMap[model];
}

// v31: initApiKeySettings removed — Backend tab is gone.
// Backend URL is fixed at deploy time via window.APP_CONFIG.API_BASE_URL.
// updateApiKeyStatus kept as no-op for any legacy call sites.
const updateApiKeyStatus = () => {};

// FIX: Bekend URL connect logic — expose a runtime setter so the Settings UI
// (or any other caller) can save a new backend URL and immediately activate it
// without a page reload. Previously AURA_CONFIG was frozen at parse time and
// there was no way to connect to a custom URL from the frontend.
function saveBackendUrl(rawUrl) {
  const url = (rawUrl || '').trim();
  if (!url) {
    toast('Please enter a backend URL', 'error'); return;
  }
  // Validate — must be http(s):// or /
  if (!/^https?:\/\//i.test(url) && !url.startsWith('/')) {
    toast('URL must start with https:// or /', 'error'); return;
  }
  try { localStorage.setItem('zenq_backend_url', url); } catch(e) {}
  // Hot-swap AURA_CONFIG without reload
  const BASE = url.replace(/\/chat$/, '').replace(/\/api$/, '').replace(/\/$/, '');
  AURA_CONFIG.backendUrl = BASE + '/api/chat';
  AURA_CONFIG.streamUrl  = BASE + '/api/stream';
  AURA_CONFIG.healthUrl  = BASE + '/api/health';
  AURA_CONFIG.fakeAI     = false; // real backend now active
  window.APP_CONFIG.API_BASE_URL = url;
  toast('✓ Backend URL saved — connected to ' + url, 'success', 3500);
}
window.saveBackendUrl = saveBackendUrl;

