// Shows FREE/PRO plan + message usage in header
// Integrates with existing initPlan() system
// ══════════════════════════════════════════════════
// updatePlanBadge removed — message count icon disabled
function updatePlanBadge() { /* removed */ }

function incrementUsage() {
  try {
    const u = JSON.parse(localStorage.getItem('aura_usage_v1') || '{}');
    const today = new Date().toDateString();
    if (u.date !== today) { u.date = today; u.count = 0; }
    u.count = (u.count || 0) + 1;
    localStorage.setItem('aura_usage_v1', JSON.stringify(u));
    updatePlanBadge();
  } catch(e) {}
}

