// ══════════════════════════════════════════════════
// PWA — Single-File: Manifest · Service Worker · Install Prompt
// Strategy: blob: SW for install eligibility + Cache API for offline
// Offline fallback embedded inline, manifest injected dynamically
// ══════════════════════════════════════════════════
(function() {
  'use strict';

  // ── Icon data (base64 PNG) ────────────────────────────────────────────────
  const ICON_192      = 'data:image/png;base64,';
  const ICON_192_MASK = 'data:image/png;base64,';
  const ICON_512      = 'data:image/png;base64,';

  // ── Offline page HTML (cached by SW) ─────────────────────────────────────
  const OFFLINE_HTML = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,viewport-fit=cover"/>
<!-- Android WebView / Samsung Internet: disable font boosting -->
<meta name="HandheldFriendly" content="True"/>
<meta name="theme-color" content="#000000"/>
<title>ZenQ — Offline</title>
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%;background:#000000;color:#ffffff;font-family:'DM Sans',system-ui,sans-serif;-webkit-font-smoothing:antialiased}


.scene{position:relative;z-index:1;display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:100%;padding:32px 24px;animation:rise .55s cubic-bezier(.16,1,.3,1) both}
@keyframes rise{from{opacity:0;transform:translateY(28px) scale(.97)}to{opacity:1;transform:none}}
.card{background:#0a0a0a;border:1px solid #1f1f1f;border-radius:24px;padding:48px 40px 40px;max-width:420px;width:100%;text-align:center;}
.logo{width:60px;height:60px;border-radius:16px;background:linear-gradient(135deg,#6c6ef7,#8b5cf6);display:flex;align-items:center;justify-content:center;margin:0 auto 22px;box-shadow:0 0 40px rgba(108,110,247,.22)}
.badge{display:inline-flex;align-items:center;gap:6px;padding:5px 12px;border-radius:99px;background:rgba(108,110,247,.1);border:1px solid rgba(108,110,247,.2);font-size:12px;font-weight:600;color:#a5b4fc;margin-bottom:22px}
.dot{width:6px;height:6px;border-radius:50%;background:#6c6ef7;animation:blink 2s infinite}
@keyframes blink{0%,100%{opacity:1}50%{opacity:.3}}
h1{font-size:24px;font-weight:800;margin-bottom:10px;background:linear-gradient(135deg,#ffffff 40%,#a0a0a0);-webkit-background-clip:text;-webkit-text-fill-color:transparent}
p{font-size:14px;color:#a0a0a0;line-height:1.65;margin-bottom:26px}
.actions{display:flex;flex-direction:column;gap:10px}
.btn-p{display:flex;align-items:center;justify-content:center;gap:8px;padding:12px 20px;border-radius:12px;background:linear-gradient(135deg,#6c6ef7,#8b5cf6);color:#fff;font-size:14px;font-weight:600;cursor:pointer;border:none;font-family:inherit}
.btn-s{display:flex;align-items:center;justify-content:center;gap:8px;padding:11px 20px;border-radius:12px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.08);color:#a0a0a0;font-size:14px;cursor:pointer;font-family:inherit;text-decoration:none}
#st{margin-top:10px;font-size:12px;color:#555555;min-height:16px}
#st.chk{color:#a5b4fc}
#st.ok{color:#34d399}
.tip{margin-top:24px;padding:14px 16px;border-radius:12px;background:rgba(108,110,247,.06);border:1px solid rgba(108,110,247,.12);font-size:12.5px;color:#555555;line-height:1.6;text-align:left}
.tip strong{color:#a0a0a0}
</style>
</head>
<body>
<div class="scene"><div class="card">
<div class="logo"><svg width="28" height="28" viewBox="0 0 32 32" fill="none"><path d="M16 4L8 26M16 4L24 26M10.4 19L21.6 19" stroke="white" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/><circle cx="16" cy="4" r="2" fill="#6366f1"/></svg></div>
<div class="badge"><span class="dot"></span>No internet connection</div>
<h1>You're offline</h1>
<p>ZenQ can't reach the server right now. Check your Wi-Fi or mobile data and try again.</p>
<div class="actions">
<button class="btn-p" id="retryBtn"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/></svg>Try again</button>
<a class="btn-s" href="/">Back to ZenQ</a>
</div>
<div id="st" role="status" aria-live="polite"></div>
<div class="tip"><strong>💡 Tip:</strong> Cached pages load instantly, even offline. API calls need an active connection.</div>
</div></div>
<script>
(function(){
var btn=document.getElementById('retryBtn'),st=document.getElementById('st'),busy=false;
function retry(){if(busy)return;busy=true;st.textContent='Checking…';st.className='chk';btn.disabled=true;
fetch('/',{method:'HEAD',cache:'no-store'}).then(function(r){if(r.ok){st.textContent='Back online! Redirecting…';st.className='ok';setTimeout(function(){location.href='/'},700);}else throw 0;}).catch(function(){st.textContent='Still offline. Try again shortly.';st.className='';btn.disabled=false;busy=false;});}
btn.addEventListener('click',retry);
window.addEventListener('online',function(){st.textContent='Network detected…';st.className='chk';setTimeout(function(){location.href='/'},600);});
window.addEventListener('offline',function(){st.textContent='Connection lost.';st.className='';});
})();
<\/script>
</body>
</html>`;

  // ── Manifest definition ───────────────────────────────────────────────────
  const MANIFEST = {
    name: 'ZenQ',
    short_name: 'ZenQ',
    description: 'Production-grade AI chat assistant with multi-model support, streaming, and offline capability.',
    start_url: location.href,
    scope: location.origin + '/',
    display: 'standalone',
    orientation: 'portrait',
    background_color: '#0f172a',
    theme_color: '#6366f1',
    lang: 'en',
    categories: ['productivity', 'utilities'],
    icons: [
      { src: ICON_192,      sizes: '192x192', type: 'image/png', purpose: 'any' },
      { src: ICON_192_MASK, sizes: '192x192', type: 'image/png', purpose: 'maskable' },
      { src: ICON_512,      sizes: '512x512', type: 'image/png', purpose: 'any'  },
    ],
    shortcuts: [
      { name: 'New Chat', short_name: 'New', description: 'Start a new conversation',
         url: location.href + '?new=1',
         icons: [{ src: ICON_192, sizes: '192x192' }] }
    ]
  };

  // ── Inject manifest link ──────────────────────────────────────────────────
  try {
    const manifestBlob = new Blob([JSON.stringify(MANIFEST)], { type: 'application/manifest+json' });
    const manifestURL  = URL.createObjectURL(manifestBlob);
    const el = document.getElementById('pwa-manifest-link');
    if (el) el.href = manifestURL;
    // Note: manifest blob URL intentionally NOT revoked — browser needs it
    // to remain valid for PWA install and icon resolution throughout the session.
    // It is a single small URL (~1KB), acceptable for session lifetime.
    // Apple touch icon
    const touchEl = document.getElementById('pwa-touch-icon');
    if (touchEl) touchEl.href = ICON_192;
  } catch(e) {
    ZenQLogger && ZenQLogger.warn('PWA', 'Manifest inject failed:', e.message);
  }

  // ── Service Worker source (embedded) ─────────────────────────────────────
  // The SW is registered via blob: URL. It provides:
  //   • Installability signal (browsers accept blob: SWs for install criteria)
  //   • Offline fallback via Cache API
  //   • Cache-first for runtime-cached assets
  //   • Network-first for API calls
  //   • install / activate / fetch / message event handlers
  // BUG FIX [v38]: Use a stable build ID constant — NOT Date.now() at page-load time.
  // Previously Date.now() was interpolated into SW_CODE when the page JS ran,
  // so every page load baked a brand-new unique timestamp into the SW source.
  // The activate handler then deleted all previous caches (they never matched KEEP),
  // meaning zero assets were ever served from cache across page loads.
  // Fix: SW_BUILD_ID is a static string changed only on intentional deploys.
  const SW_BUILD_ID = 'v38-prod-1';  // ← increment on each production deploy
  const SW_CODE = `
/* ZenQ — Embedded Service Worker — build: ${SW_BUILD_ID} */
const _BUILD    = '${SW_BUILD_ID}';
const CACHE_NAME   = 'aura-v29-' + _BUILD;
const STATIC_CACHE = 'aura-static-v29-' + _BUILD;
const API_CACHE    = 'aura-api-v29-' + _BUILD;

const APP_URL  = '${location.href}';
const ORIGIN   = '${location.origin}';

const OFFLINE_HTML = ${JSON.stringify(OFFLINE_HTML)};

const API_ORIGINS = [
  'https://generativelanguage.googleapis.com',
  'https://openrouter.ai',
  'https://identitytoolkit.googleapis.com',
  'https://securetoken.googleapis.com',
  'https://firebaseio.com',
  'https://firebaseapp.com',
  'https://accounts.google.com',
];

function isAPI(url) {
  return API_ORIGINS.some(o => url.includes(o)) || url.includes('/api/');
}

// INSTALL — pre-cache offline page + app shell
self.addEventListener('install', e => {
  console.log('[SW] Installing ZenQ…');
  e.waitUntil(
    caches.open(STATIC_CACHE).then(cache =>
      Promise.allSettled([
        cache.put(new Request(ORIGIN + '/offline.html'),
          new Response(OFFLINE_HTML, { headers: { 'Content-Type': 'text/html; charset=utf-8' } })),
        // Also cache the app URL itself
        fetch(APP_URL).then(r => cache.put(new Request(APP_URL), r.clone())).catch(() => {}),
      ])
    ).then(() => self.skipWaiting())
  );
});

// ACTIVATE — delete stale caches
self.addEventListener('activate', e => {
  const KEEP = [CACHE_NAME, STATIC_CACHE, API_CACHE];
  e.waitUntil(
    caches.keys().then(keys =>
      Promise.all(keys.filter(k => !KEEP.includes(k)).map(k => caches.delete(k)))
    ).then(() => self.clients.claim())
  );
});

// FETCH — routing
self.addEventListener('fetch', e => {
  const url = e.request.url;
  if (e.request.method !== 'GET' || !url.startsWith('http')) return;
  if (url.startsWith('chrome-extension://') || url.startsWith('blob:')) return;

  if (isAPI(url)) {
    e.respondWith(networkFirst(e.request));
  } else if (e.request.mode === 'navigate') {
    e.respondWith(navigationHandler(e.request));
  } else {
    e.respondWith(cacheFirst(e.request));
  }
});

// Cache size enforcement — prevent unlimited cache growth
const MAX_STATIC_ENTRIES = 50;
async function trimCache(cacheName, maxEntries) {
  const c = await caches.open(cacheName);
  const keys = await c.keys();
  if (keys.length > maxEntries) {
    // Delete oldest entries (FIFO — keys() returns in insertion order)
    const toDelete = keys.slice(0, keys.length - maxEntries);
    await Promise.all(toDelete.map(k => c.delete(k)));
  }
}

// Cache-first
async function cacheFirst(req) {
  const cached = await caches.match(req);
  if (cached) return cached;
  try {
    const resp = await fetch(req);
    if (resp && resp.status === 200 && resp.type !== 'opaque') {
      const c = await caches.open(STATIC_CACHE);
      await c.put(req, resp.clone());
      // Trim cache to prevent unbounded growth
      trimCache(STATIC_CACHE, MAX_STATIC_ENTRIES).catch(() => {});
    }
    return resp;
  } catch(err) {
    if (req.destination === 'image') return new Response('', { status: 404 });
    throw err;
  }
}

// Network-first
async function networkFirst(req) {
  const c = await caches.open(API_CACHE);
  try {
    const resp = await fetch(req);
    if (resp && resp.status === 200) c.put(req, resp.clone());
    return resp;
  } catch(err) {
    const cached = await caches.match(req);
    if (cached) return cached;
    return new Response(JSON.stringify({ error: 'offline' }), {
      status: 503,
      headers: { 'Content-Type': 'application/json', 'X-SW-Offline': 'true' }
    });
  }
}

// Navigation handler
async function navigationHandler(req) {
  try {
    const resp = await fetch(req);
    if (resp && resp.status === 200) {
      const c = await caches.open(STATIC_CACHE);
      c.put(req, resp.clone());
    }
    return resp;
  } catch(err) {
    const cached = await caches.match(req) || await caches.match(ORIGIN + '/offline.html');
    if (cached) return cached;
    return new Response(OFFLINE_HTML, { headers: { 'Content-Type': 'text/html' } });
  }
}

// Message handler
self.addEventListener('message', e => {
  if (e.data?.type === 'SKIP_WAITING') self.skipWaiting();
  if (e.data?.type === 'CLEAR_CACHE')  caches.keys().then(k => Promise.all(k.map(n => caches.delete(n))));
});
`;

  // ── HTTPS guard ───────────────────────────────────────────────────────────
  const isSecure = location.protocol === 'https:' ||
                   location.hostname === 'localhost' ||
                   location.hostname === '127.0.0.1';

  // ── Install prompt state ──────────────────────────────────────────────────
  let deferredPrompt = null;
  let installBtn     = null;

  function injectInstallButton() {
    if (document.getElementById('pwa-install-btn')) return;
    const btn = document.createElement('button');
    btn.id        = 'pwa-install-btn';
    btn.type      = 'button';
    btn.className = 'sb-foot-btn hidden';
    btn.setAttribute('aria-label', 'Install ZenQ as an app');
    btn.innerHTML =
      '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
        '<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/>' +
        '<polyline points="7 10 12 15 17 10"/>' +
        '<line x1="12" y1="15" x2="12" y2="3"/>' +
      '</svg>' +
      '<span class="sb-foot-lbl">Install App</span>';
    btn.addEventListener('click', triggerInstall);
    const footer = document.querySelector('.sb-footer');
    if (footer) footer.insertBefore(btn, footer.firstChild);
    else {
      Object.assign(btn.style, {
        position:'fixed',bottom:'80px',right:'16px',zIndex:'9000',
        display:'flex',alignItems:'center',gap:'8px',padding:'10px 16px',
        borderRadius:'12px',border:'1px solid rgba(108,110,247,0.3)',
        background:'rgba(108,110,247,0.12)',color:'#ffffff',
        fontSize:'13px',fontWeight:'600',cursor:'pointer',
        boxShadow:'0 4px 20px rgba(0,0,0,0.5)',
      });
      btn.classList.remove('sb-foot-btn','hidden');
      document.body.appendChild(btn);
    }
    installBtn = btn;
  }

  function showInstallBtn()  { if (!installBtn) injectInstallButton(); if (installBtn) installBtn.classList.remove('hidden'); }
  function hideInstallBtn()  { if (installBtn) installBtn.classList.add('hidden'); }

  function triggerInstall() {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    deferredPrompt.userChoice.then(c => {
      if (c.outcome === 'accepted') {
        hideInstallBtn();
        try { if(window.ZenQBus) ZenQBus.emit('pwa:installed',{}); } catch(_){}
      }
      deferredPrompt = null;
    });
  }

  window.addEventListener('beforeinstallprompt', e => {
    e.preventDefault();
    deferredPrompt = e;
    showInstallBtn();
    console.log('[PWA] Install prompt captured.');
  });

  window.addEventListener('appinstalled', () => {
    hideInstallBtn();
    deferredPrompt = null;
    try {
      if (typeof toast === 'function') toast('ZenQ installed! Launch from home screen. 🚀', 'success');
    } catch(_) {}
  });

  // ── Register Service Worker ───────────────────────────────────────────────
  if (isSecure && 'serviceWorker' in navigator) {
    window.addEventListener('load', () => {
      try {
        const swBlob = new Blob([SW_CODE], { type: 'application/javascript' });
        const swURL  = URL.createObjectURL(swBlob);

        navigator.serviceWorker.register(swURL, { scope: './' })
          .then(reg => {
            // Revoke blob URL immediately after registration — prevent memory leak
            URL.revokeObjectURL(swURL);
            console.log('[PWA] Service Worker registered. Scope:', reg.scope);
            reg.update();
            setInterval(() => reg.update(), 60000);

            reg.addEventListener('updatefound', () => {
              const nw = reg.installing;
              if (!nw) return;
              nw.addEventListener('statechange', () => {
                if (nw.state === 'installed' && navigator.serviceWorker.controller) {
                  showUpdateBanner(reg);
                }
              });
            });
          })
          .catch(err => console.warn('[PWA] SW registration failed (non-fatal):', err.message));

        navigator.serviceWorker.addEventListener('controllerchange', () => location.reload());

      } catch(e) {
        console.warn('[PWA] SW setup failed:', e.message);
      }
    });
  } else if (!isSecure) {
    console.warn('[PWA] Service workers require HTTPS or localhost.');
  }

  // ── Update banner ─────────────────────────────────────────────────────────
  function showUpdateBanner(reg) {
    try {
      if (typeof toast === 'function') { toast('⚡ Update available — tap to reload', 'info'); return; }
    } catch(_) {}
    const b = document.createElement('div');
    b.setAttribute('role','alert');
    Object.assign(b.style, {
      position:'fixed',bottom:'16px',left:'50%',transform:'translateX(-50%)',
      zIndex:'99999',display:'flex',alignItems:'center',gap:'12px',
      padding:'12px 20px',borderRadius:'14px',background:'#111111',
      border:'1px solid rgba(108,110,247,0.3)',color:'#ffffff',
      fontSize:'13px',fontWeight:'500',boxShadow:'0 8px 32px rgba(0,0,0,0.7)',fontFamily:'system-ui,sans-serif',
    });
    b.innerHTML = '<span>⚡ New version available</span>' +
      '<button id="_pwaUpd" style="padding:6px 14px;border-radius:8px;border:none;' +
      'cursor:pointer;background:#6c6ef7;color:#fff;font-size:13px;font-weight:600">Update</button>' +
      '<button id="_pwaDis" style="padding:6px;border:none;background:none;cursor:pointer;' +
      'color:rgba(255,255,255,0.5);font-size:16px">✕</button>';
    document.body.appendChild(b);
    document.getElementById('_pwaUpd').onclick = () => {
      if (reg.waiting) reg.waiting.postMessage({ type: 'SKIP_WAITING' });
      b.remove();
    };
    document.getElementById('_pwaDis').onclick = () => b.remove();
  }

  // ── Network status ────────────────────────────────────────────────────────
  // BUG FIX [v28]: The original code showed its own toast on online/offline transitions,
  // but OfflineDetector (defined earlier) ALSO registers window.addEventListener('online'/
  // 'offline') and shows toasts. Two listeners = two toasts on every network change.
  // Fix: PWA handlers now ONLY update the data-offline attribute (for CSS offline styling).
  // Toast notifications are handled exclusively by OfflineDetector to avoid duplication.
  function onOnline() {
    document.documentElement.removeAttribute('data-offline');
    // Note: toast is intentionally omitted here — OfflineDetector handles it
  }
  function onOffline() {
    document.documentElement.setAttribute('data-offline', 'true');
    // Note: toast is intentionally omitted here — OfflineDetector handles it
  }
  window.addEventListener('online',  onOnline,  { passive: true });
  window.addEventListener('offline', onOffline, { passive: true });
  if (!navigator.onLine) onOffline();

  // ── Public API ────────────────────────────────────────────────────────────
  window.__ZenQPWA = {
    showInstallButton: showInstallBtn,
    hideInstallButton: hideInstallBtn,
    triggerInstall,
    clearCache() {
      if (navigator.serviceWorker?.controller)
        navigator.serviceWorker.controller.postMessage({ type: 'CLEAR_CACHE' });
    },
  };

})();

// ══════════════════════════════════════════════════
// ERROR BOUNDARY SYSTEM
// ══════════════════════════════════════════════════
const ErrorBoundary = {
  _errors: [],
  capture(err, ctx='') {
    this._errors.push({ err, ctx, ts: Date.now() });
    ZenQLogger.error('ErrorBoundary', `[${ctx}]`, err?.message || err);
    if (this._errors.length > 50) this._errors.shift();
  },
  wrap(fn, ctx='') {
    return (...args) => {
      try { return fn(...args); }
      catch(e) { this.capture(e, ctx); }
    };
  },
  wrapAsync(fn, ctx='') {
    return async (...args) => {
      try { return await fn(...args); }
      catch(e) { this.capture(e, ctx); }
    };
  },
  getErrors() { return [...this._errors]; }
};

window.addEventListener('error', (e) => {
  ErrorBoundary.capture(e.error || new Error(e.message), 'window.error');
  if (e.error?.message?.includes('localStorage')) toast('Storage error - try clearing browser data', 'error', 4000);
  // PRODUCTION FIX [v29]: Do NOT call e.preventDefault() here — that suppresses
  // the error from the browser console entirely, making debugging impossible.
});
window.addEventListener('unhandledrejection', (e) => {
  const reason = e.reason;
  const msg = reason instanceof Error ? reason.message : String(reason || '');
  // PRODUCTION FIX [v29]: Do not suppress AbortError rejections — they are expected
  // when users stop generation. Silently capturing them hides real failures.
  if (msg.includes('AbortError') || msg.includes('abort') || msg.includes('The user aborted')) return;
  ErrorBoundary.capture(reason, 'unhandledrejection');
  // PRODUCTION FIX [v29]: Removed e.preventDefault() — it hides rejections from the
  // browser devtools console completely. Developers must be able to see unhandled
  // rejections to debug production issues.
  if (msg.includes('fetch') || msg.includes('network'))
    toast('Network error - check your connection', 'error', 3500);
});

