// AURA AI v17 — ENHANCEMENTS
// ══════════════════════════════════════════════════

// ── v17: Doc title kept in sync inside renderMessages() above ──

// ── v17: Code block line numbers & improved copy ─
// parseMarkdown enhancements handled by existing implementation

// ── v17: Auto-categorise new chat from first msg ─
// Already in codebase — no change needed

// ── v17: Keyboard shortcut hints in input area ───
(function initV17Shortcuts() {
  // Shift+/ opens command palette (in addition to Ctrl+K)
  // Already handled — skip
  
  // v17: Ctrl+Shift+C copies last AI message
  document.addEventListener('keydown', e => {
    if ((e.ctrlKey||e.metaKey) && e.shiftKey && e.key === 'C') {
      e.preventDefault();
      const aiRows = qsa('.msg-row.ai');
      if (!aiRows.length) return;
      const last = aiRows[aiRows.length-1];
      const mc = last.querySelector('.mc');
      const text = mc ? mc.innerText : '';
      if (!text) return;
      if (navigator.clipboard && window.isSecureContext) {
        navigator.clipboard.writeText(text).then(() => toast('Last AI reply copied ✓', 'success'));
      }
    }
  });
})();

// ── Premium FAB badge wiring ────────────────────
// BUG FIX: patchScrollFab had the wrong function signature.
// appendMessageToDOM(msg) takes a single msg object, but the wrapper
// declared (role, content, id, meta) — so `role` was always the msg
// object, never the string 'ai'/'assistant'. fabNotifyNewAIMessage was
// therefore never called and the unread badge count never incremented.
(function patchScrollFab() {
  const _origAppend = window.appendMessageToDOM;
  if (typeof _origAppend === 'function') {
    window.appendMessageToDOM = function(msg) {
      const result = _origAppend.apply(this, arguments);
      if (msg && (msg.role === 'ai' || msg.role === 'assistant')) {
        requestAnimationFrame(() => {
          if (typeof fabNotifyNewAIMessage === 'function') fabNotifyNewAIMessage();
        });
      }
      return result;
    };
  }
})();

// ── v17: Mobile sidebar backdrop auto-close ──────
(function initMobBackdrop() {
  // BUG FIX: The original code here added a SECOND click listener on the backdrop
  // (`bd.addEventListener('click', closeMobSidebar)`) even though the main event
  // wiring at line ~14086 already does `on('mob-sb-backdrop', 'click', closeMobSidebar)`.
  // Two listeners → double-close on every backdrop tap → the sidebar's rAF-deferred
  // `classList.remove('mob-open')` fired twice in separate frames, causing the slide
  // animation to stutter/flash on low-end Android devices.
  //
  // Additionally, the monkey-patch of window.openMobSidebar / window.closeMobSidebar
  // was redundant: the original functions already manage bd.classList directly.
  // Wrapping them added a second bd.classList.add/remove call on every open/close.
  //
  // Fix: just ensure the backdrop element exists (for defensive safety) and exit.
  // All open/close logic lives exclusively in openMobSidebar() / closeMobSidebar().
  let bd = $('mob-sb-backdrop');
  if (!bd) {
    bd = document.createElement('div');
    bd.id = 'mob-sb-backdrop';
    bd.style.cssText = 'display:block;position:fixed;inset:0;z-index:190;background:rgba(0,0,0,0.5);opacity:0;pointer-events:none;transition:opacity 0.28s ease;';
    document.body.appendChild(bd);
    // Only add the click listener if the element was just created (missing from HTML).
    // If it already existed, the listener was already bound by `on()` in the main setup.
    bd.addEventListener('click', () => { if (typeof closeMobSidebar === 'function') closeMobSidebar(); });
  }
  // No monkey-patching — original functions are correct as-is.
})();

// ── v17: Live typing word count ───────────────────
(function initWordCount() {
  const ta = $('msg-ta');
  if (!ta) return;
  ta.addEventListener('input', () => {
    const len = ta.value.length;
    const cc  = $('inp-char-count');
    if (!cc) return;
    if (len > 3000) {
      cc.textContent = `${len.toLocaleString()} / 16k`;
      cc.className = 'inp-char-count ' + (len > 12000 ? 'over' : 'near');
    } else {
      cc.textContent = '';
      cc.className = 'inp-char-count';
    }
  }, { passive: true });
})();

// ── v17: Improved copy code block feedback ────────
// Patch copyToClipboard calls to use 2s feedback window
document.addEventListener('click', e => {
  const cpBtn = e.target.closest('.cb-cp');
  if (!cpBtn) return;
  const cb = cpBtn.closest('.cb');
  if (!cb) return;
  const pre = cb.querySelector('pre');
  if (!pre) return;
  const text = pre.innerText || pre.textContent || '';
  const doCopy = () => {
    if (navigator.clipboard && window.isSecureContext) return navigator.clipboard.writeText(text);
    const ta = document.createElement('textarea');
    ta.value = text; ta.style.cssText = 'position:fixed;opacity:0;top:-9999px';
    document.body.appendChild(ta); ta.select();
    const ok = document.execCommand('copy');
    document.body.removeChild(ta);
    return ok ? Promise.resolve() : Promise.reject();
  };
  // Prevent double-fire from original handler — check if already handled
  if (cpBtn.dataset.copying) return;
  cpBtn.dataset.copying = '1';
  doCopy().then(() => {
    const origHTML = cpBtn.innerHTML;
    cpBtn.classList.add('ok');
    cpBtn.innerHTML = `<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg> Copied!`;
    setTimeout(() => {
      cpBtn.classList.remove('ok');
      cpBtn.innerHTML = origHTML;
      delete cpBtn.dataset.copying;
    }, 2000);
  }).catch(() => {
    delete cpBtn.dataset.copying;
    toast('Copy failed', 'error');
  });
}, true); // capture phase — runs before existing handlers

