// ── v19: Incremental message insert guard ─────────
// Prevents duplicate message rows when appendMessageToDOM
// is called multiple times for the same message ID.
(function patchAppendMessageToDOM() {
  const _orig = window.appendMessageToDOM || appendMessageToDOM;
  window.appendMessageToDOM = function(msg) {
    if (!msg || !msg.id) return _orig(msg);
    // Check for existing element with this message ID
    const existing = document.querySelector(`.msg-row[data-msg-id="${msg.id}"]`);
    if (existing) {
      if (DEBUG) console.warn('[ZenQ:v19] appendMessageToDOM: duplicate prevented for id', msg.id);
      return existing;
    }
    return _orig(msg);
  };
})();

