// ── v19: Performance: batch sidebar updates during generation ─
// Pause non-critical sidebar re-renders while AI is streaming
// to reduce reflows during token output.
(function patchRenderChatListForPerf() {
  const _orig = renderChatList;
  let _queued = false;
  // FIX: _renderChatListImpl was assigned without declaration → ReferenceError in strict mode.
  // It is already declared as `let _renderChatListImpl = null` above, so this assignment is valid.
  // FIX: Replaced RAF polling loop (memory leak risk) with a one-shot ZenQBus listener.
  _renderChatListImpl = window.renderChatList = function renderChatListPatched() {
    if (State.isTyping) {
      if (!_queued) {
        _queued = true;

        // BUG FIX [v28]: The original code registered an ZenQBus.once() listener AND a
        // safety setTimeout, but never coordinated them. If the timeout fired first it called
        // _orig(), then when generation:done eventually fired the once() wrapper also called
        // _orig() — resulting in a double sidebar render AND a leaked listener.
        // Fix: capture the unsubscribe fn returned by once() and call it from the timeout,
        // and clearTimeout from the once handler, so only ONE path can trigger _orig().
        let _fallbackTimer = null;
        const _unsub = ZenQBus.once('generation:done', () => {
          clearTimeout(_fallbackTimer); // cancel the safety timeout — this path wins
          _queued = false;
          _orig();
        });
        // Safety fallback: if generation:done never fires (abort/error), render after 10 s
        _fallbackTimer = setTimeout(() => {
          if (_queued) {
            _queued = false;
            _unsub(); // FIX: cancel the pending once() to prevent it firing _orig() later
            _orig();
          }
        }, 10000);
      }
      return;
    }
    _orig();
  };
})();

