// ── Global error boundary: catch unhandled promise rejections ────────────────
// Without this, failed API calls / IDB ops silently disappear in production.
// v32: Global error boundary — typed error handling with user-friendly messages
window.addEventListener('unhandledrejection', (evt) => {
  const reason = evt.reason;
  const msg = reason instanceof Error ? reason.message : String(reason || 'Unknown rejection');

  // Suppress benign abort errors (user cancelled request intentionally)
  const isAbort = msg.includes('AbortError') || msg.includes('abort') || msg.includes('The user aborted');
  if (isAbort) return;

  ZenQLogger && ZenQLogger.error('UnhandledRejection', msg, reason);

  // Typed error handling — show specific messages for known error types
  if (typeof toast === 'function') {
    if (reason instanceof ApiError) {
      if (reason.status === 401 || reason.status === 403) {
        toast('🔒 Session expired — please sign in again', 'error', 5000);
      } else if (reason.status === 429) {
        toast('⏳ Rate limit reached — please wait a moment', 'warn', 5000);
      } else if (reason.status >= 500) {
        toast('🔧 Server error — retrying automatically', 'error', 4000);
      } else if (reason.retryable) {
        toast('📡 Connection issue — check your internet', 'warn', 4000);
      } else {
        toast('⚠️ ' + reason.message, 'error', 4000);
      }
    } else {
      toast('⚠️ Unexpected error — see console for details', 'error', 4000);
    }
  }
});

// ── Global synchronous error handler ────────────────────────────────────────
window.onerror = (message, source, lineno, colno, error) => {
  ZenQLogger && ZenQLogger.error('GlobalError', `${message} @ ${source}:${lineno}:${colno}`);
  return false; // don't suppress browser's default console log
};

// ── Cleanup all timers + abort in-flight requests on page unload ─────────────
// Prevents dangling async continuations from firing after navigation/refresh
// and eliminates benign "cannot set properties of null" post-unload errors.
window.addEventListener('beforeunload', () => {
  // Stop real-time clock
  if (typeof _clockHandle !== 'undefined' && _clockHandle !== null) {
    clearTimeout(_clockHandle);
    _clockHandle = null;
  }
  // Clear guest-limit countdown
  if (typeof _glmTimer !== 'undefined' && _glmTimer !== null) {
    clearInterval(_glmTimer);
    _glmTimer = null;
  }
  // Abort any in-flight AI request
  if (typeof APP !== 'undefined' && APP._abortController) {
    try { APP._abortController.abort(); } catch(_) {}
    APP._abortController = null;
  }
  // Cancel any pending rAF streaming frame
  if (typeof APP !== 'undefined' && APP._streamRafId) {
    cancelAnimationFrame(APP._streamRafId);
    APP._streamRafId = null;
  }
});

