// AURA UX INTELLIGENCE LAYER — All 10 improvement areas
// ════════════════════════════════════════════════════════
(function AuraUX() {
  'use strict';

  // ── 1. TIME-AWARE WELCOME GREETING ─────────────────
  function initTimeGreeting() {
    const badge = document.getElementById('wlcTimeBadge');
    const title = document.getElementById('wlcTitle');
    const sub   = document.getElementById('wlcSub');
    if (!badge) return;

    const h = new Date().getHours();
    let timeLabel, emoji, greeting, subtext;
    if (h >= 5 && h < 12) {
      emoji = '🌅'; timeLabel = 'Good morning';
      greeting = 'Good morning! Ready to get things done?';
      subtext = 'Start your day right — ask anything.';
    } else if (h >= 12 && h < 17) {
      emoji = '☀️'; timeLabel = 'Good afternoon';
      greeting = 'Good afternoon! What can I help with?';
      subtext = 'Deep work, quick answers, or creative ideas — I\'m here.';
    } else if (h >= 17 && h < 21) {
      emoji = '🌆'; timeLabel = 'Good evening';
      greeting = 'Good evening! What shall we explore?';
      subtext = 'Ask anything — ZenQ thinks with you.';
    } else {
      emoji = '🌙'; timeLabel = 'Working late?';
      greeting = 'Burning the midnight oil?';
      subtext = 'I\'m here whenever you need me.';
    }
    badge.textContent = `${emoji} ${timeLabel}`;
    if (title) title.textContent = greeting;
    if (sub)   sub.textContent   = subtext;
  }
  // Run on welcome show
  const _origShowWelcome = window.showWelcome;
  if (typeof _origShowWelcome === 'function') {
    window.showWelcome = function() {
      _origShowWelcome.apply(this, arguments);
      setTimeout(initTimeGreeting, 0);
    };
  }
  document.addEventListener('DOMContentLoaded', initTimeGreeting);

  // ── 2. STREAMING PHASE INDICATOR ───────────────────
  // Intercept showTypingIndicator / hideTypingIndicator
  const phasePill = document.getElementById('stream-phase-pill');
  const phaseText = document.getElementById('stream-phase-text');
  const PHASES = [
    { label: 'Thinking…',  delay: 0    },
    { label: 'Writing…',   delay: 1200 },
    { label: 'Finishing…', delay: 4500 },
  ];
  let _phaseTimer = null;
  let _phaseIdx   = 0;

  function startStreamingPhases() {
    if (!phasePill || !phaseText) return;
    _phaseIdx = 0;
    clearTimeout(_phaseTimer);
    phasePill.classList.add('visible');
    phaseText.textContent = PHASES[0].label;
    function advance(idx) {
      if (idx >= PHASES.length) return;
      phaseText.textContent = PHASES[idx].label;
      if (idx + 1 < PHASES.length) {
        _phaseTimer = setTimeout(() => advance(idx + 1), PHASES[idx + 1].delay - (PHASES[idx].delay || 0));
      }
    }
    _phaseTimer = setTimeout(() => advance(1), PHASES[1].delay);
  }
  function stopStreamingPhases() {
    clearTimeout(_phaseTimer);
    if (phasePill) phasePill.classList.remove('visible');
  }

  // Patch showTypingIndicator / hideTypingIndicator
  const _origShow = window.showTypingIndicator;
  const _origHide = window.hideTypingIndicator;
  if (typeof _origShow === 'function') {
    window.showTypingIndicator = function() {
      _origShow.apply(this, arguments);
      startStreamingPhases();
    };
  }
  if (typeof _origHide === 'function') {
    window.hideTypingIndicator = function() {
      _origHide.apply(this, arguments);
      stopStreamingPhases();
    };
  }

  // ── 3. INTELLIGENT INPUT — SLASH COMMAND MENU ──────
  const SLASH_COMMANDS = [
    { cmd: '/summarize',  icon: '📋', desc: 'Summarize the conversation so far', label: 'Summarize' },
    { cmd: '/translate',  icon: '🌐', desc: 'Translate text to another language', label: 'Translate' },
    { cmd: '/explain',    icon: '💡', desc: 'Explain in simple terms', label: 'Explain' },
    { cmd: '/code',       icon: '⌨️', desc: 'Write or review code', label: 'Code' },
    { cmd: '/rewrite',    icon: '✏️', desc: 'Rewrite and improve this text', label: 'Rewrite' },
    { cmd: '/brainstorm', icon: '🧠', desc: 'Generate creative ideas', label: 'Brainstorm' },
    { cmd: '/email',      icon: '📧', desc: 'Draft a professional email', label: 'Email' },
    { cmd: '/plan',       icon: '📅', desc: 'Create a step-by-step plan', label: 'Plan' },
  ];

  const slashMenu = document.getElementById('slash-menu');
  const msgTa     = document.getElementById('msg-ta');
  let _slashOpen  = false;
  let _slashIdx   = -1;

  function openSlashMenu(query) {
    if (!slashMenu) return;
    const q = query.toLowerCase();
    const filtered = SLASH_COMMANDS.filter(c =>
      q === '' || c.cmd.includes(q) || c.label.toLowerCase().includes(q)
    );
    if (!filtered.length) { closeSlashMenu(); return; }
    slashMenu.innerHTML = filtered.map((c, i) =>
      `<div class="slash-item" data-cmd="${c.cmd}" role="option" tabindex="-1">
        <span class="slash-ico">${c.icon}</span>
        <div>
          <div class="slash-name">${c.label}</div>
          <div class="slash-desc">${c.desc}</div>
        </div>
        <span class="slash-kbd">${c.cmd}</span>
      </div>`
    ).join('');
    slashMenu.classList.add('open');
    _slashOpen = true;
    _slashIdx  = -1;
    slashMenu.querySelectorAll('.slash-item').forEach(item => {
      item.addEventListener('mousedown', e => {
        e.preventDefault();
        insertSlashCommand(item.dataset.cmd);
      });
    });
  }

  function closeSlashMenu() {
    if (!slashMenu) return;
    slashMenu.classList.remove('open');
    _slashOpen = false;
    _slashIdx  = -1;
  }

  function insertSlashCommand(cmd) {
    if (!msgTa) return;
    // Replace everything up to the first space (or whole value if no space)
    const val = msgTa.value;
    const spIdx = val.indexOf(' ');
    msgTa.value = cmd + ' ';
    closeSlashMenu();
    msgTa.focus();
    if (typeof window.autosize === 'function') window.autosize();
    if (typeof window.updateSendBtn === 'function') window.updateSendBtn();
  }

  if (msgTa) {
    msgTa.addEventListener('input', () => {
      const val = msgTa.value;
      if (val.startsWith('/') && !val.includes(' ')) {
        openSlashMenu(val.slice(1));
      } else {
        closeSlashMenu();
      }
    });
    msgTa.addEventListener('keydown', e => {
      if (!_slashOpen || !slashMenu) return;
      const items = slashMenu.querySelectorAll('.slash-item');
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        _slashIdx = Math.min(_slashIdx + 1, items.length - 1);
        items.forEach((it, i) => it.classList.toggle('focused', i === _slashIdx));
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        _slashIdx = Math.max(_slashIdx - 1, 0);
        items.forEach((it, i) => it.classList.toggle('focused', i === _slashIdx));
      } else if (e.key === 'Enter' || e.key === 'Tab') {
        const focused = slashMenu.querySelector('.slash-item.focused');
        if (focused) { e.preventDefault(); insertSlashCommand(focused.dataset.cmd); }
        else { closeSlashMenu(); }
      } else if (e.key === 'Escape') {
        closeSlashMenu();
      }
    });
    msgTa.addEventListener('blur', () => setTimeout(closeSlashMenu, 150));
  }

  // ── 4. LIVE CHARACTER COUNTER ───────────────────────
  const charLive = document.getElementById('charCountLive');
  const MAX_CHARS = 16000;
  if (msgTa && charLive) {
    function updateCharCount() {
      const len = msgTa.value.length;
      if (len === 0) { charLive.textContent = ''; charLive.className = 'inp-char-live'; return; }
      charLive.textContent = len >= MAX_CHARS * 0.75
        ? `${len.toLocaleString()} / ${MAX_CHARS.toLocaleString()}`
        : '';
      charLive.className = 'inp-char-live'
        + (len >= MAX_CHARS       ? ' over' : '')
        + (len >= MAX_CHARS * 0.9 && len < MAX_CHARS ? ' near' : '');
    }
    msgTa.addEventListener('input', updateCharCount);
  }

  // ── 5. STATIC PLACEHOLDER — always 'Message ZenQ' ──
  if (msgTa) {
    msgTa.setAttribute('placeholder', 'Message ZenQ');
  }

  // ── 6. ENHANCED ERROR DISPLAY ───────────────────────
  // Patch the createMessageElement to show richer errors
  const _origCreate = window.createMessageElement;
  if (typeof _origCreate === 'function') {
    window.createMessageElement = function(msg) {
      const el = _origCreate.apply(this, arguments);
      // If this is an AI error message, enhance it
      if (msg && msg.role === 'ai' && msg.isError && el) {
        const bubble = el.querySelector('.msg-bubble');
        if (bubble && bubble.querySelector('.msg-error-bubble')) {
          const errBubble = bubble.querySelector('.msg-error-bubble');
          const origHTML = errBubble.innerHTML;
          errBubble.innerHTML = `
            <div class="err-icon-row">
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
              Something went wrong
            </div>
            <div class="err-detail">${origHTML}</div>
            <div class="err-actions">
              <button class="err-btn-retry" onclick="if(typeof sendMessage==='function'){const msgs=getChat()?.messages;if(msgs&&msgs.length>1){const last=msgs[msgs.length-2];if(last&&last.role==='user')sendMessage(last.content)}}">
                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 1 0 .49-3.52"/></svg>
                Retry
              </button>
              <button class="err-btn-alt" onclick="if(typeof openSettings==='function')openSettings('api')">
                Check settings
              </button>
            </div>`;
        }
      }
      return el;
    };
  }

  // ── 7. MESSAGE ACTION BAR ENHANCEMENT ──────────────
  // Inject a richer action bar into AI messages
  function enhanceAIMessage(el) {
    if (!el || !el.classList.contains('ai')) return;
    const meta = el.querySelector('.msg-meta');
    if (!meta || meta.querySelector('.msg-action-bar')) return;
    // Skip: buildMsgHTML already injected copy/like/dislike/more buttons into .msg-actions
    if (meta.querySelector('.ma-copy')) return;
    const bar = document.createElement('div');
    bar.className = 'msg-action-bar';
    bar.setAttribute('role', 'toolbar');
    bar.setAttribute('aria-label', 'Message actions');
    bar.innerHTML = `
      <button class="mab-btn ma-like" title="Good response" aria-label="Like this response" aria-pressed="false">
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 9V5a3 3 0 0 0-3-3l-4 9v11h11.28a2 2 0 0 0 2-1.7l1.38-9a2 2 0 0 0-2-2.3H14z"/><path d="M7 22H4a2 2 0 0 1-2-2v-7a2 2 0 0 1 2-2h3"/></svg>
      </button>
      <button class="mab-btn ma-dislike" title="Poor response" aria-label="Dislike this response" aria-pressed="false">
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M10 15v4a3 3 0 0 0 3 3l4-9V2H5.72a2 2 0 0 0-2 1.7l-1.38 9a2 2 0 0 0 2 2.3H10z"/><path d="M17 2h2.67A2.31 2.31 0 0 1 22 4v7a2.31 2.31 0 0 1-2.33 2H17"/></svg>
      </button>
      <div class="mab-sep"></div>
      <button class="mab-btn ma-copy" title="Copy response" aria-label="Copy response">
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>
        Copy
      </button>
      <button class="mab-btn ma-regen" title="Regenerate" aria-label="Regenerate response">
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 1 0 .49-3.52"/></svg>
        Regenerate
      </button>
    `;
    meta.appendChild(bar);

    // Wire up action bar buttons
    bar.querySelector('.ma-like').addEventListener('click', function() {
      const isActive = this.classList.toggle('active-reaction');
      this.setAttribute('aria-pressed', isActive ? 'true' : 'false');
      if (isActive) { this.classList.add('reacted'); bar.querySelector('.ma-dislike').classList.remove('dislike-active'); }
      else this.classList.remove('reacted');
      if (isActive && typeof toast === 'function') toast('Thanks for the feedback! 👍', 'success');
    });
    bar.querySelector('.ma-dislike').addEventListener('click', function() {
      const isActive = this.classList.toggle('dislike-active');
      this.setAttribute('aria-pressed', isActive ? 'true' : 'false');
      if (isActive) bar.querySelector('.ma-like').classList.remove('active-reaction');
      if (isActive && typeof toast === 'function') toast('Got it — we\'ll improve', 'info');
    });
    bar.querySelector('.ma-copy').addEventListener('click', function() {
      const bubble = el.querySelector('.msg-bubble');
      const text = bubble ? bubble.innerText.replace(/Copy\n?/g, '').trim() : '';
      if (navigator.clipboard) navigator.clipboard.writeText(text).catch(() => {});
      const orig = this.innerHTML;
      this.innerHTML = '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg> Copied!';
      this.style.color = 'var(--mint)';
      setTimeout(() => { this.innerHTML = orig; this.style.color = ''; }, 2000);
    });
    bar.querySelector('.ma-regen').addEventListener('click', () => {
      const chat = typeof getChat === 'function' ? getChat() : null;
      if (!chat) return;
      const msgs = chat.messages;
      const lastUser = [...msgs].reverse().find(m => m.role === 'user');
      if (lastUser && typeof sendMessage === 'function') {
        // Remove last AI message and resend
        const lastAIIdx = msgs.map(m => m.role).lastIndexOf('ai');
        if (lastAIIdx > -1) chat.messages.splice(lastAIIdx, 1);
        if (typeof save === 'function') save();
        if (typeof renderMessages === 'function') renderMessages();
        sendMessage(lastUser.content);
      }
    });
  }

  // Observe new messages and enhance them
  const msgList = document.getElementById('msg-list');
  if (msgList && typeof MutationObserver !== 'undefined') {
    const obs = new MutationObserver(mutations => {
      mutations.forEach(m => {
        m.addedNodes.forEach(node => {
          if (node.nodeType === 1) {
            if (node.classList && node.classList.contains('ai')) enhanceAIMessage(node);
            node.querySelectorAll && node.querySelectorAll('.msg-row.ai').forEach(enhanceAIMessage);
          }
        });
      });
    });
    obs.observe(msgList, { childList: true, subtree: false });
  }

  // ── 8. QUICK COPY BUTTON ON AI MESSAGES ONLY ──────────
  function addQuickCopy(el) {
    if (!el || el.querySelector('.msg-quick-copy')) return;
    // Only add quick copy to AI messages — user messages use long-press menu
    if (!el.classList.contains('ai')) return;
    const bubble = el.querySelector('.msg-bubble');
    if (!bubble) return;
    const btn = document.createElement('button');
    btn.className = 'msg-quick-copy';
    btn.title = 'Copy message';
    btn.setAttribute('aria-label', 'Copy message');
    btn.innerHTML = '<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>';
    btn.addEventListener('click', () => {
      const text = bubble.innerText.trim();
      if (navigator.clipboard) navigator.clipboard.writeText(text).catch(() => {});
      btn.innerHTML = '✓';
      btn.classList.add('copied');
      setTimeout(() => {
        btn.innerHTML = '<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>';
        btn.classList.remove('copied');
      }, 1500);
    });
    bubble.appendChild(btn);
  }

  if (msgList && typeof MutationObserver !== 'undefined') {
    const obs2 = new MutationObserver(mutations => {
      mutations.forEach(m => {
        m.addedNodes.forEach(node => {
          if (node.nodeType === 1) {
            if (node.classList && node.classList.contains('ai')) addQuickCopy(node);
            node.querySelectorAll && node.querySelectorAll('.msg-row.ai').forEach(addQuickCopy);
          }
        });
      });
    });
    obs2.observe(msgList, { childList: true, subtree: false });
  }

  // ── 9. OFFLINE DETECTION BANNER ────────────────────
  const offlineBanner = document.getElementById('offline-banner');
  if (offlineBanner) {
    function setOffline(isOff) {
      offlineBanner.classList.toggle('visible', isOff);
    }
    window.addEventListener('offline', () => setOffline(true));
    window.addEventListener('online',  () => setOffline(false));
    if (!navigator.onLine) setOffline(true);
  }

  // ── 10. CONTEXT WINDOW INDICATOR ───────────────────
  function updateCtxIndicator() {
    const hdrActions = document.querySelector('.hdr-actions');
    if (!hdrActions) return;
    let ctxEl = document.getElementById('ctx-indicator');
    if (!ctxEl) {
      ctxEl = document.createElement('div');
      ctxEl.id = 'ctx-indicator';
      ctxEl.className = 'ctx-indicator';
      ctxEl.title = 'Conversation context used';
      hdrActions.prepend(ctxEl);
    }
    const chat = typeof getChat === 'function' ? getChat() : null;
    if (!chat || !chat.messages || chat.messages.length === 0) {
      ctxEl.style.display = 'none'; return;
    }
    const count = chat.messages.length;
    const pct   = Math.min(100, Math.round(count / 100 * 100));
    ctxEl.style.display = 'flex';
    ctxEl.className = 'ctx-indicator'
      + (pct >= 90 ? ' ctx-high' : pct >= 60 ? ' ctx-mid' : '');
    ctxEl.innerHTML = `<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg> ${count} msgs`;
    ctxEl.setAttribute('aria-label', `${count} messages in context`);
  }
  // Update on ZenQBus events
  if (typeof ZenQBus !== 'undefined') {
    ZenQBus.on('message:sent',      updateCtxIndicator);
    ZenQBus.on('generation:done',   updateCtxIndicator);
    ZenQBus.on('chat:switched',     updateCtxIndicator);
    ZenQBus.on('chat:created',      updateCtxIndicator);
  }

  // ── 11. SCROLL FAB UNREAD INTEGRATION ──────────────
  (function wireScrollFabUnread() {
    const msgsWrap = document.getElementById('msgs-wrap');
    const msgList  = document.getElementById('msg-list');
    if (!msgsWrap || !msgList || typeof MutationObserver === 'undefined') return;
    let _mrafPending = false;
    const unreadObs = new MutationObserver(() => {
      if (_mrafPending) return;
      _mrafPending = true;
      requestAnimationFrame(() => {
        _mrafPending = false;
        const atBottom = msgsWrap.scrollHeight - msgsWrap.scrollTop - msgsWrap.clientHeight < 80;
        if (atBottom && typeof hideScrollFab === 'function') hideScrollFab();
      });
    });
    unreadObs.observe(msgList, { childList: true });
  })();

  // ── 12. INPUT FOCUS RING WITH SHADOW UPGRADE ───────
  const inputBox = document.getElementById('inputBox');
  if (inputBox && msgTa) {
    msgTa.addEventListener('focus', () => {
      inputBox.style.boxShadow = '0 0 0 3px rgba(108,110,247,0.16), 0 4px 24px rgba(0,0,0,0.22)';
    });
    msgTa.addEventListener('blur', () => {
      inputBox.style.boxShadow = '';
    });
  }

  // ── 13. DRAG-AND-DROP VISUAL POLISH ────────────────
  if (inputBox) {
    inputBox.addEventListener('dragover', (e) => {
      e.preventDefault();
      inputBox.classList.add('drag-over');
    });
    inputBox.addEventListener('dragleave', () => inputBox.classList.remove('drag-over'));
    inputBox.addEventListener('drop', ()     => inputBox.classList.remove('drag-over'));
  }

  // ── 14. SEND BUTTON — v31: CSS class for click feedback (no setTimeout) ───
  const sendBtn = document.getElementById('send-btn');
  if (sendBtn) {
    sendBtn.addEventListener('pointerdown', () => {
      sendBtn.classList.add('pressing');
    });
    sendBtn.addEventListener('pointerup', () => {
      sendBtn.classList.remove('pressing');
    });
    sendBtn.addEventListener('pointerleave', () => {
      sendBtn.classList.remove('pressing');
    });
  }

  // ── 15. SMOOTH PAGE INIT ────────────────────────────
  document.addEventListener('DOMContentLoaded', () => {
    // Init ctx indicator after app loads
    setTimeout(updateCtxIndicator, 600);
    // Welcome hint chips fade in
    const hints = document.getElementById('wlcHints');
    if (hints) hints.style.opacity = '1';
  });

  // ── 16. CODE BLOCK ENHANCEMENTS ────────────────────
  // Add line numbers to long code blocks and language label glow
  function enhanceCodeBlocks() {
    document.querySelectorAll('.cb:not([data-enhanced])').forEach(cb => {
      cb.setAttribute('data-enhanced', '1');
      const langEl = cb.querySelector('.cb-lang');
      if (langEl) {
        const lang = langEl.textContent.trim().toLowerCase();
        const colorMap = {
          js: '#f7df1e', javascript: '#f7df1e', ts: '#3178c6', typescript: '#3178c6',
          python: '#3776ab', py: '#3776ab', css: '#1572b6', html: '#e34f26',
          rust: '#ce412b', go: '#00add8', java: '#f89820', json: '#f5a623',
          bash: '#4eaa25', shell: '#4eaa25', sql: '#cc2927',
        };
        const col = colorMap[lang];
        if (col) langEl.style.color = col;
      }
    });
  }
  // OPT: Use requestIdleCallback for code block enhancement — runs when browser is idle,
  // not blocking the main thread during active streaming
  if (msgList && typeof MutationObserver !== 'undefined') {
    const codeObs = new MutationObserver(() => {
      if (typeof requestIdleCallback === 'function') {
        requestIdleCallback(enhanceCodeBlocks, { timeout: 200 });
      } else {
        setTimeout(enhanceCodeBlocks, 50);
      }
    });
    codeObs.observe(msgList, { childList: true, subtree: true });
  }

  // OPT: beforeunload cleanup — cancel all pending async operations to prevent
  // "Cannot set property of null" errors after page unload + free memory.
  window.addEventListener('beforeunload', () => {
    // Cancel pending debounced sidebar render
    if (typeof debouncedRenderChatList !== 'undefined' && typeof debouncedRenderChatList.cancel === 'function') {
      debouncedRenderChatList.cancel();
    }
    // Cancel any in-flight streaming rAF
    if (APP._streamRafId) {
      cancelAnimationFrame(APP._streamRafId);
      APP._streamRafId = null;
    }
    // Abort any pending fetch
    if (APP._abortController) {
      try { APP._abortController.abort(); } catch(_) {}
      APP._abortController = null;
    }
    // Stop real-time clock
    if (typeof _clockHandle !== 'undefined' && _clockHandle !== null) {
      clearTimeout(_clockHandle);
    }
    // Stop audio context leak
    if (typeof _audioCtx !== 'undefined' && _audioCtx && _audioCtx.state !== 'closed') {
      _audioCtx.close().catch(() => {});
    }
  }, { once: true });

  // ── v34: SMOOTH MOBILE KEYBOARD TRACKING (visualViewport) ─────────
  // CONSOLIDATED: This handler has been replaced by initMobileKeyboardHandler()
  // at the bottom of this file. That handler uses translateY (not --vvh)
  // for zero-reflow keyboard tracking. No action needed here.

  // ── v34: SIDEBAR THEME TOGGLE BUTTON ────────────────────────────
  // Wire the new sidebar footer theme toggle (replaces the hidden header one).
  (function initSbThemeBtn() {
    const sbThemeBtn = document.getElementById('sbThemeBtn');
    const sbSunIcon  = document.getElementById('sbSunIcon');
    const sbMoonIcon = document.getElementById('sbMoonIcon');
    if (!sbThemeBtn) return;

    // Sync icon with current theme
    function syncSbThemeIcon() {
      const isDark = document.documentElement.getAttribute('data-theme') !== 'light';
      if (sbSunIcon)  sbSunIcon.classList.toggle('hidden', isDark);
      if (sbMoonIcon) sbMoonIcon.classList.toggle('hidden', !isDark);
      sbThemeBtn.setAttribute('title', isDark ? 'Switch to Light mode' : 'Switch to Dark mode');
    }

    sbThemeBtn.addEventListener('click', () => {
      const next = document.documentElement.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
      if (typeof applyTheme === 'function') applyTheme(next);
      syncSbThemeIcon();
    });

    // Keep in sync when theme changes via other means (keyboard shortcut, settings)
    const origApply = window.applyTheme;
    if (typeof origApply === 'function') {
      window.applyTheme = function(t) {
        origApply.apply(this, arguments);
        syncSbThemeIcon();
      };
    }

    // Also listen for ZenQBus theme events
    if (typeof ZenQBus !== 'undefined') {
      ZenQBus.on('theme:changed', syncSbThemeIcon);
    }

    syncSbThemeIcon();
  })();

  // ── v34: KEYBOARD SHORTCUT — Ctrl+T for theme toggle ────────────
  document.addEventListener('keydown', (e) => {
    if ((e.ctrlKey || e.metaKey) && e.key === 't' && !e.shiftKey && !e.altKey) {
      // Don't intercept in input fields
      const tag = document.activeElement?.tagName;
      if (tag === 'INPUT' || tag === 'TEXTAREA') return;
      e.preventDefault();
      const sbThemeBtn = document.getElementById('sbThemeBtn');
      if (sbThemeBtn) sbThemeBtn.click();
    }
  });

  // ── v34: INPUT BOX LIFT ANIMATION ON FOCUS ──────────────────────
  // Subtle upward translate when textarea is focused — feels alive.
  (function initInputLift() {
    const inputBox = document.getElementById('inputBox') || document.querySelector('.input-box');
    const msgTa    = document.getElementById('msg-ta');
    if (!inputBox || !msgTa) return;
    msgTa.addEventListener('focus', () => {
      inputBox.style.transition = 'border-color 0.22s ease, box-shadow 0.22s ease, transform 0.24s cubic-bezier(0.25,0.46,0.45,0.94)';
      inputBox.style.transform = 'translateY(-1px)';
    });
    msgTa.addEventListener('blur', () => {
      inputBox.style.transform = '';
    });
  })();

  // ── v34: MESSAGE ROW STAGGER ON INITIAL RENDER ──────────────────
  // When the message list is initially populated, stagger entrance delays.
  (function initMsgStagger() {
    const msgList = document.getElementById('msg-list');
    if (!msgList || typeof MutationObserver === 'undefined') return;
    let _firstBatch = true;
    const staggerObs = new MutationObserver((mutations) => {
      if (!_firstBatch) return;
      const added = mutations.flatMap(m => Array.from(m.addedNodes))
        .filter(n => n.nodeType === 1 && n.classList?.contains('msg-row'));
      if (added.length > 2) {
        _firstBatch = false;
        added.forEach((row, i) => {
          // Reset and stagger
          row.style.animationDelay = `${i * 0.04}s`;
        });
      }
    });
    staggerObs.observe(msgList, { childList: true });
    // Stop watching after first render completes
    setTimeout(() => { _firstBatch = false; staggerObs.disconnect(); }, 2000);
  })();

  // ── v34: HEADER ACTIONS HOVER RIPPLE ────────────────────────────
  // Inject a subtle background ripple on header button clicks.
  (function initHdrRipple() {
    const hdrActions = document.querySelector('.hdr-actions');
    if (!hdrActions) return;
    hdrActions.addEventListener('pointerdown', (e) => {
      const btn = e.target.closest('button');
      if (!btn || !hdrActions.contains(btn)) return;
      const r = document.createElement('span');
      r.className = 'ripple-ring';
      btn.style.position = 'relative';
      btn.style.overflow  = 'hidden';
      btn.appendChild(r);
      setTimeout(() => r.isConnected && r.remove(), 600);
    });
  })();

  // ── ACCENT COLOR THEME CUSTOMIZER ───────────────────────────────
  // Allows user to pick accent color: purple, blue, green, yellow, orange, red
  (function initAccentColorPicker() {
    const ACCENT_PRESETS = {
      purple: {
        accent: '#6c6ef7', accent2: '#8b5cf6',
        glow:   'rgba(108,110,247,0.18)', glow2: 'rgba(139,92,246,0.12)',
        light:  '#5a58e8', light2: '#7c3aed',
      },
      blue: {
        accent: '#38bdf8', accent2: '#0ea5e9',
        glow:   'rgba(56,189,248,0.18)', glow2: 'rgba(14,165,233,0.12)',
        light:  '#0284c7', light2: '#0369a1',
      },
      green: {
        accent: '#10b981', accent2: '#059669',
        glow:   'rgba(16,185,129,0.18)', glow2: 'rgba(5,150,105,0.12)',
        light:  '#059669', light2: '#047857',
      },
      yellow: {
        accent: '#eab308', accent2: '#ca8a04',
        glow:   'rgba(234,179,8,0.18)', glow2: 'rgba(202,138,4,0.12)',
        light:  '#ca8a04', light2: '#a16207',
      },
      orange: {
        accent: '#f97316', accent2: '#ea580c',
        glow:   'rgba(249,115,22,0.18)', glow2: 'rgba(234,88,12,0.12)',
        light:  '#ea580c', light2: '#c2410c',
      },
      red: {
        accent: '#ef4444', accent2: '#dc2626',
        glow:   'rgba(239,68,68,0.18)', glow2: 'rgba(220,38,38,0.12)',
        light:  '#dc2626', light2: '#b91c1c',
      },
    };

    function applyAccentColor(colorKey) {
      const p = ACCENT_PRESETS[colorKey];
      if (!p) return;
      const root = document.documentElement;
      const isLight = root.getAttribute('data-theme') === 'light';
      root.style.setProperty('--accent',      isLight ? p.light  : p.accent);
      root.style.setProperty('--accent-2',    isLight ? p.light2 : p.accent2);
      root.style.setProperty('--accent-glow',  p.glow);
      root.style.setProperty('--accent-glow2', p.glow2);
      // Also set --c-accent for v31 design system compatibility
      root.style.setProperty('--c-accent',    isLight ? p.light  : p.accent);
      try { localStorage.setItem('aura_accent_color', colorKey); } catch(_) {}
    }

    // Restore saved preference
    const savedColor = (() => {
      try { return localStorage.getItem('aura_accent_color'); } catch(_) { return null; }
    })();
    if (savedColor && ACCENT_PRESETS[savedColor]) {
      applyAccentColor(savedColor);
    }

    // Wire up swatch buttons when settings panel opens
    function wireSwatches() {
      const grid = document.getElementById('themeColorGrid');
      if (!grid) return;
      const saved = (() => { try { return localStorage.getItem('aura_accent_color') || 'purple'; } catch(_) { return 'purple'; } })();
      grid.querySelectorAll('.tc-swatch').forEach(sw => {
        const key = sw.dataset.color;
        sw.classList.toggle('active', key === saved);
        sw.addEventListener('click', () => {
          grid.querySelectorAll('.tc-swatch').forEach(s => s.classList.remove('active'));
          sw.classList.add('active');
          applyAccentColor(key);
        });
      });
    }

    // Wire on settings open
    const settBtn = document.getElementById('settBtn') || document.querySelector('[id*="sett"]');
    if (settBtn) {
      settBtn.addEventListener('click', () => setTimeout(wireSwatches, 100));
    }
    // Also try immediately (settings panel might already be in DOM)
    setTimeout(wireSwatches, 800);

    // Re-apply accent when theme changes (light/dark swap may need different shade)
    if (typeof ZenQBus !== 'undefined') {
      ZenQBus.on('theme:changed', () => {
        const cur = (() => { try { return localStorage.getItem('aura_accent_color'); } catch(_) { return null; } })();
        if (cur) applyAccentColor(cur);
      });
    }
  })();

})(); // end AuraUX IIFE


// ╔══════════════════════════════════════════════════════════════════════╗
// ║  AURA AI v37 — DEEP PERFORMANCE ENGINE                              ║
// ║  All systems initialized via AuraPerf global (console: AuraPerf.report()) ║
// ╚══════════════════════════════════════════════════════════════════════╝
(function AuraV38PerfEngine() {
  'use strict';

  // ── rAF Budget Scheduler ────────────────────────────────────────────
  // Queues tasks and executes within a 12ms per-frame budget.
  const AuraPerfScheduler = (() => {
    const BUDGET = 12;
    const queue = [];
    let rafId = null;
    let _drops = 0, _skipped = 0;
    function flush() {
      const t0 = performance.now();
      while (queue.length) {
        if (performance.now() - t0 >= BUDGET) {
          _skipped++;
          rafId = requestAnimationFrame(flush);
          return;
        }
        try { queue.shift()(); } catch(_) {}
      }
      rafId = null;
    }
    return {
      schedule(fn, hi) { hi ? queue.unshift(fn) : queue.push(fn); if (!rafId) rafId = requestAnimationFrame(flush); },
      recordDrop() { _drops++; },
      getDrops() { return _drops; },
      getSkipped() { return _skipped; },
    };
  })();

  // ── Message Render Memoization ─────────────────────────────────────
  const AuraMsgCache = (() => {
    const _cache = new Map();
    const MAX = 400;
    let _renders = 0, _hits = 0;
    function hash(s) {
      let h = 0x811c9dc5;
      for (let i = 0; i < Math.min(s.length, 1024); i++) { h ^= s.charCodeAt(i); h = (h * 0x01000193) >>> 0; }
      return h.toString(36);
    }
    function key(m) { return m.id + '_' + hash(m.content || '') + (m.liked ? 'L' : '') + (m.disliked ? 'D' : ''); }
    function evict() {
      if (_cache.size <= MAX) return;
      const trim = Math.floor(_cache.size * 0.25);
      let n = 0; for (const k of _cache.keys()) { if (n++ >= trim) break; _cache.delete(k); }
    }
    return {
      get(m) { const k = key(m); if (_cache.has(k)) { _hits++; return _cache.get(k); } return null; },
      set(m, html) { _cache.set(key(m), html); evict(); },
      invalidate(id) { for (const k of _cache.keys()) { if (k.startsWith(id + '_')) { _cache.delete(k); return; } } },
      recordRender() { _renders++; },
      getRenders() { return _renders; },
      getHits() { return _hits; },
      getSize() { return _cache.size; },
      clear() { _cache.clear(); },
    };
  })();

  // Patch createMessageElement for memoization
  (function() {
    const _orig = typeof createMessageElement === 'function' ? createMessageElement : null;
    if (!_orig) return;
    window.createMessageElement = function(msg, opts) {
      opts = opts || {};
      AuraMsgCache.recordRender();
      if (!opts.grouped && !opts.groupStart) {
        const hit = AuraMsgCache.get(msg);
        if (hit) {
          const w = document.createElement('div');
          w.innerHTML = hit;
          const el = w.firstElementChild;
          if (el) { el.dataset.rendered = '1'; return el; }
        }
      }
      const el = _orig(msg, opts);
      if (el && !opts.grouped && !opts.groupStart) AuraMsgCache.set(msg, el.outerHTML);
      if (el) el.dataset.rendered = '1';
      return el;
    };
  })();

  // Invalidate cache on ZenQDB.saveMessage
  (function() {
    if (typeof ZenQDB === 'undefined' || !ZenQDB.saveMessage) return;
    const _orig = ZenQDB.saveMessage.bind(ZenQDB);
    ZenQDB.saveMessage = function(msg, chatId) {
      if (msg && msg.id) AuraMsgCache.invalidate(msg.id);
      return _orig(msg, chatId);
    };
  })();

  // ── FPS Monitor + Frame Drop Detection ────────────────────────────
  const AuraFPSMonitor = (() => {
    let _fps = 60, _last = 0, _frames = 0, _lastFrame = 0, _drops = 0, _running = false;
    const HUD_MS = 600;
    let _hudTimer = 0;
    function tick(now) {
      if (!_running) return;
      const delta = now - _lastFrame;
      _lastFrame = now;
      _frames++;
      if (delta > 33 && _lastFrame > 500) { // > 33ms = below 30fps
        _drops++;
        AuraPerfScheduler.recordDrop();
        const bar = document.getElementById('frame-drop-indicator');
        if (bar) { bar.classList.add('flash'); setTimeout(() => bar.classList.remove('flash'), 150); }
      }
      if (now - _hudTimer >= HUD_MS) {
        const elapsed = (now - _last) / 1000;
        _fps = elapsed > 0 ? Math.round(_frames / elapsed) : 60;
        _frames = 0; _last = now; _hudTimer = now;
        _updateHUD(_fps, delta, _drops);
      }
      requestAnimationFrame(tick);
    }
    function _updateHUD(fps, delta, drops) {
      const hud = document.getElementById('perf-hud');
      const dbg = document.getElementById('render-dbg');
      if (hud && hud.classList.contains('visible')) {
        const fe = document.getElementById('ph-fps');
        if (fe) { fe.textContent = fps; fe.className = 'ph-fps' + (fps < 30 ? ' bad' : fps < 50 ? ' warn' : ''); }
        const ff = document.getElementById('ph-frame'); if (ff) ff.textContent = Math.round(delta) + 'ms';
        const fd = document.getElementById('ph-drops'); if (fd) fd.textContent = drops;
        const fn = document.getElementById('ph-nodes'); if (fn) fn.textContent = document.querySelectorAll('*').length.toLocaleString();
        const fm = document.getElementById('ph-msgs'); if (fm) fm.textContent = document.querySelectorAll('.msg-row').length;
        const fmem = document.getElementById('ph-mem');
        if (fmem && performance.memory) fmem.textContent = (performance.memory.usedJSHeapSize / 1048576).toFixed(1);
        const fr = document.getElementById('ph-renders'); if (fr) fr.textContent = AuraMsgCache.getRenders();
      }
      if (dbg && dbg.classList.contains('visible')) {
        const rm = document.getElementById('rd-memos'); if (rm) rm.textContent = AuraMsgCache.getSize() + ' (' + AuraMsgCache.getHits() + ' hits)';
        const rr = document.getElementById('rd-renders'); if (rr) rr.textContent = AuraMsgCache.getRenders();
        const rv = document.getElementById('rd-vml'); if (rv) rv.textContent = document.querySelectorAll('#msg-list .msg-row').length + ' visible';
        const rs = document.getElementById('rd-skipped'); if (rs) rs.textContent = AuraPerfScheduler.getSkipped();
        const rp = document.getElementById('rd-mem-pressure'); if (rp) rp.textContent = AuraMemMgr.getPressure();
      }
    }
    return {
      start() { if (_running) return; _running = true; _last = _lastFrame = _hudTimer = performance.now(); requestAnimationFrame(tick); },
      stop() { _running = false; },
      getFPS() { return _fps; },
      getDrops() { return _drops; },
    };
  })();

  // ── Memory Manager ────────────────────────────────────────────────
  const AuraMemMgr = (() => {
    let _pressure = 'normal', _timer = null;
    const WARN = 200, CRIT = 350;
    function check() {
      if (!performance.memory) return;
      const mb = performance.memory.usedJSHeapSize / 1048576;
      const prev = _pressure;
      _pressure = mb >= CRIT ? 'critical' : mb >= WARN ? 'warn' : 'normal';
      if (_pressure === 'critical' && prev !== 'critical') {
        AuraMsgCache.clear();
        if (window._responseCache) try { window._responseCache.clear(); } catch(_) {}
        if (typeof ZenQLogger !== 'undefined') ZenQLogger.warn('Memory', `Critical heap: ${mb.toFixed(0)}MB - purged caches`);
      }
    }
    return {
      start() { if (_timer) return; _timer = setInterval(check, 20000); },
      stop() { clearInterval(_timer); _timer = null; },
      getPressure() { return _pressure; },
      forceCheck() { check(); },
    };
  })();

  // ── DOM Batch Writer — eliminate layout thrashing ─────────────────
  const AuraBatchDOM = (() => {
    const reads = [], writes = [];
    let scheduled = false;
    function flush() {
      scheduled = false;
      const r = reads.splice(0); r.forEach(fn => { try { fn(); } catch(_) {} });
      const w = writes.splice(0); w.forEach(fn => { try { fn(); } catch(_) {} });
    }
    function schedule() { if (!scheduled) { scheduled = true; requestAnimationFrame(flush); } }
    return {
      read(fn)  { reads.push(fn);  schedule(); return AuraBatchDOM; },
      write(fn) { writes.push(fn); schedule(); return AuraBatchDOM; },
      now(fn)   { try { fn(); } catch(_) {} },
    };
  })();

  // ── Lazy Image Loader ────────────────────────────────────────────
  const AuraLazyImg = (() => {
    let _io = null;
    function init() {
      if (!window.IntersectionObserver || _io) return;
      _io = new IntersectionObserver(entries => {
        entries.forEach(e => {
          if (!e.isIntersecting) return;
          const img = e.target;
          if (img.dataset.src) {
            img.src = img.dataset.src;
            img.removeAttribute('data-src');
          }
          img.classList.remove('lazy-pending');
          const done = () => img.classList.add('lazy-loaded');
          img.complete ? done() : (img.onload = img.onerror = done);
          _io.unobserve(img);
        });
      }, { rootMargin: '200px 0px', threshold: 0.01 });
    }
    return {
      init() {
        init();
        document.querySelectorAll('#msg-list img').forEach(img => {
          if (!img.complete) { img.classList.add('lazy-pending'); _io && _io.observe(img); }
          else img.classList.add('lazy-loaded');
        });
      },
      observe(container) {
        if (!_io) init();
        if (!container || !_io) return;
        container.querySelectorAll('img').forEach(img => {
          if (!img.complete) { img.classList.add('lazy-pending'); _io.observe(img); }
          else img.classList.add('lazy-loaded');
        });
      },
    };
  })();

  // ── VML patch: lazy-load images + animation pause on bulk load ────
  (function() {
    if (typeof VML === 'undefined') return;
    const _origAppend = VML.append.bind(VML);
    VML.append = function(msg) {
      const el = _origAppend(msg);
      if (el) AuraLazyImg.observe(el);
      return el;
    };
    const _origLoad = VML.load.bind(VML);
    VML.load = function(messages) {
      document.body.classList.add('streaming');
      AuraMsgCache.clear();
      _origLoad(messages);
      requestAnimationFrame(() => {
        document.body.classList.remove('streaming');
        const list = document.getElementById('msg-list');
        if (list) AuraLazyImg.observe(list);
      });
    };
  })();

  // ── Long Conversation Optimizer ─────────────────────────────────
  const AuraLongConv = (() => {
    const THRESHOLD = 200;
    let _active = false;
    return {
      check(count) {
        if (_active || count < THRESHOLD) return;
        _active = true;
        document.documentElement.style.setProperty('--t', '0.08s');
        document.documentElement.style.setProperty('--t-slow', '0.15s');
        document.querySelectorAll('.orb').forEach(o => { o.style.animation = 'none'; o.style.opacity = '0'; });
        if (typeof ZenQLogger !== 'undefined') ZenQLogger.info('Perf', 'Long conv mode: ' + count + ' msgs');
      },
      isActive() { return _active; },
      reset() {
        _active = false;
        document.documentElement.style.removeProperty('--t');
        document.documentElement.style.removeProperty('--t-slow');
      },
    };
  })();

  // Patch sendMessage for long-conv check
  (function() {
    const _orig = window.sendMessage;
    if (typeof _orig !== 'function') return;
    window.sendMessage = function(text) {
      _orig(text);
      setTimeout(() => {
        const chat = typeof getChat === 'function' ? getChat() : null;
        if (chat && chat.messages) AuraLongConv.check(chat.messages.length);
      }, 100);
    };
  })();

  // ── PerformanceObserver — Long Tasks + CLS + LCP ────────────────
  (function() {
    if (!window.PerformanceObserver) return;
    // Long tasks
    try {
      new PerformanceObserver(list => {
        list.getEntries().forEach(e => {
          if (e.duration > 50) {
            AuraPerfScheduler.recordDrop();
            if (typeof ZenQLogger !== 'undefined') ZenQLogger.warn('Perf', 'Long task: ' + e.duration.toFixed(0) + 'ms');
          }
        });
      }).observe({ entryTypes: ['longtask'] });
    } catch(_) {}
    // CLS
    try {
      let cls = 0;
      new PerformanceObserver(list => {
        list.getEntries().forEach(e => { if (!e.hadRecentInput) cls += e.value; });
        if (cls > 0.1 && typeof ZenQLogger !== 'undefined') ZenQLogger.warn('Perf', 'High CLS: ' + cls.toFixed(3));
      }).observe({ entryTypes: ['layout-shift'] });
    } catch(_) {}
    // LCP
    try {
      const lcp = new PerformanceObserver(list => {
        const e = list.getEntries().slice(-1)[0];
        if (e && typeof ZenQLogger !== 'undefined') ZenQLogger.info('Perf', 'LCP: ' + e.startTime.toFixed(0) + 'ms');
        lcp.disconnect();
      });
      lcp.observe({ entryTypes: ['largest-contentful-paint'] });
    } catch(_) {}
  })();

  // ── Animation Budget Guard ────────────────────────────────────────
  (function() {
    let _paused = false;
    setInterval(() => {
      const fps = AuraFPSMonitor.getFPS();
      if (fps > 0 && fps < 40 && !_paused) {
        _paused = true;
        document.querySelectorAll('.orb').forEach(o => o.style.animationPlayState = 'paused');
      } else if (fps >= 55 && _paused) {
        _paused = false;
        document.querySelectorAll('.orb').forEach(o => o.style.animationPlayState = '');
      }
    }, 2000);
  })();

  // ── Keyboard shortcuts: Ctrl+Shift+P = HUD, Ctrl+Shift+D = Debug ─
  document.addEventListener('keydown', e => {
    if ((e.ctrlKey || e.metaKey) && e.shiftKey) {
      if (e.key === 'P') {
        e.preventDefault();
        const hud = document.getElementById('perf-hud');
        if (hud) {
          hud.classList.toggle('visible');
          if (hud.classList.contains('visible')) { AuraFPSMonitor.start(); if (typeof toast === 'function') toast('FPS HUD on (Ctrl+Shift+P to hide)', 'info', 2000); }
        }
      }
      if (e.key === 'D') {
        e.preventDefault();
        const dbg = document.getElementById('render-dbg');
        if (dbg) {
          dbg.classList.toggle('visible');
          if (dbg.classList.contains('visible')) { AuraFPSMonitor.start(); if (typeof toast === 'function') toast('Render debug on (Ctrl+Shift+D to hide)', 'info', 2000); }
        }
      }
    }
  });

  // ── Profile avatar lazy load patch ───────────────────────────────
  (function() {
    if (typeof applyProfileUI !== 'function') return;
    const _orig = applyProfileUI;
    window.applyProfileUI = function(p) {
      _orig(p);
      document.querySelectorAll('.msg-av img, .sb-avatar img, .fb-user-av img').forEach(img => {
        if (!img.getAttribute('loading')) { img.loading = 'lazy'; img.decoding = 'async'; }
      });
    };
  })();

  // ── ZenQBus streaming class patch ──────────────────────────────────
  if (typeof ZenQBus !== 'undefined') {
    ZenQBus.on('generation:start', () => document.body.classList.add('streaming'));
    ZenQBus.on('generation:done',  () => document.body.classList.remove('streaming'));
  }

  // ── Boot ──────────────────────────────────────────────────────────
  AuraLazyImg.init();
  AuraMemMgr.start();
  AuraFPSMonitor.start();

  if (typeof ZenQLogger !== 'undefined') {
    ZenQLogger.info('v38', 'Deep Performance Engine ready');
    ZenQLogger.info('v38', 'Ctrl+Shift+P = FPS HUD | Ctrl+Shift+D = Render Debug | AuraPerf.report() in console');
  }

  // ── Expose on window ─────────────────────────────────────────────
  window.AuraPerf = {
    fps: AuraFPSMonitor,
    scheduler: AuraPerfScheduler,
    cache: AuraMsgCache,
    memory: AuraMemMgr,
    lazyImg: AuraLazyImg,
    batchDOM: AuraBatchDOM,
    longConv: AuraLongConv,
    showHUD()   { const h = document.getElementById('perf-hud'); if (h) { h.classList.add('visible'); AuraFPSMonitor.start(); } },
    hideHUD()   { const h = document.getElementById('perf-hud'); if (h) h.classList.remove('visible'); },
    showDebug() { const d = document.getElementById('render-dbg'); if (d) { d.classList.add('visible'); AuraFPSMonitor.start(); } },
    report() {
      console.group('[AuraPerf v38]');
      console.log('FPS:', AuraFPSMonitor.getFPS());
      console.log('Frame drops:', AuraFPSMonitor.getDrops());
      console.log('Cache size:', AuraMsgCache.getSize(), '| Cache hits:', AuraMsgCache.getHits());
      console.log('Total renders:', AuraMsgCache.getRenders());
      console.log('Heap MB:', (performance.memory?.usedJSHeapSize / 1048576)?.toFixed(1) || 'N/A');
      console.log('Memory pressure:', AuraMemMgr.getPressure());
      console.log('Long conv mode:', AuraLongConv.isActive());
      console.log('rAF budget skips:', AuraPerfScheduler.getSkipped());
      console.groupEnd();
    },
  };

})(); // end AuraV38PerfEngine
// ── END AURA AI v38 DEEP PERFORMANCE ENGINE ──────────────────────────────────

// ══════════════════════════════════════════════════════════════════════════════
// ══════════════════════════════════════════════════════════════════════════════
// AURA AI — MOBILE KEYBOARD HANDLER  (ChatGPT Fixed-Bottom Architecture)
// ══════════════════════════════════════════════════════════════════════════════
//
// HOW CHATGPT DOES IT:
//   • #input-area  → position:fixed; JS sets `bottom = keyboardHeight`
//   • #msgs-wrap   → JS sets `paddingBottom = inputHeight + keyboardHeight`
//   • On keyboard open → instant scroll to bottom so last message stays visible
//   • Smooth CSS transitions handle the visual animation (no jank)
//
// iOS QUIRK: position:fixed bottom:0 does NOT auto-lift on iOS Safari.
//   We must explicitly set `inputArea.style.bottom = kbH + safeArea + 'px'`.
//
// ANDROID QUIRK: Modern Chrome/WebView auto-lifts fixed elements, so kbH
//   will read 0 there. We detect this and skip the override.
//
// SAFE AREA: Always add env(safe-area-inset-bottom) so notched phones work.
// ══════════════════════════════════════════════════════════════════════════════
/* ─────────────────────────────────────────────────────────────────────────────
   AURA AI — CHATGPT-LEVEL SMOOTH KEYBOARD HANDLER
   Strategy:
     Android Chrome 108+ : interactive-widget=resizes-content in viewport meta
       → browser resizes the layout viewport naturally, no JS position hacks needed.
       → input bar stays fixed at bottom:0, browser pushes it up automatically.
       → msgs-wrap height shrinks naturally, no padding-bottom hacks needed.
     iOS Safari + older Android: visualViewport JS with CSS transition for smooth lift.
       → CSS transition: bottom 280ms animates the bar upward as keyboard rises.
       → padding-bottom on msgs-wrap transitions in sync.
   Key rules:
     • NEVER fight the browser keyboard animation with immediate JS style writes.
     • CSS transition does the animation; JS only sets the target value.
     • Suppress transition ONLY on initial page paint, restore before first interaction.
───────────────────────────────────────────────────────────────────────────── */
(function initMobileKeyboardHandler() {
  'use strict';

  const inputArea = document.getElementById('input-area');
  const msgsWrap  = document.getElementById('msgs-wrap');
  const scrollFab = document.getElementById('scroll-fab');
  const msgTa     = document.getElementById('msg-ta');
  const root      = document.documentElement;
  if (!inputArea) return;

  // ── Platform detection ────────────────────────────────────────────────────
  const _vv    = window.visualViewport;
  const _isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent) ||
                 (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
  // Android Chrome 108+ with interactive-widget=resizes-content handles layout
  // automatically. We still run JS for scroll-to-bottom and FAB positioning.
  const _ua         = navigator.userAgent;
  const _chromeVer  = (() => { const m = _ua.match(/Chrome\/(\d+)/); return m ? +m[1] : 0; })();
  const _isModernAndroid = !_isIOS && _chromeVer >= 108;

  // ── Measure safe-area-inset-bottom once ───────────────────────────────────
  let _safeB = 0;
  try {
    const tmp = document.createElement('div');
    tmp.style.cssText = 'position:fixed;bottom:0;left:0;width:0;height:env(safe-area-inset-bottom,0px);pointer-events:none;visibility:hidden;';
    document.body.appendChild(tmp);
    _safeB = tmp.offsetHeight || 0;
    tmp.remove();
  } catch (_) {}

  // ── State ─────────────────────────────────────────────────────────────────
  let _rafId      = null;
  let _lastKbH    = -1;    // -1 forces first-run
  let _lastInputH = 0;
  let _lastVVW    = 0;
  let _lastVVH    = 0;
  let _booted     = false; // true after first paint — transitions enabled after this

  // ── Keyboard height from visualViewport ───────────────────────────────────
  function _kbH() {
    if (!_vv) return 0;
    return Math.max(0, Math.round(window.innerHeight - _vv.offsetTop - _vv.height));
  }

  // ── Core layout apply ─────────────────────────────────────────────────────
  function _apply() {
    _rafId = null;
    const isMobile = window.innerWidth <= 768;

    // Desktop: clear all inline overrides, let CSS flex layout handle it
    if (!isMobile) {
      inputArea.style.cssText = '';
      if (msgsWrap)  msgsWrap.style.paddingBottom = '';
      if (scrollFab) scrollFab.style.bottom = '';
      root.style.removeProperty('--input-area-h');
      root.style.removeProperty('--msgs-pb');
      _lastKbH = _lastInputH = 0;
      return;
    }

    const kbH    = _kbH();
    const inputH = inputArea.offsetHeight || 72;

    // Nothing changed → skip (prevents forced-layout jitter on scroll events)
    if (_booted && kbH === _lastKbH && inputH === _lastInputH) return;
    const prevKbH = _lastKbH;
    _lastKbH    = kbH;
    _lastInputH = inputH;

    // ── Update CSS custom props ──────────────────────────────────────────────
    root.style.setProperty('--input-area-h', inputH + 'px');

    if (_isModernAndroid) {
      // Modern Android: browser handles fixed bar lift via resizes-content.
      // We only need to update msgs-wrap padding and FAB position.
      const pb = inputH + _safeB;
      root.style.setProperty('--msgs-pb', pb + 'px');
      if (msgsWrap && msgsWrap.style.paddingBottom !== pb + 'px') {
        msgsWrap.style.paddingBottom = pb + 'px';
      }
      if (scrollFab) scrollFab.style.bottom = (inputH + _safeB + 12) + 'px';

    } else {
      // iOS + older Android: manually lift the bar above the keyboard.
      // CSS transition on `bottom` provides the smooth animation.
      const barBottom = Math.max(kbH, _safeB);

      // Suppress transition on page boot only (no sliding in from bottom on load)
      if (!_booted) {
        inputArea.style.transition = 'none';
        if (msgsWrap) msgsWrap.style.transition = 'none';
      }

      // Set target bottom — CSS transition animates this if _booted
      inputArea.style.setProperty('bottom', barBottom + 'px', 'important');

      const pb = inputH + Math.max(kbH, _safeB);
      root.style.setProperty('--msgs-pb', pb + 'px');
      if (msgsWrap) msgsWrap.style.paddingBottom = pb + 'px';
      if (scrollFab) scrollFab.style.bottom = (barBottom + inputH + 12) + 'px';

      // Re-enable transitions after first paint so subsequent keyboard events animate
      if (!_booted) {
        requestAnimationFrame(() => {
          inputArea.style.transition = '';
          if (msgsWrap) msgsWrap.style.transition = '';
        });
      }
    }

    // ── Scroll to bottom when keyboard FIRST opens ───────────────────────────
    // Only fires on the first open event (prevKbH was ≤ 80, now kbH > 80).
    // Uses instant scroll (auto) to avoid fighting the padding-bottom transition.
    if (kbH > 80 && prevKbH <= 80 && msgsWrap) {
      requestAnimationFrame(() => requestAnimationFrame(() => {
        const prev = msgsWrap.style.scrollBehavior;
        msgsWrap.style.scrollBehavior = 'auto';
        msgsWrap.scrollTop = msgsWrap.scrollHeight;
        requestAnimationFrame(() => { msgsWrap.style.scrollBehavior = prev || ''; });
      }));
    }

    _booted = true;
  }

  // ── Debounced schedule via rAF (max one pending frame) ───────────────────
  function _schedule() {
    if (_rafId !== null) return;
    _rafId = requestAnimationFrame(_apply);
  }

  // ── Size-change guard: skip scroll-only viewport events ──────────────────
  function _scheduleIfSizeChanged() {
    if (!_vv) return;
    const w = Math.round(_vv.width), h = Math.round(_vv.height);
    if (w === _lastVVW && h === _lastVVH) return;
    _lastVVW = w; _lastVVH = h;
    _schedule();
  }

  // ── Boot: initial layout without animation ────────────────────────────────
  if (_vv) { _lastVVW = Math.round(_vv.width); _lastVVH = Math.round(_vv.height); }
  _apply(); // synchronous first paint

  // ── ResizeObserver: textarea multiline growth ─────────────────────────────
  if (window.ResizeObserver) {
    const ro = new ResizeObserver(_schedule);
    ro.observe(inputArea);
    if (typeof APP !== 'undefined') APP._inputAreaRO = ro;
  }

  // ── visualViewport: keyboard open/close ───────────────────────────────────
  if (_vv) {
    _vv.addEventListener('resize', _scheduleIfSizeChanged, { passive: true });
    // iOS needs scroll events too (pinch-zoom repositions fixed elements)
    if (_isIOS) _vv.addEventListener('scroll', _schedule, { passive: true });
  }

  // ── window resize: orientation changes ───────────────────────────────────
  window.addEventListener('resize', () => {
    _booted = false; // reset so orientation change doesn't animate strangely
    _lastKbH = -1;
    _schedule();
  }, { passive: true });

  // ── iOS focus/blur: poll during keyboard animation ────────────────────────
  // iOS keyboard takes ~250ms to fully open/close. We poll at 100ms intervals
  // during this window to track the keyboard height as it animates.
  if (msgTa && _isIOS) {
    function _iosPoll(times) {
      if (times <= 0) return;
      _schedule();
      setTimeout(() => _iosPoll(times - 1), 50);
    }
    msgTa.addEventListener('focus', () => _iosPoll(6), { passive: true });
    msgTa.addEventListener('blur',  () => _iosPoll(6), { passive: true });
  }

  // ── Android: single deferred schedule on focus (keyboard hasn't opened yet)
  if (msgTa && !_isIOS) {
    msgTa.addEventListener('focus', () => setTimeout(_schedule, 100), { passive: true });
    msgTa.addEventListener('blur',  () => setTimeout(_schedule, 100), { passive: true });
  }

})();
// ── END MOBILE KEYBOARD HANDLER ──────────────────────────────────────────────

// ══════════════════════════════════════════════════════════════════════════════
// MSG LONG-PRESS CONTEXT MENU — v39
// Long-press on user message bubble → floating glassmorphism context menu
// Features: 420ms timer · scale feedback · ripple glow · edge-aware positioning
//           duplicate-open guard · scroll conflict prevention · iOS + Android safe
// ══════════════════════════════════════════════════════════════════════════════
(function initMsgLongPress() {
  'use strict';

  // ── Constants ──────────────────────────────────────────────────────────────
  const LP_DELAY    = 420;    // ms to trigger long-press
  const SCROLL_TOL  = 9;      // px of movement allowed before cancelling
  const MENU_MARGIN = 10;     // px from viewport edges

  // ── State ─────────────────────────────────────────────────────────────────
  let _timer      = null;
  let _activeMsgId = null;
  let _startX     = 0;
  let _startY     = 0;
  let _activeBubble = null;
  let _isOpen     = false;
  let _closeRafId = null;

  // ── Elements ───────────────────────────────────────────────────────────────
  const menu     = document.getElementById('msg-ctx-menu');
  const backdrop = document.getElementById('msg-ctx-backdrop');
  if (!menu || !backdrop) return; // safety guard

  // ── Haptic feedback (Android + iOS) ────────────────────────────────────────
  function _haptic() {
    try {
      if (navigator.vibrate) navigator.vibrate(12);
    } catch(_) {}
  }

  // ── Ripple glow effect on bubble ────────────────────────────────────────────
  function _spawnRipple(bubble, clientX, clientY) {
    const rect = bubble.getBoundingClientRect();
    const size = Math.max(rect.width, rect.height) * 1.2;
    const x = clientX - rect.left - size / 2;
    const y = clientY - rect.top  - size / 2;
    const el = document.createElement('div');
    el.className = 'msg-lp-ripple';
    el.style.cssText = `width:${size}px;height:${size}px;left:${x}px;top:${y}px;`;
    bubble.appendChild(el);
    setTimeout(() => { try { bubble.removeChild(el); } catch(_) {} }, 500);
  }

  // ── Find nearest user message row from a touch/click target ────────────────
  function _getUsrRow(target) {
    const row = target.closest('.msg-row.usr');
    if (!row) return null;
    // Don't trigger on edit UI, action buttons, or interactive inner elements
    if (target.closest('.msg-actions, .edit-ta, .edit-actions, .ma-btn')) return null;
    return row;
  }

  // ── Position menu near the bubble, avoiding viewport edges ─────────────────
  function _positionMenu(anchorEl) {
    // First render off-screen to measure
    menu.style.visibility = 'hidden';
    menu.style.left = '0px';
    menu.style.top  = '0px';

    requestAnimationFrame(() => {
      const mw  = menu.offsetWidth;
      const mh  = menu.offsetHeight;
      const vw  = window.innerWidth;
      const vh  = window.innerHeight;
      const rect = anchorEl.getBoundingClientRect();

      // Prefer: align right edge of menu to right edge of bubble
      let x = rect.right - mw;
      let y = rect.top - mh - 8; // above bubble

      // If not enough room above → place below
      if (y < MENU_MARGIN) {
        y = rect.bottom + 8;
      }

      // Clamp to viewport
      x = Math.max(MENU_MARGIN, Math.min(x, vw - mw - MENU_MARGIN));
      y = Math.max(MENU_MARGIN, Math.min(y, vh - mh - MENU_MARGIN));

      // Set origin based on bubble position (above/below, left/right)
      const originX = rect.right - mw > MENU_MARGIN ? 'right' : 'left';
      const originY = y < rect.top ? 'bottom' : 'top';
      menu.style.transformOrigin = `${originY} ${originX}`;

      menu.style.left = x + 'px';
      menu.style.top  = y + 'px';
      menu.style.visibility = '';
    });
  }

  // ── Open menu ──────────────────────────────────────────────────────────────
  function _openMenu(row, touchX, touchY) {
    if (_isOpen) _closeMenuImmediate(); // dedupe guard

    _activeMsgId = row.dataset.msgId || null;
    _activeBubble = row.querySelector('.msg-bubble');
    if (!_activeBubble) return;

    // Update pin label based on message state
    const chat = typeof getChat === 'function' ? getChat() : null;
    const msg  = chat?.messages?.find(m => m.id === _activeMsgId);
    const pinLbl = document.getElementById('mcm-pin-lbl');
    if (pinLbl) pinLbl.textContent = msg?.pinned ? 'Unpin Message' : 'Pin Message';

    _haptic();
    _spawnRipple(_activeBubble, touchX, touchY);

    // Prevent scroll while menu is open
    document.body.style.overflow = 'hidden';
    document.documentElement.style.overflow = 'hidden';

    _isOpen = true;
    backdrop.setAttribute('aria-hidden', 'false');
    menu.setAttribute('aria-hidden', 'false');
    backdrop.classList.add('active');

    _positionMenu(_activeBubble);

    // Trigger open animation next frame
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        menu.classList.remove('mcm-closing');
        menu.classList.add('mcm-open');
      });
    });
  }

  // ── Close menu (animated) ──────────────────────────────────────────────────
  function _closeMenu() {
    if (!_isOpen) return;
    _isOpen = false;

    // Remove scale-down press state from bubble
    if (_activeBubble) {
      _activeBubble.classList.remove('lp-pressing');
    }

    menu.classList.remove('mcm-open');
    menu.classList.add('mcm-closing');
    backdrop.classList.remove('active');
    backdrop.setAttribute('aria-hidden', 'true');
    menu.setAttribute('aria-hidden', 'true');

    // Restore scroll after animation
    if (_closeRafId) cancelAnimationFrame(_closeRafId);
    _closeRafId = setTimeout(() => {
      menu.classList.remove('mcm-closing');
      document.body.style.overflow = '';
      document.documentElement.style.overflow = '';
      _activeMsgId  = null;
      _activeBubble = null;
    }, 200);
  }

  // ── Close immediately (no animation, used for dedup) ──────────────────────
  function _closeMenuImmediate() {
    _isOpen = false;
    menu.classList.remove('mcm-open', 'mcm-closing');
    backdrop.classList.remove('active');
    if (_activeBubble) _activeBubble.classList.remove('lp-pressing');
    document.body.style.overflow = '';
    document.documentElement.style.overflow = '';
    _activeMsgId  = null;
    _activeBubble = null;
  }

  // ── Cancel timer and remove press state ────────────────────────────────────
  function _cancelPress() {
    if (_timer) { clearTimeout(_timer); _timer = null; }
    if (_activeBubble) {
      _activeBubble.classList.remove('lp-pressing');
    }
  }

  // ══ Touch/Pointer event handlers ══════════════════════════════════════════

  // Use the msgs-wrap (scroll container) for delegation
  const msgList = document.getElementById('msgs-wrap');
  if (!msgList) return;

  // ── touchstart — start long-press timer ─────────────────────────────────
  msgList.addEventListener('touchstart', e => {
    if (_isOpen) return;
    const touch = e.touches[0];
    const row   = _getUsrRow(e.target);
    if (!row) return;

    _startX = touch.clientX;
    _startY = touch.clientY;
    _activeBubble = row.querySelector('.msg-bubble');

    // Prevent default only to block context menu (not scroll)
    // We do NOT call e.preventDefault() here to keep scroll working

    // Scale-down press feedback after ~60ms (feels responsive)
    const delayBubble = _activeBubble;
    setTimeout(() => {
      if (_timer !== null && delayBubble) {
        delayBubble.classList.add('lp-pressing');
      }
    }, 60);

    _timer = setTimeout(() => {
      _timer = null;
      // Confirm we haven't scrolled too far
      _openMenu(row, _startX, _startY);
    }, LP_DELAY);

  }, { passive: true });

  // ── touchmove — cancel if moved too much (scroll intent) ────────────────
  msgList.addEventListener('touchmove', e => {
    if (!_timer && !_activeBubble?.classList.contains('lp-pressing')) return;
    const touch = e.touches[0];
    const dx = Math.abs(touch.clientX - _startX);
    const dy = Math.abs(touch.clientY - _startY);
    if (dx > SCROLL_TOL || dy > SCROLL_TOL) {
      _cancelPress();
    }
  }, { passive: true });

  // ── touchend / touchcancel — cancel if released before threshold ─────────
  msgList.addEventListener('touchend',    _cancelPress, { passive: true });
  msgList.addEventListener('touchcancel', _cancelPress, { passive: true });

  // ── contextmenu — block browser native menu on long-press (Android) ──────
  msgList.addEventListener('contextmenu', e => {
    const row = _getUsrRow(e.target);
    if (row) {
      e.preventDefault();
      e.stopPropagation();
    }
  });

  // ── Backdrop click — close ────────────────────────────────────────────────
  backdrop.addEventListener('click',      _closeMenu);
  backdrop.addEventListener('touchstart', e => { e.preventDefault(); _closeMenu(); }, { passive: false });

  // ── Keyboard: Escape to close ─────────────────────────────────────────────
  document.addEventListener('keydown', e => {
    if (_isOpen && e.key === 'Escape') { e.preventDefault(); _closeMenu(); }
  });

  // ── Menu item: Copy ───────────────────────────────────────────────────────
  document.getElementById('mcm-copy')?.addEventListener('click', () => {
    const chat = typeof getChat === 'function' ? getChat() : null;
    const msg  = chat?.messages?.find(m => m.id === _activeMsgId);
    _closeMenu();
    if (!msg) return;
    try {
      if (navigator.clipboard && window.isSecureContext) {
        navigator.clipboard.writeText(msg.content).then(() => {
          if (typeof toast === 'function') toast('Message copied! 📋', 'success');
        });
      } else {
        // Fallback for older Android WebView
        const ta = document.createElement('textarea');
        ta.value = msg.content;
        ta.style.cssText = 'position:fixed;left:-9999px;top:-9999px;opacity:0';
        document.body.appendChild(ta);
        ta.select();
        document.execCommand('copy');
        document.body.removeChild(ta);
        if (typeof toast === 'function') toast('Message copied! 📋', 'success');
      }
    } catch(_) {
      if (typeof toast === 'function') toast('Copy failed', 'error');
    }
  });

  // ── Menu item: Edit ───────────────────────────────────────────────────────
  document.getElementById('mcm-edit')?.addEventListener('click', () => {
    const msgId = _activeMsgId;
    _closeMenu();
    if (!msgId) return;
    // Trigger edit by simulating click on the .ma-edit button of this row
    setTimeout(() => {
      const row = document.querySelector(`.msg-row[data-msg-id="${msgId}"]`);
      const editBtn = row?.querySelector('.ma-edit');
      if (editBtn) {
        editBtn.click();
      } else {
        // Fallback: directly enter edit mode
        const chat = typeof getChat === 'function' ? getChat() : null;
        const msg  = chat?.messages?.find(m => m.id === msgId);
        if (!msg || !row) return;
        const bubble = row.querySelector('.msg-bubble');
        if (!bubble) return;
        bubble.classList.add('usr-edit-mode');
        bubble.innerHTML = `<textarea class="edit-ta"></textarea>
          <div class="edit-actions">
            <button class="edit-btn edit-save">Save &amp; Resend</button>
            <button class="edit-btn edit-cancel">Cancel</button>
          </div>`;
        const ta = bubble.querySelector('.edit-ta');
        ta.value = msg.content;
        ta.style.height = 'auto';
        ta.style.height = Math.min(ta.scrollHeight, Math.floor(window.innerHeight * 0.4)) + 'px';
        ta.addEventListener('input', () => {
          ta.style.height = 'auto';
          ta.style.height = Math.min(ta.scrollHeight, Math.floor(window.innerHeight * 0.4)) + 'px';
        }, { passive: true });
        requestAnimationFrame(() => {
          ta.focus();
          ta.selectionStart = ta.selectionEnd = ta.value.length;
          setTimeout(() => ta.scrollIntoView({ behavior: 'smooth', block: 'nearest' }), 360);
        });
      }
    }, 220); // slight delay so menu closes first
  });

  // ── Menu item: Delete ─────────────────────────────────────────────────────
  document.getElementById('mcm-delete')?.addEventListener('click', () => {
    const msgId = _activeMsgId;
    _closeMenu();
    if (!msgId) return;
    setTimeout(() => {
      const chat = typeof getChat === 'function' ? getChat() : null;
      if (!chat) return;
      const idx = chat.messages.findIndex(m => m.id === msgId);
      if (idx === -1) return;
      chat.messages.splice(idx, 1);
      // Also remove subsequent AI response if it follows immediately
      if (chat.messages[idx]?.role === 'assistant') {
        chat.messages.splice(idx, 1);
      }
      if (typeof save === 'function') save();
      if (typeof renderMessages === 'function') renderMessages();
      if (typeof toast === 'function') toast('Message deleted', 'info');
    }, 220);
  });

  // ── Menu item: Pin ────────────────────────────────────────────────────────
  document.getElementById('mcm-pin')?.addEventListener('click', () => {
    const msgId = _activeMsgId;
    _closeMenu();
    if (!msgId) return;
    setTimeout(() => {
      const chat = typeof getChat === 'function' ? getChat() : null;
      const msg  = chat?.messages?.find(m => m.id === msgId);
      if (!msg) return;
      msg.pinned = !msg.pinned;
      if (typeof save === 'function') save();
      if (typeof toast === 'function') toast(msg.pinned ? 'Message pinned 📌' : 'Message unpinned', 'info');
    }, 220);
  });

  // ── Menu item: Forward (share) ────────────────────────────────────────────
  document.getElementById('mcm-forward')?.addEventListener('click', () => {
    const msgId = _activeMsgId;
    _closeMenu();
    if (!msgId) return;
    const chat = typeof getChat === 'function' ? getChat() : null;
    const msg  = chat?.messages?.find(m => m.id === msgId);
    if (!msg) return;
    setTimeout(() => {
      const text = msg.content;
      if (navigator.share) {
        navigator.share({ text }).catch(() => {});
      } else if (navigator.clipboard && window.isSecureContext) {
        navigator.clipboard.writeText(text).then(() => {
          if (typeof toast === 'function') toast('Copied to share! 🔗', 'success');
        });
      } else {
        if (typeof toast === 'function') toast('Share not supported on this device', 'info');
      }
    }, 220);
  });

  // ── Menu item: Reply ──────────────────────────────────────────────────────
  document.getElementById('mcm-reply')?.addEventListener('click', () => {
    const msgId = _activeMsgId;
    _closeMenu();
    if (!msgId) return;
    setTimeout(() => {
      const chat = typeof getChat === 'function' ? getChat() : null;
      const msg  = chat?.messages?.find(m => m.id === msgId);
      if (!msg) return;
      const ta = document.getElementById('msg-ta');
      if (!ta) return;
      const preview = msg.content.slice(0, 80).replace(/\n/g, ' ');
      const replyPrefix = `> ${preview}${msg.content.length > 80 ? '…' : ''}\n\n`;
      ta.value = replyPrefix + ta.value;
      ta.focus();
      ta.selectionStart = ta.selectionEnd = ta.value.length;
      // Trigger input event to resize textarea
      ta.dispatchEvent(new Event('input', { bubbles: true }));
      setTimeout(() => ta.scrollIntoView({ behavior: 'smooth', block: 'nearest' }), 120);
    }, 220);
  });

  // ── Menu item: Select Multiple ────────────────────────────────────────────
  document.getElementById('mcm-select')?.addEventListener('click', () => {
    // FIX: capture _activeMsgId BEFORE _closeMenu() clears it (it doesn't clear
    // _activeMsgId but defensive capture avoids any timing edge case)
    const msgId = _activeMsgId;
    _closeMenu();
    if (!msgId) return;
    setTimeout(() => {
      // FIX: only target the specific row — remove the bad .msg-row.usr fallback
      // which selected the first user message regardless of which was right-clicked
      const row = document.querySelector(`.msg-row[data-msg-id="${msgId}"]`);
      if (!row) return;
      // Toggle selection on the tapped row
      row.classList.toggle('msg-selected');
      // Enter selection mode on the list so subsequent taps select rows
      const msgList = document.getElementById('msg-list');
      if (msgList) msgList.classList.add('selection-mode');
      if (typeof toast === 'function') toast('Tap messages to select multiple', 'info');

      // Allow tapping any message row to toggle selection while in selection-mode
      if (!msgList || msgList._selectionModeWired) return;
      msgList._selectionModeWired = true;
      msgList.addEventListener('click', function _selClick(e) {
        if (!msgList.classList.contains('selection-mode')) return;
        const r = e.target.closest('.msg-row');
        if (!r) return;
        // Don't intercept action button clicks
        if (e.target.closest('.msg-actions')) return;
        r.classList.toggle('msg-selected');
      });
    }, 220);
  });

  // ══ END MSG LONG-PRESS CONTEXT MENU ══════════════════════════════════════
  // Export for external use if needed
  if (typeof window !== 'undefined') {
    window._msgCtxMenu = { open: _openMenu, close: _closeMenu };
  }
})();
// ── END MSG LONG-PRESS CONTEXT MENU ──────────────────────────────────────────

// ╔══════════════════════════════════════════════════════════════════╗
// ║  AURA AI — GROK-STYLE SETTINGS PANEL JS                         ║
// ║  1. Back button for mobile sub-panel navigation                  ║
// ║  2. Mobile: open/close sub-panel on nav item click               ║
// ║  3. Nav value labels (shows current theme/language on row)       ║
// ╚══════════════════════════════════════════════════════════════════╝
(function initGrokSettingsPanel() {
  'use strict';

  // ── 1. Inject back button into settings header ──────────────────
  const settHdr = document.querySelector('#sett-panel .sp-hdr');
  if (settHdr && !document.getElementById('settBackBtn')) {
    const backBtn = document.createElement('button');
    backBtn.id = 'settBackBtn';
    backBtn.className = 'hdr-btn sp-back-btn';
    backBtn.setAttribute('aria-label', 'Back to settings');
    backBtn.setAttribute('type', 'button');
    backBtn.innerHTML = `<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M19 12H5"/><path d="M12 19l-7-7 7-7"/></svg>`;
    settHdr.prepend(backBtn);
    backBtn.addEventListener('click', () => {
      const panel = document.getElementById('sett-panel');
      if (panel) panel.classList.remove('sp-sub-open');
    });
  }

  // ── 2. Mobile: show sub-panel when a nav item is clicked ────────
  document.querySelectorAll('.sp-nav-item').forEach(btn => {
    btn.addEventListener('click', () => {
      if (window.innerWidth <= 768) {
        const panel = document.getElementById('sett-panel');
        if (panel) panel.classList.add('sp-sub-open');
      }
    });
  });

  // Close sub-panel on settings close (reset state)
  const origClose = window.closeSettings;
  if (typeof origClose === 'function') {
    window.closeSettings = function() {
      origClose();
      const panel = document.getElementById('sett-panel');
      if (panel) {
        // Delay reset so close animation finishes
        setTimeout(() => panel.classList.remove('sp-sub-open'), 480);
      }
    };
    // Re-wire close button with patched function
    const closeBtn = document.getElementById('settClose');
    if (closeBtn) {
      closeBtn.onclick = null;
      closeBtn.addEventListener('click', window.closeSettings);
    }
    const overlay = document.getElementById('sett-overlay');
    if (overlay) {
      overlay.onclick = null;
      overlay.addEventListener('click', window.closeSettings);
    }
  }

  // ── 3. Nav value labels ─────────────────────────────────────────
  // Map of data-tab → label text getter
  const _navVals = {
    appearance: () => {
      const t = document.documentElement.getAttribute('data-theme') || 'dark';
      return t === 'light' ? 'Light' : t === 'dark' ? 'Dark' : 'System';
    },
    language: () => {
      const sel = document.getElementById('langSel');
      if (!sel) return 'EN';
      const v = sel.value || 'en';
      return v.toUpperCase().slice(0, 2);
    },
    subscription: () => 'Free',
  };

  function _injectNavVals() {
    Object.entries(_navVals).forEach(([tab, getter]) => {
      const btn = document.querySelector(`.sp-nav-item[data-tab="${tab}"]`);
      if (!btn) return;
      let valEl = btn.querySelector('.sp-nav-val');
      if (!valEl) {
        valEl = document.createElement('span');
        valEl.className = 'sp-nav-val';
        // Insert before the ::before chevron — put as last child
        btn.appendChild(valEl);
      }
      valEl.textContent = getter();
    });
  }

  // Run on load and whenever settings panel opens
  _injectNavVals();

  const origOpen = window.openSettings;
  if (typeof origOpen === 'function') {
    window.openSettings = function(tabId) {
      origOpen(tabId);
      _injectNavVals();
    };
  }

  // Update appearance value when theme changes
  const themeObs = new MutationObserver(_injectNavVals);
  themeObs.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] });

})();
// ── END GROK-STYLE SETTINGS PANEL JS ─────────────────────────────────────────

// ╔══════════════════════════════════════════════════════════════════╗
// ║  AURA AI — GEMINI-STYLE AUTH WAVE ANIMATION                      ║
// ║  Smooth multi-layer sine wave canvas, blue palette, blurred      ║
// ╚══════════════════════════════════════════════════════════════════╝
(function initAuthWave() {
  'use strict';

  const canvas = document.getElementById('auth-wave-canvas');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');

  // Wave layer config — ZenQ purple/violet palette
  const WAVES = [
    { speed: 0.5,  amp: 72,  freq: 1.2, phase: 0,    color: 'rgba(108,110,247,0.28)', blur: 28 },
    { speed: 0.75, amp: 56,  freq: 1.8, phase: 1.1,  color: 'rgba(139,92,246,0.22)',  blur: 18 },
    { speed: 0.35, amp: 88,  freq: 0.9, phase: 2.2,  color: 'rgba(99,87,255,0.18)',   blur: 36 },
    { speed: 1.1,  amp: 44,  freq: 2.4, phase: 0.7,  color: 'rgba(167,139,250,0.14)', blur: 12 },
    { speed: 0.65, amp: 62,  freq: 1.5, phase: 3.4,  color: 'rgba(124,58,237,0.20)',  blur: 22 },
  ];

  let W = 0, H = 0, raf = null, t = 0;
  let alive = true;

  function resize() {
    const overlay = document.getElementById('auth-overlay');
    if (!overlay) return;
    W = canvas.width  = overlay.offsetWidth  || window.innerWidth;
    H = canvas.height = overlay.offsetHeight || window.innerHeight;
  }

  function drawWave(wave, time) {
    const yBase = H * 0.62;
    const t = time / 1000; // convert ms → seconds
    ctx.save();
    ctx.filter = `blur(${wave.blur}px)`;
    ctx.beginPath();
    for (let x = 0; x <= W; x += 2) {
      const progress = x / W;
      const y = yBase
        + Math.sin(progress * Math.PI * wave.freq       + t * wave.speed              + wave.phase)       * wave.amp
        + Math.sin(progress * Math.PI * wave.freq * 2.1 + t * wave.speed * 1.6        + wave.phase * 1.7) * (wave.amp * 0.38)
        + Math.sin(progress * Math.PI * wave.freq * 0.5 + t * wave.speed * 0.8        + wave.phase * 0.6) * (wave.amp * 0.22);
      if (x === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.lineTo(W, H);
    ctx.lineTo(0, H);
    ctx.closePath();
    ctx.fillStyle = wave.color;
    ctx.fill();
    ctx.restore();
  }

  function drawGlow() {
    const grad = ctx.createLinearGradient(0, H * 0.35, 0, H);
    grad.addColorStop(0,   'rgba(0,0,0,0)');
    grad.addColorStop(0.4, 'rgba(40,20,80,0.10)');
    grad.addColorStop(1,   'rgba(30,10,70,0.32)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, W, H);
  }

  function frame(ts) {
    if (!alive) return;
    t = ts;
    ctx.clearRect(0, 0, W, H);

    // Draw background glow first
    drawGlow();

    // Draw wave layers back to front (most transparent first)
    for (let i = WAVES.length - 1; i >= 0; i--) {
      drawWave(WAVES[i], ts);
    }

    raf = requestAnimationFrame(frame);
  }

  // Only run while auth overlay is visible
  function startWave() {
    if (raf) return;
    alive = true;
    resize();
    raf = requestAnimationFrame(frame);
  }

  function stopWave() {
    alive = false;
    if (raf) { cancelAnimationFrame(raf); raf = null; }
  }

  // Start/stop based on overlay visibility
  const authOverlay = document.getElementById('auth-overlay');
  if (authOverlay && !authOverlay.classList.contains('gone')) {
    startWave();
  }

  // Watch for overlay being hidden
  const overlayObs = new MutationObserver(() => {
    if (!authOverlay) return;
    if (authOverlay.classList.contains('gone') || authOverlay.classList.contains('hiding')) {
      stopWave();
    } else {
      startWave();
    }
  });
  if (authOverlay) {
    overlayObs.observe(authOverlay, { attributes: true, attributeFilter: ['class'] });
  }

  window.addEventListener('resize', () => { resize(); }, { passive: true });

  // Reduced motion: no animation
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    stopWave();
  }
})();
// ── END AUTH WAVE ANIMATION ───────────────────────────────────────────────────


// ══════════════════════════════════════════════════════════════════════════
//  GROK-STYLE SIDEBAR PATCH — top profile row, Tasks-style New Chat pill,
//  upgrade banner, collapsible "Conversations" header, bottom search/settings
//  /compose bar. UI-only: reuses existing app functions (openPlanModal,
//  openSettings, setSidebarCollapsed, showWelcome, renderChatList).
// ══════════════════════════════════════════════════════════════════════════
(function () {
  function ready(fn) {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', fn);
    } else {
      fn();
    }
  }

  ready(function () {
    // ── Conversations collapse toggle ──────────────────────────────
    var convHdr  = document.getElementById('sbConvHdr');
    var listWrap = document.getElementById('sbListWrap');
    if (convHdr && listWrap) {
      var toggleConv = function () {
        var collapsed = listWrap.classList.toggle('sb-conv-collapsed');
        convHdr.setAttribute('aria-expanded', collapsed ? 'false' : 'true');
      };
      convHdr.addEventListener('click', toggleConv);
      convHdr.addEventListener('keydown', function (e) {
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggleConv(); }
      });
    }

    // ── Upgrade banner (SuperGrok-style) → opens existing plan modal ──
    var upgradeBanner = document.getElementById('sbUpgradeBanner');
    if (upgradeBanner) {
      upgradeBanner.addEventListener('click', function () {
        if (typeof openPlanModal === 'function') openPlanModal();
      });
    }

    // ── Secondary chevron next to profile → collapse / close sidebar ──
    var profileExpandBtn = document.getElementById('sbProfileExpandBtn');
    if (profileExpandBtn) {
      profileExpandBtn.addEventListener('click', function () {
        if (typeof isMob === 'function' && isMob()) {
          if (typeof closeMobSidebar === 'function') closeMobSidebar();
        } else if (typeof setSidebarCollapsed === 'function') {
          setSidebarCollapsed(!APP.sidebarCollapsed);
        }
      });
    }

    // ── Bottom-bar compose button → same action as New Chat ──────────
    var composeBtn = document.getElementById('sbNewBtn2');
    if (composeBtn) {
      composeBtn.addEventListener('click', function () {
        APP.activeChatId = null;
        if (typeof save === 'function') save();
        if (typeof showWelcome === 'function') showWelcome();
        if (typeof renderChatList === 'function') renderChatList();
        var ta = document.getElementById('msg-ta');
        if (ta) ta.focus();
      });
    }
  });
})();
// ── END GROK-STYLE SIDEBAR PATCH ────────────────────────────────────────────
